def _is_research_absence_retry_policy(policy_id: str) -> bool:
    return (
        policy_id in _RESEARCH_ABSENCE_RETRY_COOLDOWNS
        or policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        or policy_id.startswith(_SOURCE_RANKED_FOOD_POLICY_PREFIX)
        or policy_id == _SOURCE_RANKED_FLIGHT_RESERVE_POLICY.policy_id
    )


def _research_absence_retry_cooldown(
    policy_id: str,
    *,
    default: int | None = None,
) -> int | None:
    if policy_id in _RESEARCH_ABSENCE_RETRY_COOLDOWNS:
        return _RESEARCH_ABSENCE_RETRY_COOLDOWNS[policy_id]
    if policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        return _DEFAULT_RESEARCH_CROWD_COOLDOWN
    if policy_id.startswith(_SOURCE_RANKED_FOOD_POLICY_PREFIX):
        return _DEFAULT_RESEARCH_CROWD_COOLDOWN
    if policy_id == _SOURCE_RANKED_FLIGHT_RESERVE_POLICY.policy_id:
        return _DEFAULT_RESEARCH_CROWD_COOLDOWN
    return default


def _sanctuary_visibility_revalidation_pending(
    state: Mapping[str, Any],
) -> bool:
    """Return whether revision 243 may open one corrected sanctuary route."""
    marker = state.get(_SANCTUARY_VISIBILITY_REVALIDATION_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("policy_revision")
        == _SANCTUARY_VISIBILITY_REVALIDATION_REVISION
        and marker.get("policy_id")
        == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == _level(state)
        and marker.get("status") == "pending"
    )


def _sanctuary_invisible_carrier_revalidation_pending(
    state: Mapping[str, Any],
) -> bool:
    """Return whether revision 244 may search the expanded carrier graph."""
    marker = state.get(_SANCTUARY_INVISIBLE_CARRIER_REVALIDATION_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("policy_revision")
        == _SANCTUARY_INVISIBLE_CARRIER_REVALIDATION_REVISION
        and marker.get("policy_id")
        == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == _level(state)
        and marker.get("status") == "pending"
    )


