def _quest_target_runner_options(
    source_world: WorldSource,
    current_state: Mapping[str, Any],
    *,
    character_level: int,
    policy_id: str,
) -> dict[str, Any]:
    """Build identical source-vetted options for initial and in-session dispatch."""
    quest = snapshot_quest_status(
        (current_state or {}).get("quest_status")
        if isinstance((current_state or {}).get("quest_status"), Mapping)
        else None
    )
    if not quest.needs_target_run:
        raise RuntimeError(
            "quest target policy was selected without an active quest target"
        )
    if quest.kind == "hoard":
        raise RuntimeError(QUEST_HOARD_EXECUTION_BLOCKER)
    level = character_level
    recall_origins = _source_ranked_recall_origins(current_state or {})
    max_hp = (
        int((current_state or {}).get("max_hp"))
        if isinstance((current_state or {}).get("max_hp"), (int, float))
        and int((current_state or {}).get("max_hp")) > 0
        else None
    )
    if quest.kind == "kill":
        candidate = _quest_mobile_candidate(
            source_world,
            quest,
            character_level=level,
            character_max_hp=max_hp,
            recall_origins=recall_origins,
            state=current_state,
        )
        if candidate is None:
            raise RuntimeError(
                "quest target VNUM or room is absent from the checked-in source"
            )
        # The candidate route has passed the same source hazard checks as
        # ordinary hunts. Do not replace it with a raw shortest path when
        # the quest target is a wandering mobile in its live room.
        origin_paths = _shortest_paths_from(
            source_world.rooms,
            candidate.route_origin_room_vnum,
        )
        route = Fastwalk(
            name=(
                f"quest target VNUM {quest.mob_vnum} "
                f"at source reset {candidate.room_vnum}"
            ),
            minimum_level=1,
            maximum_level=100,
            notation=_funding_route_notation(candidate.route),
            recall_after_loot=True,
            **_source_ranked_route_program_fastwalk_options(
                source_world,
                candidate,
                current_state,
                character_level=level,
            ),
            route_hard_hazard_targets=candidate.route_hard_hazard_targets,
            route_origin_recall_index=candidate.route_origin_recall_index,
            route_origin_room_vnum=candidate.route_origin_room_vnum,
            **_source_ranked_route_live_navigation(
                source_world,
                candidate,
                character_level=level,
                origin_paths=origin_paths,
            ),
        )
        hunt_stops = _source_ranked_hunt_stops(
            candidate,
            source_world,
            character_level=level,
            state=current_state,
            maximum_level_offset_override=quest_target_maximum_level_offset(
                level
            ),
        )
    else:
        route = _quest_target_route(
            source_world,
            quest,
            character_level=level,
            recall_origins=recall_origins,
            state=current_state,
        )
        if route is None:
            raise RuntimeError(
                f"no source-safe route from recall to quest room {quest.room_vnum}"
            )
        keyword = quest_object_keyword(
            source_world,
            quest.object_vnum,
        )
        if keyword is None:
            raise RuntimeError(
                f"quest object VNUM {quest.object_vnum} is absent from source"
            )
        actions = (f"get all.{keyword}",)
        hunt_stops = (
            FieldHuntStop(
                (),
                None,
                actions=actions,
                required_items=(keyword,),
                minimum_health_ratio=0.0,
                source_policy_id=policy_id,
                # Generated quest objects are identified by their exact
                # source VNUM; keep same-named prototypes from satisfying
                # the quest by accident.
                source_loot_object_vnums=(quest.object_vnum,),
            ),
        )
        admission = circus_quest_admission(
            source_world, quest.room_vnum, character_level=level,
        )
        if (
            admission is not None and route.route_origin_room_vnum == 3001
            and route.commands == (*admission.approach, *admission.continuation)
        ):
            route = _quest_fastwalk(name="quest circus admission", commands=admission.approach)
            hunt_stops = (
                FieldHuntStop(
                    (), None, actions=("buy ticket",), required_items=("a ticket",),
                    source_loot_object_vnums=(4400,), source_policy_id="quest-circus-admission",
                ),
                replace(hunt_stops[0], route=admission.continuation),
            )
    return dict(
        fastwalk_route=route,
        fastwalk_origin_actions=(
            "get all.pie",
            "eat pie",
            "drink skin",
            *(
                (
                    f"recall set {route.route_origin_recall_index}",
                    "recall",
                )
                if route.route_origin_recall_index
                else ()
            ),
        ),
        fastwalk_hunt_stops=tuple(hunt_stops),
        fastwalk_kill_limit=1,
        fastwalk_train_before_departure=True,
        require_fastwalk_kill=False,
        allow_safe_fastwalk_abort=True,
        use_sanctuary_potions=quest.kind == "kill",
    )


def _source_quest_point_shortfall(state: Mapping[str, Any]) -> int | None:
    """Return a source-derived shortfall only from observed total QP."""
    status = state.get("quest_status")
    if not isinstance(status, Mapping) or "total_points" not in status:
        return None
    raw_total = status["total_points"]
    if type(raw_total) is int:
        total_points = raw_total
    elif isinstance(raw_total, str) and raw_total.isdecimal():
        total_points = int(raw_total)
    else:
        return None
    if total_points < 0:
        return None
    return quest_points_shortfall_for_advance(_level(state), total_points)


def _required_qp_quest_request_policy(
    state: dict[str, Any], *, has_food: bool, practice_skill: str | None,
) -> ProgressionPolicy | None:
    """Request for an actual next-level QP shortfall when DD4 permits it."""
    raw_status = state.get("quest_status")
    if (
        not isinstance(raw_status, Mapping)
        or "total_points" not in raw_status
        or not quest_request_status_observed(raw_status)
    ):
        return None
    shortfall = _source_quest_point_shortfall(state)
    if shortfall is None:
        return None
    quest = snapshot_quest_status(raw_status)
    if not (
        state.get("world_boot_id")
        and has_food
        and _state_has_item(state.get("inventory"), "water skin")
        and _is_safe_healer_checkpoint(state)
        and not _campaign_needs_healer_recovery(state)
        and not state.get("dead") and not state.get("in_combat")
        and quest_request_fame_allowed(state)
        and not quest.active and quest.nextquest <= 0
        and shortfall > 0
    ):
        return None

    level = _level(state)
    questmaster = questmaster_name_for_level(level)
    return replace(
        _QUEST_REQUEST_POLICY,
        policy_id="quest-required-qp-request",
        minimum_level=level,
        maximum_level=level,
        summary=(
            f"A source-defined quest-point shortfall blocks level {level + 1}; "
            f"request a quest from {questmaster} whenever DD4's live timer "
            "allows another request."
        ),
        evidence=(
            *_QUEST_REQUEST_POLICY.evidence,
            "DD4's observed active assignment and nextquest timer are the "
            "request gates; character level and reboot do not impose a limit.",
        ),
        practice_skill=practice_skill,
    )


def _required_quest_cooldown_wait_allowed(
    state: Mapping[str, Any], *, has_food: bool,
) -> bool:
    """Permit the required QP wait after current-band hunts are exhausted."""
    status = state.get("quest_status")
    if (
        not isinstance(status, Mapping)
        or "total_points" not in status
        or not quest_request_status_observed(status)
    ):
        return False
    try:
        total = int(status["total_points"])
    except (TypeError, ValueError):
        return False
    quest = snapshot_quest_status(status)
    return bool(
        total >= 0
        and quest_points_shortfall_for_advance(_level(state), total) > 0
        and state.get("world_boot_id")
        and has_food
        and _state_has_item(state.get("inventory"), "water skin")
        and _is_safe_healer_checkpoint(state)
        and not _campaign_needs_healer_recovery(state)
        and not state.get("dead") and not state.get("in_combat")
        and quest_request_fame_allowed(state)
        and not quest.active and quest.nextquest > 0
        and not _quest_cooldown_wait_has_no_progress(state)
    )


def _quest_cooldown_wait_has_no_progress(state: Mapping[str, Any]) -> bool:
    if _quest_wait_started_new_request_cycle(state) or _legacy_quest_reader_recheck_allowed(state):
        return False
    previous = state.get("campaign_quest_cooldown_wait")
    try:
        previous_remaining = int(previous.get("remaining") or 0) if isinstance(previous, Mapping) else 0
    except (TypeError, ValueError):
        previous_remaining = 0
    return bool(
        isinstance(previous, Mapping)
        and previous.get("boot_id") == state.get("world_boot_id")
        and previous.get("level") == _level(state)
        and snapshot_quest_status(state.get("quest_status")).nextquest
        >= previous_remaining
    )


def _legacy_quest_reader_recheck_allowed(state: Mapping[str, Any]) -> bool:
    """Recheck one exact old sleep-before-read stall, never a repaired reader."""
    marker = state.get("campaign_quest_cooldown_wait")
    phases = state.get("campaign_quest_phases")
    reason = "live quest cooldown did not advance for 180 seconds"
    if not (
        isinstance(marker, Mapping) and "reader_revision" not in marker
        and marker.get("boot_id") and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == _level(state)
        and state.get("campaign_fastwalk_abort_reason") == reason
        and isinstance(phases, list) and len(phases) == 1
        and isinstance(phases[0], Mapping) and phases[0].get("phase") == "quest-cooldown"
        and not phases[0].get("objective_kills")
        and _is_safe_healer_checkpoint(state) and not _campaign_needs_healer_recovery(state)
        and not state.get("dead") and not state.get("in_combat")
        and quest_request_fame_allowed(state)
    ):
        return False
    end = phases[0].get("state")
    status = state.get("quest_status")
    if not isinstance(end, Mapping) or not isinstance(status, Mapping):
        return False
    quest = snapshot_quest_status(status)
    return bool(
        not quest.active and quest.nextquest > 0
        and quest.nextquest == marker.get("remaining")
        and type(status.get("total_points")) is int and status["total_points"] >= 0
        and quest_points_shortfall_for_advance(_level(state), quest.total_points) > 0
        and end.get("campaign_fastwalk_abort_reason") == reason
        and end.get("quest_status") == status
        and end.get("room_vnum") == "3054"
        and isinstance(end.get("xp"), int) and end.get("xp") == state.get("xp")
        and end.get("level") == _level(state)
        and isinstance(end.get("hp"), int) and end["hp"] > 0
        and end["hp"] == end.get("max_hp")
        and not end.get("dead") and not end.get("in_combat")
    )


def _quest_wait_started_new_request_cycle(
    state: Mapping[str, Any], *, previous_state: Mapping[str, Any] | None = None,
) -> bool:
    """Prove a new timer cycle after a completed wait and dispatched request."""
    attempt = state.get("campaign_quest_frontier_request")
    phases = state.get("campaign_quest_phases")
    if not (
        isinstance(attempt, Mapping)
        and attempt.get("reason") == "live quest request dispatched"
        and attempt.get("boot_id") == state.get("world_boot_id")
        and attempt.get("level") == _level(state)
        and isinstance(phases, list)
    ):
        return False
    previous_status = (previous_state or {}).get("quest_status")
    cleared = bool(
        isinstance(previous_status, Mapping)
        and previous_status.get("nextquest") in (0, "0")
        and previous_status.get("active") in (0, "0", False)
        and not snapshot_quest_status(previous_status).active
        and previous_state.get("world_boot_id") == state.get("world_boot_id")
        and _level(previous_state) == _level(state)
    )
    for phase in phases:
        if not isinstance(phase, Mapping):
            continue
        observed = phase.get("state")
        status = observed.get("quest_status") if isinstance(observed, Mapping) else None
        if not isinstance(status, Mapping):
            continue
        quest = snapshot_quest_status(status)
        if phase.get("phase") == "quest-cooldown":
            cleared = (
                "nextquest" in status and quest.nextquest == 0 and not quest.active
            )
        elif cleared and phase.get("phase") == "quest-request":
            if (
                status.get("active") in (1, "1")
                and quest.active and quest.countdown > 0 and quest.room_vnum > 0
                and (quest.object_vnum > 0 or quest.mob_vnum > 0)
            ):
                return True
            if not quest.active and quest.nextquest > 0:
                return True
    return False


def _repair_completed_quest_wait_from_segments(
    state: dict[str, Any], segments: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Recover a completed wait from the already-bounded recent segment tail."""
    marker = state.get("campaign_quest_cooldown_wait")
    if not isinstance(marker, Mapping):
        return state
    for segment in reversed(segments):
        phase = str(segment["phase"])
        if not phase.startswith("quest-"):
            continue
        if phase not in {"quest-cooldown", "quest-frontier-cooldown", "quest-request"}:
            return state
        if segment["status"] != "success" or not segment["run_id"]:
            return state
        try:
            end = json.loads(segment["end_state_json"] or "{}")
            start = (
                json.loads(segment["start_state_json"] or "{}")
                if phase == "quest-request" else None
            )
        except (KeyError, TypeError, ValueError):
            return state
        if not isinstance(end, Mapping) or (start is not None and not isinstance(start, Mapping)):
            return state
        phases = end.get("campaign_quest_phases")
        expected_phase = "quest-request" if phase == "quest-request" else "quest-cooldown"
        if (
            not isinstance(phases, list) or not phases
            or not isinstance(phases[0], Mapping)
            or phases[0].get("phase") != expected_phase
        ):
            return state
        if (
            end.get("campaign_quest_cooldown_wait") == marker
            and end.get("world_boot_id") == state.get("world_boot_id")
            and _level(end) == _level(state)
            and _quest_wait_started_new_request_cycle(end, previous_state=start)
        ):
            return {**state, "campaign_quest_cooldown_wait": None}
        return state
    return state


def _quest_session_next_phase(
    completed: str,
    state: Mapping[str, Any],
    *,
    world: WorldSource,
    gear_catalog: GearCatalog | None,
    character: CharacterSpec,
) -> QuestPhase | None:
    """Advance one quest using the live MUD timer as the request throttle."""
    status = state.get("quest_status")
    if not quest_request_status_observed(status):
        return None
    quest = snapshot_quest_status(status)
    if (
        completed == "quest-cooldown"
        and not quest.active
        and quest.nextquest <= 0
    ):
        if (
            not quest_request_fame_allowed(state)
            or not _is_safe_healer_checkpoint(state)
            or _campaign_needs_healer_recovery(state)
            or state.get("dead")
            or state.get("in_combat")
        ):
            return None
        level = int(state.get("level") or 1)
        return QuestPhase(
            "quest-request", "request a quest after the live connected cooldown cleared",
            route=_source_guard_fixed_fastwalk_route(
                world, _questmaster_fastwalk(
                    name=f"questmaster {questmaster_name_for_level(level).casefold()} request",
                    level=level,
                    current_state=state,
                ),
                character_level=level,
                character_max_hp=state.get("max_hp"),
                objective_mobile_vnums=set(),
                objective_targets=set(),
            ),
            hunt_stops=(FieldHuntStop(
                (), None, actions=("quest request",), minimum_health_ratio=0.0,
                source_policy_id="quest-request",
            ),),
        )
    if not quest.active:
        return None
    if (
        completed in {"quest-complete", "quest-abort"}
        or state.get("campaign_fastwalk_abort_reason")
        or quest.countdown <= 1
    ):
        return QuestPhase("quest-abort", "close an unfinished or interrupted quest locally")
    level = int(state.get("level") or 1)
    if quest.complete:
        giver = int((state.get("quest_status") or {}).get("giver_vnum") or 0)
        if giver not in {25305, 10001}:
            return QuestPhase("quest-abort", "the live quest giver has no audited return route")
        turnin_name, turnin_level, turnin_route = (
            questmaster_completion_choice(level)
        )
        phase = QuestPhase(
            "quest-complete", "turn in the live completed quest without logging out",
            route=_questmaster_fastwalk(
                name=f"questmaster {turnin_name.casefold()} complete",
                level=turnin_level,
                current_state=state,
                route_commands=turnin_route,
            ),
            hunt_stops=(FieldHuntStop(
                (), None, actions=("quest complete",), minimum_health_ratio=0.0,
                source_policy_id="quest-complete",
            ),),
        )
    elif completed == "quest-target-run":
        return QuestPhase("quest-abort", "the bounded target attempt did not complete the quest")
    else:
        needs_tool = quest.kind == "hoard" and not _state_has_quest_digging_tool(
            state,
            gear_catalog=gear_catalog,
            character_class=character.character_class,
            subclass=character.subclass,
        )
        if needs_tool and completed == "quest-digging-tool":
            return QuestPhase("quest-abort", "the bounded tool attempt did not supply digging capability")
        execution = "quest-digging-tool" if needs_tool else "quest-target-run"
        issue = _quest_source_preflight_issue(
            world, quest, execution=execution, character_level=level,
            character_max_hp=state.get("max_hp"),
            recall_origins=_source_ranked_recall_origins(state), state=state,
        )
        if issue is not None:
            return QuestPhase("quest-abort", issue)
        if needs_tool:
            path = _shortest_paths_from(world.rooms, 3001)[QUEST_DIGGING_TOOL_ROOM_VNUM]
            phase = QuestPhase(
                execution, "obtain the source-identified digging tool on this connection",
                route=_quest_fastwalk(name="quest digging tool", commands=path[0]),
                hunt_stops=(FieldHuntStop(
                    (), None, required_items=(QUEST_DIGGING_TOOL_KEYWORD,),
                    minimum_health_ratio=0.0, source_policy_id=execution,
                    source_loot_object_vnums=(QUEST_DIGGING_TOOL_OBJECT_VNUM,),
                ),),
            )
        else:
            options = _quest_target_runner_options(
                world, state, character_level=level, policy_id=execution,
            )
            phase = QuestPhase(
                execution, "execute the exact live quest target on this connection",
                route=options["fastwalk_route"],
                hunt_stops=options["fastwalk_hunt_stops"],
                origin_actions=options["fastwalk_origin_actions"],
                use_sanctuary_potions=options["use_sanctuary_potions"],
            )
    return replace(phase, route=_source_guard_fixed_fastwalk_route(
        world,
        phase.route,
        character_level=level,
        character_max_hp=state.get("max_hp"),
        objective_mobile_vnums={
            stop.source_mobile_vnum for stop in phase.hunt_stops
            if stop.source_mobile_vnum is not None
        },
        objective_targets={stop.target for stop in phase.hunt_stops if stop.target},
    ))


def _quest_unavailable_route_reason(
    world: WorldSource, room_vnum: int, *, character_level: int | None = None,
) -> str:
    analysis = _shortest_source_analysis_path(world.rooms, 3001, room_vnum)
    if analysis is not None and analysis[3]:
        reason = (
            "source route safety gates require registered locked-door access "
            f"to quest room {room_vnum}; the shortest analysis-only path needs "
            "key VNUMs " + ", ".join(str(vnum) for vnum in analysis[3])
        )
        chain = tentusks_key_source_chain(world, room_vnum)
        if chain is not None:
            carrier_path = _shortest_paths_from(
                world.rooms, 3001,
            ).get(chain.head_carrier_room_vnum)
            keyed_target_path = _shortest_paths_from(
                world.rooms, 3001,
                unlockable_key_vnums=(chain.key_object_vnum,),
            ).get(room_vnum)
            reason += (
                "; source identifies the stone head object "
                f"{chain.head_object_vnum} on octopus mobile "
                f"{chain.head_carrier_mobile_vnum} in room "
                f"{chain.head_carrier_room_vnum}, then a handoff to statue "
                f"mobile {chain.unlocker_mobile_vnum} in room "
                f"{chain.unlocker_room_vnum} unlocks the {chain.gate_direction} "
                "gate. This is a prerequisite chain only, not route or combat "
                "permission."
            )
            if carrier_path is not None:
                reason += (
                    f" The shortest carrier approach is {len(carrier_path[0])} "
                    "commands."
                )
                if character_level is not None:
                    hazards = source_route_hazard_rejections(
                        world, carrier_path[1],
                        character_level=character_level,
                        combat_at_destination=False,
                    )
                    if hazards:
                        reason += " Source approach hazards: " + "; ".join(hazards) + "."
                underwater_rooms = tuple(
                    vnum for vnum in carrier_path[1]
                    if world.rooms[vnum].sector_type in {
                        SECT_UNDERWATER, SECT_UNDERWATER_GROUND,
                    }
                )
                if underwater_rooms:
                    reason += (
                        " The carrier route enters underwater room(s) "
                        + ", ".join(map(str, underwater_rooms))
                        + "; DD4 starts drowning damage after two air-supply pulses "
                        "without breathe-water, so require a fresh live breathing "
                        "effect before entry."
                    )
            if keyed_target_path is not None:
                reason += (
                    f" With the key, the shortest target route is "
                    f"{len(keyed_target_path[0])} commands."
                )
                if character_level is not None:
                    hazards = source_route_hazard_rejections(
                        world, keyed_target_path[1],
                        character_level=character_level,
                        combat_at_destination=False,
                    )
                    if hazards:
                        reason += " Keyed-route source hazards: " + "; ".join(hazards) + "."
        return reason
    return f"the source graph has no route from recall to quest room {room_vnum}"


def _quest_source_preflight_issue(
    world: WorldSource | None,
    quest: QuestSnapshot,
    *,
    execution: str | None,
    character_level: int | None = None,
    character_max_hp: int | None = None,
    recall_origins: Mapping[int, int] | None = None,
    state: Mapping[str, Any] | None = None,
) -> str | None:
    """Return a source-backed reason a dynamic quest cannot be attempted."""
    if execution not in {"quest-digging-tool", "quest-target-run"}:
        return None
    if not quest.needs_target_run:
        return "the checkpoint does not contain an active quest target"
    if world is None:
        return "the checked-in DD4 source mirror is unavailable"
    if quest.kind == "hoard" and execution != "quest-digging-tool":
        return QUEST_HOARD_EXECUTION_BLOCKER
    if execution == "quest-digging-tool":
        path = _shortest_paths_from(
            world.rooms,
            3001,
        ).get(QUEST_DIGGING_TOOL_ROOM_VNUM)
        if path is None:
            return (
                "the source graph has no route from recall to the registered "
                f"digging-tool room {QUEST_DIGGING_TOOL_ROOM_VNUM}"
            )
        tool = world.objects.get(QUEST_DIGGING_TOOL_OBJECT_VNUM)
        if tool is None or not is_digging_tool(tool):
            return (
                "the source mirror does not contain the registered usable "
                f"shovel VNUM {QUEST_DIGGING_TOOL_OBJECT_VNUM}"
            )
        return None
    direct_route = _quest_target_route(world, quest)
    if quest.kind == "kill" and character_level is not None:
        candidate = _quest_mobile_candidate(
            world,
            quest,
            character_level=character_level,
            character_max_hp=character_max_hp,
            recall_origins=recall_origins,
            state=state,
        )
        if candidate is None:
            if (
                direct_route is None
                and _quest_target_route(
                    world,
                    quest,
                    character_level=character_level,
                    recall_origins=recall_origins,
                )
                is None
            ):
                return _quest_unavailable_route_reason(
                    world, quest.room_vnum, character_level=character_level,
                )
            if (
                character_level is not None
                and world.mobiles.get(quest.mob_vnum) is not None
                and world.rooms.get(quest.room_vnum) is not None
            ):
                return (
                    "source safety gates do not admit quest mobile VNUM "
                    f"{quest.mob_vnum} in room {quest.room_vnum} for level "
                    f"{character_level} and max HP {character_max_hp or 0}"
                )
            return (
                "the source mirror does not contain quest mobile VNUM "
                f"{quest.mob_vnum} in room {quest.room_vnum}"
            )
        if not _quest_mobile_candidate_admitted(
            candidate,
            character_level=character_level,
            character_max_hp=character_max_hp,
            state=state or {},
        ):
            return (
                "source safety gates reject quest mobile VNUM "
                f"{quest.mob_vnum} at source reset room {candidate.room_vnum} "
                f"(assignment hint room {quest.room_vnum}): "
                + "; ".join(candidate.autonomy_rejections)
            )
        return None

    route = _quest_target_route(
        world,
        quest,
        character_level=character_level,
        recall_origins=recall_origins,
        state=state,
    )
    if route is None:
        if direct_route is not None and character_level is not None:
            direct_path = _shortest_paths_from(world.rooms, 3001).get(quest.room_vnum)
            hazards = (
                source_route_hazard_rejections(
                    world, direct_path[1], character_level=character_level,
                )
                if direct_path is not None else ()
            )
            detail = "; shortest recall route: " + "; ".join(hazards[:4]) if hazards else ""
            return (
                "source route safety gates reject quest room "
                f"{quest.room_vnum} for level {character_level}{detail}"
            )
        return _quest_unavailable_route_reason(
            world, quest.room_vnum, character_level=character_level,
        )
    if quest.kind == "kill":
        candidate = _quest_mobile_candidate(
            world,
            quest,
            character_level=character_level,
            character_max_hp=character_max_hp,
            recall_origins=recall_origins,
        )
        if candidate is None:
            return (
                "the source mirror does not contain quest mobile VNUM "
                f"{quest.mob_vnum} in room {quest.room_vnum}"
            )
    if quest_object_keyword(world, quest.object_vnum) is None:
        return (
            "the source mirror does not contain quest object VNUM "
            f"{quest.object_vnum}"
        )
    return None


def _bind_source_combat_output_to_fame_stops(
    stops: Collection[FieldHuntStop],
    state: Mapping[str, Any] | None,
    *,
    source_world: WorldSource | None = None,
    character_level: int | None = None,
) -> tuple[FieldHuntStop, ...]:
    """Attach the current character output envelope to fixed fame stops.

    The fixed Circus, Mirror, and Lotus routes predate the source-ranked
    frontier and therefore cannot carry a state-specific action estimate on
    their own.  Preserve their source incoming bounds, but add the same
    audited opener and repeat-action metadata used by historical damage-window
    evidence.  GMCP target HP is retained for observation and reporting only.
    """
    result = tuple(stops)
    if not result or state is None:
        return result
    raw_level = character_level
    if raw_level is None:
        raw_level = state.get("level")
    try:
        effective_level = int(raw_level)
    except (TypeError, ValueError):
        return result
    if effective_level <= 0:
        return result

    bound: list[FieldHuntStop] = []
    for stop in result:
        if (
            not stop.require_damage_window_probe
            or stop.source_combat_action is not None
        ):
            bound.append(stop)
            continue
        output = _source_ranked_caster_output_for_state(
            state,
            character_level=effective_level,
            source_world=source_world,
            target_body_form_flags=stop.source_target_body_form_flags,
        )
        output = _source_ranked_output_for_target(
            output,
            target_mobile_vnum=stop.source_mobile_vnum,
            source_world=source_world,
        )
        if output is None:
            bound.append(stop)
            continue
        source_target_hp_ceiling = stop.source_target_hp_ceiling
        if (
            source_target_hp_ceiling is None
            and source_world is not None
            and stop.source_mobile_vnum is not None
        ):
            mobile = source_world.mobiles.get(stop.source_mobile_vnum)
            if mobile is not None:
                _, source_target_hp_ceiling = _mobile_base_hp_range(
                    _mobile_level_range(mobile.level),
                    rank=mobile.rank,
                    hp_modifier=mobile.hp_modifier,
                )
        bound.append(
            replace(
                stop,
                source_combat_action=output.action,
                source_combat_min_damage=output.minimum_damage,
                source_combat_expected_damage=output.expected_damage,
                source_combat_conservative_damage=output.conservative_damage,
                source_combat_max_actions=output.maximum_actions,
                source_combat_reference=output.source_reference,
                source_combat_opening_action=output.opening_action,
                source_combat_opening_min_damage=output.opening_min_damage,
                source_combat_opening_expected_damage=(
                    output.opening_expected_damage
                ),
                source_combat_opening_conservative_damage=(
                    output.opening_conservative_damage
                ),
                source_combat_opening_max_damage=output.opening_max_damage,
                source_combat_opening_reference=(
                    output.opening_source_reference
                ),
                source_target_hp_ceiling=source_target_hp_ceiling,
            )
        )
    return tuple(bound)


async def _run_policy_segment(
    spec: CharacterSpec,
    profile_path: Path,
    policy: ProgressionPolicy,
    *,
    current_state: Mapping[str, Any] | None = None,
    gear_catalog: GearCatalog | None = None,
    source_world: WorldSource | None = None,
    character_level: int | None = None,
    practice_types_spent: frozenset[str] = frozenset(),
    deferred_practice_types: frozenset[str] = frozenset(),
    rejected_practice_skills: frozenset[str] = frozenset(),
    pounding_weapon_required: bool = False,
    counterbalance_preparation_required: bool = False,
    vault_stow_items: tuple[str, ...] = (),
    vault_claim_items: tuple[str, ...] = (),
    fastwalk_skip_target_sightings: frozenset[tuple[str, str]] = frozenset(),
    provision_funding_candidate: HuntCandidate | None = None,
    source_ranked_hunt_candidate: HuntCandidate | None = None,
    source_ranked_hunt_circuit: tuple[HuntCandidate, ...] = (),
    source_consumable_candidate: HuntCandidate | None = None,
    source_consumable_object_vnums: tuple[int, ...] = (),
    source_consumable_spell: str | None = None,
    source_resource_reserve: Mapping[str, Any] | None = None,
    verified_source_resources: Mapping[str, Any] | None = None,
    source_food_candidate: HuntCandidate | None = None,
    source_flight_candidate: HuntCandidate | None = None,
    source_flight_placement: ResourcePlacement | None = None,
    source_resource_placement: ResourcePlacement | None = None,
    source_gear_placement: GearSourcePlacement | None = None,
    source_gear_candidate: HuntCandidate | None = None,
    money_container_keyword: str | None = None,
    reacquire_flight_before_route: bool = False,
    emergency_provision_sale: bool = False,
    force_training_reaudit: bool = False,
    sanctuary_deep_route_revalidation_started: bool = False,
    source_ranked_consider_revalidation_policy_id: str | None = None,
    active_starter_runner_sink: Callable[[StarterBotRunner], None] | None = None,
    progress_callback: Callable[[str], None] | None = None,
) -> RunResult:
    _check_campaign_preparation_deadline()

    def report_preparation(stage: str) -> None:
        if progress_callback is not None:
            progress_callback(
                f"Segment preparation: {stage}; no live connection opened."
            )

    report_preparation("assembling policy-specific runner inputs")
    if (
        policy.execution == "source-ranked-hunt"
        and isinstance(current_state, dict)
        and source_ranked_hunt_candidate is not None
    ):
        retry_marker = current_state.get(
            _SOURCE_RANKED_ARMED_TRANSIT_ROUTE_RETRY_KEY
        )
        retry_level = character_level or source_ranked_hunt_candidate.level
        retry_policy_id = _source_ranked_policy_id(
            source_ranked_hunt_candidate,
            character_level=retry_level,
        )
        if (
            isinstance(retry_marker, Mapping)
            and retry_marker.get("policy_id") == retry_policy_id
            and retry_marker.get("boot_id") == current_state.get("world_boot_id")
            and retry_marker.get("level") in {None, retry_level}
            and retry_marker.get("status") == "attempted"
        ):
            # Preparation segments may be split from the hunt by the outer
            # campaign budget. Mark the retry consumed only when the target
            # policy itself is actually about to open its live worker.
            current_state[_SOURCE_RANKED_ARMED_TRANSIT_ROUTE_RETRY_KEY] = {
                **dict(retry_marker),
                "target_dispatch_started": True,
            }
        protection_retry_marker = current_state.get(
            _SOURCE_RANKED_PROTECTION_RETRY_REVALIDATION_KEY
        )
        if (
            isinstance(protection_retry_marker, Mapping)
            and protection_retry_marker.get("policy_id") == retry_policy_id
            and protection_retry_marker.get("boot_id")
            == current_state.get("world_boot_id")
            and protection_retry_marker.get("level") in {None, retry_level}
            and protection_retry_marker.get("status") == "attempted"
        ):
            # Preparation may occupy one or more safe segments before the
            # exact target worker opens. Consume the protected retry only at
            # the live hunt boundary, so a potion or funding segment cannot
            # strand the target behind an already-attempted marker.
            current_state[_SOURCE_RANKED_PROTECTION_RETRY_REVALIDATION_KEY] = {
                **dict(protection_retry_marker),
                "target_dispatch_started": True,
            }
        absence_retry_marker = current_state.get(
            _SOURCE_RANKED_CURRENT_BAND_ABSENCE_RETRY_KEY
        )
        if (
            isinstance(absence_retry_marker, Mapping)
            and absence_retry_marker.get("policy_id") == retry_policy_id
            and absence_retry_marker.get("boot_id")
            == current_state.get("world_boot_id")
            and absence_retry_marker.get("level") in {None, retry_level}
            and absence_retry_marker.get("status") == "attempted"
        ):
            # Preparation segments may be split from the hunt by the outer
            # campaign budget. Record that the exact source target is about
            # to open its live worker; this is provenance, not a one-shot
            # consumption gate.
            current_state[_SOURCE_RANKED_CURRENT_BAND_ABSENCE_RETRY_KEY] = {
                **dict(absence_retry_marker),
                "target_dispatch_started": True,
            }
            _record_source_ranked_current_band_absence_retry_dispatch(
                current_state
            )
        identity_retry_marker = current_state.get(
            _SOURCE_RANKED_ROUTE_IDENTITY_REVALIDATION_KEY
        )
        if (
            isinstance(identity_retry_marker, Mapping)
            and identity_retry_marker.get("policy_id") == retry_policy_id
            and identity_retry_marker.get("boot_id")
            == current_state.get("world_boot_id")
            and identity_retry_marker.get("level") in {None, retry_level}
            and identity_retry_marker.get("status") == "attempted"
        ):
            # Preparation may span several bounded segments. Consume this
            # repair only when the exact source hunt opens its worker.
            current_state[_SOURCE_RANKED_ROUTE_IDENTITY_REVALIDATION_KEY] = {
                **dict(identity_retry_marker),
                "target_dispatch_started": True,
            }
        armed_preflight_retry_marker = current_state.get(
            _SOURCE_RANKED_MRINTHAS_ARMED_PREFLIGHT_REVALIDATION_KEY
        )
        if (
            isinstance(armed_preflight_retry_marker, Mapping)
            and armed_preflight_retry_marker.get("policy_id") == retry_policy_id
            and armed_preflight_retry_marker.get("boot_id")
            == current_state.get("world_boot_id")
            and armed_preflight_retry_marker.get("level")
            in {None, retry_level}
            and armed_preflight_retry_marker.get("status") == "attempted"
        ):
            # Preparation may span several bounded segments. Consume this
            # route-controller repair only when the exact hunt opens its
            # live worker.
            current_state[
                _SOURCE_RANKED_MRINTHAS_ARMED_PREFLIGHT_REVALIDATION_KEY
            ] = {
                **dict(armed_preflight_retry_marker),
                "target_dispatch_started": True,
            }
        handoff_retry_marker = current_state.get(
            _SOURCE_RANKED_MRINTHAS_ROUTE_HANDOFF_REVALIDATION_KEY
        )
        if (
            isinstance(handoff_retry_marker, Mapping)
            and handoff_retry_marker.get("policy_id") == retry_policy_id
            and handoff_retry_marker.get("boot_id")
            == current_state.get("world_boot_id")
            and handoff_retry_marker.get("level") in {None, retry_level}
            and handoff_retry_marker.get("status") == "attempted"
        ):
            # Consume the final controller repair only when the exact target
            # worker opens. Preparation may span separate bounded segments.
            current_state[
                _SOURCE_RANKED_MRINTHAS_ROUTE_HANDOFF_REVALIDATION_KEY
            ] = {
                **dict(handoff_retry_marker),
                "target_dispatch_started": True,
            }
        sentinel_risk_marker = current_state.get(
            _SOURCE_RANKED_PLAIN_SENTINEL_RISK_REVALIDATION_KEY
        )
        if (
            isinstance(sentinel_risk_marker, Mapping)
            and sentinel_risk_marker.get("policy_id") == retry_policy_id
            and sentinel_risk_marker.get("boot_id")
            == current_state.get("world_boot_id")
            and sentinel_risk_marker.get("level") in {None, retry_level}
            and sentinel_risk_marker.get("status") == "attempted"
        ):
            # Consume the direct-risk receipt only when the exact target
            # worker opens. Preparation may occupy an earlier segment.
            current_state[
                _SOURCE_RANKED_PLAIN_SENTINEL_RISK_REVALIDATION_KEY
            ] = {
                **dict(sentinel_risk_marker),
                "target_dispatch_started": True,
            }
        preparation_marker = current_state.get(
            _SOURCE_RANKED_PREPARATION_ABORT_REVALIDATION_KEY
        )
        if (
            isinstance(preparation_marker, Mapping)
            and preparation_marker.get("policy_id") == retry_policy_id
            and preparation_marker.get("boot_id")
            == current_state.get("world_boot_id")
            and preparation_marker.get("level") in {None, retry_level}
            and preparation_marker.get("status") == "attempted"
            and current_state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY)
            == retry_policy_id
        ):
            # This is the one consumed preparation repair selected by the
            # preceding policy pass. Mark its live dispatch window so route
            # construction can omit the unavailable generic invisibility
            # prerequisite without making the repair reusable later.
            current_state[_SOURCE_RANKED_PREPARATION_ABORT_REVALIDATION_KEY] = {
                **dict(preparation_marker),
                "target_dispatch_started": True,
            }
        wanderer_marker = current_state.get(
            _SOURCE_RANKED_WANDERER_NO_INVIS_REVALIDATION_KEY
        )
        if (
            isinstance(wanderer_marker, Mapping)
            and wanderer_marker.get("policy_id") == retry_policy_id
            and wanderer_marker.get("boot_id")
            == current_state.get("world_boot_id")
            and wanderer_marker.get("level") in {None, retry_level}
            and wanderer_marker.get("status") == "attempted"
            and current_state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY)
            == retry_policy_id
        ):
            current_state[_SOURCE_RANKED_WANDERER_NO_INVIS_REVALIDATION_KEY] = {
                **dict(wanderer_marker),
                "target_dispatch_started": True,
            }
        frontier_risk_marker = current_state.get(
            _SOURCE_RANKED_FRONTIER_RISK_REVALIDATION_KEY
        )
        if (
            isinstance(frontier_risk_marker, Mapping)
            and frontier_risk_marker.get("policy_id") == retry_policy_id
            and frontier_risk_marker.get("boot_id")
            == current_state.get("world_boot_id")
            and frontier_risk_marker.get("level") in {None, retry_level}
            and frontier_risk_marker.get("source_revision")
            == current_state.get(_SOURCE_REVISION_KEY)
            and frontier_risk_marker.get("status") == "pending"
        ):
            # This is a one-shot risk receipt. Consume it before opening the
            # live worker so an interrupted segment cannot replay the same
            # stale frontier result.
            current_state[_SOURCE_RANKED_FRONTIER_RISK_REVALIDATION_KEY] = {
                **dict(frontier_risk_marker),
                "status": "attempted",
                "attempted_before_dispatch": True,
                "target_dispatch_started": True,
                "attempted_at": datetime.now(timezone.utc).isoformat(),
            }
        stale_consider_marker = current_state.get(
            _SOURCE_RANKED_STALE_CONSIDER_REVALIDATION_KEY
        )
        if (
            isinstance(stale_consider_marker, Mapping)
            and stale_consider_marker.get("policy_id") == retry_policy_id
            and stale_consider_marker.get("boot_id")
            == current_state.get("world_boot_id")
            and stale_consider_marker.get("level") in {None, retry_level}
            and stale_consider_marker.get("source_revision")
            == current_state.get(_SOURCE_REVISION_KEY)
            and stale_consider_marker.get("status") == "pending"
        ):
            # Consume this one live consider recheck before opening the
            # worker; a repeated negative result remains durable evidence.
            current_state[_SOURCE_RANKED_STALE_CONSIDER_REVALIDATION_KEY] = {
                **dict(stale_consider_marker),
                "status": "attempted",
                "attempted_before_dispatch": True,
                "target_dispatch_started": True,
                "attempted_at": datetime.now(timezone.utc).isoformat(),
            }
            _record_source_ranked_stale_consider_revalidation(current_state)

    def quest_phase_planner(completed: str, state: Mapping[str, Any]) -> QuestPhase | None:
        world = source_world or load_world_source(
            current_source_directory(), include_all_areas=True,
        )
        return _quest_session_next_phase(
            completed, state, world=world, gear_catalog=gear_catalog, character=spec,
        )

    def starter_runner(**kwargs: Any) -> StarterBotRunner:
        # Only indexed recovery and training receipts need the compact summary;
        # ordinary live segments must keep their exact runner contract.
        if (
            kwargs.get("world_time_probe") is True
            or kwargs.get("deity_protection_probe") is True
            or kwargs.get("training_only") is True
        ):
            kwargs.setdefault("compact_run_summary", True)
        if (
            kwargs.get("flight_borrowing") is True
            and current_state is not None
        ):
            borrow_amount = current_state.get(_FLIGHT_BORROW_AMOUNT_KEY)
            borrow_boot = current_state.get(_FLIGHT_BORROW_AMOUNT_BOOT_KEY)
            if (
                isinstance(borrow_amount, int)
                and not isinstance(borrow_amount, bool)
                and 100 <= borrow_amount <= _FLIGHT_BORROW_MAX_COPPER
                and borrow_boot == current_state.get("world_boot_id")
            ):
                kwargs.setdefault("flight_borrow_amount_copper", borrow_amount)
        if (
            kwargs.get("return_home") is True
            and current_state is not None
            and source_world is not None
            and _VAMPIRE_CATACOMBS_KEY_OBJECT_VNUM
            in (
                _campaign_carried_route_key_object_vnums(
                    current_state,
                    source_world,
                )
                or ()
            )
        ):
            # A failed cache verification can leave a live checkpoint holding
            # the source key outside the healer. Carry the exact preservation
            # workflow into generic return-home so logout cannot delete it.
            kwargs.setdefault("fastwalk_world_cache_items", ("spiked",))
            kwargs.setdefault(
                "fastwalk_world_cache_object_vnums",
                (_VAMPIRE_CATACOMBS_KEY_OBJECT_VNUM,),
            )
        if kwargs.get("quest_phase") in {"quest-target-run", "quest-complete", "quest-digging-tool"}:
            quest_status = dict((current_state or {}).get("quest_status") or {})
            kwargs["quest_expected_status"] = quest_status
            excavation_checkpoint = (current_state or {}).get(
                "campaign_hoard_excavation_checkpoint"
            )
            if (
                snapshot_quest_status(quest_status).kind == "hoard"
                and excavation_checkpoint is not None
            ):
                kwargs["quest_hoard_excavation_checkpoint"] = (
                    excavation_checkpoint
                )
        if gear_catalog is not None:
            kwargs.setdefault("gear_catalog", gear_catalog)
        if source_world is not None:
            kwargs.setdefault("source_world", source_world)
        if current_state is not None:
            # The campaign checkpoint already proves that this is an
            # established character. The live runner starts with an empty
            # parser state, so pass the one-time setup receipt explicitly
            # instead of scanning the full command ledger on every segment.
            current_level = _level(current_state)
            if current_level is not None and current_level > 1:
                kwargs.setdefault("title_configured", True)
                kwargs.setdefault("description_configured", True)
            if current_state.get(_SOURCE_REVISION_KEY):
                kwargs.setdefault(
                    "source_revision",
                    str(current_state[_SOURCE_REVISION_KEY]),
                )
            inventory_source_hints = _campaign_inventory_source_hints_for_transition(
                current_state,
                current_state,
            )
            if inventory_source_hints:
                kwargs.setdefault(
                    "gear_inventory_source_hints",
                    dict(inventory_source_hints),
                )
            carried_primary_rearm_vnum = 0
            try:
                carried_primary_rearm_vnum = int(
                    current_state.get(_CARRIED_PRIMARY_REARM_VNUM_KEY)
                )
            except (TypeError, ValueError):
                pass
            if (
                policy.execution == "rearm-weapon"
                and carried_primary_rearm_vnum > 0
                and gear_catalog is not None
            ):
                carried_primary = gear_catalog.objects.get(
                    carried_primary_rearm_vnum
                )
                carried_inventory_names = {
                    _source_inventory_hint_name(description)
                    for description in _inventory_descriptions(
                        current_state.get("inventory")
                    )
                }
                carried_primary_name = (
                    _source_inventory_hint_name(
                        carried_primary.short_description
                    )
                    if carried_primary is not None
                    else ""
                )
                if (
                    carried_primary is not None
                    and carried_primary_name in carried_inventory_names
                ):
                    rearm_hints = dict(
                        kwargs.get("gear_inventory_source_hints") or {}
                    )
                    rearm_hints[carried_primary_name] = (
                        carried_primary.vnum
                    )
                    kwargs["gear_inventory_source_hints"] = rearm_hints
            raw_maxed_stats = current_state.get("campaign_maxed_stats")
            if isinstance(raw_maxed_stats, (list, tuple, set, frozenset)):
                kwargs.setdefault("maxed_stats", tuple(raw_maxed_stats))
            raw_training_stat = current_state.get(
                "campaign_selected_training_stat"
            )
            if isinstance(raw_training_stat, str):
                normalized_training_stat = raw_training_stat.casefold().strip()
                if normalized_training_stat in {"str", "int", "wis", "dex", "con"}:
                    kwargs.setdefault(
                        "selected_training_stat",
                        normalized_training_stat,
                    )
            if kwargs.get("liquidate_loot") is True:
                known_sale_rejections = _sale_rejections_for_boot(
                    current_state
                )
                if known_sale_rejections:
                    kwargs.setdefault(
                        "known_sale_rejections",
                        known_sale_rejections,
                    )
            raw_known_skills = current_state.get("campaign_known_skills")
            if isinstance(raw_known_skills, str):
                raw_known_skills = (raw_known_skills,)
            elif not isinstance(
                raw_known_skills,
                (list, tuple, set, frozenset),
            ):
                raw_known_skills = ()
            raw_known_skill_levels = current_state.get(
                "campaign_known_skill_levels"
            )
            if not isinstance(raw_known_skill_levels, Mapping):
                raw_known_skill_levels = {}
            kwargs.setdefault(
                "known_skills",
                tuple(raw_known_skills or ()),
            )
            kwargs.setdefault(
                "known_skill_levels",
                dict(raw_known_skill_levels),
            )
            training_audit = current_state.get(_TRAINING_AUDIT_KEY)
            current_level = _level(current_state)
            if (
                not force_training_reaudit
                and current_level is not None
                and not _source_ranked_training_reaudit_required(
                    current_state,
                    character_level=current_level,
                )
                and not _training_policy_revision_stale(current_state)
                and _training_audit_matches_scope(
                    current_state,
                    character_level=current_level,
                )
                and isinstance(training_audit, Mapping)
                and training_audit.get("boot_id")
                == current_state.get("world_boot_id")
                and current_state.get("world_boot_id")
            ):
                kwargs.setdefault("training_audit", dict(training_audit))
            try:
                counterbalanced_weapon_vnum = int(
                    current_state.get(_COUNTERBALANCED_WEAPON_VNUM_KEY)
                )
            except (TypeError, ValueError):
                counterbalanced_weapon_vnum = 0
            if counterbalanced_weapon_vnum > 0:
                kwargs.setdefault(
                    "counterbalanced_weapon_vnum",
                    counterbalanced_weapon_vnum,
                )
            try:
                chained_weapon_vnum = int(
                    current_state.get(_CHAINED_WEAPON_VNUM_KEY)
                )
            except (TypeError, ValueError):
                chained_weapon_vnum = 0
            if chained_weapon_vnum > 0:
                kwargs.setdefault(
                    "chained_weapon_vnum",
                    chained_weapon_vnum,
                )
            try:
                preserved_primary_weapon_vnum = int(
                    current_state.get(_PRESERVED_PRIMARY_WEAPON_VNUM_KEY)
                )
            except (TypeError, ValueError):
                preserved_primary_weapon_vnum = 0
            if preserved_primary_weapon_vnum > 0:
                carried_primary_rearm_command = None
                if (
                    policy.execution == "rearm-weapon"
                    and carried_primary_rearm_vnum > 0
                    and gear_catalog is not None
                ):
                    carried_primary = gear_catalog.objects.get(
                        carried_primary_rearm_vnum
                    )
                    carried_primary_name = (
                        _source_inventory_hint_name(
                            carried_primary.short_description
                        )
                        if carried_primary is not None
                        else ""
                    )
                    if carried_primary_name in {
                        _source_inventory_hint_name(description)
                        for description in _inventory_descriptions(
                            current_state.get("inventory")
                        )
                    }:
                        # The selector already proved the exact retained
                        # object.  The marker remains useful even when the
                        # older inventory-hint map was lost at a checkpoint.
                        carried_primary_rearm_command = "wield"
                if carried_primary_rearm_command is None:
                    carried_primary_rearm_command = (
                        _carried_primary_weapon_rearm_command(
                            current_state,
                            gear_catalog=gear_catalog,
                            character_class=spec.character_class,
                            subclass=_live_subclass(current_state),
                        )
                        if policy.execution == "rearm-weapon"
                        else None
                    )
                if carried_primary_rearm_command is None:
                    kwargs.setdefault(
                        "preserved_primary_weapon_vnum",
                        preserved_primary_weapon_vnum,
                    )
                else:
                    # A preserved route weapon is normally the safest source
                    # for the rearm controller.  When an exact inventory hint
                    # proves a better carried primary, however, seeding the
                    # preserved VNUM makes StarterPolicy prefer the old item
                    # and finish without issuing the carried-wield command.
                    # Let the live controller choose that verified upgrade;
                    # the campaign selector will then see it in the worn slot
                    # instead of repeating a no-op rearm segment.
                    kwargs.pop("preserved_primary_weapon_vnum", None)
            kwargs.setdefault(
                "verified_combat_pouch_potions",
                dict(
                    current_state.get("verified_combat_pouch_potions") or {}
                ),
            )
            kwargs.setdefault(
                "verified_source_resources",
                dict(current_state.get(_SOURCE_RESOURCE_RESERVES_KEY) or {}),
            )
        if source_resource_reserve is not None:
            kwargs.setdefault(
                "source_resource_reserve",
                dict(source_resource_reserve),
            )
        if verified_source_resources is not None:
            kwargs.setdefault(
                "verified_source_resources",
                dict(verified_source_resources),
            )
            if (
                kwargs.get("fastwalk_train_before_departure") is True
                and policy.execution != "training-deficit-repair"
                and not force_training_reaudit
                and _campaign_fastwalk_training_deferred_after_route_hazard(
                    current_state
                )
            ):
                # A current-level, current-reboot trainer-route hazard has
                # already been safely recorded. Continue progression without
                # replaying the hazardous distant training trip.
                kwargs["fastwalk_train_before_departure"] = False
        if fastwalk_skip_target_sightings:
            kwargs["fastwalk_skip_target_sightings"] = (
                fastwalk_skip_target_sightings
            )
        if source_ranked_consider_revalidation_policy_id is not None:
            kwargs["source_ranked_consider_revalidation_policy_id"] = (
                source_ranked_consider_revalidation_policy_id
            )
        # TARGETMODE IDs name live instances, not durable mobile identities.
        # StarterPolicy tracks them only within the connected encounter; never
        # seed a new runner from selectors saved by an earlier campaign segment.
        if deferred_practice_types:
            kwargs["deferred_practice_types"] = deferred_practice_types
        if (
            force_training_reaudit
            and kwargs.get("fastwalk_train_before_departure") is True
        ):
            kwargs["practice_types_spent"] = frozenset()
            kwargs["deferred_practice_types"] = frozenset()
            kwargs["rejected_practice_skills"] = frozenset()
        if pounding_weapon_required:
            kwargs["city_rearm_pounding"] = True
        if policy.policy_id == "compare-carried-weapon" and current_state is not None:
            kwargs["carried_weapon_comparison_request"] = dict(current_state[COMPARISON_KEY])
        if counterbalance_preparation_required:
            kwargs["counterbalance_preparation_required"] = True
        route = kwargs.get("fastwalk_route")
        if source_world is not None and isinstance(route, Fastwalk):
            raw_level = character_level
            if raw_level is None and current_state is not None:
                raw_level = current_state.get("level")
            try:
                dispatch_level = int(raw_level) if raw_level is not None else 0
            except (TypeError, ValueError):
                dispatch_level = 0
            if dispatch_level > 0:
                objective_vnums: set[int] = set()
                objective_targets: set[str] = set()
                requested_target = kwargs.get("fastwalk_attack_target")
                if requested_target:
                    objective_targets.add(str(requested_target))
                for stop in kwargs.get("fastwalk_hunt_stops") or ():
                    stop_target = getattr(stop, "target", None)
                    if stop_target:
                        objective_targets.add(str(stop_target))
                    stop_vnum = getattr(stop, "source_mobile_vnum", None)
                    try:
                        if stop_vnum is not None:
                            objective_vnums.add(int(stop_vnum))
                    except (TypeError, ValueError):
                        pass
                kwargs["fastwalk_route"] = _source_guard_fixed_fastwalk_route(
                    source_world,
                    route,
                    character_level=dispatch_level,
                    character_max_hp=(
                        int(current_state["max_hp"])
                        if current_state is not None
                        and isinstance(current_state.get("max_hp"), (int, float))
                        and not isinstance(current_state.get("max_hp"), bool)
                        and current_state["max_hp"] > 0
                        else None
                    ),
                    objective_mobile_vnums=objective_vnums,
                    objective_targets=objective_targets,
                )
        _check_campaign_preparation_deadline()
        if policy.execution == "provision-funding":
            kwargs.setdefault("policy_execution", policy.execution)
        report_preparation("constructing the MUD runner")
        runner = StarterBotRunner(spec, profile_path, **kwargs)
        if active_starter_runner_sink is not None:
            active_starter_runner_sink(runner)
        report_preparation("MUD runner constructed; starting the bounded session")
        _check_campaign_preparation_deadline()
        return runner

    if policy.execution in {"training-deficit-repair", "consumable-training-travel"}:
        # This maintenance policy is a fresh trainer audit even when the
        # caller's normal level ledger says both practice types were spent.
        force_training_reaudit = True
    if policy.execution == "starter":
        return await starter_runner().run()
    if policy.execution == "world-time-probe":
        city_observation = (current_state or {}).get(FIELD_CITY_OBSERVATION_KEY)
        city_route_rooms = (
            tuple(city_observation["route_rooms"])
            if isinstance(city_observation, Mapping) and city_observation.get("status") == "pending"
            else ()
        )
        return await starter_runner(
            return_home=True,
            world_time_probe=True,
            recheck_field_city_route_rooms=city_route_rooms,
            **({"recheck_city_shop_route": True}
               if (current_state or {}).get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY) else {}),
            require_fastwalk_kill=False,
            use_sanctuary_potions=False,
        ).run()
    if policy.execution == "deity-protection-probe":
        return await starter_runner(
            return_home=True,
            deity_protection_probe=True,
            require_fastwalk_kill=False,
            use_sanctuary_potions=False,
        ).run()
    if policy.execution == "training-deficit-repair":
        return await starter_runner(
            training_only=True,
            fastwalk_train_before_departure=True,
            require_fastwalk_kill=False,
            allow_safe_fastwalk_abort=True,
            use_sanctuary_potions=False,
            practice_types_spent=practice_types_spent,
            deferred_practice_types=deferred_practice_types,
            rejected_practice_skills=rejected_practice_skills,
        ).run()
    if policy.execution == "consumable-training-travel":
        trip = plan_training_travel(
            source_world, current_state or {}, spec.character_class,
            carried_descriptions=_inventory_descriptions((current_state or {}).get("inventory")),
            ignore_attempt=True,
        )
        if trip is None:
            raise RuntimeError("consumable teacher journey has no current source-audited plan")
        return await starter_runner(
            training_only=True, training_travel=trip, fastwalk_train_before_departure=True,
            require_fastwalk_kill=False, allow_safe_fastwalk_abort=True,
            use_sanctuary_potions=False,
        ).run()
    if policy.execution == "training-travel-supply":
        world = source_world or load_world_source(
            current_source_directory(), include_all_areas=True,
        )
        supply = training_travel_supply(
            world, current_state or {}, spec.character_class,
            carried_descriptions=_inventory_descriptions((current_state or {}).get("inventory")),
            ignore_attempt=True,
        )
        if supply is None:
            raise RuntimeError("training travel supply has no current source-audited purchase")
        route = Fastwalk(
            name=f"training travel supply {supply.purchase.object_vnum}",
            minimum_level=20, maximum_level=29,
            notation=_funding_route_notation(supply.commands), recall_after_loot=True,
        )
        stop = FieldHuntStop(
            (), None, source_purchase=supply.purchase,
            required_items=(supply.purchase.description,),
            source_policy_id=policy.policy_id,
        )
        return await starter_runner(
            objective_level=100, fastwalk_route=route,
            fastwalk_hunt_stops=(stop,), fastwalk_required_move=supply.required_move,
            fastwalk_origin_actions=("drink skin",), require_fastwalk_kill=False,
            allow_safe_fastwalk_abort=True, use_sanctuary_potions=False,
        ).run()
    if policy.execution == "source-invisibility-supply":
        world = source_world or load_world_source(
            current_source_directory(), include_all_areas=True,
        )
        supply = route_invisibility_supply(
            world,
            current_state or {},
            carried_descriptions=_inventory_descriptions(
                (current_state or {}).get("inventory")
            ),
            ignore_attempt=True,
        )
        if supply is None:
            raise RuntimeError(
                "route invisibility supply has no current source-audited purchase"
            )
        route = Fastwalk(
            name=f"route invisibility supply {supply.purchase.object_vnum}",
            minimum_level=2,
            maximum_level=100,
            notation=_funding_route_notation(supply.commands),
            recall_after_loot=True,
        )
        stop = FieldHuntStop(
            (),
            None,
            required_items=(supply.purchase.description,),
            source_purchase=supply.purchase,
            source_policy_id=policy.policy_id,
        )
        return await starter_runner(
            objective_level=100,
            fastwalk_route=route,
            fastwalk_hunt_stops=(stop,),
            magic_shop_buy_invisibility=True,
            magic_shop_invisibility_quantity=supply.purchase.quantity,
            fastwalk_origin_actions=("drink skin",),
            fastwalk_required_move=supply.required_move,
            fastwalk_train_before_departure=False,
            fastwalk_require_invisibility=False,
            require_fastwalk_kill=False,
            allow_safe_fastwalk_abort=True,
            use_sanctuary_potions=False,
        ).run()
    if policy.execution == "arena":
        return await starter_runner(
            objective_level=policy.maximum_level or 10,
            arena_kill_limit=policy.segment_kill_limit,
            arena_respawn_wait=False,
            practice_types_spent=practice_types_spent,
            rejected_practice_skills=rejected_practice_skills,
        ).run()
    if policy.execution == "return-home":
        return_home_kwargs: dict[str, Any] = {
            "return_home": True,
            "emergency_provision_sale": emergency_provision_sale,
        }
        if (
            current_state is not None
            and _source_ranked_locator_rebase_full_recovery_required(current_state)
        ):
            return_home_kwargs["require_full_healer_recovery"] = True
        preserved_return_commands = _source_ranked_preserved_return_commands(
            current_state
        )
        if preserved_return_commands is not None:
            return_home_kwargs[
                "preserved_return_commands"
            ] = preserved_return_commands
        if current_state is not None and (
            "combat_pouch_potions" in current_state
            or "verified_combat_pouch_potions" in current_state
        ):
            return_home_kwargs["audit_combat_pouch"] = True
        return await starter_runner(
            **return_home_kwargs,
        ).run()
    if policy.execution == "audit-combat-pouch":
        return await starter_runner(
            combat_pouch_repack=True,
            require_fastwalk_kill=False,
        ).run()
    if policy.execution == "empty-money-container":
        return await starter_runner(
            return_home=True,
            extract_money_container=True,
            money_container_keyword=money_container_keyword,
            require_fastwalk_kill=False,
        ).run()
    if policy.execution == "choose-subclass":
        if not spec.subclass:
            raise RuntimeError(
                "choose-subclass policy requires a requested subclass"
            )
        change_keyword = load_character_catalog().subclass_change_keyword(
            spec.subclass
        )
        subclass_preparation: dict[str, Any] = {}
        if current_state is not None and source_world is not None:
            teacher = source_subclass_teacher_route(
                source_world,
                spec.subclass,
                character_class=spec.character.character_class,
                preferred_mobile_vnums=(31002,)
                if spec.character.character_class.casefold() == "smithy"
                else (),
            )
            if teacher is not None:
                teacher_rooms = (
                    int(teacher.steps[0][0]),
                    *(int(step[2]) for step in teacher.steps),
                ) if teacher.steps else (3001, teacher.room_vnum)
                if (
                    source_route_requires_water_breathing(
                        source_world,
                        teacher_rooms,
                    )
                    and not can_breathe_underwater(current_state)
                ):
                    # The subclass controller owns the teacher route, but the
                    # Magic Shop controller owns the live water-breathing
                    # purchase and affect verification. Let it finish before
                    # handing control back to subclass travel.
                    subclass_preparation.update(
                        {
                            "magic_shop_research": True,
                            "magic_shop_buy_water_breathing": True,
                            "magic_shop_continue_to_fastwalk": True,
                        }
                    )
        return await starter_runner(
            subclass_selection=True,
            subclass_change_keyword=change_keyword,
            **subclass_preparation,
        ).run()
    if policy.execution == "recall-list-audit":
        return await starter_runner(
            recall_list_research=True,
        ).run()
    if policy.execution == "recall-point-acquire":
        level = character_level or int(
            (current_state or {}).get("level") or policy.minimum_level
        )
