def _source_ranked_mrinthas_guard_route_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
    state: Mapping[str, Any] | None = None,
    character_max_hp: int | None = None,
) -> bool:
    """Admit the exact M'rinthas ``spec_guard`` route as a bounded risk.

    The endpoint is not an XP target merely because its special is understood:
    the endpoint still goes through the normal live consider, identity, crowd,
    output, health, and return checks. This helper only proves the source
    shape and the one armed transit interruption that the route can expose.
    """
    if (
        source_world is None
        or character_level not in {39, 40, 41}
        or candidate.area_file.casefold() != "mrinthas.are"
        or candidate.mobile_vnum != _SOURCE_MRINTHAS_GUARD_TARGET_MOBILE_VNUM
        or candidate.room_vnum not in _SOURCE_MRINTHAS_GUARD_TARGET_ROOM_VNUMS
        or candidate.route_origin_room_vnum != RECALL_VNUM
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or tuple(candidate.specials) != ("spec_guard",)
        or candidate.equipped_weapons != ("a spear",)
        or candidate.source_spawn_limit != 15
        or candidate.room_spawn_count != 1
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
        or frozenset(candidate.autonomy_rejections)
        not in _SOURCE_MRINTHAS_GUARD_ROUTE_REJECTION_PROFILES
        or candidate.estimated_level_range != (33, 37)
        or _source_ranked_xp_loss_record(
            state or {},
            _source_ranked_policy_id(candidate, character_level=character_level),
        ) is not None
    ):
        return False
    endpoint = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        endpoint is None
        or endpoint.aggressive
        or endpoint.wanders
        or not endpoint.sentinel
        or endpoint.programs
        or endpoint.attack_programs
        or endpoint.fear_aura
        or endpoint.non_corporeal
        or endpoint.costs_fame
        or source_world.mobile_specials.get(endpoint.vnum) != ("spec_guard",)
        or endpoint.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
    ):
        return False
    endpoint_resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
        and reset.room_vnum == candidate.room_vnum
    )
    if not (
        len(endpoint_resets) == 1
        and endpoint_resets[0].maximum_count == 15
        and endpoint_resets[0].equipment
    ):
        return False
    route_rooms = _source_route_room_vnums(
        source_world,
        candidate.route_origin_room_vnum,
        candidate.route,
    )
    if not route_rooms or route_rooms[-1] != candidate.room_vnum:
        return False
    if _SOURCE_MRINTHAS_GUARD_ROUTE_AGGRESSOR_VNUM not in set(
        candidate.route_aggressive_mobile_vnums
    ):
        return False
    for raw_vnum in candidate.route_aggressive_mobile_vnums:
        try:
            mobile_vnum = int(raw_vnum)
        except (TypeError, ValueError):
            return False
        if mobile_vnum == _SOURCE_MRINTHAS_GUARD_ROUTE_AGGRESSOR_VNUM:
            continue
        mobile = source_world.mobiles.get(mobile_vnum)
        if (
            mobile is None
            or not source_mobile_route_aggressor_is_bounded(
                source_world,
                mobile,
                character_level=character_level,
                character_max_hp=character_max_hp
                or (
                    int(state["max_hp"])
                    if isinstance(state, Mapping)
                    and isinstance(state.get("max_hp"), (int, float))
                    and state.get("max_hp", 0) > 0
                    else None
                ),
            )
        ):
            return False
    transit = source_world.mobiles.get(
        _SOURCE_MRINTHAS_GUARD_ROUTE_AGGRESSOR_VNUM
    )
    transit_resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == _SOURCE_MRINTHAS_GUARD_ROUTE_AGGRESSOR_VNUM
    )
    if (
        transit is None
        or not transit.aggressive
        or not transit.wanders
        or transit.programs
        or transit.attack_programs
        or transit.fear_aura
        or transit.non_corporeal
        or transit.costs_fame
        or source_world.mobile_specials.get(transit.vnum)
        or transit.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
        or not transit.hp_modifier_known
        or not transit.damage_modifier_known
        or _mobile_level_range(transit.level)[1] != 38
        or len(transit_resets) != 1
        or transit_resets[0].room_vnum != 13014
        or transit_resets[0].maximum_count != 1
        or not transit_resets[0].equipment
        or not any(
            wear_location == WEAR_WIELD and object_vnum == 13003
            for wear_location, object_vnum in transit_resets[0].equipment
        )
    ):
        return False
    effective_max_hp = character_max_hp
    if effective_max_hp is None and isinstance(state, Mapping):
        raw_max_hp = state.get("max_hp")
        if isinstance(raw_max_hp, (int, float)) and raw_max_hp > 0:
            effective_max_hp = int(raw_max_hp)
    if effective_max_hp is not None and effective_max_hp <= 0:
        return False
    if effective_max_hp is not None:
        health_floor = (effective_max_hp + 4) // 5
        if (
            mobile_sanctuary_peak_round_damage(
                _mobile_level_range(transit.level)[1],
                wielding=True,
                dual_wielding=False,
                damage_modifier=transit.damage_modifier,
            )
            + mobile_sanctuary_critical_hit_damage(
                _mobile_level_range(transit.level)[1],
                wielding=True,
                damage_modifier=transit.damage_modifier,
            )
            + health_floor
            > effective_max_hp
        ):
            return False
    if isinstance(state, Mapping):
        if state.get("level") not in {None, character_level}:
            return False
        if not _state_has_sanctuary_reserve(state):
            return False
        raw_hp = state.get("hp")
        if (
            not isinstance(raw_hp, (int, float))
            or raw_hp < effective_max_hp * 0.95
        ):
            return False
        if _source_ranked_route_contains_current_loss(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
            route_room_vnums=set(route_rooms),
        ):
            return False
        result = _campaign_research_results(state).get(
            _source_ranked_policy_id(candidate, character_level=character_level)
        )
        if isinstance(result, Mapping) and not (
            result.get("completed_kill") is True
            and result.get("viable") is True
        ) and not _source_ranked_mrinthas_armed_preflight_revalidation_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=effective_max_hp,
            source_world=source_world,
        ) and not _source_ranked_mrinthas_route_handoff_revalidation_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=effective_max_hp,
            source_world=source_world,
        ):
            return False
    return True


def _source_ranked_mrinthas_route_identity_revalidation_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Allow one exact retry after the M'rinthas name-alias route bug.

    The failed segment reached a room containing the intended endpoint, but
    the route-hazard parser treated its shared display name as the armed
    transit mobile. Reopen only that exact no-combat result after the source
    route and Sanctuary envelope pass again; any loss, crowd, or real target
    failure remains terminal for this policy.
    """
    if (
        source_world is None
        or character_level != 39
        or character_max_hp is None
        or character_max_hp <= 0
        or state.get("level") not in {None, character_level}
        or not _state_has_sanctuary_reserve(state)
    ):
        return False
    raw_hp = state.get("hp")
    if (
        not isinstance(raw_hp, (int, float))
        or raw_hp < character_max_hp * 0.95
    ):
        return False
    if not _source_ranked_mrinthas_guard_route_allowed(
        candidate,
        character_level=character_level,
        source_world=source_world,
        state=None,
        character_max_hp=character_max_hp,
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if (
        _source_ranked_xp_loss_record(state, policy_id) is not None
        or _source_ranked_prior_level_loss_record(
            state,
            policy_id,
            character_level=character_level,
        ) is not None
    ):
        return False
    boot_id = state.get("world_boot_id")
    marker = state.get(_SOURCE_RANKED_ROUTE_IDENTITY_REVALIDATION_KEY)
    if isinstance(marker, Mapping) and marker.get("boot_id") == boot_id:
        if marker.get("policy_id") != policy_id:
            return False
        if (
            marker.get("policy_revision")
            != _SOURCE_RANKED_ROUTE_IDENTITY_REVALIDATION_REVISION
            or marker.get("level") not in {None, character_level}
            or marker.get("source_revision") != state.get(_SOURCE_REVISION_KEY)
            or marker.get("status") in {"closed", "succeeded"}
            or marker.get("target_dispatch_started") is True
        ):
            return False
    result = _campaign_research_results(state).get(policy_id)
    return bool(
        isinstance(result, Mapping)
        and result.get("boot_id") == boot_id
        and result.get("observed") is False
        and result.get("viable") is False
        and result.get("route_hazard") == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
        and not any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "crowd_exhausted",
                "fatal_failure",
                "completed_kill",
                "xp_loss_observed",
                "unattackable",
                "target_vnum_mismatch",
                "consider_viable",
            )
        )
    )


def _source_ranked_mrinthas_armed_preflight_revalidation_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Allow one exact armed-preflight repair after identity repair is spent.

    The first VNUM-aware retry reached the route's ``where`` check, but the
    controller still used the generic route-hazard exit. Reopen only that
    exact no-combat result so the source-audited Sanctuary transit contract
    can actually run once.
    """
    if (
        source_world is None
        or character_level != 39
        or character_max_hp is None
        or character_max_hp <= 0
        or state.get("level") not in {None, character_level}
        or not _state_has_sanctuary_reserve(state)
    ):
        return False
    raw_hp = state.get("hp")
    if (
        not isinstance(raw_hp, (int, float))
        or raw_hp < character_max_hp * 0.95
    ):
        return False
    if not _source_ranked_mrinthas_guard_route_allowed(
        candidate,
        character_level=character_level,
        source_world=source_world,
        state=None,
        character_max_hp=character_max_hp,
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if (
        _source_ranked_xp_loss_record(state, policy_id) is not None
        or _source_ranked_prior_level_loss_record(
            state,
            policy_id,
            character_level=character_level,
        ) is not None
    ):
        return False
    boot_id = state.get("world_boot_id")
    identity_marker = state.get(
        _SOURCE_RANKED_ROUTE_IDENTITY_REVALIDATION_KEY
    )
    if not (
        isinstance(identity_marker, Mapping)
        and identity_marker.get("policy_id") == policy_id
        and identity_marker.get("boot_id") == boot_id
        and identity_marker.get("level") in {None, character_level}
        and identity_marker.get("policy_revision")
        == _SOURCE_RANKED_ROUTE_IDENTITY_REVALIDATION_REVISION
        and identity_marker.get("status") == "attempted"
        and identity_marker.get("target_dispatch_started") is True
    ):
        return False
    marker = state.get(
        _SOURCE_RANKED_MRINTHAS_ARMED_PREFLIGHT_REVALIDATION_KEY
    )
    if isinstance(marker, Mapping) and marker.get("boot_id") == boot_id:
        if (
            marker.get("policy_id") != policy_id
            or marker.get("level") not in {None, character_level}
            or marker.get("source_revision") != state.get(_SOURCE_REVISION_KEY)
            or marker.get("policy_revision")
            != _SOURCE_RANKED_MRINTHAS_ARMED_PREFLIGHT_REVALIDATION_REVISION
            or marker.get("status") in {"closed", "succeeded"}
            or marker.get("target_dispatch_started") is True
        ):
            return False
    result = _campaign_research_results(state).get(policy_id)
    route_hazard = str(result.get("route_hazard") or "") if isinstance(
        result, Mapping
    ) else ""
    route_hazard_matches = bool(
        (
            route_hazard.startswith(
                _SOURCE_MRINTHAS_GUARD_PREFLIGHT_HAZARD_PREFIX
            )
            and route_hazard.endswith(
                _SOURCE_MRINTHAS_GUARD_PREFLIGHT_HAZARD_SUFFIX
            )
        )
        or route_hazard == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
    )
    return bool(
        isinstance(result, Mapping)
        and result.get("boot_id") == boot_id
        and result.get("observed") is False
        and result.get("viable") is False
        and route_hazard_matches
        and not any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "crowd_exhausted",
                "fatal_failure",
                "completed_kill",
                "xp_loss_observed",
                "unattackable",
                "target_vnum_mismatch",
                "consider_viable",
            )
        )
    )


def _source_ranked_mrinthas_route_handoff_revalidation_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Allow one repair after the armed route metadata was lost at handoff.

    The preceding exact retry reached the M'rinthas preflight, but the live
    worker consumed its receipt before constructing the route options. The
    resulting no-combat stop is eligible for one controller repair only; a
    combat result, loss, crowd, or target failure remains closed.
    """
    if (
        source_world is None
        or character_level != 39
        or character_max_hp is None
        or character_max_hp <= 0
        or state.get("level") not in {None, character_level}
        or not _state_has_sanctuary_reserve(state)
    ):
        return False
    raw_hp = state.get("hp")
    if (
        not isinstance(raw_hp, (int, float))
        or raw_hp < character_max_hp * 0.95
    ):
        return False
    if not _source_ranked_mrinthas_guard_route_allowed(
        candidate,
        character_level=character_level,
        source_world=source_world,
        state=None,
        character_max_hp=character_max_hp,
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if (
        _source_ranked_xp_loss_record(state, policy_id) is not None
        or _source_ranked_prior_level_loss_record(
            state,
            policy_id,
            character_level=character_level,
        ) is not None
    ):
        return False
    boot_id = state.get("world_boot_id")
    source_revision = state.get(_SOURCE_REVISION_KEY)
    identity_marker = state.get(
        _SOURCE_RANKED_ROUTE_IDENTITY_REVALIDATION_KEY
    )
    if not (
        isinstance(identity_marker, Mapping)
        and identity_marker.get("policy_id") == policy_id
        and identity_marker.get("boot_id") == boot_id
        and identity_marker.get("level") in {None, character_level}
        and identity_marker.get("source_revision") == source_revision
        and identity_marker.get("policy_revision")
        == _SOURCE_RANKED_ROUTE_IDENTITY_REVALIDATION_REVISION
        and identity_marker.get("status") == "attempted"
        and identity_marker.get("target_dispatch_started") is True
    ):
        return False
    armed_marker = state.get(
        _SOURCE_RANKED_MRINTHAS_ARMED_PREFLIGHT_REVALIDATION_KEY
    )
    if not (
        isinstance(armed_marker, Mapping)
        and armed_marker.get("policy_id") == policy_id
        and armed_marker.get("boot_id") == boot_id
        and armed_marker.get("level") in {None, character_level}
        and armed_marker.get("source_revision") == source_revision
        and armed_marker.get("policy_revision")
        == _SOURCE_RANKED_MRINTHAS_ARMED_PREFLIGHT_REVALIDATION_REVISION
        and armed_marker.get("status") == "attempted"
        and armed_marker.get("target_dispatch_started") is True
    ):
        return False
    handoff_marker = state.get(
        _SOURCE_RANKED_MRINTHAS_ROUTE_HANDOFF_REVALIDATION_KEY
    )
    if isinstance(handoff_marker, Mapping) and handoff_marker.get("boot_id") == boot_id:
        if (
            handoff_marker.get("policy_id") != policy_id
            or handoff_marker.get("level") not in {None, character_level}
            or handoff_marker.get("source_revision") != source_revision
            or handoff_marker.get("policy_revision")
            != _SOURCE_RANKED_MRINTHAS_ROUTE_HANDOFF_REVALIDATION_REVISION
            or handoff_marker.get("status") in {"closed", "succeeded"}
            or handoff_marker.get("target_dispatch_started") is True
        ):
            return False
    result = _campaign_research_results(state).get(policy_id)
    route_hazard = (
        str(result.get("route_hazard") or "")
        if isinstance(result, Mapping)
        else ""
    )
    route_hazard_matches = bool(
        route_hazard.startswith(_SOURCE_MRINTHAS_GUARD_PREFLIGHT_HAZARD_PREFIX)
        and route_hazard.endswith(_SOURCE_MRINTHAS_GUARD_PREFLIGHT_HAZARD_SUFFIX)
    )
    return bool(
        isinstance(result, Mapping)
        and result.get("boot_id") == boot_id
        and result.get("observed") is False
        and result.get("viable") is False
        and route_hazard_matches
        and not any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "crowd_exhausted",
                "fatal_failure",
                "completed_kill",
                "xp_loss_observed",
                "unattackable",
                "target_vnum_mismatch",
                "consider_viable",
            )
        )
    )


def _source_ranked_plain_aggressive_current_band_fallback_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Allow a fresh plain singleton to reach live ``consider`` without Sanctuary.

    This is a source admission rule for the ordinary post-loss fallback, not a
    prediction that the fight will succeed. The endpoint may be aggressive or
    passive. The live runner still proves the exact mobile, isolation,
    ``consider`` result, own-health floor, and return route. Target HP and
    predicted damage deliberately remain report evidence.
    """
    if (
        source_world is None
        or character_max_hp is None
        or character_max_hp <= 0
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or candidate.status == "reject"
        or not candidate.target_selection_safe
        or not candidate.autonomous_safe
        or candidate.specials
        or candidate.equipped_weapons
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or _source_ranked_psionic_candidate_requires_protection(
            candidate,
            source_world=source_world,
        )
        or not _source_ranked_level_admission_available(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    ):
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        mobile is None
        or mobile.programs
        or mobile.attack_programs
        or mobile.fear_aura
        or mobile.non_corporeal
        or mobile.costs_fame
        or mobile.vnum in source_world.shopkeepers
        or source_world.mobile_specials.get(candidate.mobile_vnum)
        or mobile.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
    ):
        return False
    resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
    )
    if (
        len(resets) != 1
        or resets[0].room_vnum != candidate.room_vnum
        or resets[0].maximum_count != 1
        or resets[0].equipment
    ):
        return False
    if (
        candidate.estimated_level_range[0] <= character_level - 5
        and not _source_ranked_invisibility_route_candidate_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    ):
        return False
    if not _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    ):
        return False
    route_specials_noncombat_only = _source_ranked_route_specials_noncombat_only(
        candidate,
        source_world,
    )
    if candidate.route_special_mobile_vnums and not route_specials_noncombat_only:
        return False
    for hazard in candidate.hazards:
        normalized_hazard = str(hazard).casefold()
        if normalized_hazard.startswith("positive alignment target"):
            continue
        if not normalized_hazard.startswith(
            (
                "route:",
                "route program attacker:",
                "route combat-joining special:",
                "reachable wanderer:",
                "reachable program attacker:",
                "reachable special mobile:",
                "reachable combat-joining special:",
            )
        ):
            continue
        if route_specials_noncombat_only and normalized_hazard.startswith(
            "reachable special mobile:"
        ):
            continue
        if normalized_hazard.startswith(
            ("route program attacker:", "reachable program attacker:")
        ):
            return False
        if candidate.route_aggressive_mobile_vnums and normalized_hazard.startswith(
            ("route:", "reachable wanderer:")
        ):
            continue
        return False
    return True


def _source_ranked_plain_route_risk_fallback_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Admit a plain or harmless-special target behind ordinary route risk.

    The source ranker quite correctly records a route attacker as a warning,
    but the generic selector historically treated every such warning as a
    terminal rejection.  That made a large part of the current-band world
    unreachable even when the route attackers were source-bounded.  This
    exception is intentionally narrower than the old aggressive fallback:
    it permits only a singleton, unscripted endpoint with no weapon. A target
    special is allowed only when the source proves the exact special set is
    noncombat and zero-bonus (for example ``spec_repairman``); dangerous or
    unknown specials remain closed. There must be no hard route hazard, no
    prior loss, and route attackers proven as deep or narrowly classified
    transit noise, or ordinary near-band encounters.
    A damage estimate alone cannot admit a five-or-more-level-below attacker.
    The live worker still owns route identity, crowd, consider, health-floor,
    combat, and return checks.
    """
    source_target_specials = (
        {
            str(special).strip().casefold()
            for special in source_world.mobile_specials.get(
                candidate.mobile_vnum, ()
            )
        }
        if source_world is not None
        else set()
    )
    candidate_target_specials = {
        str(special).strip().casefold()
        for special in candidate.specials
    }
    safe_noncombat_target_special = bool(
        candidate_target_specials
        and candidate_target_specials == source_target_specials
        and candidate_target_specials <= SAFE_NONCOMBAT_SPECIALS
        and all(
            source_special_profile(special).risk == "noncombat"
            and source_special_profile(special).xp_bonus == 0
            for special in candidate_target_specials
        )
    )
    if (
        source_world is None
        or character_max_hp is None
        or character_max_hp <= 0
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or (candidate.specials and not safe_noncombat_target_special)
        or candidate.equipped_weapons
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or not candidate.route_aggressive_mobile_vnums
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or _source_ranked_psionic_candidate_requires_protection(
            candidate,
            source_world=source_world,
        )
    ):
        return False
    minimum, maximum = candidate.estimated_level_range
    if not (
        0 < minimum <= maximum
        and maximum > character_level - 5
        and minimum <= character_level + 5
        # The source range includes load fuzz. Use the declared mobile level
        # for the +5 ceiling instead of rejecting a level-49 target at level
        # 44 merely because its conservative range ends at 51.
        and candidate.level <= character_level + 5
    ):
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        mobile is None
        or mobile.programs
        or mobile.attack_programs
        or mobile.fear_aura
        or mobile.non_corporeal
        or mobile.costs_fame
        or mobile.vnum in source_world.shopkeepers
        or (
            source_target_specials
            and not safe_noncombat_target_special
        )
        or mobile.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
    ):
        return False
    resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
    )
    if (
        len(resets) != 1
        or resets[0].room_vnum != candidate.room_vnum
        or resets[0].maximum_count != 1
    ):
        return False
    # Armor and treasure-only loadouts do not make a passive endpoint an
    # armed or cast-capable target. Reject weapons and active item types, but
    # do not hide useful source targets merely because they carry loot.
    for _wear_location, object_vnum in resets[0].equipment:
        item = source_world.objects.get(object_vnum)
        if item is None or item.item_type not in {ITEM_ARMOR, ITEM_TREASURE}:
            return False
    if (
        candidate.route_special_mobile_vnums
        and not _source_ranked_route_specials_noncombat_only(
            candidate,
            source_world,
        )
    ):
        return False
    route_rejections = {
        str(rejection).strip()
        for rejection in candidate.autonomy_rejections
        if str(rejection).strip() != _SOURCE_PEAK_DAMAGE_REJECTION
    }
    if not route_rejections:
        # Current source ranking keeps some ordinary route risk in the
        # structured hazard fields instead of repeating it as an admission
        # rejection. Treat that shape as the same bounded route-risk probe;
        # otherwise a plain singleton can be hidden from the live selector
        # even though the route audit below can prove every aggressor safe.
        if not (
            candidate.route_hazard_mobile_vnums
            and candidate.route_aggressive_mobile_vnums
            and any(
                str(hazard).casefold().startswith(
                    ("route:", "reachable wanderer:")
                )
                for hazard in candidate.hazards
            )
        ):
            return False
    else:
        for rejection in route_rejections:
            if not (
                rejection.startswith("route crosses an aggressive")
                or rejection.startswith("route crosses a higher-level aggressive")
                or rejection.startswith("an aggressive wanderer")
                or rejection.startswith("a higher-level aggressive wanderer")
                or rejection.startswith("below-band transit aggressor")
                or rejection.startswith("below-band wandering aggressor")
                or rejection.startswith("aggressive wanderer inside")
            ):
                return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if _source_ranked_xp_loss_record(state, policy_id) is not None:
        return False
    if _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    ):
        return True

    # A source-bounded route is preferred, but a plain current-band mobile
    # should still be testable when the only paper veto is one ordinary,
    # unarmed, non-scripted aggressor close to the player's level.  Keep
    # lower-band special mobiles in the route's existing caution evidence;
    # only a near-band special or more than two near-band aggressors closes
    # this deliberately riskier fallback.
    try:
        route_rooms = _source_route_room_vnums(
            source_world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
    except (TypeError, ValueError):
        return False
    if not route_rooms or route_rooms[-1] != candidate.room_vnum:
        return False
    resets_by_mobile = _source_ranked_resets_by_mobile(source_world)
    near_band_vnums: set[int] = set()
    deep_plain_route = False
    for raw_vnum in candidate.route_aggressive_mobile_vnums:
        try:
            mobile_vnum = int(raw_vnum)
        except (TypeError, ValueError):
            return False
        mobile = source_world.mobiles.get(mobile_vnum)
        if (
            mobile is None
            or not mobile.aggressive
            or mobile.programs
            or mobile.attack_programs
            or mobile.player_relocation_programs
            or mobile.fear_aura
            or mobile.non_corporeal
            or mobile.costs_fame
            or mobile.vnum in source_world.shopkeepers
            or mobile.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
        ):
            return False
        maximum_level = _mobile_level_range(mobile.level)[1]
        resets = resets_by_mobile.get(mobile_vnum, ())
        if not resets:
            return False
        if mobile.wanders:
            if not set(source_mobile_search_rooms(source_world, mobile_vnum)).intersection(
                route_rooms
            ):
                return False
        elif not any(reset.room_vnum in route_rooms for reset in resets):
            return False
        if maximum_level <= character_level - 10:
            deep_plain_route = True
            # Deep route noise still needs the armed transit proof.  An
            # unarmed or ambiguous aggressor is a route hazard, regardless of
            # how far below the pilot it is.
            if source_mobile_route_aggressor_level_only_is_bounded(
                source_world,
                mobile,
                character_level=character_level,
                resets_by_mobile=resets_by_mobile,
            ):
                continue
            return False
        if maximum_level <= character_level - 5:
            if source_mobile_route_aggressor_level_only_is_bounded(
                source_world,
                mobile,
                character_level=character_level,
                resets_by_mobile=resets_by_mobile,
            ):
                continue
            return False
        if not mobile.hp_modifier_known or not mobile.damage_modifier_known:
            return False
        if maximum_level > character_level + 1:
            return False
        if any(
            str(special).strip().casefold() not in SAFE_NONCOMBAT_SPECIALS
            for special in source_world.mobile_specials.get(mobile_vnum, ())
        ):
            return False
        if any(reset.equipment or reset.maximum_count > 3 for reset in resets):
            return False
        near_band_vnums.add(mobile_vnum)
    return bool(deep_plain_route or 1 <= len(near_band_vnums) <= 2)


def _source_ranked_sanctuary_armed_endpoint_route_risk_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Admit one armed passive endpoint behind ordinary unarmed route fights.

    This is a live ``consider`` admission for a source-singleton endpoint with
    one ordinary weapon. It is intentionally limited to at most two current-
    band, unarmed, sentinel route mobiles; deeper route mobiles must pass the
    existing bounded transit proof. Sanctuary is required before departure,
    while live identity, isolation, consider, combat and the 20% health floor
    remain authoritative.
    """
    if (
        source_world is None
        or character_max_hp is None
        or character_max_hp <= 0
        or not _state_has_sanctuary_reserve(state)
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or candidate.specials
        or len(candidate.equipped_weapons) != 1
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or not candidate.route_aggressive_mobile_vnums
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
        or not set(candidate.autonomy_rejections).issubset(
            {
                _SOURCE_PLAIN_TRANSIT_REJECTION,
                _SOURCE_ARMED_TRANSIT_REJECTION,
            }
        )
        or _source_ranked_psionic_candidate_requires_protection(
            candidate,
            source_world=source_world,
        )
    ):
        return False
    minimum, maximum = candidate.estimated_level_range
    if not (
        0 < minimum <= maximum
        and maximum > character_level - 5
        and minimum <= character_level + 5
        and maximum <= character_level + 5
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if _source_ranked_xp_loss_record(state, policy_id) is not None:
        return False
    endpoint = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        endpoint is None
        or endpoint.aggressive
        or endpoint.programs
        or endpoint.attack_programs
        or endpoint.fear_aura
        or endpoint.non_corporeal
        or endpoint.costs_fame
        or source_world.mobile_specials.get(candidate.mobile_vnum)
        or endpoint.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
    ):
        return False
    resets_by_mobile = _source_ranked_resets_by_mobile(source_world)
    endpoint_resets = resets_by_mobile.get(candidate.mobile_vnum, ())
    if (
        len(endpoint_resets) != 1
        or endpoint_resets[0].room_vnum != candidate.room_vnum
        or endpoint_resets[0].maximum_count != 1
    ):
        return False
    wielded = 0
    for wear_location, object_vnum in endpoint_resets[0].equipment:
        if wear_location == WEAR_DUAL:
            return False
        item = source_world.objects.get(object_vnum)
        if item is None:
            return False
        if wear_location == WEAR_WIELD:
            if item.item_type != ITEM_WEAPON or wielded:
                return False
            wielded += 1
        elif item.item_type not in {ITEM_ARMOR, ITEM_TREASURE}:
            return False
    if wielded != 1:
        return False
    try:
        route_rooms = _source_route_room_vnums(
            source_world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
    except (TypeError, ValueError):
        return False
    if not route_rooms or route_rooms[-1] != candidate.room_vnum:
        return False
    resets_by_mobile = _source_ranked_resets_by_mobile(source_world)
    current_band_vnums: set[int] = set()
    for raw_vnum in candidate.route_aggressive_mobile_vnums:
        try:
            mobile_vnum = int(raw_vnum)
        except (TypeError, ValueError):
            return False
        if mobile_vnum == candidate.mobile_vnum:
            continue
        mobile = source_world.mobiles.get(mobile_vnum)
        if (
            mobile is None
            or not mobile.aggressive
            or mobile.programs
            or mobile.attack_programs
            or mobile.player_relocation_programs
            or mobile.fear_aura
            or mobile.non_corporeal
            or mobile.costs_fame
            or mobile.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
        ):
            return False
        resets = resets_by_mobile.get(mobile_vnum, ())
        if not resets:
            return False
        if mobile.wanders:
            reachable = set(source_mobile_search_rooms(source_world, mobile_vnum))
            if not reachable.intersection(route_rooms):
                return False
        elif not any(reset.room_vnum in route_rooms for reset in resets):
            return False
        maximum_level = _mobile_level_range(mobile.level)[1]
        if maximum_level <= character_level - 5:
            if not (
                source_mobile_deep_transit_route_is_bounded(
                    source_world,
                    mobile,
                    character_level=character_level,
                    resets_by_mobile=resets_by_mobile,
                )
                or source_mobile_route_aggressor_level_only_is_bounded(
                    source_world,
                    mobile,
                    character_level=character_level,
                    resets_by_mobile=resets_by_mobile,
                )
                or source_mobile_route_aggressor_is_bounded(
                    source_world,
                    mobile,
                    character_level=character_level,
                    character_max_hp=character_max_hp,
                    resets_by_mobile=resets_by_mobile,
                )
                or source_mobile_unresolved_deep_plain_wanderer_is_preflight_safe(
                    source_world,
                    mobile,
                    character_level=character_level,
                    resets_by_mobile=resets_by_mobile,
                )
            ):
                return False
            continue
        if maximum_level > character_level + 1:
            return False
        if (
            not mobile.sentinel
            or mobile.wanders
            or source_world.mobile_specials.get(mobile_vnum)
            or any(reset.equipment for reset in resets)
            or sum(max(0, int(reset.maximum_count)) for reset in resets) > 2
        ):
            return False
        current_band_vnums.add(mobile_vnum)
        if len(current_band_vnums) > 2:
            return False
    return bool(current_band_vnums)


def _source_ranked_plain_sentinel_risk_revalidation_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
    require_marker: bool = True,
    allow_dispatched_marker: bool = False,
) -> bool:
    """Allow one direct-risk pass after an exact visibility-prep abort.

    This is deliberately narrower than the ordinary aggressive fallback. It
    is only for a source-singleton, unarmed, unscripted sentinel whose saved
    result says that the generic invisibility preparation stopped before any
    live observation. The marker is armed before dispatch, so a later
    connection or combat result cannot reopen it.
    """
    if (
        source_world is None
        or character_max_hp is None
        or character_max_hp <= 0
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or candidate.status == "reject"
        or not candidate.target_selection_safe
        or not candidate.autonomous_safe
        or candidate.specials
        or candidate.equipped_weapons
        or candidate.requires_detect_invisibility
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
        or _source_ranked_psionic_candidate_requires_protection(
            candidate,
            source_world=source_world,
        )
        or not _source_ranked_level_admission_available(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
        or _source_ranked_xp_loss_record(
            state,
            _source_ranked_policy_id(
                candidate,
                character_level=character_level,
            ),
        ) is not None
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    marker = state.get(_SOURCE_RANKED_PLAIN_SENTINEL_RISK_REVALIDATION_KEY)
    if not isinstance(marker, Mapping) and require_marker:
        return False
    if isinstance(marker, Mapping):
        if (
            marker.get("policy_id") != policy_id
            or marker.get("boot_id") != state.get("world_boot_id")
            or marker.get("level") not in {None, character_level}
            or marker.get("source_revision") != state.get(_SOURCE_REVISION_KEY)
            or marker.get(
                "revision",
                marker.get("policy_revision"),
            ) != _SOURCE_RANKED_PLAIN_SENTINEL_RISK_REVALIDATION_REVISION
            or marker.get("status") not in {"pending", "attempted"}
            or (
                marker.get("target_dispatch_started") is True
                and not allow_dispatched_marker
            )
        ):
            return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        mobile is None
        or not mobile.aggressive
        or not mobile.sentinel
        or mobile.wanders
        or mobile.programs
        or mobile.attack_programs
        or mobile.fear_aura
        or mobile.non_corporeal
        or mobile.costs_fame
        or mobile.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
        or candidate.mobile_vnum in source_world.shopkeepers
        or source_world.mobile_specials.get(candidate.mobile_vnum)
    ):
        return False
    resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
    )
    if (
        len(resets) != 1
        or resets[0].room_vnum != candidate.room_vnum
        or resets[0].maximum_count != 1
        or resets[0].equipment
    ):
        return False
    if not _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    ):
        return False
    if not _source_ranked_aggressive_singleton_consider_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
        source_world=source_world,
    ):
        return False
    if not _source_ranked_candidate_in_current_band(
        candidate,
        state,
        world=source_world,
        character_level=character_level,
        character_max_hp=character_max_hp,
        allow_repeated_kills=False,
    ):
        return False
    if (
        str(state.get("room_vnum") or "") != "3054"
        or state.get("dead") is True
        or state.get("in_combat") is True
        or state.get("campaign_died_during_segment") is True
    ):
        return False
    try:
        current_hp = int(state.get("hp") or 0)
        current_max_hp = int(state.get("max_hp") or 0)
    except (TypeError, ValueError):
        return False
    if current_max_hp <= 0 or current_hp < current_max_hp * 0.95:
        return False
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("observed") is False
        and result.get("viable") is False
        and result.get("route_hazard")
        == _SOURCE_RANKED_INVISIBILITY_PREPARATION_ABORT
        and not any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "crowd_exhausted",
                "fatal_failure",
                "completed_kill",
                "xp_loss_observed",
                "unattackable",
                "target_vnum_mismatch",
                "consider_viable",
            )
        )
    ):
        return False
    # This exact preparation abort can be retained as a cooldown result even
    # when no reset or crowd timer exists. The route receipt itself is the
    # bounded evidence for this one revalidation.
    return True


_SOURCE_PLAIN_TRANSIT_REJECTION = (
    "route crosses an aggressive reset inside the useful XP band"
)
_SOURCE_TARGET_CAPACITY_REJECTION = "target reset capacity exceeds one"
_SOURCE_ARMED_TRANSIT_REJECTION = (
    "an aggressive wanderer inside the transit-risk band can reach the route"
)
_SOURCE_LEVEL_ONLY_TRANSIT_REJECTION = (
    "below-band wandering aggressor is not an XP target"
)
_SOURCE_BELOW_BAND_TRANSIT_REJECTION = (
    "below-band transit aggressor is not an XP target"
)
_SOURCE_PLAIN_ARMED_TRANSIT_REJECTIONS = frozenset(
    {
        _SOURCE_PLAIN_TRANSIT_REJECTION,
        _SOURCE_ARMED_TRANSIT_REJECTION,
    }
)
_SOURCE_PLAIN_ARMED_TRANSIT_REJECTION_PROFILES = frozenset(
    {
        frozenset({_SOURCE_ARMED_TRANSIT_REJECTION}),
        frozenset({_SOURCE_LEVEL_ONLY_TRANSIT_REJECTION}),
        frozenset(
            {
                _SOURCE_BELOW_BAND_TRANSIT_REJECTION,
                _SOURCE_LEVEL_ONLY_TRANSIT_REJECTION,
            }
        ),
        _SOURCE_PLAIN_ARMED_TRANSIT_REJECTIONS,
    }
)


def _source_ranked_plain_transit_mobile_vnums(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
    *,
    character_level: int,
    max_current_band: int = 1,
    allow_armed_endpoint: bool = False,
) -> tuple[int, ...]:
    """Return one exact plain current-band transit mobile for a route.

    This exception is intentionally source-only and route-specific. Every
    other aggressive reset must pass the existing below-band transit proof;
    current-band mobiles must be unarmed, unscripted, special-free, and
    source-identifiable in the route graph. Live isolation and health checks
    remain in StarterPolicy. The Sanctuary-backed armed-endpoint contract may
    explicitly allow two current-band mobiles through ``max_current_band``;
    ordinary callers retain the historical one-mobile limit.
    """
    capacity_research_endpoint = (
        candidate.autonomy_rejections == (_SOURCE_TARGET_CAPACITY_REJECTION,)
        and 1 <= candidate.source_spawn_limit <= 4
        and candidate.room_spawn_count == 1
    )
    route_transit_candidate = bool(candidate.route_aggressive_mobile_vnums)
    if (
        source_world is None
        or candidate.is_coin_stash
        or (
            candidate.source_spawn_limit != 1
            and not (capacity_research_endpoint or route_transit_candidate)
        )
        or (
            candidate.room_spawn_count != 1
            and not route_transit_candidate
        )
        or candidate.specials
        or (candidate.equipped_weapons and not allow_armed_endpoint)
        or candidate.route_hard_hazard_targets
        or candidate.route_preflight_hard_hazard
        # Depending on which source-ranked selector admitted the endpoint,
        # the route aggressor is either the candidate's only rejection or it
        # is already represented in the route hazard audit. A capacity-only
        # endpoint is observation-only; its capacity must not suppress a
        # separately audited plain transit fight.
        or not set(candidate.autonomy_rejections).issubset(
            {
                _SOURCE_PLAIN_TRANSIT_REJECTION,
                *(
                    (_SOURCE_TARGET_CAPACITY_REJECTION,)
                    if capacity_research_endpoint or route_transit_candidate
                    else ()
                ),
            }
        )
    ):
        return ()
    endpoint_mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        endpoint_mobile is None
        or endpoint_mobile.programs
        or endpoint_mobile.attack_programs
        or source_world.mobile_specials.get(candidate.mobile_vnum)
        or endpoint_mobile.non_corporeal
        or endpoint_mobile.fear_aura
        or endpoint_mobile.costs_fame
        or endpoint_mobile.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
    ):
        return ()
    route_rooms = _source_route_room_vnums(
        source_world,
        candidate.route_origin_room_vnum,
        candidate.route,
    )
    if not route_rooms or route_rooms[-1] != candidate.room_vnum:
        return ()
    route_room_set = set(route_rooms)
    resets_by_mobile = _source_ranked_resets_by_mobile(source_world)
    current_band: list[int] = []
    safer_current_band: list[int] = []
    strict_route_rejected = False
    route_vnums: set[int] = set()
    for raw_vnum in candidate.route_aggressive_mobile_vnums:
        try:
            mobile_vnum = int(raw_vnum)
        except (TypeError, ValueError):
            return ()
        if mobile_vnum <= 0 or mobile_vnum in route_vnums:
            continue
        route_vnums.add(mobile_vnum)
        mobile = source_world.mobiles.get(mobile_vnum)
        if mobile is None or not mobile.aggressive:
            return ()
        maximum_level = _mobile_level_range(mobile.level)[1]
        if maximum_level <= character_level - 5:
            bounded_transit = (
                source_mobile_deep_transit_route_is_bounded(
                    source_world,
                    mobile,
                    character_level=character_level,
                    resets_by_mobile=resets_by_mobile,
                )
                or source_mobile_route_aggressor_level_only_is_bounded(
                    source_world,
                    mobile,
                    character_level=character_level,
                    resets_by_mobile=resets_by_mobile,
                )
                or (
                    maximum_level <= character_level - 10
                    and source_mobile_route_aggressor_is_bounded(
                        source_world,
                        mobile,
                        character_level=character_level,
                    )
                )
                or source_mobile_unresolved_deep_plain_wanderer_is_preflight_safe(
                    source_world,
                    mobile,
                    character_level=character_level,
                    resets_by_mobile=resets_by_mobile,
                )
            )
            if not bounded_transit:
                # Keep inspecting near-band plain mobiles. The route's
                # ordinary hazard controller still owns this lower-level
                # hazard; it must not hide a separate, exact transit fight.
                strict_route_rejected = True
            continue
        if maximum_level > character_level + 1:
            return ()
        specials = tuple(
            str(special).strip().casefold()
            for special in source_world.mobile_specials.get(mobile_vnum, ())
        )
        resets = resets_by_mobile.get(mobile_vnum, ())
        if (
            mobile.programs
            or mobile.attack_programs
            or specials
            or mobile.non_corporeal
            or mobile.fear_aura
            or mobile.costs_fame
            or mobile.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
            or not mobile.hp_modifier_known
            or not mobile.damage_modifier_known
            or not resets
            or any(reset.equipment for reset in resets)
            or any(reset.maximum_count > 3 for reset in resets)
        ):
            return ()
        if not any(reset.room_vnum in route_room_set for reset in resets):
            # A wandering route hazard may be reachable from the route
            # without having a reset in one of its fixed rooms. It remains a
            # normal hazard, but it must not suppress a separate exact plain
            # transit mobile that is actually reset on the path.
            continue
        current_band.append(mobile_vnum)
        if (
            maximum_level <= character_level - 3
            and source_mobile_is_ordinary_below_level_aggressor(
                source_world,
                mobile,
                character_level=character_level,
            )
            and any(reset.room_vnum in route_room_set for reset in resets)
        ):
            safer_current_band.append(mobile_vnum)
    if (
        0 < len(current_band) <= max_current_band
        and not strict_route_rejected
    ):
        return tuple(sorted(current_band))

    # A long route can contain several near-band aggressors close to its
    # endpoint while still exposing one distinctly safer, plain bystander
    # early in the route.  Keep that exact source identity admissible when it
    # is at least three levels below the pilot and the other near-band
    # aggressors are not folded into the exception.  This is a transit-fight
    # allowance only; live identity, isolation, consider, and health gates
    # still decide whether the fight starts.
    return tuple(sorted(safer_current_band)) if len(safer_current_band) == 1 else ()


def _source_ranked_sanctuary_armed_endpoint_transit_mobile_vnums(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> tuple[int, ...]:
    """Return the plain transit family for an armed Sanctuary-backed target."""
    if not _source_ranked_sanctuary_armed_endpoint_route_risk_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
        source_world=source_world,
    ):
        return ()
    return _source_ranked_plain_transit_mobile_vnums(
        candidate,
        source_world,
        character_level=character_level,
        max_current_band=2,
        allow_armed_endpoint=True,
    )


def _source_ranked_sanctuary_armed_endpoint_transit_hazard_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Keep known family members from quarantining their audited endpoint."""
    family = _source_ranked_sanctuary_armed_endpoint_transit_mobile_vnums(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
        source_world=source_world,
    )
    if not family or source_world is None:
        return False
    raw_records = state.get(_SOURCE_RANKED_TRANSIT_HAZARDS_KEY)
    if not isinstance(raw_records, Mapping):
        return False
    try:
        route_rooms = _source_route_room_vnums(
            source_world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
    except (KeyError, TypeError, ValueError):
        return False
    route_room_ids = set(int(room_vnum) for room_vnum in (route_rooms or ())[:-1])
    reset_rooms_by_mobile: dict[int, set[int]] = {}
    for reset in source_world.mob_resets:
        reset_rooms_by_mobile.setdefault(reset.mobile_vnum, set()).add(
            reset.room_vnum
        )
    matched = False
    for raw_record in raw_records.values():
        if not isinstance(raw_record, Mapping):
            continue
        if (
            raw_record.get("boot_id") != state.get("world_boot_id")
            or raw_record.get("level") != character_level
            or (
                state.get(_SOURCE_REVISION_KEY)
                and raw_record.get("source_revision")
                and raw_record.get("source_revision")
                != state.get(_SOURCE_REVISION_KEY)
            )
        ):
            continue
        try:
            mobile_vnum = int(raw_record.get("mobile_vnum") or 0)
        except (TypeError, ValueError):
            continue
        if not reset_rooms_by_mobile.get(mobile_vnum, set()).intersection(
            route_room_ids
        ):
            continue
        matched = True
        if mobile_vnum not in family:
            return False
    return matched


def _source_ranked_armed_transit_mobile_vnums(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
    *,
    character_level: int,
    character_max_hp: int | None,
) -> tuple[int, ...]:
    """Return a small Sanctuary-backed armed route family.

    This is deliberately narrower than ordinary transit admission. It is for
    a source-bounded, special-free, one-weapon wanderer family on the route to
    a source-Sanctuary target. A reset population of at most two can still
    expose one isolated live attacker; runtime still requires exact identity,
    isolation, active Sanctuary, and the player's own health floor.
    """
    if (
        source_world is None
        or character_max_hp is None
        or character_max_hp <= 0
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or not candidate.equipped_weapons
        or candidate.specials
        or candidate.route_hard_hazard_targets
        or frozenset(candidate.autonomy_rejections)
        not in {
            frozenset({_SOURCE_ARMED_TRANSIT_REJECTION}),
            frozenset({_SOURCE_LEVEL_ONLY_TRANSIT_REJECTION}),
        }
    ):
        return ()
    endpoint = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        endpoint is None
        or not source_mobile_has_sanctuary(endpoint)
        or endpoint.aggressive
        or endpoint.programs
        or endpoint.attack_programs
        or source_world.mobile_specials.get(candidate.mobile_vnum)
        or endpoint.non_corporeal
        or endpoint.fear_aura
        or endpoint.costs_fame
    ):
        return ()
    minimum_level, maximum_level = candidate.estimated_level_range
    if (
        minimum_level <= character_level - 5
        or maximum_level > character_level + 5
    ):
        return ()
    try:
        route_rooms = _source_route_room_vnums(
            source_world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
    except (TypeError, ValueError):
        return ()
    if not route_rooms or route_rooms[-1] != candidate.room_vnum:
        return ()
    preflight = _source_ranked_route_wanderer_preflight_metadata(
        candidate,
        source_world,
        character_level=character_level,
    )
    if not preflight:
        return ()
    preflight_vnums = {
        int(vnum)
        for vnum in preflight.get("source_mobile_vnums", ())
        if str(vnum).isdigit()
    }
    route_room_set = set(route_rooms)
    armed: list[int] = []
    for raw_vnum in candidate.route_aggressive_mobile_vnums:
        try:
            mobile_vnum = int(raw_vnum)
        except (TypeError, ValueError):
            return ()
        if mobile_vnum not in preflight_vnums:
            continue
        mobile = source_world.mobiles.get(mobile_vnum)
        if (
            mobile is None
            or not mobile.aggressive
            or not mobile.wanders
            or mobile.programs
            or mobile.attack_programs
            or source_world.mobile_specials.get(mobile_vnum)
            or mobile.non_corporeal
            or mobile.fear_aura
            or mobile.costs_fame
            or mobile.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
            or not mobile.hp_modifier_known
            or not mobile.damage_modifier_known
        ):
            continue
        maximum_level = _mobile_level_range(mobile.level)[1]
        if maximum_level <= character_level - 5:
            continue
        if maximum_level > character_level + 1:
            continue
        search_rooms = set(source_mobile_search_rooms(source_world, mobile_vnum))
        if not search_rooms.intersection(route_room_set):
            continue
        resets = tuple(
            reset
            for reset in source_world.mob_resets
            if reset.mobile_vnum == mobile_vnum
        )
        if (
            not resets
            or any(
                reset.maximum_count < 1 or reset.maximum_count > 2
                for reset in resets
            )
            or sum(reset.maximum_count for reset in resets) > 2
        ):
            continue
        valid_loadout = True
        for reset in resets:
            wielded = [
                object_vnum
                for slot, object_vnum in reset.equipment
                if slot == WEAR_WIELD
            ]
            if len(wielded) != 1 or any(
                slot == WEAR_DUAL for slot, _object_vnum in reset.equipment
            ):
                valid_loadout = False
                break
            for slot, object_vnum in reset.equipment:
                item = source_world.objects.get(object_vnum)
                if item is None or (
                    slot == WEAR_WIELD
                    and item.item_type != ITEM_WEAPON
                ) or (
                    slot != WEAR_WIELD
                    and item.item_type != ITEM_ARMOR
                ):
                    valid_loadout = False
                    break
            if not valid_loadout:
                break
        if not valid_loadout:
            continue
        protected_peak = mobile_sanctuary_peak_round_damage(
            maximum_level,
            wielding=True,
            dual_wielding=False,
            damage_modifier=mobile.damage_modifier,
        )
        protected_critical = mobile_sanctuary_critical_hit_damage(
            maximum_level,
            wielding=True,
            damage_modifier=mobile.damage_modifier,
        )
        health_floor = (character_max_hp + 4) // 5
        if protected_peak + protected_critical + health_floor > character_max_hp:
            continue
        armed.append(mobile_vnum)
    distinct = tuple(sorted(set(armed)))
    return distinct if 1 <= len(distinct) <= 2 else ()


def _source_ranked_plain_armed_transit_mobile_vnums(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
    *,
    character_level: int,
    character_max_hp: int | None,
    allow_route_retry_level_fringe: bool = False,
) -> tuple[int, ...]:
    """Return a tightly bounded armed wanderer family on a plain hunt route.

    This is the ordinary-target counterpart to the older Sanctuary-backed
    transit exception.  It is intentionally limited to the source shape used
    by the Smuggler route: one plain singleton endpoint, one source weapon on
    the endpoint, and at most two identical armed wanderer prototypes that
    can reach the path.  The route may be rejected solely because that armed
    wanderer family is present; an additional plain-transit rejection is also
    accepted for the older combined route shape.  A source-proven, level-only
    transit marker is accepted as the same route family after the wanderers
    are at least four levels below the pilot.  Runtime still requires
    Sanctuary, exact VNUM and description, one live enemy, and the normal
    health floor before fighting an interruption.  It does not grant
    permission to fight the endpoint.  ``allow_route_retry_level_fringe`` is
    reserved for the exact one-shot post-loss route repair; ordinary selection
    keeps the three-level fringe closed.
    """
    if (
        source_world is None
        or character_max_hp is None
        or character_max_hp <= 0
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or len(candidate.equipped_weapons) != 1
        or candidate.specials
        or candidate.route_hard_hazard_targets
        or candidate.route_preflight_hard_hazard
        or candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
        or frozenset(candidate.autonomy_rejections)
        not in _SOURCE_PLAIN_ARMED_TRANSIT_REJECTION_PROFILES
    ):
        return ()
    endpoint = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        endpoint is None
        or endpoint.programs
        or endpoint.attack_programs
        or source_world.mobile_specials.get(candidate.mobile_vnum)
        or endpoint.non_corporeal
        or endpoint.fear_aura
        or endpoint.costs_fame
        or endpoint.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
    ):
        return ()
    resets_by_mobile = _source_ranked_resets_by_mobile(source_world)
    endpoint_resets = resets_by_mobile.get(candidate.mobile_vnum, ())
    if (
        len(endpoint_resets) != 1
        or endpoint_resets[0].room_vnum != candidate.room_vnum
        or endpoint_resets[0].maximum_count != 1
    ):
        return ()
    endpoint_room_resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.room_vnum == candidate.room_vnum
    )
    if any(
        reset.mobile_vnum != candidate.mobile_vnum
        for reset in endpoint_room_resets
    ):
        return ()
    for slot, object_vnum in endpoint_resets[0].equipment:
        item = source_world.objects.get(object_vnum)
        if item is None or (
            slot == WEAR_WIELD and item.item_type != ITEM_WEAPON
        ) or (
            slot != WEAR_WIELD and item.item_type != ITEM_ARMOR
        ) or slot == WEAR_DUAL:
            return ()

    route_rooms = _source_route_room_vnums(
        source_world,
        candidate.route_origin_room_vnum,
        candidate.route,
    )
    if not route_rooms or route_rooms[-1] != candidate.room_vnum:
        return ()
    route_room_set = set(route_rooms)
    resets_by_mobile = _source_ranked_resets_by_mobile(source_world)
    current_band: list[int] = []
    for raw_vnum in candidate.route_aggressive_mobile_vnums:
        try:
            mobile_vnum = int(raw_vnum)
        except (TypeError, ValueError):
            return ()
        if mobile_vnum == candidate.mobile_vnum:
            continue
        mobile = source_world.mobiles.get(mobile_vnum)
        if mobile is None:
            return ()
        maximum_level = _mobile_level_range(mobile.level)[1]
        # Keep this exception on the proven three-level fringe.  The older
        # level-39 Smuggler route remains a normal preflight until the live
        # pilot has the additional level gap that makes this transit family
        # materially less competitive with the hunt target.
        if (
            not allow_route_retry_level_fringe
            and maximum_level > character_level - 3
        ):
            return ()
        if maximum_level <= character_level - 5:
            continue
        if maximum_level > character_level + 1:
            return ()
        search_rooms = set(source_mobile_search_rooms(source_world, mobile_vnum))
        if not search_rooms.intersection(route_room_set):
            continue
        if (
            not mobile.aggressive
            or not mobile.wanders
            or mobile.programs
            or mobile.attack_programs
            or source_world.mobile_specials.get(mobile_vnum)
            or mobile.non_corporeal
            or mobile.fear_aura
            or mobile.costs_fame
            or mobile.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
            or not mobile.hp_modifier_known
            or not mobile.damage_modifier_known
        ):
            return ()
        resets = resets_by_mobile.get(mobile_vnum, ())
        if (
            not resets
            or sum(max(0, int(reset.maximum_count)) for reset in resets) > 2
        ):
            return ()
        for reset in resets:
            wielded = [
                object_vnum
                for slot, object_vnum in reset.equipment
                if slot == WEAR_WIELD
            ]
            if len(wielded) != 1 or any(
                slot == WEAR_DUAL for slot, _object_vnum in reset.equipment
            ):
                return ()
            for slot, object_vnum in reset.equipment:
                item = source_world.objects.get(object_vnum)
                if item is None or (
                    slot == WEAR_WIELD and item.item_type != ITEM_WEAPON
                ) or (
                    slot != WEAR_WIELD and item.item_type != ITEM_ARMOR
                ):
                    return ()
        health_floor = (character_max_hp + 4) // 5
        if (
            mobile_sanctuary_peak_round_damage(
                maximum_level,
                wielding=True,
                dual_wielding=False,
                damage_modifier=mobile.damage_modifier,
            )
            + mobile_sanctuary_critical_hit_damage(
                maximum_level,
                wielding=True,
                damage_modifier=mobile.damage_modifier,
            )
            + health_floor
            > character_max_hp
        ):
            return ()
        current_band.append(mobile_vnum)
    distinct = tuple(sorted(set(current_band)))
    return distinct if 1 <= len(distinct) <= 2 else ()


def _source_ranked_level_only_armed_transit_mobile_vnums(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
    *,
    character_level: int,
) -> tuple[int, ...]:
    """Return armed route mobiles admitted by the level-only transit proof.

    This is route permission only. It does not admit the endpoint or waive
    live isolation, consider, Sanctuary, health-floor, crowd, or return
    checks. The source proof deliberately ignores target HP and only covers a
    small, special-free armed population materially below the pilot.
    """
    if (
        source_world is None
        or _SOURCE_LEVEL_ONLY_TRANSIT_REJECTION
        not in set(candidate.autonomy_rejections)
        or not candidate.route_aggressive_mobile_vnums
    ):
        return ()
    resets_by_mobile = _source_ranked_resets_by_mobile(source_world)
    endpoint_resets = resets_by_mobile.get(candidate.mobile_vnum, ())
    if (
        len(endpoint_resets) != 1
        or endpoint_resets[0].room_vnum != candidate.room_vnum
        or endpoint_resets[0].maximum_count != 1
        or any(
            reset.mobile_vnum != candidate.mobile_vnum
            for reset in source_world.mob_resets
            if reset.room_vnum == candidate.room_vnum
        )
    ):
        return ()
    admitted: list[int] = []
    for raw_vnum in candidate.route_aggressive_mobile_vnums:
        try:
            mobile_vnum = int(raw_vnum)
        except (TypeError, ValueError):
            return ()
        mobile = source_world.mobiles.get(mobile_vnum)
        if mobile is None:
            return ()
        if (
            source_mobile_deep_transit_route_is_bounded(
                source_world,
                mobile,
                character_level=character_level,
                resets_by_mobile=resets_by_mobile,
            )
            or source_mobile_route_aggressor_level_only_is_bounded(
                source_world,
                mobile,
                character_level=character_level,
                resets_by_mobile=resets_by_mobile,
            )
        ):
            admitted.append(mobile_vnum)
    return tuple(sorted(set(admitted)))


def _source_ranked_unarmed_endpoint_armed_transit_mobile_vnums(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
    *,
    character_level: int,
    character_max_hp: int | None,
) -> tuple[int, ...]:
    """Return one armed current-band wanderer on an unarmed target route.

    This is the narrow counterpart to the plain armed-endpoint exception:
    the selected target is a source-singleton, unarmed, aggressive mobile,
    while one source-singleton armed wanderer is the only current-band route
    interruption.  Lower route aggressors must pass the existing source
    bounded-transit proof.  Runtime still requires Sanctuary, exact identity,
    isolation, and the player's own health floor before fighting the guard.
    """
    if (
        source_world is None
        or character_max_hp is None
        or character_max_hp <= 0
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or candidate.equipped_weapons
        or candidate.specials
        or candidate.route_hard_hazard_targets
        or candidate.route_preflight_hard_hazard
        or candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
        or set(candidate.autonomy_rejections)
        != {_SOURCE_ARMED_TRANSIT_REJECTION}
    ):
        return ()
    endpoint = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        endpoint is None
        or not endpoint.aggressive
        or endpoint.programs
        or endpoint.attack_programs
        or source_world.mobile_specials.get(candidate.mobile_vnum)
        or endpoint.non_corporeal
        or endpoint.fear_aura
        or endpoint.costs_fame
        or endpoint.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
    ):
        return ()
    endpoint_resets = tuple(
        reset
        for reset in _source_ranked_resets_by_mobile(source_world).get(
            candidate.mobile_vnum,
            (),
        )
    )
    if (
        len(endpoint_resets) != 1
        or endpoint_resets[0].room_vnum != candidate.room_vnum
        or endpoint_resets[0].maximum_count != 1
        or endpoint_resets[0].equipment
    ):
        return ()
    try:
        route_rooms = _source_route_room_vnums(
            source_world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
    except (TypeError, ValueError):
        return ()
    if not route_rooms or route_rooms[-1] != candidate.room_vnum:
        return ()
    route_room_set = set(route_rooms)
    resets_by_mobile = _source_ranked_resets_by_mobile(source_world)
    current_band: list[int] = []
    route_vnums: set[int] = set()
    for raw_vnum in candidate.route_aggressive_mobile_vnums:
        try:
            mobile_vnum = int(raw_vnum)
        except (TypeError, ValueError):
            return ()
        if mobile_vnum <= 0 or mobile_vnum in route_vnums:
            continue
        route_vnums.add(mobile_vnum)
        if mobile_vnum == candidate.mobile_vnum:
            continue
        mobile = source_world.mobiles.get(mobile_vnum)
        if mobile is None:
            return ()
        maximum_level = _mobile_level_range(mobile.level)[1]
        if maximum_level <= character_level - 5:
            if not source_mobile_route_aggressor_is_bounded(
                source_world,
                mobile,
                character_level=character_level,
                character_max_hp=character_max_hp,
            ):
                return ()
            continue
        if maximum_level > character_level + 1:
            return ()
        if (
            not mobile.aggressive
            or not mobile.wanders
            or mobile.programs
            or mobile.attack_programs
            or source_world.mobile_specials.get(mobile_vnum)
            or mobile.non_corporeal
            or mobile.fear_aura
            or mobile.costs_fame
            or mobile.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
            or not mobile.hp_modifier_known
            or not mobile.damage_modifier_known
        ):
            return ()
        search_rooms = set(source_mobile_search_rooms(source_world, mobile_vnum))
        if not search_rooms.intersection(route_room_set):
            return ()
        resets = resets_by_mobile.get(mobile_vnum, ())
        if len(resets) != 1 or resets[0].maximum_count != 1:
            return ()
        wielded = [
            object_vnum
            for slot, object_vnum in resets[0].equipment
            if slot == WEAR_WIELD
        ]
        if (
            len(wielded) != 1
            or any(slot == WEAR_DUAL for slot, _object_vnum in resets[0].equipment)
        ):
            return ()
        for slot, object_vnum in resets[0].equipment:
            item = source_world.objects.get(object_vnum)
            if item is None or (
                slot == WEAR_WIELD and item.item_type != ITEM_WEAPON
            ) or (
                slot != WEAR_WIELD and item.item_type != ITEM_ARMOR
            ):
                return ()
        health_floor = (character_max_hp + 4) // 5
        if (
            mobile_sanctuary_peak_round_damage(
                maximum_level,
                wielding=True,
                dual_wielding=False,
                damage_modifier=mobile.damage_modifier,
            )
            + mobile_sanctuary_critical_hit_damage(
                maximum_level,
                wielding=True,
                damage_modifier=mobile.damage_modifier,
            )
            + health_floor
            > character_max_hp
        ):
            return ()
        current_band.append(mobile_vnum)
    distinct = tuple(sorted(set(current_band)))
    return distinct if len(distinct) == 1 else ()


def _source_ranked_candidate_is_runtime_autonomous_safe(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Keep source hazards strict without gating on estimated target output."""
    mirror_realm_endpoint_safe = bool(
        candidate.specials
        and source_world is not None
        and _source_ranked_mirror_realm_gardener_transit_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=source_world,
            allow_audited_special_target=True,
        )
        and _source_ranked_mirror_realm_endpoint_target_allowed(
            candidate,
            state,
            character_max_hp=character_max_hp,
            source_world=source_world,
        )
    )
    mirror_realm_plain_endpoint_safe = bool(
        not candidate.specials
        and source_world is not None
        and _source_ranked_mirror_realm_gardener_transit_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=source_world,
        )
        and _source_ranked_mirror_realm_endpoint_target_allowed(
            candidate,
            state,
            character_max_hp=character_max_hp,
            source_world=source_world,
        )
    )
    bounded_bear_transit_safe = bool(
        source_world is not None
        and _source_ranked_bounded_bear_transit_route_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
        )
    )
    return bool(
        candidate.target_selection_safe
        or (
            candidate.specials
            and (
                _audited_source_special_candidate_allowed(
                    candidate,
                    state=state,
                    character_max_hp=character_max_hp,
                    source_world=source_world,
                )
                or mirror_realm_endpoint_safe
            )
            and _source_ranked_special_candidate_in_live_level_ceiling(
                candidate,
                character_level=character_level,
            )
        )
        or _source_ranked_plain_armed_transit_mobile_vnums(
            candidate,
            source_world,
            character_level=character_level,
            character_max_hp=character_max_hp,
        )
        or _source_ranked_unarmed_endpoint_armed_transit_mobile_vnums(
            candidate,
            source_world,
            character_level=character_level,
            character_max_hp=character_max_hp,
        )
        or mirror_realm_plain_endpoint_safe
        or bounded_bear_transit_safe
    )


def _source_ranked_relative_level_target_admission_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
    allow_detect_invisibility: bool = False,
) -> bool:
    """Allow an ordinary source target through legacy paper-risk filters.

    The source ranker still records estimated HP, equipment, and aggression as
    useful evidence.  Those facts must not, by themselves, prevent a fresh
    live ``consider`` or a bounded first engagement against an otherwise
    ordinary target.  Keep this helper deliberately narrow: source specials,
    scripted mobiles, route hazards, and ambiguous populations remain closed
    before travel.  Aggression is handled by the live combat controller and
    the character's own withdrawal floor, not by a paper-risk veto here.
    """
    if source_world is None or candidate.is_coin_stash:
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if mobile is None:
        return False
    if candidate.specials or source_world.mobile_specials.get(candidate.mobile_vnum):
        return False
    if (
        getattr(mobile, "programs", ())
        or getattr(mobile, "attack_programs", ())
        or getattr(mobile, "fear_aura", False)
        or getattr(mobile, "non_corporeal", False)
        or getattr(mobile, "costs_fame", False)
    ):
        return False
    if (
        candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
    ):
        return False
    # Relative level admission must not bypass a missing movement or
    # perception capability. The ordinary route-preparation path can admit a
    # detect-invisible target only after that capability is verified. A
    # hypothetical detect-invis state is used only during healer-side
    # candidate discovery; the live state still has to buy and verify it.
    if candidate.requires_detect_invisibility and not allow_detect_invisibility:
        return False
    # A source reset that can produce several copies is not an ordinary
    # singleton hunt. Keep it in the separate bounded population-research
    # path, where live isolation is proved before any combat is admitted.
    if candidate.source_spawn_limit != 1 or candidate.room_spawn_count != 1:
        return False
    minimum, maximum = candidate.estimated_level_range
    if not (0 < minimum <= maximum):
        return False
    if maximum <= character_level - 5 or minimum > character_level + 5:
        return False
    allowed_rejections: set[str] = set()
    if _source_ranked_plain_transit_mobile_vnums(
        candidate,
        source_world,
        character_level=character_level,
    ):
        allowed_rejections.add(_SOURCE_PLAIN_TRANSIT_REJECTION)
    rejections = set(candidate.autonomy_rejections)
    # Static HP/damage output is evidence for reports, not a reason to stop a
    # live relative-level ``consider`` probe. This also covers source mobiles
    # whose modifiers are unavailable in the area data.
    rejections.difference_update(_SOURCE_OUTPUT_EVIDENCE_REJECTIONS)
    # Aggression is a live combat fact, not a source-special or route hazard.
    # The bounded singleton contract keeps it visible to the field controller
    # while allowing the current-level candidate to reach selection.
    rejections.discard("target is aggressive")
    return not (rejections - allowed_rejections)


def _source_ranked_candidate_in_current_band_uncached(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    world: WorldSource | None = None,
    character_level: int,
    character_max_hp: int | None = None,
    allow_repeated_kills: bool = False,
    check_lucky_consider_probe: bool = True,
    allow_relative_level_target: bool = False,
) -> bool:
    """Select useful source level ranges without comparing target HP."""
    if candidate.mobile_vnum in _registered_singleton_loss_mobile_vnums(state):
        return False
    plain_route_risk = bool(
        world is not None
        and _source_ranked_plain_route_risk_fallback_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=world,
        )
    )
    relative_level_target = bool(
        allow_relative_level_target
        and _source_ranked_relative_level_target_admission_allowed(
            candidate,
            character_level=character_level,
            source_world=world,
            allow_detect_invisibility=_state_has_active_affect(
                state.get("affects"), "detect invis"
            ),
        )
    )
    plain_duplicate_rotation = bool(
        world is not None
        and _source_ranked_plain_duplicate_rotation_selection_allowed(
            candidate,
            world,
        )
    )
    armed_transit_route = bool(
        world is not None
        and (
            _source_ranked_plain_armed_transit_mobile_vnums(
                candidate,
                world,
                character_level=character_level,
                character_max_hp=character_max_hp,
            )
            or _source_ranked_unarmed_endpoint_armed_transit_mobile_vnums(
                candidate,
                world,
                character_level=character_level,
                character_max_hp=character_max_hp,
            )
            or _source_ranked_cyclops_torturer_route_risk_allowed(
                candidate,
                state,
                character_level=character_level,
                source_world=world,
            )
        )
    )
    master_elf_risk_route = bool(
        world is not None
        and _source_ranked_master_elf_route_risk_allowed(
            candidate,
            world,
            character_level=character_level,
        )
    )
    capacity_armed_pair = bool(
        world is not None
        and _source_ranked_capacity_armed_pair_execution_allowed(
            candidate,
            state,
            world,
        )
    )
    effective_character_max_hp = character_max_hp
    if (
        effective_character_max_hp is None
        and isinstance(state.get("max_hp"), (int, float))
        and state.get("max_hp", 0) > 0
    ):
        effective_character_max_hp = int(state["max_hp"])
    mirror_realm_gardener_transit = bool(
        world is not None
        and _source_ranked_mirror_realm_gardener_transit_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=effective_character_max_hp,
            source_world=world,
            allow_audited_special_target=True,
        )
    )
    bounded_bear_transit_route = bool(
        world is not None
        and _source_ranked_bounded_bear_transit_route_allowed(
            candidate,
            character_level=character_level,
            source_world=world,
        )
    )
    if (
        candidate.status == "reject"
        and not relative_level_target
        and not plain_duplicate_rotation
        and not armed_transit_route
        and not plain_route_risk
        and not master_elf_risk_route
        and not candidate.target_selection_safe
        and not capacity_armed_pair
        and not mirror_realm_gardener_transit
        and not bounded_bear_transit_route
    ):
        return False
    if candidate.boot_kills >= 3 and not allow_repeated_kills:
        return False
    aggressive_consider_probe = _source_ranked_aggressive_consider_probe_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
        source_world=world,
    )
    split_reset_aggressive_consider_probe = bool(
        world is not None
        and _source_ranked_split_reset_aggressive_consider_probe_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=world,
        )
    )
    armed_singleton_consider_probe = bool(
        world is not None
        and candidate.equipped_weapons
        and _source_ranked_aggressive_singleton_consider_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=effective_character_max_hp,
            source_world=world,
        )
    )
    armed_duplicate_pair_consider_probe = bool(
        world is not None
        and candidate.equipped_weapons
        and _source_ranked_aggressive_duplicate_pair_consider_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=effective_character_max_hp,
            source_world=world,
        )
    )
    plain_singleton_consider_probe = bool(
        world is not None
        and not candidate.equipped_weapons
        and _source_ranked_aggressive_singleton_consider_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=effective_character_max_hp,
            source_world=world,
        )
    )
    protected_special_probe = bool(
        world is not None
        and candidate.specials
        and _source_ranked_protected_special_hp_fuzz_probe_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=world,
        )
    )
    target_is_aggressive = (
        "target is aggressive" in candidate.autonomy_rejections
        or "target is aggressive" in candidate.hazards
        or bool(
            world is not None
            and (source_mobile := world.mobiles.get(candidate.mobile_vnum)) is not None
            and source_mobile.aggressive
        )
    )
    aggressive_entry_below_safe_probe_floor = bool(
        target_is_aggressive
        and (
            candidate.level <= character_level - 5
            or (
                candidate.estimated_level_range[0] <= character_level - 5
                and candidate.estimated_level_range[1] <= character_level - 4
            )
        )
    )
    if aggressive_entry_below_safe_probe_floor:
        # A nominal level at the XP boundary can still load within the useful
        # band. The source-audited relative-level contract already admits
        # ordinary aggression; this economic uncertainty is not a hard hazard.
        # Live identity/consider and the player's own floor remain mandatory.
        if not (protected_special_probe or relative_level_target):
            return False
    if (
        target_is_aggressive
        and world is not None
        and not (
            aggressive_consider_probe
            or split_reset_aggressive_consider_probe
            or armed_singleton_consider_probe
            or armed_duplicate_pair_consider_probe
            or plain_singleton_consider_probe
            or protected_special_probe
        )
        and not armed_transit_route
        and not plain_route_risk
        and not master_elf_risk_route
        and not relative_level_target
    ):
        # An armed aggressive endpoint must still be a verified singleton.
        # Removing the Sanctuary gate must not turn duplicate source resets
        # into an unbounded live entry.
        return False
    current_hp = state.get("hp")
    current_max_hp = state.get("max_hp")
    safe_healer_aggressive_reentry = bool(
        target_is_aggressive
        and _is_safe_healer_checkpoint(state)
        and not _has_poison_affect(state.get("affects"))
        and isinstance(current_hp, (int, float))
        and isinstance(current_max_hp, (int, float))
        and current_max_hp > 0
        and current_hp >= (
            current_max_hp
            * _SOURCE_RANKED_SAFE_HEALER_AGGRESSIVE_REENTRY_RATIO
        )
    )
    wounded_aggressive_probe = bool(
        target_is_aggressive
        and isinstance(current_hp, (int, float))
        and isinstance(current_max_hp, (int, float))
        and current_max_hp > 0
        and current_hp < current_max_hp * 0.95
        and not safe_healer_aggressive_reentry
    )
    aggressive_special_below_floor = bool(
        target_is_aggressive
        and candidate.specials
        and candidate.estimated_level_range[0] <= character_level - 5
    )
    if wounded_aggressive_probe:
        return False
    audited_source_band_retry = bool(
        allow_repeated_kills
        and candidate.target_selection_safe
        and not candidate.specials
        and not candidate.equipped_weapons
        and candidate.estimated_level_range[1] > character_level - 5
    )
    if (
        (
            _source_ranked_aggressive_target_below_useful_floor(
                candidate, character_level=character_level,
            )
            or aggressive_special_below_floor
        )
        and not aggressive_consider_probe
        and not relative_level_target
        and not armed_transit_route
        and not master_elf_risk_route
        and not audited_source_band_retry
        and not protected_special_probe
    ):
        return False
    return (
        relative_level_target
        or plain_route_risk
        or armed_transit_route
        or master_elf_risk_route
        or protected_special_probe
        or mirror_realm_gardener_transit
        or bounded_bear_transit_route
        or _source_ranked_level_admission_available(
        candidate, state, character_level=character_level, source_world=world,
        )
    )


def _source_ranked_candidate_in_current_band(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    world: WorldSource | None = None,
    character_level: int,
    character_max_hp: int | None = None,
    allow_repeated_kills: bool = False,
    check_lucky_consider_probe: bool = True,
    allow_relative_level_target: bool = False,
) -> bool:
    """Memoize the pure source-band gate during one bounded policy pass."""
    cache = _CAMPAIGN_SOURCE_GATE_CACHE.get()
    if cache is None:
        return _source_ranked_candidate_in_current_band_uncached(
            candidate,
            state,
            world=world,
            character_level=character_level,
            character_max_hp=character_max_hp,
            allow_repeated_kills=allow_repeated_kills,
            check_lucky_consider_probe=check_lucky_consider_probe,
            allow_relative_level_target=allow_relative_level_target,
        )
    state_signature = (
        state.get("world_boot_id"),
        state.get("level"),
        state.get("hp"),
        state.get("max_hp"),
        state.get("xp"),
        state.get("campaign_last_policy"),
        id(state.get("affects")),
        id(state.get("campaign_research_results")),
        id(state.get("campaign_source_ranked_xp_loss_policies")),
        id(state.get(_REGISTERED_RESEARCH_XP_LOSS_POLICIES_KEY)),
        id(state.get("campaign_protection_recovery_required")),
        id(state.get("campaign_source_ranked_safe_absence_revalidation")),
        id(state.get("campaign_source_ranked_current_band_absence_retry")),
        id(state.get("campaign_source_ranked_frontier_risk_revalidation")),
        id(state.get("campaign_source_ranked_stale_consider_revalidation")),
        id(state.get("campaign_source_ranked_protection_retry_revalidation")),
    )
    key = (
        id(candidate),
        id(world),
        state_signature,
        character_level,
        character_max_hp,
        allow_repeated_kills,
        check_lucky_consider_probe,
        allow_relative_level_target,
    )
    if key in cache:
        return cache[key]
    result = _source_ranked_candidate_in_current_band_uncached(
        candidate,
        state,
        world=world,
        character_level=character_level,
        character_max_hp=character_max_hp,
        allow_repeated_kills=allow_repeated_kills,
        check_lucky_consider_probe=check_lucky_consider_probe,
        allow_relative_level_target=allow_relative_level_target,
    )
    if len(cache) >= 8192:
        cache.clear()
    cache[key] = result
    return result


def _source_ranked_fame_fixed_route_failed(
    state: Mapping[str, Any],
    mobile_vnum: int,
) -> bool:
    """Keep a dynamic probe from replaying a failed fixed fame route."""
    policy_ids = _FAME_RECOVERY_FIXED_MOBILE_POLICIES.get(mobile_vnum, ())
    if not policy_ids:
        return False
    results = _campaign_research_results(state)
    boot_id = state.get("world_boot_id")
    return any(
        isinstance(result, Mapping)
        and result.get("boot_id") == boot_id
        and result.get("completed_kill") is not True
        for policy_id in policy_ids
        for result in (results.get(policy_id),)
    )


def _source_ranked_fame_level_window(
    candidate: HuntCandidate,
    *,
    character_level: int,
    awards_fame: bool,
    maximum_level_delta: int | None = None,
) -> tuple[int, int] | None:
    """Return the live levels that can award fame for a target.

    ``fight.c`` uses two fame branches: ordinary kills require a victim at
    least six levels above the player (a strict ``level_dif > 5``), while
    ``ACT_IS_FAMOUS`` victims award fame whenever they are less than ten
    levels below the player.  Keep the latter useful for progression by
    excluding the server's <= -5 low-XP floor.  The game imposes no upper
    level limit on either branch; callers may provide a smaller research
    horizon for a bounded campaign search.
    """
    minimum_level, maximum_level = candidate.estimated_level_range
    if awards_fame:
        useful_low = character_level - 4
    else:
        useful_low = character_level + _FAME_RECOVERY_MIN_LEVEL_DELTA
    useful_high = (
        100
        if maximum_level_delta is None
        else character_level + maximum_level_delta
    )
    low = max(1, minimum_level, useful_low)
    high = min(maximum_level, useful_high, 100)
    return (low, high) if low <= high else None


def _source_ranked_famous_gas_recovery_allowed(
    candidate: HuntCandidate,
    world: WorldSource,
    state: Mapping[str, Any],
) -> bool:
    """Prove the single famous gas target allowed to use healer recovery."""
    mobile = world.mobiles.get(candidate.mobile_vnum)
    return bool(
        mobile is not None
        and mobile.awards_fame
        and set(candidate.specials) == {"spec_breath_gas"}
        and set(candidate.autonomy_rejections)
        == {"target has special procedure spec_breath_gas"}
        and _source_ranked_healer_poison_recovery_allowed(
            candidate,
            state,
            source_world=world,
        )
    )


def _source_ranked_effective_output_actions(
    output: SourceCombatOutput,
    *,
    famous_gas_recovery: bool,
) -> int:
    """Return the finite action horizon admitted by the current contract."""
    try:
        actions = int(output.maximum_actions)
    except (TypeError, ValueError):
        return 0
    if not famous_gas_recovery:
        return actions
    return max(actions, _SOURCE_RANKED_FAMOUS_GAS_MAX_ACTIONS)


def _source_ranked_famous_gas_route_program_allowed(
    candidate: HuntCandidate,
    world: WorldSource,
    *,
    character_level: int,
) -> bool:
    """Reuse the bounded route-greeter audit for the exact gas exception.

    The route audit normally rejects any target special.  For this one
    source-proven fame target, remove only the target's already-audited gas
    rejection while retaining every route identity, level, and program gate.
    """
    if not candidate.route_preflight_hard_hazard:
        return True
    if set(candidate.specials) != {"spec_breath_gas"} or set(
        candidate.autonomy_rejections
    ) != {"target has special procedure spec_breath_gas"}:
        return False
    route_candidate = replace(
        candidate,
        specials=(),
        autonomy_rejections=(),
    )
    return _source_ranked_route_program_candidate_allowed(
        route_candidate,
        character_level=character_level,
        source_world=world,
        allow_sanctuary_protected_target=True,
    )


def _source_ranked_famous_gas_combat_output_revalidation_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Allow one exact Green Dragon retry after output materially improves."""
    if not (
        source_world is not None
        and _state_has_sanctuary_reserve(state)
        and _source_ranked_famous_gas_recovery_allowed(
            candidate,
            source_world,
            state,
        )
    ):
        return False
    # Ordinary output revalidation is retired for target admission. The exact
    # famous-gas maintenance contract retains its separately audited,
    # source-backed improved-output exception, so call the evidence parser
    # directly rather than widening the ordinary selector.
    return (
        _source_ranked_combat_output_revalidation_details(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
            allow_famous_gas_recovery=True,
        )
        is not None
    )


def _source_ranked_fame_recovery_candidate_allowed(
    candidate: HuntCandidate,
    world: WorldSource,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
) -> bool:
    """Return whether one source mobile can be a bounded fame probe.

    Ordinary targets use DD4's strict +6-or-more fame window; the game does
    not impose an upper target-level limit. ``ACT_IS_FAMOUS`` targets use the
    source's separate less-than-ten-level-below branch, but still stay above
    the low-XP floor. A famous gas target is the only special-procedure
    exception: it requires a source-proven passive healer recovery route and
    source-hazard preparation. Target HP and projected output remain evidence
    for the report, not admission gates.
    """
    if character_max_hp is None or character_max_hp <= 0:
        return False
    mobile = world.mobiles.get(candidate.mobile_vnum)
    if mobile is None:
        return False
    famous_gas_recovery = _source_ranked_famous_gas_recovery_allowed(
        candidate,
        world,
        state,
    )
    famous_gas_output_revalidation = (
        _source_ranked_famous_gas_combat_output_revalidation_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=world,
        )
        if famous_gas_recovery
        else False
    )
    if (
        candidate.is_coin_stash
        or (candidate.specials and not famous_gas_recovery)
        or candidate.equipped_weapons
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or candidate.route_hard_hazard_targets
    ):
        return False
    uses_sanctuary = _source_ranked_fame_candidate_uses_sanctuary(
        candidate,
        state=state,
        character_level=character_level,
        source_world=world,
    )
    route_program_preflight_allowed = (
        candidate.route_preflight_hard_hazard
        and _source_ranked_route_program_candidate_allowed(
            candidate,
            character_level=character_level,
            source_world=world,
            allow_sanctuary_protected_target=uses_sanctuary,
        )
    )
    if famous_gas_recovery:
        route_program_preflight_allowed = (
            route_program_preflight_allowed
            or _source_ranked_famous_gas_route_program_allowed(
                candidate,
                world,
                character_level=character_level,
            )
        )
    if (
        candidate.route_preflight_hard_hazard
        and not route_program_preflight_allowed
    ):
        return False
    if candidate.autonomy_rejections and not (
        famous_gas_recovery
        and set(candidate.autonomy_rejections)
        == {"target has special procedure spec_breath_gas"}
    ) and not candidate.target_selection_safe:
        return False
    if uses_sanctuary and not _state_has_sanctuary_reserve(state):
        return False
    if not _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=world,
        character_max_hp=character_max_hp,
    ):
        return False
    if (
        mobile.attack_programs
        or mobile.vnum in world.shopkeepers
        or bool(getattr(mobile, "costs_fame", False))
    ):
        return False
    if mobile.aggressive and not famous_gas_recovery:
        return False
    fame_level_window = _source_ranked_fame_level_window(
        candidate,
        character_level=character_level,
        awards_fame=mobile.awards_fame,
        maximum_level_delta=None,
    )
    if fame_level_window is None:
        return False
    _minimum_level, maximum_level = candidate.estimated_level_range
    if famous_gas_recovery and not (
        _source_ranked_protected_special_hp_fuzz_probe_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=world,
        )
        or famous_gas_output_revalidation
    ):
        return False
    if not _source_candidate_fits_movement(candidate, state, world=world):
        return False
    if candidate.requires_flight and state.get("affects") is not None:
        if not any(
            _state_has_active_affect(state.get("affects"), effect)
            for effect in ("fly", "levitation")
        ):
            return False
    # The source peak and critical estimate are retained on the stop for
    # reporting and post-fight analysis. A fresh live level/consider result,
    # source identity, route, and the character's own withdrawal floor decide
    # whether the fight continues.
    return True


def _source_ranked_fame_candidate_uses_sanctuary(
    candidate: HuntCandidate,
    state: Mapping[str, Any] | None = None,
    *,
    character_level: int | None = None,
    source_world: WorldSource | None = None,
) -> bool:
    """Return whether a source fame hazard needs protection preparation."""
    # A predicted peak or the target's HP range is evidence only. The famous
    # gas exception remains protection-gated because its source special can
    # poison the character before ordinary recovery is available.
    return set(candidate.specials) == {"spec_breath_gas"}


def _source_ranked_fame_output_hp_probe_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource,
) -> bool:
    """Permit a plain fame probe with an executable action and no HP gate."""
    if (
        not _state_has_sanctuary_reserve(state)
        or candidate.equipped_weapons
        or candidate.specials
        or not candidate.target_selection_safe
    ):
        return False
    return _source_ranked_caster_output_can_cover(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
        protected_incoming_damage=True,
    )


def _select_source_ranked_fame_recovery_candidate(
    candidates: Collection[HuntCandidate],
    world: WorldSource,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    ) -> HuntCandidate | None:
    """Choose one fresh, source-safe, high-level ordinary mobile for fame."""
    persisted = _source_ranked_candidate_from_record(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY),
        source_revision=state.get(_SOURCE_REVISION_KEY),
    )
    marker = state.get(_FAME_RECOVERY_SOURCE_RANKED_KEY)
    persisted_famous_gas_revalidation = bool(
        persisted is not None
        and _source_ranked_famous_gas_combat_output_revalidation_allowed(
            persisted,
            state,
            character_level=character_level,
            source_world=world,
        )
    )
    if (
        persisted is not None
        and isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == character_level
        and marker.get("policy_id")
        == _source_ranked_policy_id(
            persisted,
            character_level=character_level,
        )
        and state.get("campaign_last_policy") == marker.get("policy_id")
        and _source_ranked_fame_recovery_candidate_allowed(
            persisted,
            world,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
        )
        and (
            _source_ranked_result_status(
                persisted,
                state,
                character_level=character_level,
                allow_cooldown_retry=False,
            )
            == "fresh"
            or persisted_famous_gas_revalidation
        )
    ):
        return persisted

    choices: list[tuple[float, float, int, int, float, HuntCandidate]] = []
    last_policy_id = str(state.get("campaign_last_policy") or "")
    for candidate in candidates:
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        famous_gas_revalidation = (
            _source_ranked_famous_gas_combat_output_revalidation_allowed(
                candidate,
                state,
                character_level=character_level,
                source_world=world,
            )
        )
        result_status = _source_ranked_result_status(
            candidate,
            state,
            character_level=character_level,
            allow_cooldown_retry=False,
        )
        if (
            candidate.boot_kills >= 3
            or (policy_id == last_policy_id and not famous_gas_revalidation)
            or _source_ranked_fame_fixed_route_failed(
                state,
                candidate.mobile_vnum,
            )
            or _source_ranked_candidate_excluded_by_below_band_evidence(
                candidate,
                state,
                character_level=character_level,
            )
            or (result_status != "fresh" and not famous_gas_revalidation)
            or not _source_ranked_fame_recovery_candidate_allowed(
                candidate,
                world,
                state,
                character_level=character_level,
                character_max_hp=character_max_hp,
            )
        ):
            continue
        fame_level_window = _source_ranked_fame_level_window(
            candidate,
            character_level=character_level,
            awards_fame=bool(
                world.mobiles.get(candidate.mobile_vnum)
                and world.mobiles[candidate.mobile_vnum].awards_fame
            ),
            maximum_level_delta=None,
        )
        if fame_level_window is None:
            continue
        minimum_level, maximum_level = candidate.estimated_level_range
        possible_low, possible_high = fame_level_window
        possible_levels = max(0, possible_high - possible_low + 1)
        fuzz_width = max(1, maximum_level - minimum_level + 1)
        fame_probability = possible_levels / fuzz_width
        reward_per_step = max(0.0, float(candidate.score)) / max(
            1, len(candidate.route)
        )
        choices.append(
            (
                reward_per_step,
                fame_probability,
                -len(candidate.route),
                candidate.score,
                candidate,
            )
        )
    if not choices:
        return None
    return max(choices, key=lambda item: item[:-1])[-1]


def _source_ranked_candidate_needs_flight_refresh(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
) -> bool:
    """Require renewal when flight is absent or too close to expiring.

    A visible fly or levitation affect is authoritative for the current
    route. Its timer may be reported as zero while the effect is still live;
    the fastwalk controller will observe any later expiry and handle the
    return. Route-specific reserve checks are performed separately by
    ``_source_ranked_candidate_flight_reserve_too_short``.
    """
    if state.get("affects") is None:
        # An unknown affect snapshot is deliberately kept compatible with the
        # existing optimistic route behavior; the live fastwalk gate remains
        # the final authority.
        return False
    if not candidate.requires_flight:
        return False
    if not any(
        _state_has_active_affect(state.get("affects"), effect)
        for effect in ("fly", "levitation")
    ):
        return True
    if candidate.area_file.casefold() == "abyss.are":
        duration = _state_flight_duration(state.get("affects"))
        required_duration = _source_ranked_candidate_required_flight_duration(
            candidate
        )
        if (
            duration is not None
            and required_duration is not None
            and duration < required_duration
        ):
            return True
    return False


def _source_ranked_candidate_required_flight_duration(
    candidate: HuntCandidate,
) -> int | None:
    """Return the affect reserve required to complete a source-ranked route."""
    if not candidate.requires_flight or candidate.estimated_flying_move_cost <= 0:
        return None
    route_steps = max(1, len(candidate.route))
    # DD4 decrements affects once per 30-second PULSE_TICK. The source
    # ``get_move_ws`` returns one pulse for ordinary flying movement and
    # ``PULSE_PER_SECOND`` is four, so count a quarter-second per route step
    # and keep one extra tick as a latency/combat reserve. Open-door commands
    # are included in ``route_steps`` conservatively.
    required_duration = max(
        2,
        math.ceil(route_steps * 0.25 / 30.0) + 1,
    )
    if candidate.area_file.casefold() == "abyss.are":
        # Every Abyss room is an air sector and its randomized search can use
        # most of a bounded segment. A level-30 potion grants 33 ticks; retain
        # enough time for the search plus the source-proven four-step return.
        required_duration = max(required_duration, 16)
    return required_duration


def _source_ranked_candidate_flight_reserve_too_short(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
) -> bool:
    """Require more than the minimum timer before dispatching a flight route."""
    if not candidate.requires_flight:
        return False
    reserve = _source_ranked_candidate_required_flight_duration(candidate)
    duration = _state_flight_duration(state.get("affects"))
    return bool(
        reserve is not None
        and duration is not None
        and duration > 0
        and duration <= reserve
    )


def _campaign_verified_flight_fallback_available(
    state: Mapping[str, Any],
) -> bool:
    """Keep aerial candidates eligible when a live minimum flight reserve exists.

    Candidate-specific flight-duration checks still run before dispatch.
    """
    duration = _state_flight_duration(state.get("affects"))
    return duration is not None and duration >= 2


def _repair_movement_limited_flight_funding(
    state: Mapping[str, Any],
    segments: Collection[Mapping[str, Any]],
    *,
    storage: RunStorage,
) -> dict[str, Any]:
    """Fund optional flight after a productive trip proves walking is limiting it."""
    updated = dict(state)
    if (
        not state.get("world_boot_id")
        or state.get(_FLIGHT_FUNDING_REQUIRED_KEY)
        or state.get("affects") is None
        or any(
            _state_has_active_affect(state.get("affects"), name)
            for name in ("fly", "levitation")
        )
        or any(
            _skill_levels_from_state(state).get(name, 0) > 0
            for name in ("fly", "levitation")
        )
    ):
        return updated
    prior = state.get("campaign_optional_flight_evidence")
    prior_run = prior.get("run_id", 0) if isinstance(prior, Mapping) else 0
    if type(prior_run) is not int:
        return updated
    recent = sorted(
        (dict(row) for row in segments),
        key=lambda row: int(row["id"]), reverse=True,
    )[:8]
    for segment in recent:
        run_id = segment.get("run_id")
        if (
            type(run_id) is not int
            or run_id <= prior_run
            or segment.get("status") != "success"
            or not str(segment.get("phase") or "").startswith(_SOURCE_RANKED_POLICY_PREFIX)
        ):
            continue
        try:
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, ValueError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        if (
            any(
                type(snapshot.get("xp")) not in (int, float)
                or not math.isfinite(snapshot["xp"])
                for snapshot in (start, end)
            )
            or start.get("world_boot_id") != state.get("world_boot_id")
            or end.get("world_boot_id") != state.get("world_boot_id")
            or _level(start) != _level(state) or _level(end) != _level(state)
            or start.get("affects") is None
            or any(
                _state_has_active_affect(start.get("affects"), name)
                for name in ("fly", "levitation")
            )
            or _xp_delta(start, end) < _MEANINGFUL_FIELD_SEGMENT_XP
            or any(end.get(key) for key in (
                "dead", "campaign_died_during_segment", "xp_loss_observed",
                "campaign_xp_loss_observed",
            ))
            or not _segment_objective_kills(storage, segment)
        ):
            continue
        candidate = _source_ranked_candidate_from_record(
            start.get(_SOURCE_RANKED_CANDIDATE_KEY)
        )
        if (
            candidate is None
            or not _source_ranked_candidate_benefits_from_flight(candidate)
        ):
            continue
        home = _run_latest_state(storage, run_id) or {}
        if (
            str(home.get("room_vnum")) != "3054" or home.get("dead")
            or home.get("in_combat") or home.get("position") not in {4, 5, 7}
            or "enemies" not in home or not _enemy_snapshot_empty(home["enemies"])
            or _numeric_progress(dict(home), "hp") <= 0
        ):
            continue
        for row in storage.list_state_snapshots(run_id, limit=512):
            try:
                observed = json.loads(row["state_json"])
            except (TypeError, ValueError):
                continue
            if not isinstance(observed, Mapping):
                continue
            move, hp, maximum_hp = (
                observed.get(key) for key in ("move", "hp", "max_hp")
            )
            if (
                all(
                    type(value) in (int, float) and math.isfinite(value)
                    for value in (move, hp, maximum_hp)
                )
                and 0 <= move <= 8 and maximum_hp > 0 and hp >= maximum_hp * 0.8
                and str(observed.get("room_vnum")) not in {"None", "3054", "3001"}
                and not observed.get("in_combat") and observed.get("position") == 7
                and not observed.get("dead")
            ):
                updated["campaign_optional_flight_evidence"] = {
                    "boot_id": state.get("world_boot_id"), "level": _level(state),
                    "run_id": run_id, "policy_id": segment["phase"],
                    "snapshot_id": row["id"], "field_movement": move,
                    "ground_cost": candidate.estimated_move_cost,
                    "flying_cost": candidate.estimated_flying_move_cost,
                    "reason": "productive healthy field trip exhausted walking movement",
                }
                updated[_FLIGHT_FUNDING_REQUIRED_KEY] = True
                updated[_FLIGHT_FUNDING_RETRY_KEY] = True
                return updated
    return updated


def _source_ranked_candidate_benefits_from_flight(
    candidate: HuntCandidate,
) -> bool:
    """Return whether optional flight materially shortens a safe ground route."""
    ground_cost = candidate.estimated_move_cost
    flying_cost = candidate.estimated_flying_move_cost
    return bool(
        not candidate.requires_flight
        and ground_cost >= _OPTIONAL_FLIGHT_MINIMUM_GROUND_COST
        and flying_cost > 0
        and ground_cost - flying_cost >= _OPTIONAL_FLIGHT_MINIMUM_SAVINGS
    )


def _source_ranked_level_ceiling_probe_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    character_max_hp: int | None,
) -> bool:
    """Allow a source-supported probe through the +5 consider band."""
    del character_max_hp
    if candidate.is_coin_stash or not candidate.autonomous_safe:
        return False
    if not character_level < candidate.level <= character_level + 5:
        return False
    if candidate.estimated_level_range[0] <= character_level - 5:
        return False
    if candidate.estimated_level_range[1] <= character_level + 1:
        return False
    return True


def _source_ranked_nominal_level_fuzz_probe_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    character_max_hp: int | None,
) -> bool:
    """Allow a nominal-current-level target through one source-fuzz step."""
    del character_max_hp
    if candidate.is_coin_stash or not candidate.autonomous_safe:
        return False
    if candidate.level != character_level:
        return False
    if not (
        character_level + 1
        < candidate.estimated_level_range[1]
        <= character_level + 2
    ):
        return False
    if candidate.estimated_level_range[0] <= character_level - 5:
        return False
    if candidate.autonomy_rejections or candidate.specials:
        return False
    return True


def _source_ranked_level_ceiling_probe_in_current_band(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    world: WorldSource | None = None,
    character_level: int,
    character_max_hp: int | None,
    allow_repeated_kills: bool = False,
) -> bool:
    """Apply reboot, movement, and useful-XP gates to a ceiling probe."""
    if not _source_ranked_level_ceiling_probe_allowed(
        candidate,
        character_level=character_level,
        character_max_hp=character_max_hp,
    ):
        return False
    return not (
        (candidate.boot_kills >= 3 and not allow_repeated_kills)
        or not _source_candidate_fits_movement(
            candidate,
            state,
            world=world,
        )
        or _funding_candidate_is_below_band(
            dict(state),
            candidate,
            character_level=character_level,
            boot_id=state.get("world_boot_id"),
        )
    )


_SOURCE_CAPACITY_RESEARCH_RE = re.compile(
    r"target reset permits up to \d+ matching mobiles in the room"
)
_SOURCE_CAPACITY_RESEARCH_MAX_RESET_ENTRIES = 2
_SOURCE_CAPACITY_RESEARCH_MAX_GLOBAL_POPULATION = 4


def _source_ranked_candidate_requires_sanctuary(
    candidate: HuntCandidate,
) -> bool:
    """Return whether the audited special needs a protection reserve first."""
    specials = set(candidate.specials)
    if specials == {"spec_poison"} and candidate.equipped_weapons:
        # An armed poison target can force an immediate combat withdrawal once
        # nausea lands. Require the available Sanctuary reserve up front so a
        # failed poison exchange does not turn into an XP-losing recall.
        return True
    if (
        candidate.mobile_vnum == _SOURCE_MASTER_ELF_MOBILE_VNUM
        and candidate.room_vnum == _SOURCE_MASTER_ELF_ROOM_VNUM
        and specials in (
            {"spec_cast_undead"},
            {"spec_vampire", "spec_cast_undead"},
        )
    ):
        # The source table can choose harm, energy drain, or gate at level 40;
        # enter only with a verified Sanctuary reserve and keep one potion for
        # the healer-bound recovery path.
        return True
    if specials & (_SOURCE_SANCTUARY_SPECIALS | _SOURCE_BREATH_SPECIALS):
        return True
    # Fear becomes available at source level 15 and the druid can then
    # choose direct damage, fear, and eventually blindness. Treat that
    # source-level transition as a sanctuary frontier without classifying
    # lower-level flamestrike-only druids as protected hunts.
    return bool(
        specials == {"spec_cast_druid"}
        and candidate.estimated_level_range[1] >= 15
    )


def _source_ranked_low_reserve_route_retry_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Re-admit one source-audited route stopped only by low reserve.

    A dynamic low-reserve result is useful route evidence, not a reboot-scoped
    ban. Reopen it only while a Sanctuary reserve is carried and the source
    shape is still a singleton, current-band target with no hard route,
    program, special, crowd, or loss evidence. The live worker still owns
    every identity, consider, health-floor, combat, and return decision.
    """
    if source_world is None or not _state_has_sanctuary_reserve(state):
        return False
    if (
        not candidate.autonomous_safe
        or not candidate.target_selection_safe
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or candidate.specials
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or not candidate.route_aggressive_mobile_vnums
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
    ):
        return False
    minimum_level, maximum_level = candidate.estimated_level_range
    if not (
        character_level - 5 < minimum_level <= maximum_level <= character_level + 5
    ):
        return False
    try:
        route_vnums = {
            int(vnum) for vnum in candidate.route_aggressive_mobile_vnums
        }
    except (TypeError, ValueError):
        return False
    if not route_vnums or not route_vnums <= set(source_world.mobiles):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    route_hazard = result.get("route_hazard") if isinstance(result, Mapping) else None
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("observed") is False
        and result.get("viable") is False
        and result.get("retryable_failure") is True
        and result.get("transit_resume_revalidation_attempted") is not True
        and isinstance(route_hazard, str)
        and route_hazard.startswith(_SOURCE_RANKED_LOW_RESERVE_ROUTE_HAZARD_PREFIX)
        and not any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "crowd_exhausted",
                "fatal_failure",
                "completed_kill",
                "xp_loss_observed",
                "unattackable",
                "target_vnum_mismatch",
            )
        )
        and _source_ranked_xp_loss_record(state, policy_id) is None
    ):
        return False
    return True


def _source_ranked_transit_resume_revalidation_used(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Recognize the exact low-reserve route whose bounded retry was spent."""
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    return bool(
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and (
            result.get("transit_resume_revalidation_attempted") is True
            or result.get("transit_resume_revalidation_exhausted") is True
        )
        and isinstance(result.get("route_hazard"), str)
        and result["route_hazard"].startswith(
            _SOURCE_RANKED_LOW_RESERVE_ROUTE_HAZARD_PREFIX
        )
    )


def _source_ranked_candidate_requires_blindness_recovery_reserve(
    candidate: HuntCandidate,
) -> bool:
    """Return whether the opener can blind before healer recovery."""
    specials = set(candidate.specials)
    if specials & _SOURCE_SANCTUARY_SPECIALS:
        return True
    return bool(
        specials == {"spec_cast_druid"}
        and candidate.estimated_level_range[1] >= 18
    )


def _source_ranked_armed_target_requires_sanctuary(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int | None = None,
    source_world: WorldSource | None = None,
) -> bool:
    """Keep target weapon output as evidence, never an ordinary gate.

    The live target level and ``consider`` response select the encounter.
    The combat controller uses the player's own observed health floor while
    fighting; predicted target damage and the absence of Sanctuary do not
    veto an otherwise ordinary source target.
    """
    return False


def _source_ranked_equipped_weapon_for_state(
    state: Mapping[str, Any],
    source_world: WorldSource | None,
    *,
    slots: Collection[str],
    wear_locations: Collection[int],
    require_ranged: bool,
    fallback_state_key: str | None = None,
) -> Any | None:
    """Resolve one structured source weapon slot without guessing.

    Structured GMCP equipment is authoritative for both the primary wield and
    DD4's separate ranged-weapon slot.  Legacy descriptions are accepted only
    for a caller-provided slot when exactly one source prototype matches them;
    ambiguous display names remain unassessed.
    """
    if source_world is None:
        return None
    accepted_slots = {
        str(slot).casefold().replace(" ", "_") for slot in slots
    }
    accepted_wear_locations = {int(location) for location in wear_locations}
    raw_form = state.get("form")
    if raw_form is not None and str(raw_form).casefold() != "normal":
        # Natural-form equipment can hide or replace the carried weapon. Do
        # not let a stale pre-morph snapshot create physical output evidence.
        return None

    def parse_payload(value: Any) -> Any:
        if not isinstance(value, str):
            return value
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            return None

    def direct_weapon(
        value: Mapping[str, Any],
        parent_slot: str | None = None,
    ) -> Any | None:
        slot = str(value.get("slot", "")).casefold().replace(" ", "_")
        try:
            wear_loc = int(value.get("wear_loc"))
        except (TypeError, ValueError):
            wear_loc = None
        if (
            slot not in accepted_slots
            and parent_slot not in accepted_slots
            and wear_loc not in accepted_wear_locations
        ):
            return None
        try:
            vnum = int(value.get("vnum"))
        except (TypeError, ValueError):
            return None
        weapon = source_world.objects.get(vnum)
        if weapon is None or weapon.item_type != ITEM_WEAPON:
            return None
        is_ranged = item_category(weapon) == "ranged_weapon"
        if is_ranged != require_ranged:
            return None
        if len(weapon.values) <= 2:
            return None
        return weapon

    def walk(value: Any, parent_slot: str | None = None) -> Any | None:
        value = parse_payload(value)
        if isinstance(value, Mapping):
            if (weapon := direct_weapon(value, parent_slot)) is not None:
                return weapon
            for key, nested in value.items():
                key_name = str(key).casefold().replace(" ", "_")
                if isinstance(nested, (Mapping, list, tuple, str)):
                    nested_slot = (
                        key_name
                        if key_name in accepted_slots
                        else parent_slot
                    )
                    if (weapon := walk(nested, nested_slot)) is not None:
                        return weapon
        elif isinstance(value, (list, tuple)):
            for nested in value:
                if (weapon := walk(nested, parent_slot)) is not None:
                    return weapon
        return None

    if (weapon := walk(state.get("equipment"))) is not None:
        return weapon

    if fallback_state_key is None:
        return None
    fallback_description = state.get(fallback_state_key)
    if not isinstance(fallback_description, str):
        return None
    normalized_description = normalize_item_name(fallback_description)
    if not normalized_description:
        return None
    matches = []
    for weapon in source_world.objects.values():
        if weapon.item_type != ITEM_WEAPON:
            continue
        if (item_category(weapon) == "ranged_weapon") != require_ranged:
            continue
        if not (
            normalize_item_name(weapon.short_description)
            == normalized_description
            or normalize_item_name(weapon.keywords) == normalized_description
        ):
            continue
        if len(weapon.values) <= 2:
            continue
        matches.append(weapon)
    return matches[0] if len(matches) == 1 else None


def _source_ranked_primary_weapon_for_state(
    state: Mapping[str, Any],
    source_world: WorldSource | None,
) -> Any | None:
    """Resolve the currently wielded non-ranged source weapon."""
    return _source_ranked_equipped_weapon_for_state(
        state,
        source_world,
        slots=("wield", "weapon"),
        wear_locations=(16,),
        require_ranged=False,
        fallback_state_key="campaign_primary_weapon",
    )


def _source_ranked_straight_shifter_natural_weapon_for_state(
    state: Mapping[str, Any],
    source_world: WorldSource | None,
    *,
    known_skills: Collection[str],
    known_skill_levels: Mapping[str, int] | None,
) -> Any | None:
    """Resolve the source-created fangs for a straight shifter.

    ``sft.c:do_morph_snake`` creates object VNUM 59 and equips it in the
    wield slot.  A live snake form is direct evidence that this object exists;
    a normal-form checkpoint may project it only when the same morph and mana
    gates used by the starter can execute immediately.  Subclass forms are
    intentionally excluded because they have separate source lifecycles.
    """
    if source_world is None:
        return None
    character_class = state.get("character_class")
    if (
        not isinstance(character_class, str)
        or " ".join(character_class.casefold().split()) != "shifter"
        or _live_subclass(state) is not None
    ):
        return None
    raw_form = state.get("form")
    if raw_form is None:
        return None
    form = " ".join(str(raw_form).casefold().split())
    if form == "normal":
        skills = _source_known_skill_set(known_skills, known_skill_levels)
        if not {"morph", _STRAIGHT_SHIFTER_SNAKE_FORM_SKILL} <= skills:
            return None
        form_percent = _source_skill_percent(
            _STRAIGHT_SHIFTER_SNAKE_FORM_SKILL,
            skills,
            known_skill_levels,
        )
        if (
            isinstance(known_skill_levels, Mapping)
            and form_percent < _STRAIGHT_SHIFTER_MIN_FORM_PROFICIENCY
        ):
            return None
        try:
            mana = int(state.get("mana"))
        except (TypeError, ValueError):
            return None
        if isinstance(known_skill_levels, Mapping):
            try:
                learned = int(
                    next(
                        (
                            value
                            for raw_skill, value in known_skill_levels.items()
                            if " ".join(str(raw_skill).casefold().split())
                            == _STRAIGHT_SHIFTER_SNAKE_FORM_SKILL
                        ),
                        form_percent,
                    )
                )
            except (TypeError, ValueError):
                learned = form_percent
        else:
            learned = form_percent
        mana_cost = max(
            _STRAIGHT_SHIFTER_MIN_FORM_MANA,
            60 - learned,
        )
        if mana < mana_cost:
            return None
    elif form != _STRAIGHT_SHIFTER_SNAKE_FORM:
        return None

    weapon = source_world.objects.get(_STRAIGHT_SHIFTER_SNAKE_WEAPON_VNUM)
    if weapon is None or weapon.item_type != ITEM_WEAPON:
        return None
    if len(weapon.values) <= 2:
        return None
    try:
        minimum = int(weapon.values[1])
        maximum = int(weapon.values[2])
    except (TypeError, ValueError):
        return None
    if minimum <= 0 or maximum < minimum:
        return None
    return weapon


def _source_ranked_ranged_weapon_for_state(
    state: Mapping[str, Any],
    source_world: WorldSource | None,
) -> Any | None:
    """Resolve the currently equipped source bow without guessing."""
    return _source_ranked_equipped_weapon_for_state(
        state,
        source_world,
        slots=("ranged_weapon", "ranged", "bow"),
        wear_locations=(17, 21),
        require_ranged=True,
    )


def _source_ranked_state_stat(
    state: Mapping[str, Any],
    name: str,
    default: int | None = None,
) -> int | None:
    """Read a numeric stat from the structured live score snapshot."""
    stats = state.get("stats")
    if not isinstance(stats, Mapping):
        return default
    try:
        return int(stats.get(name))
    except (TypeError, ValueError):
        return default


def _source_ranked_level_ceiling_requires_sanctuary(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
    allow_unarmed_singleton_withdrawal: bool = False,
) -> bool:
    """Compatibility stub for the retired target-HP Sanctuary gate.

    Ordinary target admission is source-level plus live ``consider``. Keep
    this private hook harmless for older callers and serialized policies;
    source specials still use their own explicit hazard gates.
    """
    return False


_SOURCE_UNPROTECTED_HP_FUZZ_MAX_PEAK_RATIO = 0.80
_SOURCE_POST_LOSS_PLAIN_PROBE_MAX_PEAK_RATIO = 0.50
_SOURCE_POST_LOSS_PLAIN_HP_FUZZ_MAX_PEAK_RATIO = 0.65
_SOURCE_PROTECTED_HP_FUZZ_MAX_PEAK_RATIO = 0.80
_SOURCE_PROGRAM_PREFLIGHT_LEVEL_GAP = 2


def _source_ranked_resets_by_mobile(
    source_world: WorldSource | None,
) -> Mapping[int, tuple[MobReset, ...]]:
    """Index immutable reset rows once for the current selector pass."""
    if source_world is None:
        return {}
    cache = _CAMPAIGN_SOURCE_SELECTOR_CACHE.get()
    cache_key = ("resets-by-mobile", id(source_world))
    existing = cache.get(cache_key) if cache is not None else None
    if isinstance(existing, Mapping):
        return existing
    grouped: dict[int, list[MobReset]] = {}
    for reset in source_world.mob_resets:
        grouped.setdefault(reset.mobile_vnum, []).append(reset)
    indexed = {
        mobile_vnum: tuple(resets)
        for mobile_vnum, resets in grouped.items()
    }
    if cache is not None:
        cache[cache_key] = indexed
    return indexed


def _source_ranked_route_aggressors_are_bounded_uncached(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
    character_max_hp: int | None = None,
) -> bool:
    """Allow only typed, bounded route aggressors on an emergency probe.

    ``ACT_AGGRESSIVE`` is not enough to make a transit mobile equally risky.
    A level-2 swarm and DD4's source-defined fido can be incidental route
    noise, while an attack program, special procedure, or near-band mobile is
    a real combat hazard.  One source-proven level-4 fringe reset may also be
    defeated on the live below-band roll; multiple such interruptions remain
    closed. Keep the fallback fail-closed when source metadata is unavailable.
    """
    route_aggressors: set[int] = set()
    for raw_vnum in candidate.route_aggressive_mobile_vnums:
        if not str(raw_vnum).strip():
            continue
        try:
            mobile_vnum = int(raw_vnum)
        except (TypeError, ValueError):
            return False
        if mobile_vnum <= 0:
            return False
        route_aggressors.add(mobile_vnum)
    if not route_aggressors:
        return True
    if source_world is None:
        return False
    resets_by_mobile = _source_ranked_resets_by_mobile(source_world)
    borderline_vnums: set[int] = set()
    for mobile_vnum in route_aggressors:
        mobile = source_world.mobiles.get(mobile_vnum)
        if mobile is None:
            return False
        # A source-safe special such as spec_fido is not a combat route
        # hazard, but only when its reset placement is known. Missing reset
        # metadata remains fail-closed rather than silently proving safety.
        has_source_reset = any(
            reset.mobile_vnum == mobile_vnum
            for reset in resets_by_mobile.get(mobile_vnum, ())
        )
        if (
            has_source_reset
            and _source_mobile_safe_special_suppresses_route_hazard(
                source_world,
                mobile,
                character_level=character_level,
            )
        ):
            continue
        maximum_level = _mobile_level_range(mobile.level)[1]
        if (
            source_mobile_deep_transit_route_is_bounded(
                source_world,
                mobile,
                character_level=character_level,
                resets_by_mobile=resets_by_mobile,
            )
            or source_mobile_route_aggressor_level_only_is_bounded(
                source_world,
                mobile,
                character_level=character_level,
                resets_by_mobile=resets_by_mobile,
            )
        ):
            # Source level and reset/loadout evidence is sufficient to classify
            # a deeply below-band armed mobile as transit noise. The live
            # deployment may intentionally lack the unreleased template
            # damage modifiers; that uncertainty must not turn an old route
            # crossing into a target or a permanent route veto.
            continue
        if maximum_level <= character_level - 5:
            if source_mobile_route_aggressor_level_only_is_bounded(
                source_world,
                mobile,
                character_level=character_level,
                resets_by_mobile=resets_by_mobile,
            ):
                # Only the armed, source-bounded transit contract can remove
                # a below-band route veto.  Low damage estimates are evidence,
                # not a substitute for the loadout proof.
                continue
            return False
        if source_mobile_is_ordinary_below_level_aggressor(
            source_world,
            mobile,
            character_level=character_level,
        ):
            # A plain near-band mobile below the player's source level may
            # interrupt transit, but it is not a paper-only route veto. The
            # live runner still proves its identity, consider, crowd state,
            # and the player's own withdrawal floor.
            continue
        if character_max_hp is None or character_max_hp <= 0:
            return False
        if not any(
            _bounded_borderline_route_aggressor(
                source_world,
                reset,
                character_level=character_level,
                character_max_hp=character_max_hp,
            )
            for reset in resets_by_mobile.get(mobile_vnum, ())
        ):
            return False
        borderline_vnums.add(mobile_vnum)
    return len(borderline_vnums) <= 1


_SOURCE_RANKED_ROUTE_AGGRESSORS_ARE_BOUNDED_UNCACHED = (
    _source_ranked_route_aggressors_are_bounded_uncached
)


def _source_ranked_route_aggressors_are_bounded(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
    character_max_hp: int | None = None,
) -> bool:
    """Cache immutable route-aggressor proofs within one selector pass."""
    cache = _CAMPAIGN_SOURCE_SELECTOR_CACHE.get()
    route_aggressors = tuple(
        sorted(str(value) for value in candidate.route_aggressive_mobile_vnums)
    )
    cache_key = (
        "route-aggressors-bounded",
        id(source_world),
        route_aggressors,
        character_level,
        character_max_hp,
    )
    if (
        cache is not None
        and _CAMPAIGN_PREPARATION_DEADLINE.get() is not None
        and cache_key in cache
    ):
        return bool(cache[cache_key])
    result = _SOURCE_RANKED_ROUTE_AGGRESSORS_ARE_BOUNDED_UNCACHED(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    )
    if cache is not None and _CAMPAIGN_PREPARATION_DEADLINE.get() is not None:
        cache[cache_key] = result
    return result


_SOURCE_BOUNDED_TRANSIT_ROUTE_REJECTIONS = frozenset(
    {
        "below-band transit aggressor is not an XP target",
        "below-band wandering aggressor is not an XP target",
        _SOURCE_TARGET_CAPACITY_REJECTION,
    }
)


def _source_ranked_current_band_route_aggressor_count(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> int:
    """Count route mobiles whose source fuzz can reach useful XP levels.

    A route aggressor can remain admissible when its nominal source level is
    below the pilot.  That is useful evidence, not a clean-route guarantee:
    DD4's load fuzz can still put the mobile inside the live XP band.  Keep
    this as a ranking signal only; live identity, ``consider``, crowd, and
    health gates remain authoritative.
    """
    if source_world is None or character_level < 1:
        return 0
    route_vnums = {
        int(raw_vnum)
        for raw_vnum in (
            *candidate.route_aggressive_mobile_vnums,
            *candidate.route_attack_program_mobile_vnums,
        )
        if str(raw_vnum).strip().lstrip("-").isdigit()
    }
    route_vnums.discard(int(candidate.mobile_vnum))
    count = 0
    for mobile_vnum in route_vnums:
        mobile = source_world.mobiles.get(mobile_vnum)
        if mobile is None:
            continue
        minimum_level, maximum_level = _mobile_level_range(mobile.level)
        if (
            maximum_level >= character_level - 4
            and minimum_level <= character_level + 5
        ):
            count += 1
    return count


def _source_ranked_bounded_transit_route_target_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    character_max_hp: int,
    source_world: WorldSource | None,
) -> bool:
    """Admit a current-band target behind only bounded transit hazards.

    This is a route admission, not permission to attack the transit mobiles.
    StarterPolicy still verifies each live interruption, permits only its
    bounded one-at-a-time transit handling, and keeps the normal target
    identity, isolation, ``consider``, health-floor, and return checks. A
    harmless source special on the endpoint, such as ``spec_fido``, does not
    make an otherwise ordinary route unsafe.
    """
    rejections = set(candidate.autonomy_rejections)
    capacity_research_marker = (
        _SOURCE_TARGET_CAPACITY_REJECTION in rejections
        and rejections <= _SOURCE_BOUNDED_TRANSIT_ROUTE_REJECTIONS
    )
    if (
        source_world is None
        or character_max_hp <= 0
        or candidate.is_coin_stash
        or (
            (not candidate.target_selection_safe or not candidate.autonomous_safe)
            and not capacity_research_marker
        )
        or candidate.route_hard_hazard_targets
        or candidate.route_preflight_hard_hazard
        or candidate.route_special_mobile_vnums
        or candidate.route_attack_program_mobile_vnums
        or not candidate.route_aggressive_mobile_vnums
    ):
        return False
    if not rejections <= _SOURCE_BOUNDED_TRANSIT_ROUTE_REJECTIONS:
        return False
    # Current source ranking can retain the route hazard in structured fields
    # without adding the legacy synthetic rejection. The bounded source proof
    # below is the authority; an empty rejection set is valid here.
    minimum_level, maximum_level = candidate.estimated_level_range
    if not (
        maximum_level > character_level - 5
        and minimum_level <= character_level + 5
        and maximum_level <= character_level + 5
    ):
        return False
    endpoint = source_world.mobiles.get(candidate.mobile_vnum)
    endpoint_specials = {
        str(special).strip().casefold()
        for special in (
            candidate.specials
            or source_world.mobile_specials.get(candidate.mobile_vnum, ())
        )
    }
    if (
        endpoint is None
        or endpoint.aggressive
        or endpoint.programs
        or endpoint.attack_programs
        or not endpoint_specials <= SAFE_NONCOMBAT_SPECIALS
        or endpoint.non_corporeal
        or endpoint.fear_aura
        or endpoint.costs_fame
        or endpoint.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
    ):
        return False
    route_rooms = _source_route_room_vnums(
        source_world,
        candidate.route_origin_room_vnum,
        candidate.route,
    )
    if not route_rooms or route_rooms[-1] != candidate.room_vnum:
        return False
    return _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    )


_SOURCE_INVISIBILITY_ROUTE_REJECTION = (
    "route crosses an aggressive transit attacker inside the transit-risk band"
)
_SOURCE_INVISIBILITY_USEFUL_BAND_ROUTE_REJECTION = (
    "route crosses an aggressive reset inside the useful XP band"
)
_SOURCE_INVISIBILITY_WANDERER_REJECTION = (
    "an aggressive wanderer inside the transit-risk band can reach the route"
)
_SOURCE_INVISIBILITY_TARGET_REJECTION = "target is aggressive"
_SOURCE_INVISIBILITY_ROUTE_REJECTIONS = frozenset(
    {
        _SOURCE_INVISIBILITY_ROUTE_REJECTION,
        _SOURCE_INVISIBILITY_USEFUL_BAND_ROUTE_REJECTION,
        _SOURCE_INVISIBILITY_WANDERER_REJECTION,
    }
)


def _source_ranked_plain_aggressive_target_invisibility_allowed(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
) -> bool:
    """Return whether source invisibility blocks the endpoint target's aggression.

    A plain aggressive target can initiate combat on room entry, before live
    ``consider`` has a chance to select an opener. Keep this exception narrow:
    scripted, special, detection-capable, and otherwise unparsed mobiles do
    not become safe merely because the player can cast invisibility.
    """
    if source_world is None:
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    return bool(
        mobile is not None
        and mobile.aggressive
        and not mobile.attack_programs
        and not mobile.programs
        and not source_world.mobile_specials.get(mobile.vnum)
        and invisibility_blocks_source_aggression(source_world, mobile.vnum)
    )


def _source_ranked_unarmed_aggressive_hp_fuzz_probe_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Allow one live-bounded probe against a plain, singleton aggressor."""
    if source_world is None:
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if not (
        mobile is not None
        and mobile.aggressive
        and not mobile.programs
        and not mobile.attack_programs
        and not source_world.mobile_specials.get(mobile.vnum)
        and candidate.sentinel
        and candidate.status != "reject"
        and candidate.autonomous_safe
        and candidate.source_spawn_limit == 1
        and candidate.room_spawn_count == 1
        and not candidate.equipped_weapons
        and not candidate.specials
        and not candidate.route_hard_hazard_targets
        # A close source-level range may straddle the useful-XP floor. Let
        # live ``consider`` decide that case rather than rejecting it from
        # the low end of the parser's fuzz range.
        and candidate.estimated_level_range[1] > character_level - 5
        and candidate.estimated_level_range[1] <= character_level + 5
    ):
        return False
    if (
        candidate.estimated_level_range[0] <= character_level - 5
        and not _source_ranked_invisibility_route_candidate_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    ):
        return False
    probe_state = state
    if (
        character_max_hp is not None
        and character_max_hp > 0
        and not isinstance(state.get("max_hp"), (int, float))
    ):
        probe_state = {**state, "max_hp": character_max_hp}
    return _source_ranked_unprotected_hp_fuzz_probe_allowed(
        candidate,
        probe_state,
        character_level=character_level,
        source_world=source_world,
    )


def _source_ranked_route_invisibility_mobile_vnums(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
) -> tuple[int, ...]:
    """Return audited aggressive mobiles that require fresh route invisibility."""
    mobile_vnums = set(candidate.route_aggressive_mobile_vnums)
    if _source_ranked_plain_aggressive_target_invisibility_allowed(
        candidate,
        source_world,
    ):
        mobile_vnums.add(candidate.mobile_vnum)
    return tuple(sorted(mobile_vnums))


def _source_ranked_candidate_route_invisibility_source_vnums(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> tuple[int, ...]:
    """Resolve route-invisibility identities before the affect is active.

    Route safety is source-derived. Use a short synthetic visibility receipt
    only to evaluate that static contract; live dispatch still requires the
    actual affect or a verified potion/spell.
    """
    if (
        source_world is not None
        and _source_ranked_cyclops_smithy_visibility_marker_active(
            state,
            candidate,
            character_level=character_level,
        )
        and _source_ranked_cyclops_smithy_route_risk_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
            allow_visibility_route_revalidation=True,
        )
    ):
        # The exact Smithy route is already covered by its source-audited
        # Sanctuary transit contract. Do not add the unrelated generic
        # invisibility requirement that caused the prior no-combat abort.
        return ()
    if source_world is None:
        return _source_ranked_hunt_route_invisibility_mobile_vnums(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    visibility_state = dict(state)
    if not _state_has_active_affect(state.get("affects"), "invis"):
        affects = list(state.get("affects") or ())
        affects.append({"name": "invis", "duration": "1"})
        visibility_state["affects"] = affects
    if not _source_ranked_invisibility_route_candidate_allowed(
        candidate,
        visibility_state,
        character_level=character_level,
        source_world=source_world,
    ):
        if not _source_ranked_plain_aggressive_target_invisibility_allowed(
            candidate,
            source_world,
        ):
            return ()
    return _source_ranked_route_invisibility_mobile_vnums(candidate, source_world)


def _source_ranked_candidate_required_invisibility_duration(
    candidate: HuntCandidate,
) -> int:
    """Reserve enough invisibility for a long source-ranked route."""
    route_steps = max(1, len(candidate.route))
    return max(2, min(30, math.ceil(route_steps / 4)))


def _source_ranked_invisibility_route_candidate_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Admit a source-ranked route whose aggression is blocked by invisibility."""
    if (
        source_world is not None
        and not _state_has_active_affect(state.get("affects"), "invis")
        and _source_ranked_carried_route_invisibility_potion(
            state,
            source_world,
        )
    ):
        # The route builder quaffs this exact, source-verified potion at the
        # healer before departure. Treat that pending activation as a static
        # capability here; live route checks still require the real affect.
        prepared_state = dict(state)
        prepared_affects = list(state.get("affects") or ())
        prepared_affects.append({"name": "invis", "duration": "1"})
        prepared_state["affects"] = prepared_affects
        state = prepared_state
    rejections = set(candidate.autonomy_rejections)
    target_invisibility = (
        _source_ranked_plain_aggressive_target_invisibility_allowed(
            candidate,
            source_world,
        )
    )
    allowed_rejections = set(_SOURCE_INVISIBILITY_ROUTE_REJECTIONS)
    # A bounded below-band aggressor is still a hard stop for an ordinary
    # XP route. A fresh, source-verified invisibility route is different: it
    # is allowed only when every such route aggressor is one that source
    # evidence proves invisibility will block, so the bot can pass without
    # making a low-value kill.
    allowed_rejections.update(
        {
            "below-band transit aggressor is not an XP target",
            "below-band wandering aggressor is not an XP target",
        }
    )
    if target_invisibility:
        allowed_rejections.add(_SOURCE_INVISIBILITY_TARGET_REJECTION)
    invisibility_vnums = _source_ranked_route_invisibility_mobile_vnums(
        candidate,
        source_world,
    )
    if (
        source_world is None
        or not invisibility_vnums
        or (not rejections and not target_invisibility)
        or not rejections <= allowed_rejections
        or candidate.route_hard_hazard_targets
    ):
        return False
    if (
        candidate.route_attack_program_mobile_vnums
        and not _source_ranked_route_program_preflight_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
        )
    ):
        return False
    mana_cost = learned_invisibility_mana_cost(
        str(state.get("character_class") or ""),
        _live_subclass(state),
        _skill_levels_from_state(state),
    )
    if _state_has_active_affect(state.get("affects"), "invis"):
        # A source-verified carried potion is a real route capability.  The
        # old gate only accepted a learned spell, so a Warrior who had just
        # quaffed a verified potion was still filtered out before live route
        # selection could use the active affect.
        return all(
            source_invisibility_blocks_mobile_aggression(
                source_world,
                mobile_vnum,
                audit_equipment=True,
            )
            for mobile_vnum in invisibility_vnums
        )
    mana = state.get("mana")
    if (
        mana_cost is None
        or not isinstance(mana, (int, float))
        or isinstance(mana, bool)
        or mana < mana_cost
    ):
        return False
    return all(
        source_invisibility_blocks_mobile_aggression(
            source_world,
            mobile_vnum,
            audit_equipment=True,
        )
        for mobile_vnum in invisibility_vnums
    )


def _source_ranked_hunt_route_invisibility_mobile_vnums(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> tuple[int, ...]:
    """Require invisibility unless an exact combat proof safely covers entry."""
    raw_max_hp = state.get("max_hp")
    character_max_hp = (
        int(raw_max_hp)
        if isinstance(raw_max_hp, (int, float))
        and not isinstance(raw_max_hp, bool)
        and raw_max_hp > 0
        else None
    )
    if (
        _source_ranked_no_decision_route_revalidation_pending(
            state,
            candidate,
            character_level=character_level,
        )
        or _source_ranked_no_decision_route_revalidation_dispatch_active(
            state,
            candidate,
            character_level=character_level,
        )
    ):
        # The one-shot repair re-tests a loss-free route that previously
        # reached neither target identity nor live consider. Keep its ordinary
        # route-risk and live combat checks, but do not turn that repair into
        # an impossible invisibility prerequisite for this class.
        return ()
    if (
        _source_ranked_plain_armed_transit_mobile_vnums(
            candidate,
            source_world,
            character_level=character_level,
            character_max_hp=character_max_hp,
        )
        or _source_ranked_unarmed_endpoint_armed_transit_mobile_vnums(
            candidate,
            source_world,
            character_level=character_level,
            character_max_hp=character_max_hp,
        )
        or _source_ranked_cyclops_torturer_route_risk_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    ):
        # This route has its own Sanctuary-backed one-enemy transit contract;
        # invisibility is neither required nor a substitute for that live
        # isolation check.
        return ()
    if _source_ranked_plain_sentinel_risk_revalidation_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
        source_world=source_world,
        allow_dispatched_marker=True,
    ):
        # The exact one-shot risk receipt intentionally skips the generic
        # invisibility preparation step. The target is still checked live
        # for identity, isolation, consider, and the player's health floor.
        return ()
    preparation_marker = state.get(
        _SOURCE_RANKED_PREPARATION_ABORT_REVALIDATION_KEY
    )
    preparation_dispatch_active = bool(
        isinstance(preparation_marker, Mapping)
        and preparation_marker.get("policy_id")
        == _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        and preparation_marker.get("status") == "attempted"
        and preparation_marker.get("target_dispatch_started") is True
        and preparation_marker.get("boot_id") == state.get("world_boot_id")
        and preparation_marker.get("level") == character_level
        and preparation_marker.get("source_revision")
        == state.get(_SOURCE_REVISION_KEY)
        and state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY)
        == _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
    )
    wanderer_marker = state.get(
        _SOURCE_RANKED_WANDERER_NO_INVIS_REVALIDATION_KEY
    )
    wanderer_dispatch_active = bool(
        isinstance(wanderer_marker, Mapping)
        and wanderer_marker.get("policy_id")
        == _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        and wanderer_marker.get("status") == "attempted"
        and wanderer_marker.get("target_dispatch_started") is True
        and wanderer_marker.get("boot_id") == state.get("world_boot_id")
        and wanderer_marker.get("level") in {None, character_level}
        and wanderer_marker.get("source_revision")
        == state.get(_SOURCE_REVISION_KEY)
        and state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY)
        == _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
    )
    frontier_risk_marker = state.get(
        _SOURCE_RANKED_FRONTIER_RISK_REVALIDATION_KEY
    )
    frontier_risk_dispatch_active = bool(
        isinstance(frontier_risk_marker, Mapping)
        and frontier_risk_marker.get("policy_id")
        == _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        and frontier_risk_marker.get("status") == "attempted"
        and frontier_risk_marker.get("target_dispatch_started") is True
        and frontier_risk_marker.get("boot_id") == state.get("world_boot_id")
        and frontier_risk_marker.get("level") in {None, character_level}
        and frontier_risk_marker.get("source_revision")
        == state.get(_SOURCE_REVISION_KEY)
    )
    if (
        _source_ranked_plain_route_risk_fallback_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=source_world,
        )
        and (
            _source_ranked_result_status(
                candidate,
                state,
                character_level=character_level,
            ) == "fresh"
            or _source_ranked_preparation_abort_revalidation_pending(
                state,
                candidate,
                character_level=character_level,
            )
            or _source_ranked_no_decision_route_revalidation_pending(
                state,
                candidate,
                character_level=character_level,
            )
            or preparation_dispatch_active
            or wanderer_dispatch_active
            or frontier_risk_dispatch_active
        )
    ):
        # This exact fresh plain route is deliberately testing ordinary live
        # transit risk. Do not turn its source warning into an unavailable
        # invisibility requirement; the fastwalk still checks each route
        # mobile and the player's health floor before continuing.
        return ()
    if _source_ranked_invisibility_route_candidate_allowed(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
    ):
        return _source_ranked_route_invisibility_mobile_vnums(
            candidate,
            source_world,
        )
    if not _source_ranked_plain_aggressive_target_invisibility_allowed(
        candidate,
        source_world,
    ):
        return ()
    if _source_ranked_unarmed_aggressive_hp_fuzz_probe_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
        source_world=source_world,
    ):
        return ()
    if candidate.equipped_weapons and character_max_hp is not None:
        # The singleton opener is the separate Sanctuary-backed armed
        # contract. Unarmed sentinels use the HP-fuzz proof above; leaving
        # this branch unarmed would let a stale singleton proof bypass its
        # current live-probe evidence.
        if _source_ranked_aggressive_singleton_consider_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=source_world,
        ):
            return ()
    if _source_ranked_aggressive_wanderer_endpoint_no_invisibility_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
        source_world=source_world,
    ):
        return ()
    return (candidate.mobile_vnum,)


def _source_ranked_route_invisibility_unavailable(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Reject a route that needs true invisibility the character cannot cast."""
    if not _source_ranked_candidate_route_invisibility_source_vnums(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
    ):
        return False
    if _source_ranked_carried_route_invisibility_potion(state, source_world):
        return False
    if (
        learned_invisibility_mana_cost(
            str(state.get("character_class") or ""),
            _live_subclass(state),
            _skill_levels_from_state(state),
        )
        is not None
    ):
        return False
    if not _state_has_active_affect(state.get("affects"), "invis"):
        return True
    duration = _named_affect_duration(state.get("affects"), "invis")
    return bool(
        duration is None
        or duration
        < _source_ranked_candidate_required_invisibility_duration(candidate)
    )


def _source_ranked_invisibility_preparation_retry_available(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Allow one route retry after the exact invisibility capability is ready."""
    if source_world is None:
        return False
    if not _source_ranked_candidate_route_invisibility_source_vnums(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
    ):
        return False
    if _source_ranked_carried_route_invisibility_potion(state, source_world):
        return True
    duration = _named_affect_duration(state.get("affects"), "invis")
    return bool(
        duration is not None
        and duration
        >= _source_ranked_candidate_required_invisibility_duration(candidate)
    )


def _source_ranked_carried_route_invisibility_potion(
    state: Mapping[str, Any],
    source_world: WorldSource | None,
) -> bool:
    """Recognize the exact source potion reserved for the next field route."""
    if source_world is None:
        return False
    item = source_world.objects.get(ROUTE_INVISIBILITY_OBJECT_VNUM)
    if item is None or item.item_type != ITEM_POTION:
        return False
    if potion_spell_names(item)[:1] != ("invis",):
        return False
    description = normalize_item_name(item.short_description)
    return any(
        normalize_item_name(value) == description
        for value in _inventory_descriptions(state.get("inventory"))
    )


def _source_ranked_route_invisibility_supply_available(
    state: Mapping[str, Any],
    source_world: WorldSource | None,
) -> bool:
    """Keep potion-unlocked routes visible to the capability planner."""
    if source_world is None:
        return False
    if _source_ranked_carried_route_invisibility_potion(state, source_world):
        return True
    prior = state.get(ROUTE_INVISIBILITY_SUPPLY_KEY)
    refresh_stale_acquisition = bool(
        isinstance(prior, Mapping)
        and prior.get("status") in {"attempted", "acquired"}
        and not _source_ranked_carried_route_invisibility_potion(
            state,
            source_world,
        )
    )
    return (
        route_invisibility_supply(
            source_world,
            state,
            carried_descriptions=_inventory_descriptions(
                state.get("inventory")
            ),
            ignore_attempt=refresh_stale_acquisition,
        )
        is not None
    )


def _source_ranked_selected_candidate_invisibility_supply(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> RouteInvisibilitySupply | None:
    """Return the verified potion needed before a selected route can depart."""
    if source_world is None or not _source_ranked_route_invisibility_unavailable(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
    ):
        return None
    return route_invisibility_supply(
        source_world,
        state,
        carried_descriptions=_inventory_descriptions(state.get("inventory")),
        ignore_attempt=True,
    )


def _source_ranked_route_program_mobile_vnums(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
) -> tuple[Any, ...]:
    """Resolve the audited route-program identity for a candidate."""
    raw_program_vnums = candidate.route_attack_program_mobile_vnums
    if raw_program_vnums:
        return tuple(raw_program_vnums)
    if not (candidate.is_food_stash or candidate.is_coin_stash):
        return ()
    target = candidate.route_preflight_target
    if source_world is None or not target or not candidate.route_preflight_command:
        return ()
    normalized_target = _source_ranked_normalized_target(target)
    matching_mobile_vnums = tuple(
        mobile.vnum
        for mobile in source_world.mobiles.values()
        if mobile.attack_programs
        and _source_ranked_normalized_target(mobile.short_description)
        == normalized_target
    )
    return matching_mobile_vnums if len(matching_mobile_vnums) == 1 else ()


def _source_ranked_route_program_preflight_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Allow one low-band probabilistic greet program behind ``where``.

    DD4's Midgaard drunk is a level-2 ``greet_prog 10`` mobile that can issue
    ``mpkill``.  Treating every source program as an automatic route death
    strands otherwise plain targets, but allowing a program without a live
    locator is unsafe.  The candidate must therefore carry one exact source
    mobile, a source-matched ``where`` preflight starting at its recall origin,
    and a route-room map that the StarterBot can check before departure.
    Deterministic, near-band, multi-program, legacy, or malformed records fail
    closed.
    """
    raw_program_vnums = _source_ranked_route_program_mobile_vnums(
        candidate,
        source_world,
    )
    if source_world is None or not raw_program_vnums:
        return False
    try:
        program_vnums = tuple(sorted({int(vnum) for vnum in raw_program_vnums}))
    except (TypeError, ValueError):
        return False
    family_preflight = bool(
        len(program_vnums) > 1
        and source_mobile_route_program_family_is_preflight_safe(
            source_world,
            program_vnums,
            character_level=character_level,
        )
    )
    if not program_vnums or len(program_vnums) > 1 and not family_preflight:
        return False
    mobile = source_world.mobiles.get(program_vnums[0])
    if mobile is None or not mobile.attack_programs:
        return False
    if family_preflight:
        source_ranges = tuple(
            _mobile_level_range(source_world.mobiles[vnum].level)
            for vnum in program_vnums
        )
        source_level_range = (
            min(low for low, _ in source_ranges),
            max(high for _, high in source_ranges),
        )
    else:
        if _source_mobile_has_deterministic_attack_program(mobile):
            return False
        try:
            source_level_range = _mobile_level_range(mobile.level)
        except (TypeError, ValueError):
            return False
        if source_level_range[1] > (
            character_level - _SOURCE_PROGRAM_PREFLIGHT_LEVEL_GAP
        ):
            return False
    if not candidate.route_preflight_hard_hazard:
        return False
    if (
        candidate.route_preflight_room_vnum is None
        or str(candidate.route_preflight_room_vnum)
        != str(candidate.route_origin_room_vnum)
        or not candidate.route_preflight_command
        or not candidate.route_preflight_command.casefold().startswith("where ")
        or not candidate.route_preflight_target
        or _source_ranked_normalized_target(candidate.route_preflight_target)
        != _source_ranked_normalized_target(mobile.short_description)
        or tuple(candidate.route_preflight_level_range) != source_level_range
        or not candidate.route_preflight_route_room_names
    ):
        return False
    return True


def _source_ranked_route_program_scan_room_vnums(
    world: WorldSource,
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> tuple[str, ...]:
    """Return every room where the exact preflight mobile may intercept."""
    if not _source_ranked_route_program_preflight_allowed(
        candidate,
        character_level=character_level,
        source_world=world,
    ):
        return ()
    try:
        mobile_vnums = tuple(
            int(vnum)
            for vnum in _source_ranked_route_program_mobile_vnums(candidate, world)
        )
    except (TypeError, ValueError):
        return ()
    rooms: list[str] = []
    for mobile_vnum in mobile_vnums:
        rooms.extend(
            str(room_vnum)
            for room_vnum in source_mobile_search_rooms(world, mobile_vnum)
        )
    return tuple(dict.fromkeys(rooms))


_SOURCE_WANDERER_PREFLIGHT_REJECTIONS = frozenset(
    {
        _SOURCE_INVISIBILITY_WANDERER_REJECTION,
        _SOURCE_PLAIN_TRANSIT_REJECTION,
        _SOURCE_BELOW_BAND_TRANSIT_REJECTION,
        _SOURCE_LEVEL_ONLY_TRANSIT_REJECTION,
    }
)
_SOURCE_WANDERER_PREFLIGHT_MAX_CHECKS = 4
_SOURCE_AUDITED_ROUTE_TARGET_SPECIALS = frozenset({"spec_guard"})


def _source_ranked_route_wanderer_preflight_metadata(
    candidate: HuntCandidate,
    world: WorldSource | None,
    *,
    character_level: int,
) -> dict[str, Any] | None:
    """Build a bounded ``where`` preflight for known route wanderers.

    A source-ranked route can cross several areas, so a single recall-origin
    query cannot see a wandering attacker in the destination area.  Admit
    only a small, exact family of unprogrammed, source-bounded wanderers whose
    profiles are otherwise understood.  Separately audited ``spec_guard`` and
    explicitly non-combat endpoint specials may use this route check; their
    combat permission is still checked independently.  The route executor
    checks each source keyword in order, then scans the wanderers' reachable
    rooms before entering them.  This is route avoidance evidence, never
    combat permission.
    """
    target_special_rejections = {
        f"target has special procedure {special}"
        for special in candidate.specials
    }
    mrinthas_guard_preflight = _source_ranked_mrinthas_guard_route_allowed(
        candidate,
        character_level=character_level,
        source_world=world,
    )
    target_specials = set(candidate.specials)
    audited_target_special = (
        target_specials == _SOURCE_AUDITED_ROUTE_TARGET_SPECIALS
        and target_special_rejections
        == {"target has special procedure spec_guard"}
    )
    safe_noncombat_target_special = bool(
        target_specials
        and target_specials <= SAFE_NONCOMBAT_SPECIALS
        and not (
            target_special_rejections
            & set(candidate.autonomy_rejections)
        )
    )
    if candidate.specials and not (
        audited_target_special or safe_noncombat_target_special
    ):
        return None
    allowed_rejections = (
        _SOURCE_WANDERER_PREFLIGHT_REJECTIONS
        | target_special_rejections
    )
    if (
        world is None
        or candidate.is_coin_stash
        or (
            candidate.source_spawn_limit != 1
            and not mrinthas_guard_preflight
        )
        or candidate.room_spawn_count != 1
        or candidate.is_food_stash
        or candidate.route_preflight_target
        or candidate.route_preflight_command
        or candidate.route_attack_program_mobile_vnums
        or not candidate.route_aggressive_mobile_vnums
        or not candidate.autonomy_rejections
        or not set(candidate.autonomy_rejections).issubset(allowed_rejections)
        or (
            not {
                _SOURCE_INVISIBILITY_WANDERER_REJECTION,
                _SOURCE_LEVEL_ONLY_TRANSIT_REJECTION,
            }.intersection(candidate.autonomy_rejections)
            and not mrinthas_guard_preflight
        )
    ):
        return None
    try:
        route_rooms = _source_route_room_vnums(
            world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
    except (TypeError, ValueError):
        return None
    if not route_rooms:
        return None

    mobiles: list[Any] = []
    for raw_vnum in candidate.route_aggressive_mobile_vnums:
        try:
            mobile_vnum = int(raw_vnum)
        except (TypeError, ValueError):
            return None
        mobile = world.mobiles.get(mobile_vnum)
        if mobile is None:
            return None
        if source_mobile_route_aggressor_is_bounded(
            world,
            mobile,
            character_level=character_level,
        ):
            continue
        if source_mobile_unresolved_deep_plain_wanderer_is_preflight_safe(
            world,
            mobile,
            character_level=character_level,
        ):
            continue
        maximum_level = _mobile_level_range(mobile.level)[1]
        if (
            not mobile.aggressive
            or not mobile.wanders
            or mobile.programs
            or mobile.attack_programs
            or world.mobile_specials.get(mobile_vnum)
            or mobile.non_corporeal
            or mobile.fear_aura
            or mobile.costs_fame
            or mobile_vnum in world.shopkeepers
            or mobile.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
            or not mobile.hp_modifier_known
            or not mobile.damage_modifier_known
            or maximum_level > character_level + 1
        ):
            return None
        reachable_rooms = set(source_mobile_search_rooms(world, mobile_vnum))
        if not reachable_rooms or reachable_rooms.isdisjoint(route_rooms):
            return None
        mobiles.append(mobile)

    unique_mobiles = tuple({mobile.vnum: mobile for mobile in mobiles}.values())
    if not unique_mobiles or len(unique_mobiles) > _SOURCE_WANDERER_PREFLIGHT_MAX_CHECKS:
        return None
    areas = {str(mobile.area_file).casefold() for mobile in unique_mobiles}
    if len(areas) != 1:
        return None
    route_area_indexes = [
        index
        for index, room_vnum in enumerate(route_rooms)
        if (
            (room := world.rooms.get(room_vnum)) is not None
            and str(room.area_file).casefold() in areas
        )
    ]
    if not route_area_indexes:
        return None
    route_area_rooms = tuple(route_rooms[index] for index in route_area_indexes)
    checks: list[tuple[str, str]] = []
    for mobile in sorted(unique_mobiles, key=lambda item: item.vnum):
        command = f"where {_least_ambiguous_source_keyword(world, mobile)}"
        check = (command, str(mobile.short_description))
        if check not in checks:
            checks.append(check)
    if not checks:
        return None
    scan_rooms: set[int] = set()
    for mobile in unique_mobiles:
        scan_rooms.update(source_mobile_search_rooms(world, mobile.vnum))
    return {
        "room_vnum": str(route_rooms[route_area_indexes[0]]),
        "checks": tuple(checks),
        "level_range": (
            min(_mobile_level_range(mobile.level)[0] for mobile in unique_mobiles),
            max(_mobile_level_range(mobile.level)[1] for mobile in unique_mobiles),
        ),
        "route_room_names": _source_route_room_names(world, route_area_rooms),
        "scan_room_vnums": tuple(str(room_vnum) for room_vnum in sorted(scan_rooms)),
        "source_mobile_vnums": tuple(mobile.vnum for mobile in unique_mobiles),
    }


def _source_ranked_route_program_aggressors_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Apply the shared source proof for non-program route aggressors."""
    if source_world is None:
        return False
    for raw_vnum in candidate.route_aggressive_mobile_vnums:
        try:
            mobile_vnum = int(raw_vnum)
        except (TypeError, ValueError):
            return False
        mobile = source_world.mobiles.get(mobile_vnum)
        if mobile is None or mobile.attack_programs:
            return False
        specials = set(source_world.mobile_specials.get(mobile_vnum, ()))
        if specials and not specials <= SAFE_NONCOMBAT_SPECIALS:
            # Reuse the route-aggressor proof for a combat-only special that
            # is inert under DD4's ten-level ordinary-aggression cutoff.
            if not source_mobile_route_aggressor_is_bounded(
                source_world,
                mobile,
                character_level=character_level,
            ):
                return False
        try:
            level_max = _mobile_level_range(mobile.level)[1]
        except (TypeError, ValueError):
            return False
        if level_max > character_level - _SOURCE_PROGRAM_PREFLIGHT_LEVEL_GAP:
            return False
    return True


def _source_ranked_moria_funding_transit_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Prove the exact low-risk bystanders on the Moria funding route."""
    if (
        source_world is None
        or not isinstance(character_max_hp, int)
        or character_max_hp <= 0
        or candidate.area_file.casefold() != "moria.are"
        or candidate.mobile_vnum != _MORIA_RING_FUNDING_MOBILE_VNUM
        or candidate.room_vnum != _MORIA_RING_FUNDING_ROOM_VNUM
        or not candidate.route_aggressive_mobile_vnums
        or not set(candidate.route_aggressive_mobile_vnums).issubset(
            _MORIA_RING_ROUTE_WIMPY_TRANSIT_VNUMS
        )
        or candidate.route_attack_program_mobile_vnums
        != _MORIA_RING_ROUTE_PROGRAM_VNUMS
        or candidate.route_preflight_command != "where drunk"
        or _source_ranked_normalized_target(candidate.route_preflight_target or "")
        != "drunk"
        or not candidate.route_preflight_hard_hazard
        or frozenset(candidate.autonomy_rejections)
        not in _MORIA_RING_TRANSIT_REJECTION_PROFILES
    ):
        return False
    for mobile_vnum in candidate.route_aggressive_mobile_vnums:
        mobile = source_world.mobiles.get(mobile_vnum)
        resets = tuple(
            reset
            for reset in source_world.mob_resets
            if reset.mobile_vnum == mobile_vnum
        )
        if (
            mobile is None
            or mobile.area_file.casefold() != "midgaard.are"
            or not mobile.aggressive
            or not mobile.wimpy
            or not mobile.wanders
            or mobile.programs
            or source_world.mobile_specials.get(mobile_vnum) != ("spec_fido",)
            or not resets
            or any(reset.equipment for reset in resets)
            or not source_mobile_route_aggressor_is_bounded(
                source_world,
                mobile,
                character_level=character_level,
                character_max_hp=character_max_hp,
            )
        ):
            return False
    # The loop above is the complete Moria-specific transit proof. The
    # generic route helper deliberately requires armed or deep-transit
    # loadout evidence and would reject DD4's harmless unarmed Fido reset.
    # This exact maintenance route has already checked every named bystander,
    # reset and special.
    return True


def _source_ranked_adept_support_target_allowed(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
) -> bool:
    """Prove the exact passive, singleton target with benign adept support."""
    if source_world is None:
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    resets = [
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
    ]
    return bool(
        set(candidate.specials) == {"spec_cast_adept"}
        and set(source_world.mobile_specials.get(candidate.mobile_vnum, ()))
        == {"spec_cast_adept"}
        and mobile is not None
        and mobile.area_file == candidate.area_file
        and mobile.sentinel
        and not mobile.aggressive
        and not mobile.wanders
        and not mobile.fear_aura
        and not mobile.programs
        and not mobile.non_corporeal
        and not mobile.costs_fame
        and candidate.sentinel
        and not candidate.equipped_weapons
        and candidate.source_spawn_limit == 1
        and candidate.room_spawn_count == 1
        and len(resets) == 1
        and resets[0].room_vnum == candidate.room_vnum
        and resets[0].maximum_count == 1
        and all(
            (item := source_world.objects.get(object_vnum)) is not None
            and item.item_type != ITEM_WEAPON
            for reset in resets
            for _slot, object_vnum in reset.equipment
        )
        and candidate.mobile_vnum not in source_world.shopkeepers
    )


def _source_ranked_apollo_armed_sanctuary_target_allowed(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
) -> bool:
    """Prove Apollo's one-weapon, beneficial-adept Sanctuary endpoint."""
    if source_world is None:
        return False
    mobile = source_world.mobiles.get(
        _OLYMPUS_APOLLO_SANCTUARY_CARRIER_MOBILE_VNUM
    )
    resets = [
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == _OLYMPUS_APOLLO_SANCTUARY_CARRIER_MOBILE_VNUM
    ]
    return bool(
        candidate.mobile_vnum == _OLYMPUS_APOLLO_SANCTUARY_CARRIER_MOBILE_VNUM
        and candidate.room_vnum == _OLYMPUS_APOLLO_SANCTUARY_CARRIER_ROOM_VNUM
        and candidate.area_file.casefold() == "olympus.are"
        and set(candidate.specials) == {"spec_cast_adept"}
        and candidate.equipped_weapons == ("a silver bow",)
        and candidate.sentinel
        and not candidate.route_hard_hazard_targets
        and candidate.source_spawn_limit == 1
        and candidate.room_spawn_count == 1
        and mobile is not None
        and mobile.sentinel
        and not mobile.aggressive
        and not mobile.wanders
        and not mobile.programs
        and len(resets) == 1
        and resets[0].room_vnum == candidate.room_vnum
        and resets[0].maximum_count == 1
        # The nectar is loaded by the reset's ordinary object command, while
        # the bow is equipment.  Inspect both reset channels so the source
        # contract matches DD4's actual load order.
        and _OLYMPUS_HEPHAESTUS_SANCTUARY_OBJECT_VNUM in _reset_object_vnums(
            resets[0]
        )
        and any(
            object_vnum == _OLYMPUS_APOLLO_BOW_OBJECT_VNUM
            for _slot, object_vnum in resets[0].equipment
        )
        and candidate.mobile_vnum not in source_world.shopkeepers
    )


def _source_ranked_ota_arena_preflight_metadata(
    candidate: HuntCandidate,
    world: WorldSource | None,
    *,
    character_level: int,
) -> dict[str, Any] | None:
    """Build the exact locator contract for Ota'ar's Arenamaster route.

    The route is useful, but it is not plain transit.  Several mobiles can
    attack, steal, or trigger a greet program on the way to the arena.  The
    policy therefore admits only this source shape and carries every
    non-benign mobile into the ordered ``where`` and adjacent-room scans.
    """
    if world is None:
        return None
    if (
        candidate.area_file.casefold() != _OTAAR_ARENA_TARGET_AREA
        or candidate.mobile_vnum != _OTAAR_ARENA_TARGET_MOBILE_VNUM
        or candidate.room_vnum != _OTAAR_ARENA_TARGET_ROOM_VNUM
        or candidate.route_origin_room_vnum != RECALL_VNUM
        or candidate.specials
        or candidate.equipped_weapons != ("a leather whip",)
        or candidate.route_hard_hazard_targets
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or not set(candidate.route_special_mobile_vnums).issubset(
            _OTAAR_ARENA_ROUTE_SPECIAL_MOBILE_VNUMS
        )
        or set(candidate.route_attack_program_mobile_vnums)
        != set(_OTAAR_ARENA_ROUTE_PROGRAM_MOBILE_VNUMS)
        or set(candidate.route_hazard_mobile_vnums)
        != set(_OTAAR_ARENA_ROUTE_HAZARD_MOBILE_VNUMS)
        or set(candidate.route_aggressive_mobile_vnums)
        != {3062, 3066, 27000, 27103, 27106}
        or not set(candidate.autonomy_rejections).issubset(
            _OTAAR_ARENA_ROUTE_REJECTIONS
        )
        # The arena endpoint remains useful across the source-supported
        # five-level consider window.  Live ``consider`` is still required
        # before combat; this check must not silently close the route merely
        # because the pilot has advanced past the endpoint's nominal level.
        or candidate.level > character_level + 5
        or candidate.estimated_level_range[1] <= character_level - 5
    ):
        return None
    route_rooms = _source_route_room_vnums(
        world,
        candidate.route_origin_room_vnum,
        candidate.route,
    )
    if (
        not route_rooms
        or route_rooms[-1] != candidate.room_vnum
    ):
        return None
    target = world.mobiles.get(candidate.mobile_vnum)
    target_resets = tuple(
        reset
        for reset in world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
    )
    if (
        target is None
        or target.aggressive
        or target.programs
        or target.attack_programs
        or target.wanders
        or target.fear_aura
        or target.non_corporeal
        or target.costs_fame
        or tuple(world.mobile_specials.get(target.vnum, ()))
        or not target.sentinel
        or len(target_resets) != 1
        or target_resets[0].room_vnum != candidate.room_vnum
        or target_resets[0].maximum_count != 1
        or target_resets[0].equipment != ((13, 27425), (16, 27487))
        or target_resets[0].object_vnums != (27425, 27487, 27473)
    ):
        return None

    expected_specials = {
        27106: ("spec_bloodsucker",),
        27115: ("spec_thief",),
        27246: ("spec_thief",),
    }
    for mobile_vnum, expected in expected_specials.items():
        mobile = world.mobiles.get(mobile_vnum)
        if (
            mobile is None
            or tuple(world.mobile_specials.get(mobile_vnum, ())) != expected
            or not mobile.wanders
            or mobile.attack_programs
            or not source_mobile_search_rooms(world, mobile_vnum)
        ):
            return None
        if mobile_vnum == 27106 and not mobile.aggressive:
            return None
        if mobile_vnum != 27106 and mobile.aggressive:
            return None
    economic_thief = world.mobiles.get(_OTAAR_ARENA_ROUTE_ECONOMIC_MOBILE_VNUM)
    if (
        economic_thief is None
        or tuple(
            world.mobile_specials.get(
                _OTAAR_ARENA_ROUTE_ECONOMIC_MOBILE_VNUM,
                (),
            )
        )
        != ("spec_thief",)
        or economic_thief.aggressive
        or economic_thief.attack_programs
        or economic_thief.level + 2 > candidate.level
        or economic_thief.damage_modifier is None
        or economic_thief.damage_modifier > 0
        or not economic_thief.damage_modifier_known
        or not economic_thief.wanders
        or not source_mobile_search_rooms(
            world,
            _OTAAR_ARENA_ROUTE_ECONOMIC_MOBILE_VNUM,
        )
    ):
        return None

    expected_program_specials = {
        27000: ("spec_fido",),
        27009: ("spec_poison",),
        27013: (),
        27267: (),
        27268: (),
    }
    for mobile_vnum, expected in expected_program_specials.items():
        mobile = world.mobiles.get(mobile_vnum)
        resets = tuple(
            reset
            for reset in world.mob_resets
            if reset.mobile_vnum == mobile_vnum
        )
        try:
            trigger_percent = int(
                str(mobile.attack_programs[0].condition).strip()
            ) if mobile is not None and mobile.attack_programs else None
        except (TypeError, ValueError):
            trigger_percent = None
        if (
            mobile is None
            or tuple(world.mobile_specials.get(mobile_vnum, ())) != expected
            or mobile.aggressive and mobile_vnum != 27000
            or mobile.fear_aura
            or mobile.costs_fame
            or len(mobile.attack_programs) != 1
            or mobile.attack_programs[0].trigger.casefold()
            not in {"greet_prog", "all_greet_prog"}
            or _source_mobile_has_deterministic_attack_program(mobile)
            or trigger_percent is None
            or not 0 < trigger_percent <= 25
            or not any(
                "mpkill $n" in str(command).casefold()
                for command in mobile.attack_programs[0].commands
            )
            or any(
                any(
                    command.casefold().startswith(prefix)
                    for prefix in ("mptransfer", "mpforce", "mpat")
                )
                for program in mobile.programs
                for command in program.commands
            )
            or not resets
            or any(
                reset.maximum_count < 1
                or reset.maximum_count > 5
                or world.rooms.get(reset.room_vnum) is None
                or world.rooms[reset.room_vnum].random_exits
                for reset in resets
            )
            or _mobile_level_range(mobile.level)[1]
            > character_level - (10 if mobile_vnum == 27000 else 2)
            or not source_mobile_search_rooms(world, mobile_vnum)
        ):
            return None

    rolling_calf = world.mobiles.get(27103)
    if (
        rolling_calf is None
        or not rolling_calf.aggressive
        or not rolling_calf.wanders
        or tuple(world.mobile_specials.get(27103, ()))
        != ("spec_breath_fire",)
        or _mobile_level_range(rolling_calf.level)[1] > character_level - 10
        or not source_mobile_search_rooms(world, 27103)
    ):
        return None

    preflight_vnums = tuple(
        dict.fromkeys(
            (
                *_OTAAR_ARENA_ROUTE_SPECIAL_MOBILE_VNUMS,
                *_OTAAR_ARENA_ROUTE_PROGRAM_MOBILE_VNUMS,
                27103,
            )
        )
    )
    checks: list[tuple[str, str]] = []
    for mobile_vnum in preflight_vnums:
        mobile = world.mobiles.get(mobile_vnum)
        if mobile is None:
            return None
        check = (
            f"where {_least_ambiguous_source_keyword(world, mobile)}",
            mobile.short_description,
        )
        if check not in checks:
            checks.append(check)
    scan_rooms = {
        int(room_vnum)
        for mobile_vnum in preflight_vnums
        for room_vnum in source_mobile_search_rooms(world, mobile_vnum)
    }
    if not checks or not scan_rooms:
        return None
    ranges = tuple(
        _mobile_level_range(world.mobiles[mobile_vnum].level)
        for mobile_vnum in preflight_vnums
    )
    return {
        "revision": _OTAAR_ARENA_ROUTE_PREFLIGHT_REVISION,
        "room_vnum": str(candidate.route_origin_room_vnum),
        "checks": tuple(checks),
        "level_range": (
            min(low for low, _ in ranges),
            max(high for _, high in ranges),
        ),
        "route_room_names": _source_route_room_names(world, route_rooms),
        "scan_room_vnums": tuple(str(room_vnum) for room_vnum in sorted(scan_rooms)),
        "source_mobile_vnums": preflight_vnums,
    }


def _source_ranked_ota_arena_first_favour_current_band(
    candidate: HuntCandidate,
    world: WorldSource | None,
    *,
    character_level: int,
) -> bool:
    """Keep the no-recall arena entry inside the useful favour band.

    The Arenamaster is level 41, but the first forced fight is the level-40
    Kaer'l gladiator.  The endpoint can therefore look source-eligible after
    the pilot has outgrown the actual captive circuit.  Entering at that point
    strands the character in a no-recall room while every required favour
    returns the below-band consider message.
    """
    if (
        world is None
        or candidate.area_file.casefold() != _OTAAR_ARENA_TARGET_AREA
        or candidate.mobile_vnum != _OTAAR_ARENA_TARGET_MOBILE_VNUM
        or candidate.room_vnum != _OTAAR_ARENA_TARGET_ROOM_VNUM
        or not OTA_ARENA_TARGETS
    ):
        return False
    first_target = world.mobiles.get(OTA_ARENA_TARGETS[0].mobile_vnum)
    if first_target is None:
        return False
    # Use the reset's declared level here rather than its broader load-fuzz
    # range.  The live consider gate still decides every actual fight, but a
    # no-recall entry must not be opened when the first forced reset is already
    # at the below-band threshold on its ordinary source level.
    return int(first_target.level) > character_level - 5


def _source_ranked_ota_arena_deep_below_band_mobile_vnums(
    candidate: HuntCandidate,
    world: WorldSource | None,
    *,
    character_level: int,
) -> tuple[int, ...]:
    """Return the Ota'ar approach hazards proven harmless by level band.

    The route contains a forced arena transfer at the eastern guard.  Every
    other mobile used by the route preflight is source-audited here and must
    be at least five levels below the pilot before the route can treat a live
    ``where`` or adjacent scan result as transit evidence.  This does not
    authorize combat or skip the live identity, crowd, health, or return
    gates; it only prevents a stale route hazard from making the arena
    unreachable once the pilot has clearly outgrown the approach mobiles.
    """
    metadata = _source_ranked_ota_arena_preflight_metadata(
        candidate,
        world,
        character_level=character_level,
    )
    if metadata is None or world is None:
        return ()

    guard = world.mobiles.get(27365)
    guard_programs = tuple(
        program
        for program in (guard.programs if guard is not None else ())
        if program.trigger.casefold() == "all_greet_prog"
    )
    guard_resets = tuple(
        reset
        for reset in world.mob_resets
        if reset.mobile_vnum == 27365
        and reset.room_vnum == OTA_ARENA_GUARD_ROOM_VNUM
    )
    if (
        guard is None
        or guard.area_file.casefold() != _OTAAR_ARENA_TARGET_AREA
        or guard.short_description.casefold() != "an ota'ar dar cityguard"
        or guard.aggressive
        or not guard.sentinel
        or guard.wanders
        or tuple(world.mobile_specials.get(27365, ())) != ("spec_guard",)
        or len(guard_programs) != 1
        or str(guard_programs[0].condition).strip() != "100"
        or not any(
            "mptransfer $n "
            f"{OTA_ARENA_FORCED_ENTRY_ROOM_VNUM}" in " ".join(
                str(command).split()
            ).casefold()
            for command in guard_programs[0].commands
        )
        or len(guard_resets) != 1
        or guard_resets[0].maximum_count != 4
        or guard_resets[0].object_vnums != (27364, 27231, 27242)
        or guard_resets[0].equipment
        != ((3, 27364), (13, 27231), (16, 27242))
    ):
        return ()

    try:
        mobile_vnums = tuple(int(vnum) for vnum in metadata["source_mobile_vnums"])
    except (KeyError, TypeError, ValueError):
        return ()
    if not mobile_vnums:
        return ()
    for mobile_vnum in mobile_vnums:
        mobile = world.mobiles.get(mobile_vnum)
        if (
            mobile is None
            or _mobile_level_range(mobile.level)[1] > character_level - 5
        ):
            return ()
    return mobile_vnums


def _source_ranked_ota_arena_route_revalidation_candidate(
    world: WorldSource,
    state: Mapping[str, Any],
    *,
    character_level: int,
    rank_kwargs: Mapping[str, Any],
    blocked_room_vnums: Collection[int],
) -> HuntCandidate | None:
    """Re-rank only Ota'ar after its old adjacent-scan rooms are repaired."""
    blocked = {
        int(room_vnum)
        for room_vnum in blocked_room_vnums
        if str(room_vnum).isdigit()
    }
    repaired_rooms = blocked - _OTAAR_ARENA_REPAIRED_BLOCKED_ROOM_VNUMS
    if not blocked.intersection(_OTAAR_ARENA_REPAIRED_BLOCKED_ROOM_VNUMS):
        return None
    raw_hazards = state.get("campaign_fastwalk_route_hazards")
    if not isinstance(raw_hazards, (list, tuple, set, frozenset)):
        return None
    if not all(
        any(
            re.match(
                rf"adjacent scan blocked room {room_vnum}:",
                str(raw_hazard).strip(),
                re.IGNORECASE,
            )
            for raw_hazard in raw_hazards
        )
        for room_vnum in blocked.intersection(
            _OTAAR_ARENA_REPAIRED_BLOCKED_ROOM_VNUMS
        )
    ):
        return None

    rerank_kwargs = dict(rank_kwargs)
    rerank_kwargs["route_blocked_room_vnums"] = tuple(sorted(repaired_rooms))
    try:
        reranked = rank_hunt_candidates(
            world,
            **rerank_kwargs,
            preparation_check=_check_campaign_preparation_deadline,
        )
    except TypeError:
        # Keep this repair inert if a legacy caller supplies a future-only
        # selector keyword that the source ranker does not understand.
        return None
    for source_candidate in reranked:
        if (
            source_candidate.mobile_vnum != _OTAAR_ARENA_TARGET_MOBILE_VNUM
            or source_candidate.room_vnum != _OTAAR_ARENA_TARGET_ROOM_VNUM
            or source_candidate.area_file.casefold() != _OTAAR_ARENA_TARGET_AREA
        ):
            continue
        candidate = _source_ranked_ota_arena_candidate(
            economic_hunt_candidate(source_candidate, state, world),
            world,
            state,
            character_level=character_level,
        )
        if _source_ranked_ota_arena_deep_below_band_mobile_vnums(
            candidate,
            world,
            character_level=character_level,
        ):
            return candidate
    return None


def _source_ranked_ota_arena_candidate(
    candidate: HuntCandidate,
    world: WorldSource | None,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> HuntCandidate:
    """Admit the exact Ota'ar route only when its purse gate is satisfied."""
    metadata = _source_ranked_ota_arena_preflight_metadata(
        candidate,
        world,
        character_level=character_level,
    )
    if metadata is None or known_purse(state.get("currencies")) is None:
        return candidate
    if known_purse(state.get("currencies")) > ECONOMIC_HUNT_MAX_COPPER:
        return candidate
    return replace(
        candidate,
        status="caution",
        autonomy_rejections=tuple(
            rejection
            for rejection in candidate.autonomy_rejections
            if rejection not in _OTAAR_ARENA_ROUTE_REJECTIONS
        ),
        route_preflight_room_vnum=metadata["room_vnum"],
        route_preflight_command=metadata["checks"][0][0],
        route_preflight_target=metadata["checks"][0][1],
        route_preflight_checks=metadata["checks"],
        route_preflight_level_range=metadata["level_range"],
        route_preflight_hard_hazard=True,
        route_preflight_route_room_names=metadata["route_room_names"],
        # The route thief is source-audited here as a non-combat preflight
        # hazard. Do not pass it to the ordinary economic-hunt executor,
        # which intentionally rejects this armed source reset.
        route_economic_hunt_mobile_vnums=(),
        route_economic_source_rejections=(),
    )


def _source_ranked_ota_arena_captive_resume_candidate(
    world: WorldSource,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> HuntCandidate | None:
    """Recover the exact arena policy after entry became out-of-band.

    Ordinary selection must stop sending a level-45 pilot into level-40
    gladiators, but a checkpoint already inside Ota'ar still has to finish its
    five-favour captive circuit.  Prefer the persisted source candidate and
    fall back to one fresh source lookup; neither path authorizes a new entry.
    """
    source_revision = state.get(_SOURCE_REVISION_KEY)
    recorded = _source_ranked_candidate_from_record(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY),
        source_revision=source_revision if isinstance(source_revision, str) else None,
    )

    def exact(candidate: HuntCandidate | None) -> HuntCandidate | None:
        if candidate is None or (
            candidate.area_file.casefold() != _OTAAR_ARENA_TARGET_AREA
            or candidate.mobile_vnum != _OTAAR_ARENA_TARGET_MOBILE_VNUM
            or candidate.room_vnum != _OTAAR_ARENA_TARGET_ROOM_VNUM
            or _source_ranked_ota_arena_preflight_metadata(
                candidate,
                world,
                character_level=character_level,
            )
            is None
        ):
            return None
        return _source_ranked_ota_arena_candidate(
            economic_hunt_candidate(candidate, state, world),
            world,
            state,
            character_level=character_level,
        )

    recovered = exact(recorded)
    if recovered is not None:
        return recovered

    raw_max_hp = state.get("max_hp")
    character_max_hp = (
        int(raw_max_hp)
        if isinstance(raw_max_hp, (int, float)) and raw_max_hp > 0
        else None
    )
    try:
        candidates = rank_hunt_candidates(
            world,
            character_level=character_level,
            character_max_hp=character_max_hp,
            include_all_areas=True,
            include_level_ceiling_candidates=True,
            level_ceiling_offset=5,
            include_xp_only=True,
            recall_origins=_source_ranked_recall_origins(state),
            preparation_check=_check_campaign_preparation_deadline,
        )
    except (TypeError, ValueError, RuntimeError):
        return None
    for candidate in candidates:
        recovered = exact(candidate)
        if recovered is not None:
            return recovered
    return None


def _source_ranked_ota_arena_favour_gate_revalidation_receipt(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> dict[str, Any] | None:
    """Authorize one retry after the arena controller learned its hard gate.

    The old arena attempt is retained as evidence. This marker changes only
    the software contract: it does not clear a loss, make a route safe, or
    waive the live water, identity, consider, crowd, and combat checks.
    """
    if source_world is None:
        return None
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if (
        candidate.area_file.casefold() != _OTAAR_ARENA_TARGET_AREA
        or candidate.mobile_vnum != _OTAAR_ARENA_TARGET_MOBILE_VNUM
        or candidate.room_vnum != _OTAAR_ARENA_TARGET_ROOM_VNUM
        or not candidate.route_preflight_hard_hazard
        or _source_ranked_retry_exclusion(state) != policy_id
        or not state.get("world_boot_id")
        or not state.get(_SOURCE_REVISION_KEY)
        or _source_ranked_ota_arena_preflight_metadata(
            candidate,
            source_world,
            character_level=character_level,
        )
        is None
    ):
        return None
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("fatal_failure") is True
        and result.get("observed") is True
        and result.get("completed_kill") is False
        and result.get("viable") is False
    ):
        return None
    if (
        state.get("campaign_died_during_segment") is True
        or state.get("campaign_objective_kills")
        or state.get("campaign_completed_kills")
        or _source_ranked_xp_loss_record(state, policy_id) is not None
    ):
        return None
    existing = state.get(_OTAAR_ARENA_FAVOUR_GATE_REVALIDATION_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == state.get("world_boot_id")
        and existing.get("level") in {None, character_level}
        and existing.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and existing.get("status")
        in {"pending", "attempted", "closed", "succeeded"}
    ):
        return None
    return {
        "schema_version": 1,
        "revision": _OTAAR_ARENA_FAVOUR_GATE_REVALIDATION_REVISION,
        "boot_id": state.get("world_boot_id"),
        "level": character_level,
        "policy_id": policy_id,
        "source_revision": state.get(_SOURCE_REVISION_KEY),
        "mobile_vnum": candidate.mobile_vnum,
        "room_vnum": candidate.room_vnum,
        "route_preflight_revision": _OTAAR_ARENA_ROUTE_PREFLIGHT_REVISION,
        "prior_result": {
            key: result.get(key)
            for key in (
                "boot_id",
                "fatal_failure",
                "observed",
                "completed_kill",
                "viable",
            )
        },
        "status": "pending",
        "attempted": False,
        "reason": (
            "one exact retry after the arena controller was corrected to "
            "collect all five source-gated favours before leaving"
        ),
    }


def _consume_ota_arena_source_refresh_before_dispatch(
    state: dict[str, Any],
    *,
    policy_id: str,
    character_level: int,
) -> bool:
    """Consume the Arena source-refresh receipt at the live-hunt boundary."""
    marker = state.get(_OTAAR_ARENA_SOURCE_REFRESH_REVALIDATION_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("status") == "pending"
        and marker.get("policy_id") == policy_id
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("revision")
        == _OTAAR_ARENA_SOURCE_REFRESH_REVALIDATION_REVISION
    ):
        return False
    state[_OTAAR_ARENA_SOURCE_REFRESH_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
    }
    return True


def _source_ranked_ota_arena_source_refresh_revalidation_receipt(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> dict[str, Any] | None:
    """Authorize one arena retry after the source revision changed.

    This is narrower than the favour-gate repair above. It does not reinterpret
    an old loss as safe and it does not clear the timeout or loss ledgers. It
    only permits one fresh current-source audit when the exact old attempt was
    interrupted/lost under a different source revision.
    """
    if source_world is None:
        return None
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    source_revision = state.get(_SOURCE_REVISION_KEY)
    boot_id = state.get("world_boot_id")
    if (
        candidate.area_file.casefold() != _OTAAR_ARENA_TARGET_AREA
        or candidate.mobile_vnum != _OTAAR_ARENA_TARGET_MOBILE_VNUM
        or candidate.room_vnum != _OTAAR_ARENA_TARGET_ROOM_VNUM
        or not candidate.route_preflight_hard_hazard
        or not isinstance(boot_id, str)
        or not boot_id
        or not isinstance(source_revision, str)
        or not source_revision
        or _source_ranked_ota_arena_preflight_metadata(
            candidate,
            source_world,
            character_level=character_level,
        )
        is None
    ):
        return None

    timeout_record = next(
        (
            record
            for record in state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY, ())
            if isinstance(record, Mapping)
            and record.get("boot_id") == boot_id
            and record.get("level") in {None, character_level}
            and record.get("policy_id") == policy_id
            and record.get("objective_kill_count") in {None, 0}
        ),
        None,
    )
    loss_record = _source_ranked_xp_loss_record(state, policy_id)
    prior_source_revision = (
        str(loss_record.get("source_revision") or "")
        if isinstance(loss_record, Mapping)
        else ""
    )
    if (
        timeout_record is None
        or loss_record is None
        or _source_ranked_xp_loss_count(loss_record) != 1
        or not prior_source_revision
        or prior_source_revision == source_revision
        or state.get("campaign_died_during_segment") is True
        or state.get("campaign_objective_kills")
        or state.get("campaign_completed_kills")
    ):
        return None

    existing = state.get(_OTAAR_ARENA_SOURCE_REFRESH_REVALIDATION_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
        and existing.get("level") in {None, character_level}
        and existing.get("source_revision") == source_revision
        and existing.get("policy_id") == policy_id
        and existing.get("status")
        in {"pending", "attempted", "closed", "succeeded"}
    ):
        selector_repair_is_available = (
            existing.get("status") == "closed"
            and existing.get("attempted") is not True
            and existing.get("reason")
            == _OTAAR_ARENA_SOURCE_REFRESH_SELECTOR_CLOSE_REASON
            and existing.get("selector_repair_rearmed") is not True
        )
        if not selector_repair_is_available:
            return None

    metadata = _source_ranked_ota_arena_preflight_metadata(
        candidate,
        source_world,
        character_level=character_level,
    )
    if metadata is None:
        return None
    return {
        "schema_version": 1,
        "revision": _OTAAR_ARENA_SOURCE_REFRESH_REVALIDATION_REVISION,
        "boot_id": boot_id,
        "level": character_level,
        "policy_id": policy_id,
        "source_revision": source_revision,
        "prior_source_revision": prior_source_revision,
        "mobile_vnum": candidate.mobile_vnum,
        "room_vnum": candidate.room_vnum,
        "route_preflight_revision": metadata["revision"],
        "route_room_names": metadata["route_room_names"],
        "source_mobile_vnums": metadata["source_mobile_vnums"],
        "prior_timeout": {
            key: timeout_record.get(key)
            for key in ("boot_id", "level", "policy_id", "reason")
        },
        "prior_loss": {
            key: loss_record.get(key)
            for key in (
                "boot_id",
                "level",
                "loss_count",
                "loss_event_id",
                "source_revision",
                "xp_delta",
            )
        },
        "status": "pending",
        "attempted": False,
        "selector_repair_rearmed": bool(
            isinstance(existing, Mapping)
            and existing.get("status") == "closed"
        ),
        "reason": (
            "one exact Ota'ar arena retry after a complete current-source "
            "audit; stale timeout/loss evidence remains in the ledger and "
            "all five favours remain mandatory before exit"
        ),
    }


def _source_ranked_ota_arena_route_recovery_revalidation_receipt(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> dict[str, Any] | None:
    """Authorize one retry after the exact Ota'ar recall-loop repair.

    The preceding source-refresh receipt has already been consumed and is
    intentionally one-shot. This receipt reopens only the route failure it
    exposed: a no-kill timeout followed by a safe healer return, with the same
    source, boot, level, and single historical XP loss. It never clears that
    loss or permits a second ordinary arena retry.
    """
    if source_world is None:
        return None
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    source_revision = state.get(_SOURCE_REVISION_KEY)
    boot_id = state.get("world_boot_id")
    previous = state.get(_OTAAR_ARENA_SOURCE_REFRESH_REVALIDATION_KEY)
    metadata = _source_ranked_ota_arena_preflight_metadata(
        candidate,
        source_world,
        character_level=character_level,
    )
    if (
        candidate.area_file.casefold() != _OTAAR_ARENA_TARGET_AREA
        or candidate.mobile_vnum != _OTAAR_ARENA_TARGET_MOBILE_VNUM
        or candidate.room_vnum != _OTAAR_ARENA_TARGET_ROOM_VNUM
        or metadata is None
        or not isinstance(boot_id, str)
        or not boot_id
        or not isinstance(source_revision, str)
        or not source_revision
        or not _is_safe_healer_checkpoint(state)
        or not isinstance(previous, Mapping)
        or previous.get("status") != "closed"
        or previous.get("attempted") is not True
        or previous.get("outcome") != "no_kill"
        or previous.get("policy_id") != policy_id
        or previous.get("boot_id") != boot_id
        or previous.get("level") not in {None, character_level}
        or previous.get("source_revision") != source_revision
        or previous.get("route_preflight_revision") != metadata["revision"]
        or not isinstance(previous.get("prior_timeout"), Mapping)
        or not _is_source_ranked_timeout_failure(
            previous["prior_timeout"].get("reason")
        )
    ):
        return None

    loss_record = _source_ranked_xp_loss_record(state, policy_id)
    prior_loss = previous.get("prior_loss")
    if (
        not isinstance(loss_record, Mapping)
        or _source_ranked_xp_loss_count(loss_record) != 1
        or not isinstance(prior_loss, Mapping)
        or loss_record.get("loss_event_id") != prior_loss.get("loss_event_id")
        or loss_record.get("source_revision") != prior_loss.get("source_revision")
        or state.get("campaign_died_during_segment") is True
        or state.get("campaign_objective_kills")
        or state.get("campaign_completed_kills")
    ):
        return None

    existing = state.get(_OTAAR_ARENA_ROUTE_RECOVERY_REVALIDATION_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
        and existing.get("level") in {None, character_level}
        and existing.get("source_revision") == source_revision
        and existing.get("policy_id") == policy_id
        and existing.get("status")
        in {"pending", "attempted", "closed", "succeeded"}
    ):
        return None

    return {
        "schema_version": 1,
        "revision": _OTAAR_ARENA_ROUTE_RECOVERY_REVALIDATION_REVISION,
        "boot_id": boot_id,
        "level": character_level,
        "policy_id": policy_id,
        "source_revision": source_revision,
        "mobile_vnum": candidate.mobile_vnum,
        "room_vnum": candidate.room_vnum,
        "route_preflight_revision": metadata["revision"],
        "source_mobile_vnums": metadata["source_mobile_vnums"],
        "prior_timeout": dict(previous["prior_timeout"]),
        "prior_loss": dict(prior_loss),
        "status": "pending",
        "attempted": False,
        "reason": (
            "one exact Ota'ar arena retry after repairing the local recall "
            "escape; the earlier timeout and XP loss remain recorded"
        ),
    }


def _consume_ota_arena_route_recovery_before_dispatch(
    state: dict[str, Any],
    *,
    policy_id: str,
    character_level: int,
) -> bool:
    """Consume the route-recovery receipt at the exact arena boundary."""
    marker = state.get(_OTAAR_ARENA_ROUTE_RECOVERY_REVALIDATION_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("status") == "pending"
        and marker.get("policy_id") == policy_id
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("revision")
        == _OTAAR_ARENA_ROUTE_RECOVERY_REVALIDATION_REVISION
    ):
        return False
    state[_OTAAR_ARENA_ROUTE_RECOVERY_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
    }
    return True


def _source_refresh_history_records(
    state: Mapping[str, Any],
) -> tuple[Mapping[str, Any], ...]:
    """Return durable source-refresh receipts, including the active handoff."""
    records: list[Mapping[str, Any]] = []
    raw_history = state.get(_SOURCE_RANKED_SOURCE_REFRESH_HISTORY_KEY)
    if isinstance(raw_history, (list, tuple)):
        records.extend(
            record for record in raw_history if isinstance(record, Mapping)
        )
    current = state.get(_SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_KEY)
    if isinstance(current, Mapping):
        records.append(current)
    return tuple(records)


def _archive_source_refresh_marker(state: dict[str, Any]) -> None:
    """Move the active receipt into the bounded per-target audit history."""
    marker = state.get(_SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_KEY)
    if not isinstance(marker, Mapping) or not marker.get("policy_id"):
        return
    raw_history = state.get(_SOURCE_RANKED_SOURCE_REFRESH_HISTORY_KEY)
    history: list[dict[str, Any]] = []
    if isinstance(raw_history, (list, tuple)):
        history = [
            dict(record) for record in raw_history if isinstance(record, Mapping)
        ]
    identity = tuple(
        marker.get(key)
        for key in ("policy_id", "boot_id", "level", "source_revision")
    )
    if not any(
        tuple(record.get(key) for key in ("policy_id", "boot_id", "level", "source_revision"))
        == identity
        and record.get("status") == marker.get("status")
        for record in history
    ):
        history.append(dict(marker))
    state[_SOURCE_RANKED_SOURCE_REFRESH_HISTORY_KEY] = history[
        -_SOURCE_RANKED_SOURCE_REFRESH_HISTORY_LIMIT:
    ]


def _source_ranked_source_refresh_target_shape_allowed(
    candidate: HuntCandidate,
    mobile: Any,
    source_world: WorldSource,
) -> bool:
    """Keep source-refresh retries limited to audited plain target shapes."""
    if candidate.sentinel:
        return True
    if (
        not mobile.wanders
        or mobile.aggressive
        or not candidate.requires_detect_invisibility
        or candidate.route_origin_room_vnum != RECALL_VNUM
    ):
        return False
    search_rooms = source_mobile_search_rooms(
        source_world,
        mobile.vnum,
        maximum_rooms=_SOURCE_RANKED_WANDER_SEARCH_LIMIT,
    )
    return bool(search_rooms and candidate.room_vnum in set(search_rooms))


def _source_ranked_rearm_preparation_source_refresh_marker(
    state: Mapping[str, Any],
) -> bool:
    """Rearm one exact special receipt after protection-only preparation.

    The source-refresh marker is normally consumed before a field connection,
    but a visibility or flight purchase can run first.  A prior interrupted
    preparation segment is identifiable by its exact special marker, fresh
    protection affects, no combat/death evidence, and a different last policy.
    Never rearm a marker after the field policy itself has run.
    """
    if not isinstance(state, dict):
        return False
    marker = state.get(_SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("status") == "attempted"
        and marker.get("special_source_refresh") is True
        and not state.get("campaign_died_during_segment")
        and not state.get("campaign_objective_kills")
        and not state.get("campaign_completed_kills")
        and not state.get("dead")
        and not state.get("in_combat")
        and marker.get("policy_id") != state.get("campaign_last_policy")
        and _has_named_affect(state.get("affects"), "detect invis")
        and _has_named_affect(state.get("affects"), "fly")
    ):
        return False
    state[_SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "pending",
        "attempted": False,
        "deferred_for_preparation": True,
    }
    return True


def _source_ranked_reconcile_pending_source_refresh_marker(
    state: dict[str, Any],
) -> bool:
    """Close a pending retry when its exact target has a newer XP loss.

    Preparation may leave a source-refresh receipt pending across a checkpoint.
    If a field segment then records a newer exact loss before the receipt is
    merged, the loss ledger is authoritative and the receipt must not reopen
    that target on the next selector pass.
    """
    marker = state.get(_SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("status") == "pending"
        and marker.get("policy_id")
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, _level(state)}
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
    ):
        return False
    current_loss = _source_ranked_xp_loss_record(
        state,
        str(marker.get("policy_id")),
    )
    prior_loss = marker.get("prior_loss")
    if not isinstance(current_loss, Mapping) or not isinstance(prior_loss, Mapping):
        return False
    current_count = _source_ranked_xp_loss_count(current_loss)
    prior_count = _source_ranked_xp_loss_count(prior_loss)
    current_event_id = current_loss.get("loss_event_id")
    prior_event_id = prior_loss.get("loss_event_id")
    newer_event = (
        isinstance(current_event_id, int)
        and isinstance(prior_event_id, int)
        and current_event_id > prior_event_id
    )
    if current_count <= prior_count and not newer_event:
        return False
    state[_SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "closed",
        "attempted": False,
        "outcome": "no_kill",
        "reason": (
            "closed after the exact target recorded a newer XP-loss event; "
            "the pending source-refresh receipt cannot replay that loss"
        ),
    }
    _archive_source_refresh_marker(state)
    return True


def _source_ranked_mark_source_refresh_dispatch(
    state: dict[str, Any],
    selected: ProgressionPolicy,
    *,
    character_level: int,
) -> bool:
    """Consume a source-refresh receipt only when field dispatch is ready."""
    if selected.execution != "source-ranked-hunt":
        return False
    marker = state.get(_SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("status") == "pending"
        and marker.get("policy_id") == selected.policy_id
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("revision")
        == _SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_REVISION
    ):
        return False
    state[_SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
        "deferred_for_preparation": False,
    }
    return True


def _source_ranked_source_refresh_special_shape_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    source_world: WorldSource | None,
    *,
    character_level: int,
) -> bool:
    """Allow only the separately audited Hephaestus lightning retry."""
    if source_world is None:
        return False
    if not _source_hephaestus_sanctuary_candidate_shape_allowed(
        candidate,
        source_world,
    ):
        return False
    if not _source_ranked_special_candidate_in_live_level_ceiling(
        candidate,
        character_level=character_level,
    ):
        return False
    character_max_hp = (
        int(state["max_hp"])
        if isinstance(state.get("max_hp"), (int, float))
        and state.get("max_hp") > 0
        else None
    )
    return _audited_source_special_candidate_allowed(
        candidate,
        state=state,
        character_max_hp=character_max_hp,
        source_world=source_world,
    )


def _source_ranked_source_refresh_revalidation_receipt(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> dict[str, Any] | None:
    """Authorize one exact retry after a target's source audit changed.

    Source refreshes must not reopen every old failure. This receipt is limited
    to a current-source, fixed-room, unarmed singleton with one to three
    recorded losses and a changed source revision. The ordinary shape has no
    target special; the separately audited Hephaestus lightning reset and the
    exact plain aggressive current-band fallback are the only exceptions. A
    third-loss retry remains limited to a plain, unarmed, source-singleton
    target. The old loss is retained; the receipt only buys one fresh live
    identity/consider/combat attempt. Receipts are tracked per target so one
    failed audit cannot hide the rest of a newly parsed source frontier.
    """
    if source_world is None:
        return None
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    boot_id = state.get("world_boot_id")
    source_revision = state.get(_SOURCE_REVISION_KEY)
    loss_record = _source_ranked_xp_loss_record(state, policy_id)
    prior_source_revision = (
        str(loss_record.get("source_revision") or "")
        if isinstance(loss_record, Mapping)
        else ""
    )
    if not (
        isinstance(boot_id, str)
        and boot_id
        and isinstance(source_revision, str)
        and source_revision
        and isinstance(loss_record, Mapping)
        and loss_record.get("boot_id") == boot_id
        and loss_record.get("exact_stop_loss") is True
        and _source_ranked_xp_loss_count(loss_record) in {1, 2, 3}
        and prior_source_revision
        and prior_source_revision != source_revision
        and not state.get("campaign_died_during_segment")
        and not state.get("campaign_objective_kills")
        and not state.get("campaign_completed_kills")
    ):
        return None

    result = _campaign_research_results(state).get(policy_id)
    prior_result: dict[str, Any] | None = None
    if isinstance(result, Mapping) and result.get("boot_id") == boot_id:
        prior_result = dict(result)
        result_source_revision = str(result.get("source_revision") or "")
        if result.get("completed_kill") is True:
            # Older research rows did not persist source provenance.  Once
            # the linked loss proves that the old source revision changed,
            # that legacy success is historical evidence for the refresh, not
            # proof that the current source plan was already tested.  A row
            # explicitly stamped with the current revision remains closed so
            # a current-source success cannot be replayed after a loss.
            if result_source_revision == source_revision:
                return None
            if result_source_revision and result_source_revision != prior_source_revision:
                return None
        if result.get("viable") is False or any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "crowd_exhausted",
                "fatal",
                "fatal_failure",
                "hazard",
                "route_hazard",
                "unattackable",
                "target_vnum_mismatch",
                "low_reward",
                "xp_loss_observed",
            )
        ):
            return None

    refresh_records = _source_refresh_history_records(state)
    matching_refresh_records = tuple(
        record
        for record in refresh_records
        if record.get("policy_id") == policy_id
        and record.get("boot_id") == boot_id
        and record.get("level") in {None, character_level}
        and record.get("source_revision") == source_revision
        and record.get("status")
        in {"pending", "attempted", "closed", "succeeded"}
    )
    if matching_refresh_records:
        return None
    current_refresh_count = sum(
        1
        for record in refresh_records
        if record.get("boot_id") == boot_id
        and record.get("level") in {None, character_level}
        and record.get("source_revision") == source_revision
        and record.get("status") in {"attempted", "closed", "succeeded"}
    )
    if current_refresh_count >= _SOURCE_RANKED_SOURCE_REFRESH_MAX_ATTEMPTS:
        return None

    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    room = source_world.rooms.get(candidate.room_vnum)
    special_refresh = _source_ranked_source_refresh_special_shape_allowed(
        candidate,
        state,
        source_world,
        character_level=character_level,
    )
    character_max_hp = (
        int(state["max_hp"])
        if isinstance(state.get("max_hp"), (int, float))
        and state.get("max_hp") > 0
        else None
    )
    aggressive_plain_refresh = (
        not special_refresh
        and _source_ranked_plain_aggressive_current_band_fallback_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=source_world,
        )
    )
    loss_count = _source_ranked_xp_loss_count(loss_record)
    source_refresh_kill_cap_reopen = bool(
        not special_refresh
        and candidate.autonomous_safe
        and candidate.target_selection_safe
        and not candidate.specials
        and not candidate.equipped_weapons
        and candidate.source_spawn_limit == 1
        and candidate.room_spawn_count == 1
    )
    third_loss_plain_refresh = (
        loss_count == 3
        and not special_refresh
        and candidate.status != "reject"
        and candidate.autonomous_safe
        and candidate.target_selection_safe
        and not candidate.specials
        and not candidate.equipped_weapons
        and _source_ranked_source_refresh_target_shape_allowed(
            candidate,
            mobile,
            source_world,
        )
    )
    if not (
        mobile is not None
        and room is not None
        and not _source_ranked_psionic_candidate_requires_protection(
            candidate,
            source_world=source_world,
        )
        and candidate.status != "reject"
        and (
            (
                loss_count in {1, 2}
                and (
                    special_refresh
                    or aggressive_plain_refresh
                    or (
                        candidate.autonomous_safe
                        and candidate.target_selection_safe
                        and _source_ranked_source_refresh_target_shape_allowed(
                            candidate,
                            mobile,
                            source_world,
                        )
                    )
                )
            )
            or third_loss_plain_refresh
        )
        and candidate.source_spawn_limit == 1
        and candidate.room_spawn_count == 1
        # The ordinary three-kill cap is a current-plan guard, not a reason
        # to reject one fresh source audit after the source revision changed.
        # Keep this exception plain, singleton, and one-shot; the nested
        # selector still consumes the source-refresh receipt and all live
        # combat gates remain authoritative.
        and (candidate.boot_kills < 3 or source_refresh_kill_cap_reopen)
        and (not candidate.specials or special_refresh)
        and not candidate.equipped_weapons
        and not candidate.route_preflight_hard_hazard
        and not candidate.route_hard_hazard_targets
        and not candidate.route_special_mobile_vnums
        and not candidate.route_attack_program_mobile_vnums
        and (
            not candidate.requires_flight
            or _source_ranked_flight_handoff_available(candidate, state)
        )
        and not candidate.requires_water_breathing
        and (aggressive_plain_refresh or not mobile.aggressive)
        and not mobile.attack_programs
        and not mobile.programs
        and (
            not source_world.mobile_specials.get(mobile.vnum)
            or special_refresh
        )
        and _source_ranked_normalized_target(candidate.target)
        == _source_ranked_normalized_target(mobile.short_description)
        and bool(_source_ranked_target_identity(candidate))
        and _source_ranked_candidate_in_current_band(
            candidate,
            state,
            world=source_world,
            character_level=character_level,
            allow_repeated_kills=True,
        )
        and _source_ranked_route_aggressors_are_bounded(
            candidate,
            character_level=character_level,
            source_world=source_world,
            character_max_hp=character_max_hp,
        )
    ):
        return None

    return {
        "schema_version": 1,
        "revision": _SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_REVISION,
        "source_refresh": True,
        "boot_id": boot_id,
        "level": character_level,
        "policy_id": policy_id,
        "source_revision": source_revision,
        "prior_source_revision": prior_source_revision,
        "area_file": candidate.area_file,
        "mobile_vnum": candidate.mobile_vnum,
        "room_vnum": candidate.room_vnum,
        "target": candidate.target,
        "target_identity": candidate.target_identity,
        "source_route": list(candidate.route),
        "route_aggressive_mobile_vnums": list(
            candidate.route_aggressive_mobile_vnums
        ),
        "source_reset_limit": candidate.source_spawn_limit,
        "room_spawn_count": candidate.room_spawn_count,
        "special_source_refresh": special_refresh,
        "prior_loss": {
            key: loss_record.get(key)
            for key in (
                "boot_id",
                "level",
                "loss_count",
                "loss_event_id",
                "source_revision",
                "xp_delta",
            )
        },
        "prior_result": prior_result,
        "status": "pending",
        "attempted": False,
        "reason": (
            "one exact Hephaestus lightning retry after a complete "
            "current-source route/loadout audit; the older loss remains "
            "historical evidence"
            if special_refresh
            else "one exact plain current-band retry after a complete "
            "current-source route/loadout audit; the older loss remains "
            "historical evidence"
        ),
    }


def _source_ranked_route_program_candidate_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
    allow_capacity_research: bool = False,
    allow_capacity_endpoint: bool = False,
    allow_sanctuary_protected_target: bool = False,
    allow_bounded_moria_transit: bool = False,
    character_max_hp: int | None = None,
) -> bool:
    """Return whether one route-program candidate can use live preflight."""
    if _source_ranked_mrinthas_guard_route_allowed(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    ):
        return True
    if (
        candidate.area_file.casefold() == _OTAAR_ARENA_TARGET_AREA
        and candidate.mobile_vnum == _OTAAR_ARENA_TARGET_MOBILE_VNUM
        and candidate.room_vnum == _OTAAR_ARENA_TARGET_ROOM_VNUM
    ):
        return bool(
            _source_ranked_ota_arena_preflight_metadata(
                candidate,
                source_world,
                character_level=character_level,
            )
            is not None
            and _source_ranked_ota_arena_first_favour_current_band(
                candidate,
                source_world,
                character_level=character_level,
            )
        )
    if _source_ranked_ota_arena_preflight_metadata(
        candidate,
        source_world,
        character_level=character_level,
    ) is not None:
        return True
    if not _source_ranked_route_program_preflight_allowed(
        candidate,
        character_level=character_level,
        source_world=source_world,
    ):
        return False
    armed_protected_peak_target = (
        allow_sanctuary_protected_target
        and len(candidate.equipped_weapons) == 1
        and set(candidate.autonomy_rejections) == {
            _SOURCE_PEAK_DAMAGE_REJECTION
        }
    )
    if (
        (
            candidate.specials
            and not _source_ranked_adept_support_target_allowed(
                candidate,
                source_world,
            )
        )
        or (
            candidate.equipped_weapons
            and not armed_protected_peak_target
        )
        or candidate.route_hard_hazard_targets
        or not _source_ranked_route_specials_noncombat_only(
            candidate,
            source_world,
        )
    ):
        return False
    if any(
        "target is aggressive" in str(rejection).casefold()
        or "target has special procedure" in str(rejection).casefold()
        for rejection in candidate.autonomy_rejections
    ):
        return False
    capacity_research = bool(
        allow_capacity_research
        and _source_ranked_capacity_research_candidate(
            candidate,
            character_level=character_level,
            source_world=source_world,
        )
    )
    capacity_endpoint = bool(
        allow_capacity_endpoint
        and _source_ranked_bounded_route_program_capacity_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
        )
        and _source_ranked_capacity_research_candidate(
            candidate,
            character_level=character_level,
            source_world=source_world,
            allow_bounded_route_program=True,
        )
    )
    bounded_moria_transit = bool(
        allow_bounded_moria_transit
        and _source_ranked_moria_funding_transit_allowed(
            candidate,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=source_world,
        )
    )
    if (
        candidate.area_file.casefold() == "moria.are"
        and candidate.mobile_vnum == _MORIA_RING_FUNDING_MOBILE_VNUM
        and candidate.room_vnum == _MORIA_RING_FUNDING_ROOM_VNUM
        and candidate.route_aggressive_mobile_vnums
        and set(candidate.route_aggressive_mobile_vnums).issubset(
            _MORIA_RING_ROUTE_WIMPY_TRANSIT_VNUMS
        )
        and candidate.route_attack_program_mobile_vnums
        == _MORIA_RING_ROUTE_PROGRAM_VNUMS
        and not bounded_moria_transit
    ):
        # The exact Moria funding route carries aggressive Fido bystanders.
        # Its source proof is an explicit maintenance exception, not a
        # generic route-program admission.
        return False
    permitted_rejection_fragments = ("program-triggered attacker",)
    if bounded_moria_transit:
        permitted_rejection_fragments += tuple(_MORIA_RING_TRANSIT_REJECTIONS)
    if allow_sanctuary_protected_target:
        permitted_rejection_fragments += (_SOURCE_PEAK_DAMAGE_REJECTION,)
    if not capacity_research and not capacity_endpoint and any(
        not any(
            fragment.casefold() in str(rejection).casefold()
            for fragment in permitted_rejection_fragments
        )
        for rejection in candidate.autonomy_rejections
    ):
        return False
    return _source_ranked_route_program_aggressors_allowed(
        candidate,
        character_level=character_level,
        source_world=source_world,
    )


def _source_ranked_route_program_fastwalk_options(
    world: WorldSource,
    candidate: HuntCandidate,
    state: Mapping[str, Any] | None,
    *,
    character_level: int,
    allow_sanctuary_protected_target: bool = False,
    force_route_program_preflight: bool = False,
    allow_bounded_moria_transit: bool = False,
) -> dict[str, Any]:
    """Skip a route locator only for an exact, source-bounded low-level greeter."""
    raw_max_hp = (state or {}).get("max_hp")
    character_max_hp = (
        int(raw_max_hp)
        if isinstance(raw_max_hp, (int, float)) and raw_max_hp > 0
        else None
    )
    borderline_route_mobile_vnums = (
        _source_ranked_borderline_route_aggressor_vnums(
            candidate,
            world,
            character_level=character_level,
            character_max_hp=character_max_hp,
        )
    )
    plain_transit_mobile_vnums = _source_ranked_plain_transit_mobile_vnums(
        candidate,
        world,
        character_level=character_level,
    )
    sanctuary_armed_endpoint_transit_mobile_vnums: tuple[int, ...] = ()
    if isinstance(state, Mapping):
        sanctuary_armed_endpoint_transit_mobile_vnums = (
            _source_ranked_sanctuary_armed_endpoint_transit_mobile_vnums(
                candidate,
                state,
                character_level=character_level,
                character_max_hp=character_max_hp,
                source_world=world,
            )
        )
    if sanctuary_armed_endpoint_transit_mobile_vnums:
        plain_transit_mobile_vnums = (
            sanctuary_armed_endpoint_transit_mobile_vnums
        )
    plain_transit_room_vnums: tuple[str, ...] = ()
    if plain_transit_mobile_vnums:
        route_rooms = _source_route_room_vnums(
            world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
        if route_rooms:
            plain_transit_room_vnums = tuple(
                str(room_vnum) for room_vnum in dict.fromkeys(route_rooms)
            )
    armed_transit_mobile_vnums = _source_ranked_armed_transit_mobile_vnums(
        candidate,
        world,
        character_level=character_level,
        character_max_hp=character_max_hp,
    )
    if not armed_transit_mobile_vnums:
        armed_transit_mobile_vnums = (
            _source_ranked_plain_armed_transit_mobile_vnums(
                candidate,
                world,
                character_level=character_level,
                character_max_hp=character_max_hp,
            )
        )
    if not armed_transit_mobile_vnums:
        armed_transit_mobile_vnums = (
            _source_ranked_unarmed_endpoint_armed_transit_mobile_vnums(
                candidate,
                world,
                character_level=character_level,
                character_max_hp=character_max_hp,
            )
        )
    if not armed_transit_mobile_vnums:
        armed_transit_mobile_vnums = (
            _source_ranked_level_only_armed_transit_mobile_vnums(
                candidate,
                world,
                character_level=character_level,
            )
        )
    # The live worker marks the one-shot armed-preflight receipt as consumed
    # before it constructs the StarterPolicy.  Keep that durable consumption
    # state, but let this exact in-flight route still read the receipt while
    # rebuilding its audited transit metadata.  Otherwise the route loses
    # Sanctuary preparation and falls back to the generic hazard stop.
    mrinthas_route_state = state
    if isinstance(state, Mapping):
        armed_preflight_marker = state.get(
            _SOURCE_RANKED_MRINTHAS_ARMED_PREFLIGHT_REVALIDATION_KEY
        )
        if (
            isinstance(armed_preflight_marker, Mapping)
            and armed_preflight_marker.get("policy_id")
            == _source_ranked_policy_id(
                candidate,
                character_level=character_level,
            )
            and armed_preflight_marker.get("target_dispatch_started") is True
        ):
            mrinthas_route_state = dict(state)
            mrinthas_route_state[
                _SOURCE_RANKED_MRINTHAS_ARMED_PREFLIGHT_REVALIDATION_KEY
            ] = {
                **dict(armed_preflight_marker),
                "target_dispatch_started": False,
            }
        handoff_marker = state.get(
            _SOURCE_RANKED_MRINTHAS_ROUTE_HANDOFF_REVALIDATION_KEY
        ) if isinstance(state, Mapping) else None
        if (
            isinstance(handoff_marker, Mapping)
            and handoff_marker.get("policy_id")
            == _source_ranked_policy_id(
                candidate,
                character_level=character_level,
            )
            and handoff_marker.get("target_dispatch_started") is True
        ):
            if mrinthas_route_state is state:
                mrinthas_route_state = dict(state)
            mrinthas_route_state[
                _SOURCE_RANKED_MRINTHAS_ROUTE_HANDOFF_REVALIDATION_KEY
            ] = {
                **dict(handoff_marker),
                "target_dispatch_started": False,
            }
    mrinthas_guard_transit = _source_ranked_mrinthas_guard_route_allowed(
        candidate,
        character_level=character_level,
        source_world=world,
        state=mrinthas_route_state,
        character_max_hp=character_max_hp,
    )
    if mrinthas_guard_transit:
        armed_transit_mobile_vnums = (
            _SOURCE_MRINTHAS_GUARD_ROUTE_AGGRESSOR_VNUM,
        )
    cyclops_route_state = state or {}
    cyclops_route_retry = False
    if isinstance(state, Mapping):
        retry_marker = state.get(_SOURCE_RANKED_ARMED_TRANSIT_ROUTE_RETRY_KEY)
        retry_policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        if (
            candidate.mobile_vnum == _SOURCE_CYCLOPS_TORTURER_MOBILE_VNUM
            and candidate.room_vnum == _SOURCE_CYCLOPS_TORTURER_ROOM_VNUM
            and isinstance(retry_marker, Mapping)
            and retry_marker.get("policy_id") == retry_policy_id
            and retry_marker.get("boot_id") == state.get("world_boot_id")
            and retry_marker.get("level") in {None, character_level}
            and retry_marker.get("mobile_vnums")
            == sorted(_SOURCE_CYCLOPS_TORTURER_ARMED_TRANSIT_MOBILE_VNUMS)
            and (
                retry_marker.get("status") in {"pending", "attempted"}
                or retry_marker.get("target_dispatch_started") is True
            )
        ):
            # The campaign marks this exact route retry as attempted before
            # assembling the live worker.  Preserve the already-authorized
            # source contract through construction without resurrecting the
            # retry marker or reopening any other prior loss.
            cyclops_route_retry = True
    cyclops_torturer_transit = _source_ranked_cyclops_torturer_route_risk_allowed(
        candidate,
        cyclops_route_state,
        character_level=character_level,
        source_world=world,
        allow_prior_route_loss=cyclops_route_retry,
    )
    if cyclops_torturer_transit:
        armed_transit_mobile_vnums = tuple(
            sorted(_SOURCE_CYCLOPS_TORTURER_ARMED_TRANSIT_MOBILE_VNUMS)
        )
    cyclops_smithy_route_revalidation = False
    cyclops_smithy_visibility_revalidation = False
    if isinstance(state, Mapping):
        smithy_marker = state.get(
            _SOURCE_RANKED_CYCLOPS_SMITHY_ROUTE_REVALIDATION_KEY
        )
        smithy_policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        cyclops_smithy_route_revalidation = bool(
            isinstance(smithy_marker, Mapping)
            and smithy_marker.get("policy_id") == smithy_policy_id
            and smithy_marker.get("boot_id") == state.get("world_boot_id")
            and smithy_marker.get("level") in {None, character_level}
            and smithy_marker.get("source_revision")
            == state.get(_SOURCE_REVISION_KEY)
            and smithy_marker.get("revision")
            == _SOURCE_RANKED_CYCLOPS_SMITHY_ROUTE_REVALIDATION_REVISION
            and smithy_marker.get("status") in {"pending", "attempted"}
        )
        cyclops_smithy_visibility_revalidation = (
            _source_ranked_cyclops_smithy_visibility_marker_active(
                state,
                candidate,
                character_level=character_level,
            )
        )
    cyclops_smithy_transit = _source_ranked_cyclops_smithy_route_risk_allowed(
        candidate,
        state or {},
        character_level=character_level,
        source_world=world,
        allow_prior_route_hazard=cyclops_smithy_route_revalidation,
        allow_visibility_route_revalidation=(
            cyclops_smithy_visibility_revalidation
        ),
    )
    if cyclops_smithy_transit:
        armed_transit_mobile_vnums = tuple(
            sorted(_SOURCE_CYCLOPS_TORTURER_ARMED_TRANSIT_MOBILE_VNUMS)
        )
    armed_transit_room_vnums: tuple[str, ...] = ()
    if armed_transit_mobile_vnums:
        route_rooms = _source_route_room_vnums(
            world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
        reachable_rooms: set[int] = set()
        for mobile_vnum in armed_transit_mobile_vnums:
            reachable_rooms.update(
                source_mobile_search_rooms(world, mobile_vnum)
            )
        armed_transit_room_vnums = tuple(
            str(room_vnum)
            for room_vnum in dict.fromkeys(route_rooms)
            if room_vnum in reachable_rooms
        )
    bounded_program = False
    bounded_program_below_xp_band = False
    route_program_mobile_vnums = _source_ranked_route_program_mobile_vnums(
        candidate,
        world,
    )
    preflight_room_vnum = candidate.route_preflight_room_vnum
    preflight_command = candidate.route_preflight_command
    preflight_target = candidate.route_preflight_target
    preflight_hard_hazard = candidate.route_preflight_hard_hazard
    preflight_retryable = bool(candidate.route_preflight_route_room_names)
    preflight_route_room_names = candidate.route_preflight_route_room_names
    preflight_any_location_hazard = False
    preflight_checks = tuple(candidate.route_preflight_checks)
    if (
        not preflight_checks
        and preflight_command
        and preflight_target
    ):
        preflight_checks = ((preflight_command, preflight_target),)
    preflight_mobile_vnums = route_program_mobile_vnums
    ota_arena_preflight = _source_ranked_ota_arena_preflight_metadata(
        candidate,
        world,
        character_level=character_level,
    )
    ota_arena_deep_below_band_mobile_vnums = (
        _source_ranked_ota_arena_deep_below_band_mobile_vnums(
            candidate,
            world,
            character_level=character_level,
        )
        if ota_arena_preflight is not None
        else ()
    )
    if ota_arena_preflight is not None:
        preflight_room_vnum = ota_arena_preflight["room_vnum"]
        preflight_checks = tuple(ota_arena_preflight["checks"])
        preflight_command, preflight_target = preflight_checks[0]
        preflight_hard_hazard = not bool(
            ota_arena_deep_below_band_mobile_vnums
        )
        preflight_retryable = True
        preflight_route_room_names = tuple(
            ota_arena_preflight["route_room_names"]
        )
        preflight_mobile_vnums = tuple(
            ota_arena_preflight["source_mobile_vnums"]
        )
    forced_drunk_preflight = False
    if force_route_program_preflight and not route_program_mobile_vnums:
        drunk = world.mobiles.get(3064)
        route_rooms = _source_route_room_vnums(
            world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
        drunk_rooms = set(source_mobile_search_rooms(world, 3064))
        if (
            candidate.route_origin_room_vnum == RECALL_VNUM
            and drunk is not None
            and drunk.short_description.casefold() == "the drunk"
            and not _source_mobile_has_deterministic_attack_program(drunk)
            and source_mobile_route_program_attacker_is_bounded(
                world,
                drunk,
                character_level=character_level,
                character_max_hp=character_max_hp,
            )
            and set(route_rooms).intersection(drunk_rooms)
        ):
            forced_drunk_preflight = True
            preflight_room_vnum = str(RECALL_VNUM)
            preflight_command = "where drunk"
            preflight_target = drunk.short_description
            preflight_checks = ((preflight_command, preflight_target),)
            preflight_hard_hazard = True
            preflight_retryable = True
            preflight_route_room_names = _source_route_room_names(
                world,
                route_rooms,
            )
            preflight_mobile_vnums = (3064,)
    white_lotus_preflight = _source_ranked_white_lotus_route_preflight_metadata(
        candidate,
        world,
        character_level=character_level,
    )
    if (
        white_lotus_preflight is not None
        and not preflight_command
        and not preflight_target
    ):
        preflight_room_vnum = white_lotus_preflight["room_vnum"]
        preflight_checks = tuple(white_lotus_preflight["checks"])
        preflight_command, preflight_target = preflight_checks[0]
        # The two exact Miden'nir wanderers are source-proven, deep below-band
        # and unarmed.  Their locations are useful route evidence, but a
        # positive ``where`` result is not a hard stop for a level-45 pilot.
        # Keep the checks so a live identity can still be handled by the
        # ordinary below-band/crowd/health gates while the White Lotus Chief
        # remains behind its own mage-special and Sanctuary contract.
        preflight_hard_hazard = False
        preflight_retryable = True
        preflight_route_room_names = tuple(
            white_lotus_preflight["route_room_names"]
        )
        preflight_mobile_vnums = tuple(
            white_lotus_preflight["source_mobile_vnums"]
        )
        preflight_any_location_hazard = False
    wanderer_preflight = _source_ranked_route_wanderer_preflight_metadata(
        candidate,
        world,
        character_level=character_level,
    )
    if (
        wanderer_preflight is not None
        and not preflight_command
        and not preflight_target
    ):
        preflight_room_vnum = wanderer_preflight["room_vnum"]
        preflight_checks = tuple(wanderer_preflight["checks"])
        preflight_command, preflight_target = preflight_checks[0]
        preflight_hard_hazard = True
        preflight_retryable = True
        preflight_route_room_names = tuple(
            wanderer_preflight["route_room_names"]
        )
        preflight_any_location_hazard = True
    if mrinthas_guard_transit:
        route_rooms = _source_route_room_vnums(
            world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
        mobile = world.mobiles.get(
            _SOURCE_MRINTHAS_GUARD_ROUTE_AGGRESSOR_VNUM
        )
        if route_rooms and mobile is not None:
            preflight_room_vnum = str(candidate.route_origin_room_vnum)
            preflight_command = (
                f"where {_source_mobile_where_keyword(mobile)}"
            )
            preflight_target = mobile.short_description
            preflight_checks = ((preflight_command, preflight_target),)
            preflight_hard_hazard = True
            preflight_retryable = True
            preflight_route_room_names = _source_route_room_names(
                world,
                route_rooms,
            )
    plain_armed_transit_preflight = bool(
        armed_transit_mobile_vnums
        and armed_transit_mobile_vnums
        == _source_ranked_plain_armed_transit_mobile_vnums(
            candidate,
            world,
            character_level=character_level,
            character_max_hp=character_max_hp,
        )
    )
    sanctuary_armed_transit_preflight = bool(
        armed_transit_mobile_vnums
        and armed_transit_mobile_vnums
        == _source_ranked_armed_transit_mobile_vnums(
            candidate,
            world,
            character_level=character_level,
            character_max_hp=character_max_hp,
        )
    )
    unarmed_endpoint_armed_transit_preflight = bool(
        armed_transit_mobile_vnums
        and armed_transit_mobile_vnums
        == _source_ranked_unarmed_endpoint_armed_transit_mobile_vnums(
            candidate,
            world,
            character_level=character_level,
            character_max_hp=character_max_hp,
        )
    )
    level_only_armed_transit_preflight = bool(
        armed_transit_mobile_vnums
        and armed_transit_mobile_vnums
        == _source_ranked_level_only_armed_transit_mobile_vnums(
            candidate,
            world,
            character_level=character_level,
        )
    )
    armed_transit_preflight = (
        plain_armed_transit_preflight
        or sanctuary_armed_transit_preflight
        or unarmed_endpoint_armed_transit_preflight
        or level_only_armed_transit_preflight
        or mrinthas_guard_transit
        or cyclops_torturer_transit
        or cyclops_smithy_transit
    )
    if armed_transit_preflight and not preflight_command:
        route_rooms = _source_route_room_vnums(
            world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
        checks = tuple(
            (
                f"where {_source_mobile_where_keyword(world.mobiles[vnum])}",
                world.mobiles[vnum].short_description,
            )
            for vnum in armed_transit_mobile_vnums
            if vnum in world.mobiles
        )
        if checks and route_rooms:
            preflight_room_vnum = str(candidate.route_origin_room_vnum)
            preflight_checks = checks
            preflight_command, preflight_target = checks[0]
            preflight_hard_hazard = True
            preflight_retryable = True
            preflight_route_room_names = _source_route_room_names(
                world,
                route_rooms,
            )
    if armed_transit_preflight:
        # This contract checks only the audited route rooms.  Do not inherit
        # the broader wanderer preflight that treats every source location as
        # a hazard; the live controller still requires one exact enemy,
        # Sanctuary, and the ordinary health/output gates.
        preflight_any_location_hazard = False
    bounded_moria_transit = bool(
        allow_bounded_moria_transit
        and _source_ranked_moria_funding_transit_allowed(
            candidate,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=world,
        )
    )
    capacity_endpoint = bool(
        _source_ranked_bounded_route_program_capacity_allowed(
            candidate,
            character_level=character_level,
            source_world=world,
        )
        and _source_ranked_capacity_research_candidate(
            candidate,
            character_level=character_level,
            source_world=world,
            allow_bounded_route_program=True,
        )
    )
    route_program_admitted = _source_ranked_route_program_candidate_allowed(
        candidate,
        character_level=character_level,
        source_world=world,
        # Selection has already admitted this endpoint for exact live
        # isolation. Its population does not change the transit greeter.
        allow_capacity_research=True,
        allow_capacity_endpoint=True,
        allow_sanctuary_protected_target=allow_sanctuary_protected_target,
        allow_bounded_moria_transit=allow_bounded_moria_transit,
        character_max_hp=character_max_hp,
    )
    if route_program_admitted:
        try:
            mobile_vnum = int(route_program_mobile_vnums[0])
        except (IndexError, TypeError, ValueError):
            mobile_vnum = 0
        mobile = world.mobiles.get(mobile_vnum)
        bounded_program = bool(
            mobile is not None
            and source_mobile_route_program_attacker_is_bounded(
                world,
                mobile,
                character_level=character_level,
                character_max_hp=character_max_hp,
            )
        )
        bounded_program_below_xp_band = bool(
            bounded_program
            and mobile is not None
            and _mobile_level_range(mobile.level)[1] <= character_level - 5
        )
    if (
        bounded_program_below_xp_band
        or capacity_endpoint
    ) and (
        bounded_program
        and not bounded_moria_transit
        and not force_route_program_preflight
        and not armed_transit_mobile_vnums
    ):
        return {
            "route_preflight_room_vnum": None,
            "route_preflight_command": None,
            "route_preflight_target": None,
            "route_preflight_checks": (),
            "route_preflight_hard_hazard": False,
            "route_preflight_retryable": False,
            "route_preflight_route_room_names": (),
            "route_preflight_any_location_hazard": False,
            "route_preflight_scan_room_vnums": (),
            "route_preflight_deep_below_band_mobile_vnums": (
                ota_arena_deep_below_band_mobile_vnums
            ),
            "route_source_program_audited": True,
            "route_bounded_borderline_source_mobile_vnums": (
                borderline_route_mobile_vnums
            ),
            "route_allowed_plain_transit_mobile_vnums": (
                plain_transit_mobile_vnums
            ),
            "route_allowed_plain_transit_room_vnums": (
                plain_transit_room_vnums
            ),
            "route_allowed_armed_transit_mobile_vnums": (
                armed_transit_mobile_vnums
            ),
            "route_allowed_armed_transit_room_vnums": (
                armed_transit_room_vnums
            ),
            "refresh_sanctuary_between_plain_transit_fights": bool(
                sanctuary_armed_endpoint_transit_mobile_vnums
            ),
            "require_sanctuary_at_endpoint": bool(
                sanctuary_armed_endpoint_transit_mobile_vnums
            ),
        }
    armed_preflight_mobile_vnums = tuple(
        int(vnum)
        for vnum in preflight_mobile_vnums
        if str(vnum).isdigit() and int(vnum) in set(armed_transit_mobile_vnums)
    )
    return {
        "route_preflight_room_vnum": preflight_room_vnum,
        "route_preflight_command": preflight_command,
        "route_preflight_target": preflight_target,
        "route_preflight_checks": preflight_checks,
        "route_preflight_hard_hazard": preflight_hard_hazard,
        "route_preflight_retryable": preflight_retryable,
        "route_preflight_route_room_names": preflight_route_room_names,
        "route_preflight_any_location_hazard": preflight_any_location_hazard,
        "route_preflight_scan_room_vnums": (
            tuple(str(room_vnum) for room_vnum in ota_arena_preflight["scan_room_vnums"])
            if ota_arena_preflight is not None
            else tuple(
                str(room_vnum)
                for mobile_vnum in armed_transit_mobile_vnums
                for room_vnum in source_mobile_search_rooms(world, mobile_vnum)
            )
            if armed_transit_preflight
            else tuple(
                str(room_vnum)
                for room_vnum in source_mobile_search_rooms(
                    world,
                    preflight_mobile_vnums[0],
                )
            )
            if forced_drunk_preflight
            else tuple(white_lotus_preflight["scan_room_vnums"])
            if white_lotus_preflight is not None and not route_program_mobile_vnums
            else (
                tuple(wanderer_preflight["scan_room_vnums"])
                if wanderer_preflight is not None and not route_program_mobile_vnums
                else _source_ranked_route_program_scan_room_vnums(
                    world,
                    candidate,
                    character_level=character_level,
                )
            )
        ),
        "route_source_program_audited": True,
        "route_bounded_borderline_source_mobile_vnums": (
            borderline_route_mobile_vnums
        ),
        "route_allowed_plain_transit_mobile_vnums": (
            plain_transit_mobile_vnums
        ),
        "route_allowed_plain_transit_room_vnums": (
            plain_transit_room_vnums
        ),
        "route_allowed_armed_transit_mobile_vnums": (
            armed_transit_mobile_vnums
        ),
        "route_allowed_armed_transit_room_vnums": (
            armed_transit_room_vnums
        ),
        "refresh_sanctuary_between_plain_transit_fights": bool(
            sanctuary_armed_endpoint_transit_mobile_vnums
        ),
        "require_sanctuary_at_endpoint": bool(
            sanctuary_armed_endpoint_transit_mobile_vnums
        ),
        "route_preflight_source_mobile_vnum": (
            armed_transit_mobile_vnums[0]
            if armed_transit_preflight and armed_transit_mobile_vnums
            else
            armed_preflight_mobile_vnums[0]
            if len(armed_preflight_mobile_vnums) == 1
            else int(preflight_mobile_vnums[0])
            if len(preflight_mobile_vnums) == 1
            and str(preflight_mobile_vnums[0]).isdigit()
            else (
                int(white_lotus_preflight["source_mobile_vnums"][0])
                if white_lotus_preflight is not None
                and white_lotus_preflight["source_mobile_vnums"]
                else (
                int(wanderer_preflight["source_mobile_vnums"][0])
                if wanderer_preflight is not None
                and wanderer_preflight["source_mobile_vnums"]
                else None
                )
            )
        ),
        "route_preflight_below_band_transit_mobile_vnums": (
            tuple(int(vnum) for vnum in white_lotus_preflight["source_mobile_vnums"])
            if white_lotus_preflight is not None
            and white_lotus_preflight["source_mobile_vnums"]
            else ()
        ),
        "route_preflight_deep_below_band_mobile_vnums": (
            ota_arena_deep_below_band_mobile_vnums
        ),
    }


def _source_ranked_borderline_route_aggressor_vnums(
    candidate: HuntCandidate,
    world: WorldSource,
    *,
    character_level: int,
    character_max_hp: int | None,
) -> tuple[int, ...]:
    """Return the one source-validated fringe aggressor carried by a route.

    The ordinary bounded-transit proof already covers strict low-risk
    mobiles.  This separate list records only the narrower level-4 fringe
    proof so StarterPolicy can consume it without making every source-known
    aggressive mobile attackable.
    """
    if character_max_hp is None or character_max_hp <= 0:
        return ()
    resets_by_mobile = _source_ranked_resets_by_mobile(world)
    if not _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=world,
        character_max_hp=character_max_hp,
    ):
        return ()
    borderline: list[int] = []
    for raw_vnum in candidate.route_aggressive_mobile_vnums:
        try:
            mobile_vnum = int(raw_vnum)
        except (TypeError, ValueError):
            continue
        mobile = world.mobiles.get(mobile_vnum)
        if mobile is None or source_mobile_route_aggressor_is_bounded(
            world,
            mobile,
            character_level=character_level,
            character_max_hp=character_max_hp,
            resets_by_mobile=resets_by_mobile,
        ):
            continue
        resets = tuple(resets_by_mobile.get(mobile_vnum, ()))
        # The borderline transit escape hatch is only for an armed route
        # mobile.  An unarmed aggressor remains a route hazard, even when the
        # older damage envelope says it could probably be survived.
        if not resets or any(
            sum(
                slot in {WEAR_WIELD, WEAR_DUAL}
                for slot, _object_vnum in reset.equipment
            )
            != 1
            or any(
                (
                    slot in {WEAR_WIELD, WEAR_DUAL}
                    and (
                        (item := world.objects.get(object_vnum)) is None
                        or item.item_type != ITEM_WEAPON
                    )
                )
                or (
                    slot not in {WEAR_WIELD, WEAR_DUAL}
                    and (
                        (item := world.objects.get(object_vnum)) is None
                        or item.item_type != ITEM_ARMOR
                    )
                )
                for slot, object_vnum in reset.equipment
            )
            for reset in resets
        ):
            continue
        if any(
            _bounded_borderline_route_aggressor(
                world,
                reset,
                character_level=character_level,
                character_max_hp=character_max_hp,
            )
            for reset in resets
        ):
            borderline.append(mobile_vnum)
    return tuple(sorted(set(borderline)))


_SOURCE_RANKED_BORDERLINE_ROUTE_AGGRESSOR_VNUMS_UNCACHED = (
    _source_ranked_borderline_route_aggressor_vnums
)


def _source_ranked_borderline_route_aggressor_vnums(
    candidate: HuntCandidate,
    world: WorldSource,
    *,
    character_level: int,
    character_max_hp: int | None,
) -> tuple[int, ...]:
    cache = _CAMPAIGN_SOURCE_SELECTOR_CACHE.get()
    cache_key = (
        "borderline-route-aggressors",
        id(candidate),
        id(world),
        character_level,
        character_max_hp,
    )
    if (
        cache is not None
        and _CAMPAIGN_PREPARATION_DEADLINE.get() is not None
        and cache_key in cache
    ):
        return cache[cache_key]
    result = _SOURCE_RANKED_BORDERLINE_ROUTE_AGGRESSOR_VNUMS_UNCACHED(
        candidate,
        world,
        character_level=character_level,
        character_max_hp=character_max_hp,
    )
    if cache is not None and _CAMPAIGN_PREPARATION_DEADLINE.get() is not None:
        cache[cache_key] = result
    return result


def _source_ranked_route_program_preflight_result_retryable(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Recognize the one route-program result that may be rechecked.

    A source-registered preflight hazard is normally a cooldown because a
    static route hazard must never be retried blindly. The narrow exception
    is a candidate already admitted by
    ``_source_ranked_route_program_candidate_allowed``: its exact ``where``
    locator and bounded StarterPolicy retry can safely recheck a wandering
    greet-program mobile from the healer.
    """
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    return bool(
        isinstance(result, Mapping)
        and str(result.get("route_hazard") or "").startswith(
            _SOURCE_RANKED_PREFLIGHT_ROUTE_HAZARD_PREFIX
        )
    )


def _source_ranked_unprotected_hp_fuzz_probe_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
    allow_exact_aggressive_endpoint: bool = False,
) -> bool:
    """Permit one empirical probe across a source HP-fuzz boundary.

    The source parser's fuzz range is useful for scouting, but it is not a
    target HP or predicted-output admission rule. Keep the exact source
    identity, level-band, route, special, and prior-loss boundaries here;
    fresh live ``consider`` and the starter's own health floor decide combat.
    """
    candidate_rejections = set(candidate.autonomy_rejections)
    candidate_rejections.difference_update(_SOURCE_OUTPUT_EVIDENCE_REJECTIONS)
    exact_aggressive_endpoint = bool(
        allow_exact_aggressive_endpoint
        and candidate_rejections == {"target is aggressive"}
    )
    if _state_has_sanctuary_reserve(state) and not allow_exact_aggressive_endpoint:
        return False
    if (
        candidate.is_coin_stash
        or not (candidate.target_selection_safe or exact_aggressive_endpoint)
        or candidate.equipped_weapons
        or (
            candidate.specials
            and not _source_ranked_adept_support_target_allowed(
                candidate,
                source_world,
            )
        )
        or candidate.route_hard_hazard_targets
    ):
        return False
    if candidate.route_preflight_hard_hazard and not (
        source_world is not None
        and _source_ranked_route_program_candidate_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
        )
    ):
        # Only the exact, source-locatable low-level route program may share
        # this one-time HP probe. Unknown transit hazards remain blocked.
        return False
    minimum_level, maximum_level = candidate.estimated_level_range
    if maximum_level <= character_level - 5:
        # A live consider may prove that a close fuzzy-loaded mobile is still
        # useful XP. This only admits the bounded scout; it does not authorize
        # combat against an instance that the entire source range places below
        # the useful-XP floor.
        return False
    current_level_fuzz = (
        candidate.level == character_level
        and minimum_level <= character_level - 2
        and maximum_level <= character_level + 2
    )
    adjacent_higher_fuzz = (
        candidate.level == character_level + 1
        and minimum_level <= character_level + 1
        and maximum_level <= character_level + 3
    )
    two_levels_higher_fuzz = (
        candidate.level == character_level + 2
        and minimum_level >= character_level
        and maximum_level <= character_level + 4
    )
    higher_nominal_plain_fuzz = (
        character_level + 3 <= candidate.level <= character_level + 5
        and minimum_level > character_level
        and minimum_level >= candidate.level - 2
        and maximum_level <= min(candidate.level + 2, character_level + 7)
    )
    if maximum_level > character_level + 1 and not (
        current_level_fuzz
        or adjacent_higher_fuzz
        or two_levels_higher_fuzz
        or higher_nominal_plain_fuzz
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if _source_ranked_xp_loss_record(state, policy_id) is None:
        return True
    if _source_ranked_special_hp_revalidation_pending(
        state,
        policy_id=policy_id,
    ):
        return True
    return False


def _source_ranked_protected_hp_fuzz_probe_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
    allow_level_ceiling: bool = False,
    allow_nominal_level_fuzz: bool = False,
) -> bool:
    """Retain only the source and resource checks for a legacy protected path.

    Target HP, predicted target output, and a Sanctuary-derived HP probe are
    historical evidence. Ordinary admission is handled by relative level and
    live ``consider``; this compatibility helper must not recreate the old
    HP-window gate.
    """
    if source_world is None or not _state_has_usable_sanctuary_reserve(state):
        return False
    if (
        candidate.is_coin_stash
        or not candidate.target_selection_safe
        or candidate.equipped_weapons
        or candidate.specials
        or candidate.route_hard_hazard_targets
    ):
        return False
    target_mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        target_mobile is None
        or target_mobile.aggressive
        or target_mobile.attack_programs
    ):
        # Aggressive or scripted attackers can engage before the protected
        # opener. Keep this source procedure separate because it cannot issue
        # live consider before entry; any GMCP HP is observation evidence.
        return False
    if candidate.route_preflight_hard_hazard:
        # The only permitted hard route hazard is the already-audited,
        # probabilistic ``where drunk`` locator contract.
        if not _source_ranked_route_program_candidate_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
            allow_sanctuary_protected_target=True,
        ):
            return False
    elif candidate.route_attack_program_mobile_vnums:
        # A route program without the exact preflight is an unknown hazard.
        return False
    for raw_mobile_vnum in candidate.route_special_mobile_vnums:
        try:
            mobile_vnum = int(raw_mobile_vnum)
        except (TypeError, ValueError):
            return False
        specials = set(source_world.mobile_specials.get(mobile_vnum, ()))
        if specials and not specials <= SAFE_NONCOMBAT_SPECIALS:
            return False
    minimum_level, maximum_level = candidate.estimated_level_range
    level_ceiling_probe = (
        allow_level_ceiling
        and _source_ranked_level_ceiling_probe_allowed(
            candidate,
            character_level=character_level,
            character_max_hp=None,
        )
    )
    nominal_level_fuzz_probe = (
        allow_nominal_level_fuzz
        and _source_ranked_nominal_level_fuzz_probe_allowed(
            candidate,
            character_level=character_level,
            character_max_hp=None,
        )
    )
    if (
        minimum_level <= 0
        or maximum_level <= 0
        or candidate.level <= character_level - 5
        or (
            maximum_level > character_level + 1
            and not (level_ceiling_probe or nominal_level_fuzz_probe)
        )
    ):
        return False
    if not _source_ranked_caster_output_can_cover(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    return _source_ranked_xp_loss_record(state, policy_id) is None


def _source_ranked_protected_aggressive_hp_fuzz_probe_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
) -> bool:
    """Permit one exact-route sanctuary probe for a plain aggressive target.

    A source-ranked aggressive mobile can already engage while the endpoint
    snapshot is being processed, so it cannot use the passive HP-fuzz opener.
    Keep this separate and narrower: the target must be unarmed and unscripted,
    its route must have the audited exact preflight, and the source special
    and route hazards must be bounded. Target HP and predicted output remain
    evidence; the live runner owns the player's withdrawal floor.
    """
    if source_world is None or not _state_has_usable_sanctuary_reserve(state):
        return False
    raw_max_hp = state.get("max_hp")
    if not isinstance(raw_max_hp, (int, float)) or raw_max_hp <= 0:
        return False
    character_max_hp = int(raw_max_hp)
    if (
        candidate.is_coin_stash
        or not candidate.target_selection_safe
        or candidate.equipped_weapons
        or candidate.specials
        or candidate.route_hard_hazard_targets
    ):
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if mobile is None or not mobile.aggressive or mobile.attack_programs:
        return False
    if not candidate.route_preflight_hard_hazard:
        # The aggressive exception is only for a route whose exact source
        # preflight was audited; it is not a general aggressive-target bypass.
        return False
    if not _source_ranked_route_program_candidate_allowed(
        candidate,
        character_level=character_level,
        source_world=source_world,
        allow_sanctuary_protected_target=True,
    ):
        return False
    if not _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    ):
        return False
    minimum_level, maximum_level = candidate.estimated_level_range
    if (
        minimum_level <= 0
        or maximum_level <= 0
        or candidate.level <= character_level - 5
        or maximum_level > character_level + 1
    ):
        return False
    if not _source_ranked_caster_output_can_cover(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
        protected_incoming_damage=True,
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    return _source_ranked_xp_loss_record(state, policy_id) is None


def _source_ranked_protected_level_ceiling_hp_probe_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
) -> bool:
    """Permit one protected probe for a nominally next-level mobile.

    The ordinary protected HP-fuzz contract stops at character level plus one.
    A source nominally one level above the character can legitimately load up
    to two levels higher, so retain the same sanctuary, route, output, and
    live-GMCP gates while using the existing level-ceiling admission rule.
    """
    mobile = source_world.mobiles.get(candidate.mobile_vnum) if source_world else None
    if mobile is None or mobile.attack_programs:
        # Scripted attackers do not qualify for the ordinary level-ceiling
        # probe; their entry behavior needs the stricter special path.
        return False
    return _source_ranked_protected_hp_fuzz_probe_allowed(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
        allow_level_ceiling=True,
    )


def _source_ranked_protected_nominal_level_fuzz_probe_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
) -> bool:
    """Permit a protected probe for a nominal-current-level mobile.

    DD4's source load fuzz allows a nominally current-level mobile to load two
    levels higher. Keep that extra level only for a passive, source-audited
    target whose normal current-level probe already passes the movement,
    route, output, and sanctuary bounds.
    """
    mobile = source_world.mobiles.get(candidate.mobile_vnum) if source_world else None
    if mobile is None or mobile.attack_programs:
        return False
    return _source_ranked_protected_hp_fuzz_probe_allowed(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
        allow_nominal_level_fuzz=True,
    )


_SOURCE_SMALL_DRAGON_LIGHTNING_MOBILE_VNUM = 9925
_SOURCE_SMALL_DRAGON_LIGHTNING_ROOM_VNUM = 9955
_SOURCE_LIGHTNING_BREATH_ROUTE_REJECTION = (
    "below-band transit aggressor is not an XP target"
)


def _source_ranked_small_dragon_lightning_route_repair_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
    character_max_hp: int | None,
) -> bool:
    """Permit the audited Kaladim route hazard beside Small Dragon."""
    special_rejection = "target has special procedure spec_breath_lightning"
    if (
        source_world is None
        or candidate.mobile_vnum != _SOURCE_SMALL_DRAGON_LIGHTNING_MOBILE_VNUM
        or candidate.room_vnum != _SOURCE_SMALL_DRAGON_LIGHTNING_ROOM_VNUM
        or candidate.specials != ("spec_breath_lightning",)
        or set(candidate.autonomy_rejections)
        != {special_rejection, _SOURCE_LIGHTNING_BREATH_ROUTE_REJECTION}
        or not candidate.route_aggressive_mobile_vnums
    ):
        return False
    return _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    )


def _source_ranked_protected_special_hp_fuzz_probe_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
    maximum_level_offset: int | None = None,
    allow_lower_hp_above_character: bool = False,
) -> bool:
    """Permit one source-audited special opener behind its hazard reserve.

    The exact special, route, and recovery contracts remain strict. Target HP
    and predicted output are retained as evidence only; the live controller
    owns the player's withdrawal floor after the opener.
    """
    if (
        source_world is None
        or len(candidate.specials) != 1
        or candidate.specials[0] not in _SOURCE_SPECIAL_HP_FUZZ_PROBE_SPECIALS
        or not _state_has_usable_sanctuary_reserve(state)
    ):
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    economic_endpoint = bool(
        candidate.specials[0] in ECONOMIC_SPECIALS
        and source_special_profile(candidate.specials[0]).risk == "economic"
        and source_special_profile(candidate.specials[0]).xp_bonus == 0
    )
    if mobile is None or (
        candidate.equipped_weapons and not mobile.aggressive and not economic_endpoint
    ):
        # DD4 sends enemy HP only during combat. The starter cannot open this
        # passive armed-special probe without it, so reject before travelling.
        return False
    raw_max_hp = state.get("max_hp")
    if not isinstance(raw_max_hp, (int, float)) or raw_max_hp <= 0:
        return False
    character_max_hp = int(raw_max_hp)
    del allow_lower_hp_above_character
    famous_gas_recovery = _source_ranked_famous_gas_recovery_allowed(
        candidate,
        source_world,
        state,
    )
    if not famous_gas_recovery:
        if maximum_level_offset is None:
            if not _source_ranked_special_candidate_in_live_level_ceiling(
                candidate,
                character_level=character_level,
            ):
                return False
        elif (
            maximum_level_offset < 0
            or candidate.level > character_level + maximum_level_offset
        ):
            return False
    if candidate.route_hard_hazard_targets:
        return False
    if candidate.route_preflight_hard_hazard:
        # Retain the exact, source-matched ``where`` contract used for the
        # Midgaard drunk.  Other hard route hazards remain closed to a target
        # that may already be fighting on arrival.
        if not _source_ranked_route_program_preflight_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
        ):
            return False
    elif candidate.route_attack_program_mobile_vnums:
        return False
    route_aggressors_bounded = _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    )
    white_lotus_route = _source_ranked_white_lotus_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
    )
    if not route_aggressors_bounded and not white_lotus_route:
        return False
    audit_candidate = candidate
    if _source_ranked_small_dragon_lightning_route_repair_allowed(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    ):
        # The route proof already owns this exact below-band transit hazard.
        # Remove only that route annotation while checking the target's
        # lightning procedure; it is not permission for a different route or
        # a different special.
        audit_candidate = replace(
            candidate,
            autonomy_rejections=(
                "target has special procedure spec_breath_lightning",
            ),
        )
    if not _audited_source_special_candidate_allowed(
        audit_candidate,
        state=state,
        character_max_hp=character_max_hp,
        source_world=source_world,
        protected_incoming_damage=True,
    ):
        return False
    if economic_endpoint:
        # Economic specials such as spec_thief do not contribute combat
        # damage.  Their admission is owned by the source economic audit and
        # route/identity gates above; requiring a caster damage envelope here
        # would incorrectly close safe gear-recovery carriers.
        return True
    if not _source_ranked_caster_output_can_cover(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
        protected_incoming_damage=True,
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    return (
        _source_ranked_xp_loss_record(state, policy_id) is None
        or _source_ranked_special_hp_revalidation_pending(
            state,
            policy_id=policy_id,
        )
    )


def _source_ranked_route_specials_noncombat_only(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
) -> bool:
    """Allow only fully source-verified harmless specials along the route."""
    if not candidate.route_special_mobile_vnums:
        return True
    if source_world is None:
        return False
    for mobile_vnum in candidate.route_special_mobile_vnums:
        if (
            mobile_vnum in candidate.route_economic_hunt_mobile_vnums
            and "an economic special mobile can reach the route"
            in candidate.route_economic_source_rejections
            and set(candidate.route_economic_source_rejections) <= {
                "an economic special mobile can reach the route",
                "target reset capacity exceeds one",
            }
            and passive_economic_hunt_mobile(
                source_world,
                mobile_vnum,
                level=candidate.level,
                allow_bounded_population=plain_bounded_population(
                    candidate,
                    source_world,
                ),
            )
        ):
            continue
        mobile = source_world.mobiles.get(mobile_vnum)
        specials = tuple(source_world.mobile_specials.get(mobile_vnum, ()))
        resets = tuple(
            reset
            for reset in source_world.mob_resets
            if reset.mobile_vnum == mobile_vnum
        )
        if (
            mobile is None
            or mobile.aggressive
            or mobile.programs
            or not specials
            or not set(specials) <= SAFE_NONCOMBAT_SPECIALS
            or not resets
            or any(reset.equipment or reset.object_vnums for reset in resets)
            or any(
                source_special_profile(special).risk != "noncombat"
                or source_special_profile(special).xp_bonus != 0
                for special in specials
            )
        ):
            return False
    return True


def _source_ranked_post_loss_aggressive_probe_marker_matches(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    allow_unarmed: bool,
    allow_consumed: bool,
) -> bool:
    """Match the one exact aggressive post-loss probe for this level/boot."""
    boot_id = state.get("world_boot_id")
    marker = state.get(_SOURCE_RANKED_POST_LOSS_AGGRESSIVE_PROBE_KEY)
    if not isinstance(marker, Mapping):
        return bool(allow_unarmed and boot_id is not None)
    if (
        marker.get("boot_id") != boot_id
        or marker.get("level") != character_level
    ):
        return bool(allow_unarmed and boot_id is not None)
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if (
        marker.get("policy_id") != policy_id
        or marker.get("target") != candidate.target
        or marker.get("mobile_vnum") != candidate.mobile_vnum
        or marker.get("room_vnum") != candidate.room_vnum
        or marker.get("source_revision") != state.get(_SOURCE_REVISION_KEY)
    ):
        return False
    if marker.get("status") == "pending":
        return True
    record = state.get(_SOURCE_RANKED_CANDIDATE_KEY)
    return bool(
        allow_consumed
        and marker.get("status") == "attempted"
        and isinstance(record, Mapping)
        and record.get("post_loss_aggressive_probe") is True
    )


def _arm_source_ranked_post_loss_aggressive_probe(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Persist one source-bounded aggressive probe before campaign dispatch."""
    if not _source_ranked_post_loss_plain_probe_allowed(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
        allow_aggressive_target=True,
        allow_unarmed_aggressive_probe=True,
    ):
        return False
    marker = state.get(_SOURCE_RANKED_POST_LOSS_AGGRESSIVE_PROBE_KEY)
    if (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == character_level
        and marker.get("status") == "pending"
    ):
        return True
    state[_SOURCE_RANKED_POST_LOSS_AGGRESSIVE_PROBE_KEY] = {
        "boot_id": state.get("world_boot_id"),
        "level": character_level,
        "policy_id": _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        ),
        "target": candidate.target,
        "mobile_vnum": candidate.mobile_vnum,
        "room_vnum": candidate.room_vnum,
        "source_revision": state.get(_SOURCE_REVISION_KEY),
        "status": "pending",
    }
    return True


def _mark_source_ranked_post_loss_aggressive_probe(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Consume the exact aggressive probe before opening its live segment."""
    record = state.get(_SOURCE_RANKED_CANDIDATE_KEY)
    if (
        not isinstance(record, Mapping)
        or record.get("post_loss_aggressive_probe") is not True
        or not _source_ranked_post_loss_plain_probe_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
            allow_aggressive_target=True,
        )
    ):
        return False
    marker = state.get(_SOURCE_RANKED_POST_LOSS_AGGRESSIVE_PROBE_KEY)
    if not isinstance(marker, Mapping) or marker.get("status") != "pending":
        return False
    state[_SOURCE_RANKED_POST_LOSS_AGGRESSIVE_PROBE_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted_at": datetime.now(timezone.utc).isoformat(),
    }
    return True


def _source_ranked_post_loss_plain_probe_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
    resets_by_mobile: Mapping[int, Sequence[MobReset]] | None = None,
    allow_improved_output_revalidation: bool = False,
    allow_consumed_output_revalidation: bool = False,
    allow_aggressive_target: bool = False,
    allow_unarmed_aggressive_probe: bool = False,
    allow_consumed_aggressive_probe: bool = False,
) -> bool:
    """Allow one stricter plain probe after current-reboot XP losses.

    After a current-level loss, keep this path narrow: it cannot use a
    special, armed target, hard route hazard, or a policy that has already
    lost XP. Its separate aggressive form is one-use per level and boot, and
    still requires an exact source sentinel with no special, program, or
    weapon. Low-level route mobiles remain subject to the normal live route,
    identity, consider, and return gates. The player's own health floor and
    source route hazards remain authoritative; target HP and predicted output
    are recorded only as evidence. The improved-output arguments are retained
    for checkpoint compatibility, but their retired retry path is disabled.
    """
    if _state_has_sanctuary_reserve(state):
        return False
    raw_max_hp = state.get("max_hp")
    if not isinstance(raw_max_hp, (int, float)) or raw_max_hp <= 0:
        return False
    character_max_hp = int(raw_max_hp)
    if not any(
        record.get("level") in {None, character_level}
        for record in _source_ranked_xp_loss_records(state)
    ):
        # Fresh characters should use the ordinary probe, which retains the
        # wider single-attempt semantics and its existing audit trail.
        return False
    if source_world is None:
        return False
    training_audit = state.get(_TRAINING_AUDIT_KEY)
    if (
        isinstance(training_audit, Mapping)
        and not _campaign_training_audit_is_current(
            state,
            character_level=character_level,
        )
    ):
        return False
    loss_records = _source_ranked_xp_loss_records(state)
    if allow_aggressive_target and not any(
        record.get("boot_id") == state.get("world_boot_id")
        and record.get("level") == character_level
        for record in loss_records
    ):
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    all_target_resets = tuple(
        resets_by_mobile.get(candidate.mobile_vnum, ())
        if resets_by_mobile is not None
        else (
            reset
            for reset in source_world.mob_resets
            if reset.mobile_vnum == candidate.mobile_vnum
        )
    )
    target_resets = [
        reset for reset in all_target_resets
        if reset.room_vnum == candidate.room_vnum
    ]
    isolated_population = plain_bounded_population(
        candidate,
        source_world,
        resets_by_mobile=resets_by_mobile,
    )
    bounded_stay_area_target = bool(
        mobile is not None
        and mobile.stay_area
        and not mobile.sentinel
        and (isolated_population or (
            len(all_target_resets) == 1
            and all_target_resets[0].room_vnum == candidate.room_vnum
        ))
    )
    if (
        mobile is None
        or not (mobile.sentinel or bounded_stay_area_target)
        or mobile.aggressive != allow_aggressive_target
        or mobile.fear_aura
        or mobile.confused
        or (
            mobile.programs
            and (allow_aggressive_target or not noncombat_echo_programs_only(mobile.programs))
        )
        or source_world.mobile_specials.get(candidate.mobile_vnum)
        or (candidate.source_spawn_limit != 1 and not isolated_population)
        or candidate.room_spawn_count != 1
        or len(target_resets) != 1
        or target_resets[0].maximum_count != (candidate.source_spawn_limit if isolated_population else 1)
        or (
            allow_aggressive_target
            and (
                len(all_target_resets) != 1
                or all_target_resets[0].room_vnum != candidate.room_vnum
            )
        )
        or (
            mobile.stay_area
            and not mobile.sentinel
            and not bounded_stay_area_target
        )
    ):
        return False
    if allow_aggressive_target and not (
        _source_ranked_post_loss_aggressive_probe_marker_matches(
            candidate,
            state,
            character_level=character_level,
            allow_unarmed=allow_unarmed_aggressive_probe,
            allow_consumed=allow_consumed_aggressive_probe,
        )
    ):
        return False
    if (
        candidate.is_coin_stash
        or (not candidate.autonomous_safe and not isolated_population)
        or candidate.equipped_weapons
        or candidate.specials
        or (
            candidate.route_preflight_hard_hazard
            and not (
                source_world is not None
                and _source_ranked_route_program_candidate_allowed(
                    candidate,
                    character_level=character_level,
                    source_world=source_world,
                    allow_capacity_endpoint=isolated_population,
                    character_max_hp=character_max_hp,
                )
            )
        )
        or candidate.route_hard_hazard_targets
        or not _source_ranked_route_specials_noncombat_only(
            candidate,
            source_world,
        )
    ):
        return False
    if not _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    ):
        return False
    minimum_level, maximum_level = candidate.estimated_level_range
    # A passive target whose source fuzz straddles the useful-XP floor may be
    # admitted to this bounded live probe; exact live consider still decides.
    if maximum_level <= character_level - 5:
        return False
    if allow_aggressive_target and minimum_level <= character_level - 5:
        return False
    if (
        candidate.level > character_level
        or maximum_level > character_level + 2
    ):
        return False
    if not _source_ranked_caster_output_can_cover(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if _source_ranked_xp_loss_record(state, policy_id) is None:
        return True
    if (
        allow_improved_output_revalidation
        and _source_ranked_combat_output_revalidation_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    ):
        return True
    return bool(
        allow_consumed_output_revalidation
        and _source_ranked_consumed_output_revalidation_matches_candidate(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    )


def _source_ranked_passive_defense_probability(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
    allow_single_armed_target: bool = False,
    attacker_level_ceiling: int | None = None,
) -> Fraction | None:
    """Return the fresh, source-bounded chance an ordinary hit lands.

    Source HP/level fuzz can extend beyond the live consider scouting band.
    When this estimate is used to preflight that band, cap the attacker at the
    highest level the live check is allowed to admit; live consider remains
    authoritative for the actual target.
    """
    target_is_armed = bool(candidate.equipped_weapons)
    candidate_specials = frozenset(candidate.specials)
    source_specials = frozenset(
        source_world.mobile_specials.get(candidate.mobile_vnum, ())
        if source_world is not None
        else ()
    )
    verified_support_specials = bool(candidate_specials) and (
        candidate_specials == source_specials
        and source_specials <= SAFE_NONCOMBAT_SPECIALS
    )
    if (
        source_world is None
        or not _campaign_training_audit_is_current(
            state, character_level=character_level,
        )
        or state.get("form") != "normal"
        or not isinstance(state.get("affects"), (list, Mapping))
        or not isinstance(state.get("equipment"), list)
        or type(state.get("position")) is not int
        or state["position"] <= 4
        or (
            target_is_armed
            and (
                not allow_single_armed_target
                or len(candidate.equipped_weapons) != 1
            )
        )
        or candidate.specials and not (allow_single_armed_target and verified_support_specials)
        or (candidate.source_spawn_limit != 1 and not plain_bounded_population(candidate, source_world))
        or candidate.room_spawn_count != 1
        or candidate.estimated_level_range[1] <= 0
    ):
        return None
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        mobile is None
        or mobile.aggressive
        or mobile.fear_aura
        or not noncombat_echo_programs_only(mobile.programs)
        or source_specials
        and not (allow_single_armed_target and verified_support_specials)
    ):
        return None
    resets = [
        reset for reset in source_world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
        and reset.room_vnum == candidate.room_vnum
    ]
    if len(resets) != 1:
        return None
    if target_is_armed:
        if single_weapon_loadout(
            candidate,
            source_world,
        ) is None:
            return None
    reset_weapons: list[ObjectSource] = []
    for object_vnum in _reset_object_vnums(resets[0]):
        item = source_world.objects.get(object_vnum)
        if item is None:
            return None
        if item.item_type == ITEM_WEAPON:
            if not allow_single_armed_target or is_bow(item):
                return None
            reset_weapons.append(item)
            continue
        if item.item_type in {
            ITEM_WAND, ITEM_STAFF, ITEM_SCROLL, ITEM_POTION, ITEM_PILL,
        }:
            return None
    if target_is_armed:
        if (
            len(reset_weapons) != 1
            or normalize_item_name(reset_weapons[0].short_description)
            != normalize_item_name(candidate.equipped_weapons[0])
        ):
            return None
    elif reset_weapons:
        return None
    if allow_single_armed_target and not target_is_armed:
        return None
    if any(
        _state_has_active_affect(state["affects"], effect)
        for effect in (
            "blindness", "dazed", "arm trauma", "leg trauma", "hold",
            "hold person", "prone", "confusion",
        )
    ):
        return None
    character_class = state.get("character_class")
    if not isinstance(character_class, str) or not character_class:
        return None
    audit = state[_TRAINING_AUDIT_KEY]
    levels = audit.get("known_skill_levels")
    if not isinstance(levels, Mapping):
        return None
    # Do not combine a fresh audit with a conflicting historical skill map.
    skills = state.get("campaign_known_skills")
    current_levels = _skill_levels_from_state(state)
    if not isinstance(skills, (list, tuple)) or any(
        levels.get(skill) != current_levels.get(skill)
        for skill in ("dodge", "parry", "shield block", "pre-empt")
        if skill in skills
    ):
        return None
    shield = any(
        isinstance(record, Mapping)
        and record.get("wear_loc") == 11
        and (item := source_world.objects.get(record.get("vnum"))) is not None
        and item.item_type == 9
        for record in state["equipment"]
    )
    attacker_level = candidate.estimated_level_range[1]
    if attacker_level_ceiling is not None:
        attacker_level = min(attacker_level, attacker_level_ceiling)
    return normal_attack_landing_probability(
        character_level=character_level,
        attacker_level=attacker_level,
        character_class=character_class,
        known_skills=skills,
        known_skill_levels=levels,
        wielding=_source_ranked_primary_weapon_for_state(state, source_world) is not None,
        shield=shield,
    )


def _source_ranked_armed_defense_probe_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource,
    protected_incoming_damage: bool = False,
) -> bool:
    """Admit a singleton weapon target when defense and preparation bound risk.

    A verified sanctuary reserve may reduce the peak-round estimate, but the
    ordinary health-floor, passive-defense, and source-output checks remain.
    """
    if (
        len(candidate.equipped_weapons) != 1
        or not candidate.autonomous_safe
        or candidate.source_damage_modifier is None
    ):
        return False
    loadout = single_weapon_loadout(
        candidate,
        source_world,
    )
    if loadout is None:
        return False
    if protected_incoming_damage and not _state_has_usable_sanctuary_reserve(state):
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    candidate_specials = frozenset(candidate.specials)
    source_specials = frozenset(
        source_world.mobile_specials.get(candidate.mobile_vnum, ())
    )
    if (
        mobile is None
        or mobile.aggressive
        or mobile.fear_aura
        or mobile.programs
        or candidate_specials != source_specials
        or not source_specials <= SAFE_NONCOMBAT_SPECIALS
    ):
        return False
    raw_max_hp = state.get("max_hp")
    raw_hp = state.get("hp")
    if (
        not isinstance(raw_max_hp, (int, float))
        or raw_max_hp <= 0
        or not isinstance(raw_hp, (int, float))
        or raw_hp < math.ceil(raw_max_hp * 0.95)
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if _source_ranked_xp_loss_record(state, policy_id) is not None:
        return False
    hit_probability = _source_ranked_passive_defense_probability(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
        allow_single_armed_target=True,
        attacker_level_ceiling=character_level + 5,
    )
    return bool(
        hit_probability is not None
        and hit_probability <= Fraction(1, 2)
        and _source_ranked_caster_output_can_cover(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
            normal_hit_probability=hit_probability,
            allow_armed_defense_probe=True,
            protected_incoming_damage=protected_incoming_damage,
            source_damage_bonus=loadout.damage_bonus,
            target_has_sanctuary=loadout.target_sanctuary,
        )
    )


def _source_ranked_target_hp_gate_evidence(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    source_world: WorldSource | None = None,
) -> dict[str, Any] | None:
    """Extract target-specific live HP evidence from a source hunt abort."""
    if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        return None
    abort_reason = str(state.get("campaign_fastwalk_abort_reason") or "")
    live_hp_match = _SOURCE_RANKED_LIVE_HP_GATE_RE.match(abort_reason)
    damage_window_match = _SOURCE_RANKED_DAMAGE_WINDOW_RE.match(abort_reason)
    hard_health_match = _SOURCE_RANKED_HARD_HEALTH_RE.match(abort_reason)
    match = live_hp_match or damage_window_match or hard_health_match
    if match is None:
        return None
    candidate_record = state.get(_SOURCE_RANKED_CANDIDATE_KEY)
    candidate = _source_ranked_candidate_from_record(candidate_record)
    if candidate is None:
        return None
    try:
        level = _level(state)
        observed_max_hp = int(match.group("max_hp"))
    except (TypeError, ValueError):
        return None
    source_output_ceiling: int | None = None
    if live_hp_match is not None:
        try:
            source_output_ceiling = int(live_hp_match.group("budget"))
        except (TypeError, ValueError):
            return None
    elif hard_health_match is not None:
        try:
            source_output_ceiling = int(hard_health_match.group("budget"))
        except (TypeError, ValueError):
            return None
    elif damage_window_match is not None:
        try:
            raw_budget = damage_window_match.group("budget")
            source_output_ceiling = int(raw_budget) if raw_budget else None
        except (TypeError, ValueError):
            return None
        if source_output_ceiling is None and source_world is not None:
            output = _source_ranked_caster_output_for_state(
                state,
                character_level=level,
                source_world=source_world,
                target_body_form_flags=candidate.target_body_form_flags,
            )
            output = _source_ranked_output_for_target(
                output,
                target_mobile_vnum=candidate.mobile_vnum,
                source_world=source_world,
            )
            if output is not None and output.conservative_damage > 0:
                action_budget = _source_ranked_effective_output_actions(
                    output,
                    famous_gas_recovery=False,
                )
                if action_budget > 0:
                    source_output_ceiling = (
                        output.conservative_damage * action_budget
                        + int(output.opening_conservative_damage or 0)
                    )
    if (
        level <= 0
        or observed_max_hp <= 0
        or (
            live_hp_match is not None
            and (source_output_ceiling is None or source_output_ceiling <= 0)
        )
        or _source_ranked_policy_id(candidate, character_level=level)
        != policy_id
    ):
        return None
    target = match.group("target").strip()
    if len(target) >= 2 and target[0] in "'\"" and target[-1] == target[0]:
        target = target[1:-1]
    if normalize_item_name(target) != normalize_item_name(candidate.target):
        return None
    candidate_revision = (
        candidate_record.get("source_revision")
        if isinstance(candidate_record, Mapping)
        else None
    )
    current_revision = state.get(_SOURCE_REVISION_KEY)
    if candidate_revision and current_revision and candidate_revision != current_revision:
        return None
    evidence: dict[str, Any] = {
        "policy_id": policy_id,
        "target": candidate.target,
        "mobile_vnum": candidate.mobile_vnum,
        "room_vnum": candidate.room_vnum,
        "observed_max_hp": observed_max_hp,
        "abort_reason": abort_reason,
    }
    if source_output_ceiling is not None:
        evidence["source_output_ceiling"] = source_output_ceiling
        loss = source_combat_loss_records(state).get(policy_id)
        output_at_withdrawal = loss.get("output_at_withdrawal") if loss else None
        if (
            isinstance(output_at_withdrawal, Mapping)
            and output_at_withdrawal.get("boot_id") == state.get("world_boot_id")
            and type(output_at_withdrawal.get("ceiling")) is int
            and output_at_withdrawal["ceiling"] > 0
            and type(output_at_withdrawal.get("weapon_vnum")) is int
            and output_at_withdrawal["weapon_vnum"] > 0
            and type(output_at_withdrawal.get("damroll")) is int
            and str(output_at_withdrawal.get("action") or "").strip()
            and str(output_at_withdrawal.get("weapon") or "").strip()
            and normalize_item_name(str(loss.get("target") or ""))
            == normalize_item_name(candidate.target)
        ):
            evidence["planned_source_output_ceiling"] = source_output_ceiling
            evidence["source_output_ceiling"] = max(
                source_output_ceiling, output_at_withdrawal["ceiling"],
            )
            evidence["withdrawal_output_basis"] = "observed-combat-equipment"
            evidence["output_at_withdrawal"] = dict(output_at_withdrawal)
    if damage_window_match is not None:
        try:
            observed_damage = int(damage_window_match.group("observed_damage"))
            effective_damage = int(
                damage_window_match.group("effective_damage")
                or observed_damage
            )
            regenerated_hp = int(
                damage_window_match.group("regenerated_hp") or 0
            )
            player_damage = int(damage_window_match.group("player_damage"))
        except (TypeError, ValueError):
            return None
        if (
            observed_damage <= 0
            or effective_damage < 0
            or regenerated_hp < 0
            or player_damage < 0
            or (
                source_output_ceiling is not None
                and source_output_ceiling <= 0
            )
        ):
            return None
        evidence.update(
            {
                "failure_kind": "damage_window",
                "observed_damage": observed_damage,
                "effective_damage": effective_damage,
                "regenerated_hp": regenerated_hp,
                "player_damage": player_damage,
            }
        )
    elif hard_health_match is not None:
        evidence["failure_kind"] = "hard_health_floor"
    if current_revision:
        evidence["source_revision"] = str(current_revision)
    weapon = state.get("campaign_primary_weapon")
    if isinstance(weapon, str) and weapon.strip():
        evidence["weapon"] = weapon.strip()
    return evidence


def _source_ranked_combat_output_revalidation_details(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
    allow_famous_gas_recovery: bool = False,
) -> tuple[Mapping[str, Any], Mapping[str, Any]] | None:
    """Parse legacy retry evidence without granting current retry permission.

    Current selection never calls this proof as an admission gate. It remains
    for reading old loss records and explaining historical decisions.
    """
    famous_gas_recovery = bool(
        allow_famous_gas_recovery
        and source_world is not None
        and _state_has_sanctuary_reserve(state)
        and _source_ranked_famous_gas_recovery_allowed(
            candidate,
            source_world,
            state,
        )
        and not candidate.equipped_weapons
        and not candidate.route_hard_hazard_targets
        and _source_ranked_famous_gas_route_program_allowed(
            candidate,
            source_world,
            character_level=character_level,
        )
    )
    audited_route_program_preflight = bool(
        candidate.route_preflight_hard_hazard
        and _source_ranked_route_program_candidate_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
        )
    )
    if (
        source_world is None
        or candidate.status == "reject"
        or (not candidate.autonomous_safe and not famous_gas_recovery)
        or (candidate.specials and not famous_gas_recovery)
        or candidate.equipped_weapons
        # This only retains the candidate's registered locator; the live
        # route must still stop if it finds the exact program attacker.
        or (
            candidate.route_preflight_hard_hazard
            and not (famous_gas_recovery or audited_route_program_preflight)
        )
        or candidate.route_hard_hazard_targets
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or (
            source_world.mobile_specials.get(candidate.mobile_vnum, ())
            and not famous_gas_recovery
        )
    ):
        return None
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    loss_record = _source_ranked_xp_loss_record(state, policy_id)
    if (
        loss_record is None
        or _source_ranked_xp_loss_count(loss_record) != 1
        or loss_record.get("level") not in {None, character_level}
    ):
        return None
    evidence = loss_record.get("target_hp_evidence")
    if not isinstance(evidence, Mapping):
        return None
    if (
        evidence.get("policy_id") not in {None, policy_id}
        or evidence.get("mobile_vnum") != candidate.mobile_vnum
        or evidence.get("room_vnum") != candidate.room_vnum
        or normalize_item_name(str(evidence.get("target") or ""))
        != normalize_item_name(candidate.target)
        or (
            evidence.get("source_revision")
            and state.get(_SOURCE_REVISION_KEY)
            and evidence.get("source_revision")
            != state.get(_SOURCE_REVISION_KEY)
        )
    ):
        return None
    try:
        observed_max_hp = int(evidence.get("observed_max_hp"))
        previous_output_ceiling = int(
            evidence.get("source_output_ceiling")
        )
    except (TypeError, ValueError):
        return None
    if observed_max_hp <= 0 or previous_output_ceiling <= 0:
        return None
    if _source_ranked_combat_output_revalidation_attempted(
        state,
        policy_id=policy_id,
    ):
        return None
    if famous_gas_recovery:
        famous_mobile = source_world.mobiles.get(candidate.mobile_vnum)
        if (
            famous_mobile is None
            or _source_ranked_fame_level_window(
                candidate,
                character_level=character_level,
                awards_fame=famous_mobile.awards_fame,
            )
            is None
        ):
            return None
    elif not _source_ranked_candidate_in_current_band(
        candidate,
        state,
        world=source_world,
        character_level=character_level,
        allow_repeated_kills=True,
        check_lucky_consider_probe=False,
    ):
        return None
    output = _source_ranked_caster_output_for_state(
        state,
        character_level=character_level,
        source_world=source_world,
        target_body_form_flags=candidate.target_body_form_flags,
    )
    output = _source_ranked_output_for_target(
        output,
        target_mobile_vnum=candidate.mobile_vnum,
        source_world=source_world,
    )
    if output is None or output.conservative_damage <= 0:
        return None
    try:
        action_budget = _source_ranked_effective_output_actions(
            output,
            famous_gas_recovery=famous_gas_recovery,
        )
        current_output_ceiling = (
            int(output.conservative_damage) * action_budget
            + int(output.opening_conservative_damage or 0)
        )
    except (TypeError, ValueError):
        return None
    if (
        current_output_ceiling <= previous_output_ceiling
        or current_output_ceiling < observed_max_hp
    ):
        return None
    current_weapon = _source_ranked_primary_weapon_for_state(
        state,
        source_world,
    )
    if (
        evidence.get("failure_kind") in {"hard_health_floor", "damage_window"}
        and evidence.get("withdrawal_output_basis") != "observed-combat-equipment"
        and current_weapon is not None
        and normalize_item_name(str(evidence.get("weapon") or ""))
        == normalize_item_name(current_weapon.short_description)
    ):
        # Legacy plans may have used recovery gear while the failed fight
        # already wore the combat set. That stance change proves no upgrade.
        return None
    signature: dict[str, Any] = {
        "output_ceiling": current_output_ceiling,
        "action": output.action,
    }
    if current_weapon is not None:
        signature["weapon_vnum"] = int(current_weapon.vnum)
        signature["weapon"] = current_weapon.short_description
    return evidence, signature


def _source_ranked_combat_output_revalidation_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
    allow_famous_gas_recovery: bool = False,
) -> bool:
    """Return whether the retired target-HP/output retry may enter selection.

    The detailed parser remains available for historical evidence migration,
    but the October target-admission policy never reopens a fight because a
    predicted output ceiling changed.
    """
    del candidate, state, character_level, source_world, allow_famous_gas_recovery
    return False


def _source_ranked_combat_output_revalidation_attempted(
    state: Mapping[str, Any],
    *,
    policy_id: str,
) -> bool:
    """Return whether the one-shot improved-output retry was consumed."""
    marker = state.get(_SOURCE_RANKED_COMBAT_OUTPUT_REVALIDATION_KEY)
    marker_attempted = bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, _level(state)}
        and marker.get("policy_id") == policy_id
        and marker.get("attempted") is True
    )
    loss_record = _source_ranked_xp_loss_record(state, policy_id)
    recorded_attempt = bool(
        isinstance(loss_record, Mapping)
        and loss_record.get("level") in {None, _level(state)}
        and loss_record.get("combat_output_revalidation_attempted") is True
    )
    return marker_attempted or recorded_attempt


def _source_ranked_consumed_output_revalidation_matches_candidate(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Keep retired output-retry markers out of current field-stop selection."""
    del candidate, state, character_level, source_world
    return False


def _mark_source_ranked_combat_output_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
    allow_famous_gas_recovery: bool = False,
) -> bool:
    """Consume the narrow famous-gas retry receipt before dispatch.

    Ordinary target-HP/output retries are retired by the current policy.  The
    source-proven famous-gas fame recovery exception is intentionally kept
    because its route, Sanctuary, and output gates are independently audited.
    """
    if not allow_famous_gas_recovery:
        return False
    details = _source_ranked_combat_output_revalidation_details(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
        allow_famous_gas_recovery=True,
    )
    if details is None:
        return False
    evidence, signature = details
    state[_SOURCE_RANKED_COMBAT_OUTPUT_REVALIDATION_KEY] = {
        "boot_id": state.get("world_boot_id"),
        "level": character_level,
        "policy_id": _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        ),
        "target": candidate.target,
        "mobile_vnum": candidate.mobile_vnum,
        "room_vnum": candidate.room_vnum,
        "observed_max_hp": evidence.get("observed_max_hp"),
        "previous_output_ceiling": evidence.get("source_output_ceiling"),
        "current_output_ceiling": signature.get("output_ceiling"),
        "previous_weapon": evidence.get("weapon"),
        "current_weapon": signature.get("weapon"),
        "current_weapon_vnum": signature.get("weapon_vnum"),
        "action": signature.get("action"),
        "attempted": True,
        "status": "attempted",
        "famous_gas_recovery": True,
        "reason": (
            "one source-validated retry after combat output improved enough "
            "to cover the previously observed target HP"
        ),
    }
    return True


def _source_ranked_level_admission_available(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource,
    allow_unarmed_post_loss_aggressive_probe: bool = False,
) -> bool:
    """Check the scouting level band; target HP is evidence only.

    Route, source hazards, previous losses and live consider are checked by
    our callers and the combat controller.
    """
    # Ota'ar's endpoint is a level-41 Arenamaster, but entry forces the
    # captive through a level-40 gladiator first.  Keep this no-recall route
    # out of ordinary selection once that first required favour is below the
    # useful-XP band; an already captive character is resumed by the dedicated
    # arena handoff before this shared admission check.
    if (
        not _source_ranked_ota_arena_first_favour_current_band(
            candidate,
            source_world,
            character_level=character_level,
        )
        and candidate.area_file.casefold() == _OTAAR_ARENA_TARGET_AREA
        and candidate.mobile_vnum == _OTAAR_ARENA_TARGET_MOBILE_VNUM
        and candidate.room_vnum == _OTAAR_ARENA_TARGET_ROOM_VNUM
    ):
        return False
    minimum, maximum = candidate.estimated_level_range
    # The source prototype level is the scouting boundary.  Area-file reset
    # fuzz is deliberately retained as evidence, but using its upper bound
    # here hid nominally eligible +5 targets (for example a level-45 mobile
    # with a source-fuzz range of 43-47 from a level-40 pilot).  The live
    # ``consider`` response remains the authority before combat dispatch.
    nominal_level = candidate.level
    return bool(
        0 < minimum <= maximum
        and maximum > character_level - 5
        and nominal_level <= character_level + 5
    )


def _source_ranked_ordinary_navigation_candidate_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource,
    allow_unarmed_post_loss_aggressive_probe: bool = False,
) -> bool:
    """Keep only level-eligible candidates that passed source safety gates.

    ``target_selection_safe`` deliberately ignores output-only evidence, so
    this retains candidates whose static damage estimate is incomplete while
    preventing genuine source hazards from re-entering the expensive route
    audit merely because their level is current.
    """
    aggressive_endpoint_probe = _source_ranked_aggressive_consider_probe_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=(
            int(state["max_hp"])
            if isinstance(state.get("max_hp"), (int, float))
            and int(state["max_hp"]) > 0
            else None
        ),
        source_world=source_world,
    )
    return bool(
        (
            candidate.target_selection_safe
            or aggressive_endpoint_probe
            or _source_ranked_bounded_bear_transit_route_allowed(
                candidate,
                character_level=character_level,
                source_world=source_world,
            )
        )
        and _source_ranked_level_admission_available(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
            allow_unarmed_post_loss_aggressive_probe=(
                allow_unarmed_post_loss_aggressive_probe
            ),
        )
    )


def _source_ranked_special_reserve_acquisition_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Keep only a special candidate needed to acquire protection first."""
    if source_world is None or not candidate.specials:
        return False
    if not _source_ranked_candidate_requires_sanctuary_for_state(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
    ):
        return False
    if _source_ranked_sanctuary_reserve_cooldown_active(state):
        return False
    if not _state_has_sanctuary_reserve(state):
        # The policy layer will return the first-reserve handoff before the
        # candidate can be persisted or dispatched to the field.
        return True
    if not _source_ranked_candidate_requires_blindness_recovery_reserve(
        candidate
    ):
        # A single reserve already protects this non-caster special; there is
        # no second-reserve handoff that can make its HP ceiling executable.
        return False
    if _state_has_blindness_recovery_reserve(state):
        return False
    if _source_ranked_healer_blindness_recovery_allowed(
        candidate,
        state,
        source_world=source_world,
    ):
        return False
    # The policy layer will return the second-reserve handoff before field
    # dispatch. This is intentionally narrower than a generic special bypass.
    return True


def _source_ranked_persisted_candidate_admission_valid(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
    allow_unarmed_post_loss_aggressive_probe: bool = False,
) -> bool:
    """Recheck a saved target before reusing its live route."""
    if source_world is None:
        # Small source-less policy tests and research callers cannot reproduce
        # the output envelope. Live campaign runs load the source world and
        # take the conservative validation branch below.
        return True
    if _source_ranked_psionic_candidate_requires_protection(
        candidate,
        source_world=source_world,
    ):
        # A compact saved candidate must not bypass the source special gate.
        # In particular, level-14-plus psionics may have energy drain and
        # level-35-plus may also disintegrate; no generic protection receipt
        # exists in the current live state model.
        return False
    # A persisted route is not a substitute for the perception capability it
    # required when it was selected.  The visibility preparation policy can
    # buy and verify a fresh potion, or the selector can choose another
    # target; opening the saved route without detect-invis would only produce
    # an avoidable false absence at the endpoint.
    if (
        candidate.requires_detect_invisibility
        and not _state_has_active_affect(state.get("affects"), "detect invis")
    ):
        return False
    # A persisted record can outlive the ranking pass that created it.  Do
    # not let a rejected candidate, or an ordinary target that has fallen five
    # or more levels below the player, bypass the fresh-candidate band gate.
    # Below-band targets remain reserved for exact source-required resource or
    # loot objectives, which do not reuse the ordinary source-ranked-hunt
    # admission path.
    if candidate.status == "reject" and not (
        _source_ranked_bounded_bear_transit_route_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
        )
        or _source_ranked_plain_duplicate_rotation_selection_allowed(
            candidate,
            source_world,
        )
        or (
            plain_bounded_population(candidate, source_world)
        and _source_ranked_post_loss_plain_probe_allowed(
            candidate, state, character_level=character_level, source_world=source_world,
        )
        )
    ):
        return False
    if candidate.estimated_level_range[1] <= character_level - 5:
        return False
    return _source_ranked_level_admission_available(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
        allow_unarmed_post_loss_aggressive_probe=(
            allow_unarmed_post_loss_aggressive_probe
        ),
    )


def _source_ranked_caster_output_for_state(
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
    target_body_form_flags: int | None = None,
) -> SourceCombatOutput | None:
    """Return the audited repeatable combat action in durable character state."""
    character_class = state.get("character_class")
    if not isinstance(character_class, str) or not character_class.strip():
        return None
    raw_skills = state.get("campaign_known_skills")
    if isinstance(raw_skills, str):
        known_skills: Collection[str] = (raw_skills,)
    elif isinstance(raw_skills, (list, tuple, set, frozenset)):
        known_skills = tuple(str(skill) for skill in raw_skills)
    else:
        known_skills = ()
    raw_levels = state.get("campaign_known_skill_levels")
    known_skill_levels = raw_levels if isinstance(raw_levels, Mapping) else None
    weapon = _source_ranked_straight_shifter_natural_weapon_for_state(
        state,
        source_world,
        known_skills=known_skills,
        known_skill_levels=known_skill_levels,
    )
    natural_weapon = weapon is not None
    if weapon is None:
        weapon = _source_ranked_primary_weapon_for_state(state, source_world)
    weapon_damage_range = None
    weapon_vnum = None
    weapon_damage_type = None
    if weapon is not None:
        weapon_damage_range = (
            (int(weapon.values[1]), int(weapon.values[2])) if natural_weapon
            else source_weapon_damage(weapon, weapon_record(state.get("equipment")))
        )
        weapon_vnum = int(weapon.vnum)
        if len(weapon.values) > 3:
            try:
                weapon_damage_type = int(weapon.values[3])
            except (TypeError, ValueError):
                weapon_damage_type = None
    ranged_weapon = _source_ranked_ranged_weapon_for_state(
        state,
        source_world,
    )
    ranged_weapon_damage_range = None
    ranged_weapon_vnum = None
    if ranged_weapon is not None:
        ranged_weapon_damage_range = source_weapon_damage(
            ranged_weapon, weapon_record(state.get("equipment"), ranged=True),
        )
        ranged_weapon_vnum = int(ranged_weapon.vnum)
    try:
        counterbalanced_weapon_vnum = int(
            state.get(_COUNTERBALANCED_WEAPON_VNUM_KEY)
        )
    except (TypeError, ValueError):
        counterbalanced_weapon_vnum = 0
    weapon_counterbalanced = bool(
        weapon is not None
        and counterbalanced_weapon_vnum > 0
        and int(weapon.vnum) == counterbalanced_weapon_vnum
    )
    try:
        chained_weapon_vnum = int(state.get(_CHAINED_WEAPON_VNUM_KEY))
    except (TypeError, ValueError):
        chained_weapon_vnum = 0
    weapon_chained = bool(
        weapon is not None
        and chained_weapon_vnum > 0
        and int(weapon.vnum) == chained_weapon_vnum
    )
    try:
        player_rage = int(state.get("rage"))
    except (TypeError, ValueError):
        player_rage = None
    try:
        player_max_rage = int(state.get("max_rage"))
    except (TypeError, ValueError):
        player_max_rage = None
    return source_combat_output_estimate(
        character_level=character_level,
        character_class=character_class,
        character_subclass=_live_subclass(state),
        known_skills=known_skills,
        known_skill_levels=known_skill_levels,
        weapon_damage_range=weapon_damage_range,
        weapon_vnum=weapon_vnum,
        weapon_damage_type=weapon_damage_type,
        ranged_weapon_damage_range=ranged_weapon_damage_range,
        ranged_weapon_vnum=ranged_weapon_vnum,
        player_damroll=_source_ranked_state_stat(state, "damroll", 0) or 0,
        player_swiftness=_source_ranked_state_stat(state, "swift"),
        player_rage=player_rage,
        player_max_rage=player_max_rage,
        weapon_counterbalanced=weapon_counterbalanced,
        weapon_chained=weapon_chained,
        target_body_form_flags=target_body_form_flags,
    )


def _source_ranked_output_for_target(
    output: SourceCombatOutput | None,
    *,
    target_mobile_vnum: int | None,
    source_world: WorldSource | None,
    target_has_sanctuary: bool = False,
) -> SourceCombatOutput | None:
    """Apply source-known target defenses before comparing damage output."""
    if output is None:
        return None
    mobile = (
        source_world.mobiles.get(target_mobile_vnum)
        if source_world is not None and target_mobile_vnum is not None
        else None
    )
    if target_has_sanctuary or source_mobile_has_sanctuary(mobile):
        return sanctuary_limited_output(output)
    return output


def _source_ranked_caster_output_can_cover(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
    protected_incoming_damage: bool = False,
    target_hp_ceiling: int | None = None,
    normal_hit_probability: Fraction | None = None,
    allow_armed_defense_probe: bool = False,
    source_damage_bonus: int = 0,
    target_has_sanctuary: bool = False,
    allow_unarmed_singleton_withdrawal: bool = False,
) -> bool:
    """Check one practiced action without a target HP/output veto.

    Source target output remains report evidence. Live target level, identity,
    consider, route hazards, and the player's own observed withdrawal floor
    decide the encounter; this helper only verifies that the player has an
    executable action and enough of the action resource to issue it.
    """
    del target_hp_ceiling, protected_incoming_damage
    del source_damage_bonus, allow_unarmed_singleton_withdrawal
    target_is_armed = bool(candidate.equipped_weapons)
    if (
        target_is_armed
        and (
            not allow_armed_defense_probe
            or len(candidate.equipped_weapons) != 1
        )
        or allow_armed_defense_probe and not target_is_armed
    ):
        return False
    source_specials = frozenset(
        source_world.mobile_specials.get(candidate.mobile_vnum, ())
        if source_world is not None
        else ()
    )
    source_verified_safe_specials = bool(candidate.specials) and (
        frozenset(candidate.specials) == source_specials
        and source_specials <= SAFE_NONCOMBAT_SPECIALS
    )
    if normal_hit_probability is not None and (
        not isinstance(normal_hit_probability, Fraction)
        or not 0 < normal_hit_probability <= 1
        or candidate.specials and not source_verified_safe_specials
    ):
        return False
    output = _source_ranked_output_for_target(
        _source_ranked_caster_output_for_state(
            state,
            character_level=character_level,
            source_world=source_world,
            target_body_form_flags=candidate.target_body_form_flags,
        ),
        target_mobile_vnum=candidate.mobile_vnum,
        source_world=source_world,
        target_has_sanctuary=target_has_sanctuary,
    )
    if output is None or output.conservative_damage <= 0:
        return False
    required_actions = 1
    if output.resource == "mana":
        raw_max_mana = state.get("max_mana")
        if not isinstance(raw_max_mana, (int, float)) or raw_max_mana <= 0:
            return False
        mana_reserve = int(raw_max_mana * 0.15)
        return (
            int(raw_max_mana) - required_actions * output.resource_cost
            >= mana_reserve
        )
    if output.resource == "actions" and output.resource_cost == 0:
        # Natural attacks consume a between-round action, not mana. The live
        # runner still enforces action timing and the player's own-health
        # withdrawal floor.
        return True
    return False


def _source_ranked_aggressive_special_output_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None = None,
) -> bool:
    """Require a killable source output envelope before an auto-attack entry."""
    source_specials = tuple(candidate.specials)
    if not source_specials and source_world is not None:
        source_specials = tuple(
            source_world.mobile_specials.get(candidate.mobile_vnum, ())
        )
    if not source_specials:
        return True
    mobile = (
        source_world.mobiles.get(candidate.mobile_vnum)
        if source_world is not None
        else None
    )
    aggressive = (
        mobile.aggressive
        if mobile is not None
        else "target is aggressive" in set(candidate.hazards)
    )
    if not aggressive:
        return True
    if source_world is None:
        # A synthetic legacy candidate can still be selected when its source
        # graph is unavailable; there is no source identity to classify here.
        return True
    if _source_ranked_master_elf_risk_shape_allowed(candidate, source_world):
        # This is the one armed special target deliberately admitted at the
        # current-band frontier.  The target's weapon remains live combat
        # evidence; allowing one source-verified weapon here does not waive
        # the normal identity, consider, crowd, or own-health gates.
        return _source_ranked_caster_output_can_cover(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
            allow_armed_defense_probe=True,
        )
    coverage_state: Mapping[str, Any] = state
    if (
        character_max_hp is not None
        and not isinstance(state.get("max_hp"), (int, float))
    ):
        coverage_state = dict(state)
        coverage_state["max_hp"] = character_max_hp
    if _source_ranked_protected_special_hp_fuzz_probe_allowed(
        candidate,
        coverage_state,
        character_level=character_level,
        source_world=source_world,
    ):
        # An aggressive special cannot wait for consider, but a source-audited
        # sanctuary probe can still enter safely enough to read live GMCP HP.
        # The endpoint gate establishes sanctuary before the opener and the
        # live damage-budget gate withdraws on an oversized load.
        return True
    if _source_ranked_mage_special_risk_allowed(
        candidate,
        state,
        source_world=source_world,
    ):
        # The exact source-audited mage contracts already prove Sanctuary,
        # healer recovery, route traversal, and the target shape. Let those
        # contracts reach the normal live identity/consider gate instead of
        # discarding them because the generic caster-output estimate lacks a
        # player mana profile.
        return True
    return _source_ranked_caster_output_can_cover(
        candidate,
        coverage_state,
        character_level=character_level,
        source_world=source_world,
    )


_SOURCE_FAMILIAR_MOBILE_VNUM = 19900
_SOURCE_FAMILIAR_ROOM_INDOORS = 1 << 3
_SOURCE_FAMILIAR_ROOM_PRIVATE = 1 << 9
_SOURCE_FAMILIAR_SECT_INSIDE = 1
_SOURCE_FAMILIAR_UNDERWATER_SECTORS = frozenset({8, 12})
# An armed target may be admitted to the familiar probe only when one source
# weapon is present and the pony retains substantial headroom for its first
# exchange. This is intentionally tighter than the ordinary unarmed probe.
_SOURCE_FAMILIAR_ARMED_PEAK_RATIO = 0.75
_SOURCE_FAMILIAR_ARMED_CRITICAL_RATIO = 0.60


def _source_ranked_familiar_minimum_damage(
    source_world: WorldSource | None,
) -> int | None:
    """Return the guaranteed first unarmed hit of the source pony."""
    if source_world is None:
        return None
    familiar = source_world.mobiles.get(_SOURCE_FAMILIAR_MOBILE_VNUM)
    if familiar is None:
        return None
    familiar_level = _mobile_level_range(familiar.level)[0]
    return _apply_mobile_damage_modifier(
        _mobile_normal_hit_damage(familiar_level, wielding=False),
        familiar.damage_modifier,
    )


def _source_ranked_familiar_skill_available(
    state: Mapping[str, Any],
) -> bool:
    """Require live-observed summon-familiar practice before admission."""
    character_class = str(state.get("character_class") or "").casefold()
    character_subclass = str(
        state.get("subclass") or state.get("character_subclass") or ""
    ).casefold()
    return learned_familiar_available(
        character_class, character_subclass,
        state.get("campaign_known_skill_levels") or {},
    )


def _source_ranked_familiar_destinations(
    candidate: HuntCandidate, world: WorldSource,
) -> tuple[int, ...]:
    mobile = world.mobiles.get(candidate.mobile_vnum)
    if mobile is None:
        return ()
    if mobile.wanders:
        return tuple(source_mobile_search_rooms(
            world, candidate.mobile_vnum,
            maximum_rooms=_SOURCE_RANKED_WANDER_SEARCH_LIMIT,
        ))
    return (candidate.room_vnum,)


def _source_ranked_familiar_withdrawal_exit_exists(
    destination_rooms: Collection[int],
    world: WorldSource,
    *,
    character_level: int | None = None,
    character_alignment: int | None = None,
    ignore_mobile_vnums: Collection[int] = (),
) -> bool:
    """Use the runtime escape audit before admitting a familiar-backed trip."""
    return familiar_withdrawal_rooms_safe(
        world, destination_rooms, character_level=character_level,
        character_alignment=character_alignment,
        ignore_mobile_vnums=ignore_mobile_vnums,
    )


def _source_ranked_familiar_destination_blocks_follower(
    destination_rooms: Collection[int],
    world: WorldSource,
) -> bool:
    """Reject private destinations where a source reset occupies the room."""
    reset_rooms = {
        reset.room_vnum
        for reset in world.mob_resets
        if reset.maximum_count > 0
    }
    return any(
        (room := world.rooms.get(room_vnum)) is not None
        and room.room_flags & _SOURCE_FAMILIAR_ROOM_PRIVATE
        and room_vnum in reset_rooms
        for room_vnum in destination_rooms
    )


def _source_ranked_familiar_staging_room(
    candidate: HuntCandidate, world: WorldSource,
) -> str | None:
    destinations = _source_ranked_familiar_destinations(candidate, world)
    if not any(
        (room := world.rooms.get(vnum)) is not None
        and (room.room_flags & _SOURCE_FAMILIAR_ROOM_INDOORS or room.sector_type == 0)
        for vnum in destinations
    ):
        return None
    route = _source_route_room_vnums(
        world, candidate.route_origin_room_vnum, candidate.route,
    )
    if route is None or route[-1] != candidate.room_vnum:
        return None
    room_vnum = familiar_staging_room(world, route, destinations)
    return str(room_vnum) if room_vnum is not None else None


def _source_ranked_familiar_capacity_result_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Require useful live proof before a capacity target uses a familiar."""
    if not _source_ranked_capacity_research_candidate(
        candidate,
        character_level=character_level,
        allow_bounded_route_program=True,
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    if not isinstance(result, Mapping):
        return False
    if not (
        result.get("boot_id") == state.get("world_boot_id")
        and result.get("observed") is True
        and result.get("consider_viable") is True
        and result.get("viable") is True
        and result.get("completed_kill") is True
    ):
        return False
    if any(
        result.get(key)
        for key in (
            "absent",
            "crowded",
            "crowd_exhausted",
            "route_hazard",
            "unattackable",
            "target_vnum_mismatch",
        )
    ) or result.get("low_reward") is True:
        return False
    try:
        return int(result.get("max_objective_kill_xp") or 0) >= (
            _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
        )
    except (TypeError, ValueError):
        return False


def _source_ranked_familiar_probe_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
) -> bool:
    """Admit one narrow, familiar-backed combat probe.

    ``spell_summon_familiar`` creates the source-defined level-15 pony below
    level 25. The starter already orders it before the player's opener, but
    the source selector used to require sanctuary for every armed target
    before that capability could be exercised. This remains a bounded
    source/route probe: the target must be isolated and free of unsafe
    specials, any armed target may have only one source weapon, and the live
    runner must require the familiar when the class would not receive its
    finishing blow's XP. Target hitpoints and predicted damage are evidence
    for reports only.
    """
    if (
        source_world is None or _state_has_sanctuary_reserve(state)
        or not 4 <= character_level < 25
    ):
        return False
    source_mobiles = getattr(source_world, "mobiles", None)
    if not isinstance(source_mobiles, Mapping):
        return False
    target_mobile = source_mobiles.get(candidate.mobile_vnum)
    if (
        target_mobile is None
        or target_mobile.level < character_level - 5
    ):
        # A familiar is a bounded damage aid, not permission to turn a
        # six-level-below target into progression XP. Keep the nominal source
        # level floor separate from the fuzzy runtime range below.
        return False
    familiar_capacity_repeat = bool(
        _source_ranked_familiar_capacity_result_allowed(
            candidate,
            state,
            character_level=character_level,
        )
    )
    familiar_route_rejections = set(candidate.autonomy_rejections)
    edge_band_route_allowed = False
    if familiar_route_rejections == {
        _SOURCE_FAMILIAR_EDGE_BAND_WANDER_REJECTION
    }:
        edge_band_route_allowed = bool(
            target_mobile is not None
            and target_mobile.level == character_level - 5
            and target_mobile.sentinel
            and not target_mobile.wanders
            and not target_mobile.aggressive
            and not target_mobile.attack_programs
            and _source_ranked_familiar_staging_room(candidate, source_world)
            is not None
        )
    invisibility_familiar_route_allowed = bool(
        familiar_route_rejections
        and familiar_route_rejections <= (
            set(_SOURCE_INVISIBILITY_ROUTE_REJECTIONS)
            | {
                "below-band transit aggressor is not an XP target",
                "below-band wandering aggressor is not an XP target",
            }
        )
        and _source_ranked_invisibility_route_candidate_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
        and target_mobile.sentinel
        and not target_mobile.wanders
        and not target_mobile.aggressive
        and not target_mobile.attack_programs
        and not target_mobile.programs
        and not candidate.route_special_mobile_vnums
        and _source_ranked_familiar_staging_room(candidate, source_world)
        is not None
    )
    route_rejections_allowed = familiar_route_rejections == {
        _SOURCE_FAMILIAR_TRANSIT_RISK_REJECTION
    } or (
        edge_band_route_allowed
        and familiar_route_rejections == {
            _SOURCE_FAMILIAR_EDGE_BAND_WANDER_REJECTION
        }
    ) or invisibility_familiar_route_allowed
    if (
        candidate.is_coin_stash
        or (candidate.status == "reject" and not familiar_capacity_repeat)
        or (
            familiar_route_rejections
            and not route_rejections_allowed
            and not familiar_capacity_repeat
        )
        or (not candidate.target_selection_safe and not familiar_capacity_repeat)
        or candidate.specials
        or candidate.route_hard_hazard_targets
    ):
        return False
    if len(candidate.equipped_weapons) > 1:
        # Dual wielding turns the familiar opener into an unbounded exchange
        # because the source peak is no longer a single-weapon bound.
        return False
    lower_level, upper_level = candidate.estimated_level_range
    if (
        lower_level <= 0
        or (
            lower_level <= character_level - 5
            and not (
                candidate.equipped_weapons
                and upper_level > character_level - 5
                or (
                    invisibility_familiar_route_allowed
                    and target_mobile.level >= character_level - 5
                    and upper_level > character_level - 5
                )
            )
        )
        or upper_level > character_level + 1
    ):
        return False
    raw_max_hp = state.get("max_hp")
    raw_max_mana = state.get("max_mana")
    if not isinstance(raw_max_hp, (int, float)) or raw_max_hp <= 0:
        return False
    if not isinstance(raw_max_mana, (int, float)) or raw_max_mana <= 0:
        return False

    if not _source_ranked_familiar_skill_available(state):
        return False

    recoverable_route_preflight = (
        not candidate.route_preflight_hard_hazard
        or (
            candidate.route_preflight_command == "where drunk"
            and bool(candidate.route_preflight_target)
        )
    )
    if not recoverable_route_preflight:
        # The shared drunk locator has an explicit safe-stop contract. Other
        # source-identified hard route hazards remain closed to this probe.
        return False
    route_aggressors_bounded = _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=int(raw_max_hp),
    )
    if not route_aggressors_bounded and familiar_capacity_repeat:
        # A capacity target may reuse a completed, source-matched familiar
        # result when the only route interruption is a source-bounded mobile
        # whose special is already known to be noncombat.  Keep this fallback
        # restricted to the productive repeat contract; an unproven fresh
        # route still uses the stricter generic transit audit above.
        route_aggressors_bounded = bool(
            candidate.route_aggressive_mobile_vnums
            and all(
                (mobile := source_world.mobiles.get(int(raw_vnum))) is not None
                and source_mobile_route_aggressor_is_bounded(
                    source_world,
                    mobile,
                    character_level=character_level,
                    character_max_hp=int(raw_max_hp),
                )
                for raw_vnum in candidate.route_aggressive_mobile_vnums
            )
        )
    if not route_aggressors_bounded and not invisibility_familiar_route_allowed:
        # Familiar control is an endpoint damage-window capability, not a
        # license to cross an unknown armed wanderer on the way there. The
        # exact invisibility route is the one audited exception: source
        # aggression is blocked before the familiar route opens.
        return False

    familiar = source_world.mobiles.get(_SOURCE_FAMILIAR_MOBILE_VNUM)
    if familiar is None:
        return False

    destination_rooms = _source_ranked_familiar_destinations(candidate, source_world)
    if not destination_rooms:
        return False
    if _source_ranked_familiar_destination_blocks_follower(
        destination_rooms,
        source_world,
    ):
        # DD4 checks private-room occupancy again when a follower enters. A
        # reset mobile plus its newly arrived player blocks the pony's move.
        return False
    staged = _source_ranked_familiar_staging_room(candidate, source_world) is not None
    if (target_mobile.aggressive or target_mobile.attack_programs) and not staged:
        # An aggressive or scripted endpoint can engage on room entry, before
        # the starter gets a chance to summon and identify the familiar.
        # Require a source-audited no-mob waypoint for that pre-entry gate.
        return False
    for room_vnum in destination_rooms:
        room = source_world.rooms.get(room_vnum)
        if (
            room is None
            or room.sector_type in _SOURCE_FAMILIAR_UNDERWATER_SECTORS
            or (
                not staged
                and (room.room_flags & _SOURCE_FAMILIAR_ROOM_INDOORS
                     or room.sector_type == _SOURCE_FAMILIAR_SECT_INSIDE)
            )
        ):
            return False

    if not _source_ranked_caster_output_can_cover(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
        allow_armed_defense_probe=bool(candidate.equipped_weapons),
    ):
        return False
    owner_gets_familiar_xp = familiar_kill_credits_owner_xp(
        str(state.get("character_class") or ""),
        str(state.get("subclass") or state.get("character_subclass") or ""),
    )
    if not owner_gets_familiar_xp:
        if not _source_ranked_familiar_withdrawal_exit_exists(
            destination_rooms,
            source_world,
            character_level=character_level,
            character_alignment=_state_alignment(state),
            ignore_mobile_vnums=(candidate.mobile_vnum,),
        ):
            return False

    # A failed probe is evidence against this source policy for the current
    # reboot; do not reopen it as an unprotected familiar experiment. Target
    # HP and familiar output remain diagnostic evidence, not admission gates.
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    return _source_ranked_xp_loss_record(state, policy_id) is None


def _source_ranked_familiar_revalidation_attempted(
    state: Mapping[str, Any],
    *,
    policy_id: str,
) -> bool:
    marker = state.get(_SOURCE_RANKED_FAMILIAR_REVALIDATION_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, _level(dict(state))}
        and marker.get("policy_id") == policy_id
        and marker.get("status") in {"attempted", "closed", "succeeded"}
    )


def _source_ranked_familiar_revalidation_pending(
    state: Mapping[str, Any],
    *,
    policy_id: str,
) -> bool:
    marker = state.get(_SOURCE_RANKED_FAMILIAR_REVALIDATION_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, _level(dict(state))}
        and marker.get("policy_id") == policy_id
        and marker.get("status") == "pending"
    )


def _mark_source_ranked_familiar_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> None:
    """Consume the familiar retry immediately before opening its segment."""
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    marker = state.get(_SOURCE_RANKED_FAMILIAR_REVALIDATION_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
        and marker.get("policy_id") == policy_id
        and marker.get("status") == "pending"
    ):
        return
    state[_SOURCE_RANKED_FAMILIAR_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
    }


def _arm_source_ranked_familiar_revalidation(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> None:
    """Arm one exact familiar retry after a no-loss hard-health withdrawal."""
    if source_world is None or _state_has_sanctuary_reserve(state):
        return
    protection = state.get(_PROTECTION_RECOVERY_KEY)
    if not (
        isinstance(protection, Mapping)
        and protection.get("boot_id") == state.get("world_boot_id")
        and protection.get("level") in {None, character_level}
        and protection.get("trigger") == _PROTECTION_RECOVERY_HARD_HEALTH_TRIGGER
    ):
        return
    raw_xp_delta = protection.get("xp_delta")
    if type(raw_xp_delta) not in (int, float) or raw_xp_delta < 0:
        return
    policy_id = str(protection.get("policy_id") or "")
    if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        return
    if _source_ranked_xp_loss_record(state, policy_id) is not None:
        return
    existing = state.get(_SOURCE_RANKED_FAMILIAR_REVALIDATION_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == state.get("world_boot_id")
        and existing.get("level") in {None, character_level}
        and existing.get("status")
        in {"pending", "attempted", "closed", "succeeded"}
    ):
        return
    candidate = next(
        (
            candidate
            for candidate in candidates
            if _source_ranked_policy_id(
                candidate,
                character_level=character_level,
            )
            == policy_id
        ),
        None,
    )
    if candidate is None:
        return
    candidate_source_revision = getattr(candidate, "source_revision", None)
    marker_source_revision = protection.get("source_revision")
    if (
        marker_source_revision
        and candidate_source_revision
        and marker_source_revision != candidate_source_revision
    ):
        return
    if not _source_ranked_familiar_probe_allowed(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
    ):
        return
    state[_SOURCE_RANKED_FAMILIAR_REVALIDATION_KEY] = {
        "boot_id": state.get("world_boot_id"),
        "level": character_level,
        "policy_id": policy_id,
        "target": candidate.target,
        "mobile_vnum": candidate.mobile_vnum,
        "room_vnum": candidate.room_vnum,
        "source_revision": candidate_source_revision
        or state.get(_SOURCE_REVISION_KEY),
        "status": "pending",
        "reason": (
            "one familiar-backed retry after the exact source target reached "
            "the hard health floor without an XP loss"
        ),
    }


def _arm_source_ranked_familiar_withdrawal_bug_revalidation(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    character_level: int,
    source_world: WorldSource | None,
    segments: Collection[Any],
    storage: RunStorage | None,
) -> None:
    """Reopen one exact hunt aborted by the former familiar sleep mistake."""
    boot_id = state.get("world_boot_id")
    source_revision = str(state.get(_SOURCE_REVISION_KEY) or "")
    policy_id = str(state.get(_SOURCE_RANKED_RETRY_EXHAUSTED_KEY) or "")
    if (
        source_world is None
        or storage is None
        or not source_revision
        or not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        or state.get(_SOURCE_RANKED_RETRY_EXHAUSTED_BOOT_KEY) != boot_id
        or state.get("campaign_last_policy") != policy_id
        or _level(state) != character_level
        or str(state.get("room_vnum") or "")
        not in _MIDGAARD_HEALER_CHECKPOINT_ROOMS
        or state.get("dead") is True
        or state.get("in_combat") is True
        or _numeric_progress(state, "hp") <= 0
        or _numeric_progress(state, "hp") < _numeric_progress(state, "max_hp")
        or _source_ranked_xp_loss_record(state, policy_id) is not None
    ):
        return
    existing = state.get(_SOURCE_RANKED_FAMILIAR_REVALIDATION_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
        and existing.get("level") in {None, character_level}
        and existing.get("status")
        in {"pending", "attempted", "closed", "succeeded"}
    ):
        return

    candidate = next(
        (
            item
            for item in candidates
            if _source_ranked_policy_id(
                item,
                character_level=character_level,
            )
            == policy_id
        ),
        None,
    )
    if (
        candidate is None
        or (
            getattr(candidate, "source_revision", None)
            and getattr(candidate, "source_revision") != source_revision
        )
        or not _source_ranked_familiar_probe_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    ):
        return

    target = str(candidate.target)
    room_vnum = str(candidate.room_vnum)
    exact_abort = (
        f"could not withdraw the familiar before '{target}': "
        "withdrawal order refused"
    )
    withdrawal = state.get("campaign_familiar_withdrawal")
    preparation = state.get("campaign_familiar_preparation")
    sightings = state.get("campaign_fastwalk_source_present_sightings")
    source_sighting = any(
        isinstance(item, Mapping)
        and item.get("policy_id") == policy_id
        and str(item.get("room_vnum") or "") == room_vnum
        and str(item.get("target") or "").casefold() == target.casefold()
        for item in sightings or ()
    ) if isinstance(sightings, (list, tuple)) else False
    consider = state.get("campaign_fastwalk_consider_outcomes")
    source_consider = state.get("campaign_fastwalk_source_consider_outcomes")
    if not (
        isinstance(preparation, Mapping)
        and preparation.get("summoned") is True
        and preparation.get("grouped") is True
        and preparation.get("order_confirmed") is True
        and preparation.get("stage") == "ready"
        and isinstance(withdrawal, Mapping)
        and withdrawal.get("confirmed") is False
        and withdrawal.get("control") == "sleep"
        and withdrawal.get("failure") == "withdrawal order refused"
        and withdrawal.get("attempts") == 1
        and state.get("campaign_fastwalk_target_present_observed") is True
        and state.get("campaign_fastwalk_target_absent") is False
        and state.get("campaign_fastwalk_crowded") is False
        and state.get("campaign_fastwalk_sanctuary_consumed_in_combat") is False
        and not state.get("campaign_fastwalk_route_hazards")
        and not state.get("campaign_fastwalk_below_band_targets")
        and not state.get("campaign_fastwalk_source_below_band_sightings")
        and isinstance(consider, Mapping)
        and consider.get(target) is True
        and isinstance(source_consider, Mapping)
        and source_consider.get(policy_id) is True
        and source_sighting
    ):
        return

    matching_segment: Mapping[str, Any] | None = None
    for raw_segment in reversed(tuple(segments)):
        if isinstance(raw_segment, Mapping):
            segment = raw_segment
        else:
            keys = getattr(raw_segment, "keys", None)
            if not callable(keys):
                continue
            segment = {key: raw_segment[key] for key in keys()}
        if (
            str(segment.get("phase") or "") != policy_id
            or str(segment.get("status") or "") != "success"
            or segment.get("run_id") is None
        ):
            continue
        try:
            start_state = json.loads(segment.get("start_state_json") or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if (
            isinstance(start_state, Mapping)
            and start_state.get("world_boot_id") == boot_id
            and _level(dict(start_state)) == character_level
            and start_state.get("name") == state.get("name")
            and start_state.get(_SOURCE_REVISION_KEY) == source_revision
        ):
            matching_segment = segment
            break
    if matching_segment is None:
        return

    try:
        run_id = int(matching_segment["run_id"])
        segment_id = int(matching_segment.get("id") or 0)
        start_state = json.loads(
            matching_segment.get("start_state_json") or "{}"
        )
        end_state = json.loads(matching_segment.get("end_state_json") or "{}")
    except (KeyError, TypeError, ValueError, json.JSONDecodeError):
        return
    start_xp = start_state.get("xp") if isinstance(start_state, Mapping) else None
    end_xp = end_state.get("xp") if isinstance(end_state, Mapping) else None
    if not (
        type(start_xp) in (int, float)
        and type(end_xp) in (int, float)
        and end_xp == start_xp
        and isinstance(end_state, Mapping)
        and end_state.get("world_boot_id") == boot_id
        and end_state.get(_SOURCE_REVISION_KEY) == source_revision
        and str(end_state.get("room_vnum") or "")
        in _MIDGAARD_HEALER_CHECKPOINT_ROOMS
        and end_state.get("dead") is False
        and _numeric_progress(dict(end_state), "hp")
        == _numeric_progress(dict(end_state), "max_hp")
    ):
        return

    terminal = _run_terminal_state(storage, run_id)
    terminal_withdrawal = (
        terminal.get("familiar_withdrawal")
        if isinstance(terminal, Mapping)
        else None
    )
    terminal_preparation = (
        terminal.get("familiar_preparation")
        if isinstance(terminal, Mapping)
        else None
    )
    terminal_consider = (
        terminal.get("fastwalk_consider_outcomes")
        if isinstance(terminal, Mapping)
        else None
    )
    terminal_source_consider = (
        terminal.get("fastwalk_source_consider_outcomes")
        if isinstance(terminal, Mapping)
        else None
    )
    if not (
        isinstance(terminal, Mapping)
        and terminal.get("state") == "completed"
        and terminal.get("world_boot_id") == boot_id
        and terminal.get("fastwalk_abort_reason") == exact_abort
        and terminal.get("fastwalk_target_present_observed") is True
        and terminal.get("fastwalk_target_absent") is False
        and terminal.get("fastwalk_crowded") is False
        and terminal.get("fastwalk_objective_killed") is False
        and not terminal.get("objective_kills")
        and not terminal.get("completed_kills")
        and not terminal.get("fastwalk_route_hazards")
        and isinstance(terminal_preparation, Mapping)
        and terminal_preparation.get("selector")
        == preparation.get("selector")
        and isinstance(terminal_withdrawal, Mapping)
        and terminal_withdrawal.get("confirmed") is False
        and terminal_withdrawal.get("control") == "sleep"
        and terminal_withdrawal.get("failure") == "withdrawal order refused"
        and isinstance(terminal_consider, Mapping)
        and terminal_consider.get(target) is True
        and isinstance(terminal_source_consider, Mapping)
        and terminal_source_consider.get(policy_id) is True
    ):
        return

    selector = str(preparation.get("selector") or "")
    if not selector:
        return
    saw_flee = False
    saw_confirmed_flee = False
    saw_errant_sleep = False
    try:
        events = storage.list_events(run_id)
    except (AttributeError, OSError, RuntimeError):
        return
    for event in events:
        try:
            payload = json.loads(event.get("payload_json") or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(payload, Mapping):
            continue
        if (
            event.get("kind") == "command"
            and payload.get("command") == f"order {selector} flee Fear"
        ):
            saw_flee = True
        elif (
            saw_flee
            and event.get("kind") == "response"
            and "The pony has fled!" in str(payload.get("text") or "")
        ):
            saw_confirmed_flee = True
        elif (
            saw_confirmed_flee
            and event.get("kind") == "command"
            and payload.get("command") == f"order {selector} sleep"
        ):
            saw_errant_sleep = True
            break
    if not (saw_confirmed_flee and saw_errant_sleep):
        return

    state[_SOURCE_RANKED_FAMILIAR_REVALIDATION_KEY] = {
        "boot_id": boot_id,
        "level": character_level,
        "policy_id": policy_id,
        "target": target,
        "mobile_vnum": candidate.mobile_vnum,
        "room_vnum": candidate.room_vnum,
        "source_revision": source_revision,
        "status": "pending",
        "evidence": {
            "run_id": run_id,
            "segment_id": segment_id,
            "confirmed_flee_before_sleep": True,
            "xp_delta": end_xp - start_xp,
        },
        "reason": (
            "one retry after the prior runner ordered sleep after the familiar "
            "had already confirmed its flee"
        ),
    }


def _source_ranked_candidate_requires_sanctuary_for_state(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
    allow_consumed_output_revalidation: bool = False,
    allow_consumed_post_loss_aggressive_probe: bool = False,
    allow_unarmed_post_loss_aggressive_probe: bool = False,
    allow_unarmed_singleton_withdrawal: bool = False,
    ignore_ordinary_target_risk: bool = False,
) -> bool:
    """Require protection for incoming danger, independently of target HP."""
    # Ota'ar's Arenamaster is behind a forced arena transfer.  Outside the
    # arena, the route itself is the risk boundary: do not spend a bounded
    # segment travelling to the gate unless a verified Sanctuary reserve is
    # ready.  Once the live checkpoint is inside the arena, the dedicated
    # favour controller owns the captive circuit and its separate fallback.
    ota_arena_target = bool(
        candidate.area_file.casefold() == _OTAAR_ARENA_TARGET_AREA
        and candidate.mobile_vnum == _OTAAR_ARENA_TARGET_MOBILE_VNUM
        and candidate.room_vnum == _OTAAR_ARENA_TARGET_ROOM_VNUM
    )
    if ota_arena_target:
        if source_world is not None:
            return not _source_room_is_in_area(
                source_world,
                state.get("room_vnum"),
                _OTAAR_ARENA_TARGET_AREA,
            )
        live_area = str(state.get("area") or "").casefold().replace(" ", "_")
        return live_area not in {
            "sahuagin_arena_jail",
            "sahuagin_arena_jail.are",
        }
    protection = state.get(_PROTECTION_RECOVERY_KEY)
    if (
        isinstance(protection, Mapping)
        and protection.get("boot_id") == state.get("world_boot_id")
        and protection.get("level") in {None, character_level}
        and protection.get("policy_id")
        == _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
    ):
        # The exact route that produced the current protection marker remains
        # protection-gated even when its source damage estimate is otherwise
        # below the ordinary risk threshold.
        return True
    retry_marker = state.get(
        _SOURCE_RANKED_PROTECTION_RETRY_REVALIDATION_KEY
    )
    if (
        isinstance(retry_marker, Mapping)
        and retry_marker.get("boot_id") == state.get("world_boot_id")
        and retry_marker.get("level") in {None, character_level}
        and retry_marker.get("policy_id")
        == _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        and retry_marker.get("status") == "pending"
    ):
        # A fresh, exact retry spends the verified purple reserve before the
        # first live exchange. Keep the ordinary target and route checks, but
        # do not send this one-shot retry into unprotected combat.
        return True
    if _source_ranked_candidate_requires_sanctuary(candidate):
        return True
    if (
        source_world is not None
        and _source_ranked_low_reserve_route_retry_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    ):
        # The previous route stopped only after an incidental combat left an
        # insufficient reserve. Keep the retry explicitly Sanctuary-backed;
        # this does not make the target or route safe without fresh live proof.
        return True
    if (
        source_world is not None
        and hasattr(source_world, "mobiles")
        and _source_ranked_armed_duplicate_pair_source_allowed(
            candidate,
            source_world,
            room_vnum=candidate.room_vnum,
        )
    ):
        # The exact two-copy armed reset is a crowd/resource contract, not a
        # target-HP estimate. Keep selector admission aligned with the stop
        # builder, which dispatches this pair only with Sanctuary active.
        return True
    if ignore_ordinary_target_risk:
        return False
    # A single exact plain-target XP loss may be repaired by a fresh
    # Sanctuary reserve. Keep that retry visibly protection-gated without
    # reviving the retired target-HP/output admission rules or extending the
    # exception to specials.
    loss_record = _source_ranked_xp_loss_record(
        state,
        _source_ranked_policy_id(candidate, character_level=character_level),
    )
    if (
        not candidate.specials
        and isinstance(loss_record, Mapping)
        and not _source_ranked_xp_loss_was_protected(loss_record)
        and _source_ranked_xp_loss_count(loss_record) < 2
        and _state_has_usable_sanctuary_reserve(state)
    ):
        return True
    return _source_ranked_armed_target_requires_sanctuary(
        candidate, state, character_level=character_level, source_world=source_world,
    )


def _source_ranked_deity_protection_probe_candidate_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Expose only a protection-gated candidate to the no-combat prayer step."""
    return bool(
        not _state_has_sanctuary_reserve(state)
        and _deity_protection_probe_due(
            state,
            character_level=character_level,
        )
        and _source_ranked_candidate_requires_sanctuary_for_state(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    )


def _source_ranked_sanctuary_frontier_reserve_evidence(
    state: Mapping[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    selection_kwargs: Mapping[str, Any],
    additionally_blocked_policy_ids: Collection[str] = (),
    required_policy_id: str | None = None,
    allow_repeated_policy_ids: Collection[str] = (),
    defer_sanctuary_required_candidate: bool = False,
    deferred_candidate: HuntCandidate | None = None,
) -> dict[str, Any] | None:
    """Diagnose whether Sanctuary is the only source-selector gate.

    This is a diagnostic simulation, not hunt permission. It records a
    resource opportunity only when the ordinary selector finds no target, or
    the campaign explicitly defers its exact sanctuary-required pick, and the
    same selector with one simulated purple potion selects a source target
    that requires sanctuary. Other outcomes remain diagnostics, not trip
    permission.
    """
    if (
        _state_has_sanctuary_reserve(state)
        or not state.get("world_boot_id")
        or not state.get(_SOURCE_REVISION_KEY)
    ):
        return None
    level = _level(state)

    def diagnostic(status: str, reason: str) -> dict[str, Any]:
        return {
            "schema_version": 1,
            "status": status,
            "boot_id": state.get("world_boot_id"),
            "level": level,
            "source_revision": state.get(_SOURCE_REVISION_KEY),
            "reason": reason,
        }

    exact_deferred_candidate = (
        deferred_candidate
        if defer_sanctuary_required_candidate
        else None
    )
    pool = (
        (exact_deferred_candidate,)
        if exact_deferred_candidate is not None
        else tuple(
            candidate
            for candidate in candidates
            if required_policy_id is None
            or _source_ranked_policy_id(
                candidate,
                character_level=level,
            )
            == required_policy_id
        )
    )
    if not pool:
        return diagnostic(
            "no_source_candidates",
            "the source-ranked candidate pool was empty after policy constraints",
        )

    blocked_policy_ids = {
        str(policy_id)
        for policy_id in (
            *selection_kwargs.get("additional_blocked_policy_ids", ()),
            *additionally_blocked_policy_ids,
        )
    }
    selector_kwargs = dict(selection_kwargs)
    selector_kwargs["additional_blocked_policy_ids"] = frozenset(
        blocked_policy_ids
    )
    selector_kwargs["allow_repeated_policy_ids"] = frozenset(
        str(policy_id) for policy_id in allow_repeated_policy_ids
    )
    selector_kwargs["state"] = dict(state)
    baseline = (
        None
        if exact_deferred_candidate is not None
        else _select_source_ranked_hunt_candidate(pool, **selector_kwargs)
    )
    world = selector_kwargs.get("world")
    source_world = world if isinstance(world, WorldSource) else None
    if baseline is not None:
        baseline_requires_sanctuary = (
            _source_ranked_candidate_requires_sanctuary_for_state(
                baseline,
                state,
                character_level=level,
                source_world=source_world,
                allow_unarmed_post_loss_aggressive_probe=bool(
                    selector_kwargs.get(
                        "allow_unarmed_post_loss_aggressive_probe"
                    )
                ),
            )
        )
        if not (
            defer_sanctuary_required_candidate
            and baseline_requires_sanctuary
        ):
            return {
                **diagnostic(
                    "reserve_not_needed",
                    "the ordinary selector already found a target without Sanctuary",
                ),
                "target_policy_id": _source_ranked_policy_id(
                    baseline,
                    character_level=level,
                ),
                "target": baseline.target,
            }

    simulated_state = dict(state)
    for key in ("combat_pouch_potions", "verified_combat_pouch_potions"):
        raw = simulated_state.get(key)
        counts = dict(raw) if isinstance(raw, Mapping) else {}
        try:
            current = int(counts.get("purple") or 0)
        except (TypeError, ValueError):
            current = 0
        counts["purple"] = max(1, current)
        simulated_state[key] = counts
    selector_kwargs["state"] = simulated_state
    selected = _select_source_ranked_hunt_candidate(pool, **selector_kwargs)
    level = int(selector_kwargs.get("character_level") or _level(state))
    if selected is None:
        return diagnostic(
            "reserve_did_not_unlock_target",
            "the source selector found no target even with one simulated purple potion",
        )
    if not _source_ranked_candidate_requires_sanctuary_for_state(
        selected,
        state,
        character_level=level,
        source_world=source_world,
    ):
        return {
            **diagnostic(
                "reserve_not_required_for_target",
                "the simulated selector target does not require Sanctuary",
            ),
            "target_policy_id": _source_ranked_policy_id(
                selected,
                character_level=level,
            ),
            "target": selected.target,
        }
    return {
        **diagnostic(
            "needed",
            "no target selected without a sanctuary reserve; the same source "
            "selector selected this target after simulating one purple potion",
        ),
        "target_policy_id": _source_ranked_policy_id(
            selected,
            character_level=level,
        ),
        "target": selected.target,
        "mobile_vnum": selected.mobile_vnum,
        "room_vnum": selected.room_vnum,
    }


def _source_ranked_sanctuary_frontier_candidates(
    executable_candidates: Collection[HuntCandidate],
    ranked_candidates: Collection[HuntCandidate],
    *,
    preserve_sanctuary_reserve: bool,
    state: Mapping[str, Any],
    character_level: int,
    source_world: WorldSource | None,
    allow_unarmed_post_loss_aggressive_probe: bool,
) -> Collection[HuntCandidate]:
    """Keep protected targets in reserve diagnostics, never combat selection.

    The ordinary candidate pool intentionally removes Sanctuary-dependent
    targets when no reserve is carried. Include only those protected targets
    in the resource diagnostic; stale ordinary targets in the wider ranked
    pool can otherwise mask a real reserve opportunity. The simulated potion
    authorizes only a bounded resource handoff; live target and combat gates
    remain unchanged.
    """
    if not preserve_sanctuary_reserve:
        return executable_candidates
    return tuple(
        candidate
        for candidate in ranked_candidates
        if _source_ranked_candidate_requires_sanctuary_for_state(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
            allow_unarmed_post_loss_aggressive_probe=(
                allow_unarmed_post_loss_aggressive_probe
            ),
        )
    )


def _source_ranked_sanctuary_frontier_reserve_needed(
    state: Mapping[str, Any],
) -> bool:
    """Validate a current source-ranked target that still needs the reserve."""
    marker = state.get(_SANCTUARY_FRONTIER_RESERVE_KEY)
    valid_marker = bool(
        not _state_has_sanctuary_reserve(state)
        and isinstance(marker, Mapping)
        and marker.get("schema_version") == 1
        and marker.get("status") == "needed"
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == _level(state)
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and str(marker.get("target_policy_id") or "").startswith(
            _SOURCE_RANKED_POLICY_PREFIX
        )
        and type(marker.get("mobile_vnum")) is int
        and type(marker.get("room_vnum")) is int
    )
    if not valid_marker:
        return False

    diagnosis = state.get(_SOURCE_RANKED_FRONTIER_DIAGNOSIS_KEY)
    if not isinstance(diagnosis, Mapping):
        return True
    if (
        diagnosis.get("boot_id") != state.get("world_boot_id")
        or diagnosis.get("level") != _level(state)
        or diagnosis.get("diagnosis_revision")
        != _SOURCE_RANKED_FRONTIER_DIAGNOSIS_REVISION
        or diagnosis.get("source_revision") != state.get(_SOURCE_REVISION_KEY)
    ):
        return False

    candidates = diagnosis.get("sanctuary_required_candidates")
    if not isinstance(candidates, (list, tuple)):
        return False
    for candidate in candidates:
        if not isinstance(candidate, Mapping):
            continue
        if (
            candidate.get("policy_id") != marker.get("target_policy_id")
            or candidate.get("mobile_vnum") != marker.get("mobile_vnum")
            or candidate.get("room_vnum") != marker.get("room_vnum")
            or candidate.get("same_boot_status") not in {"fresh", "productive"}
            or candidate.get("same_boot_loss_count") != 0
        ):
            continue
        blockers = candidate.get("same_boot_blockers")
        if isinstance(blockers, (list, tuple)) and all(
            blocker == "does not pass unprotected fallback source gates"
            for blocker in blockers
        ):
            return True
    return False


def _record_source_ranked_frontier_diagnosis(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    recent_source_candidates: Collection[HuntCandidate],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
    sanctuary_reserve_candidate: HuntCandidate | None = None,
    blocked_policy_ids: Collection[str] = (),
) -> None:
    """Persist a compact explanation when source ranking finds no target.

    The selector has already applied the expensive source, route, movement,
    and output gates by the time this runs. Keep the durable record small and
    diagnostic: it explains why a healer checkpoint is waiting without
    authorizing a route or causing another live connection. Keep the exact
    simulated Sanctuary pick when it came from the wider reserve-only pool.
    """
    unique: dict[str, HuntCandidate] = {}
    for candidate in (*candidates, *recent_source_candidates):
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        unique.setdefault(policy_id, candidate)
    if sanctuary_reserve_candidate is not None:
        policy_id = _source_ranked_policy_id(
            sanctuary_reserve_candidate,
            character_level=character_level,
        )
        unique[policy_id] = sanctuary_reserve_candidate

    pool = tuple(unique.values())
    reason_counts: Counter[str] = Counter()
    current_band_count = 0
    autonomous_safe_count = 0
    sanctuary_required_count = 0
    no_sanctuary_count = 0
    psionic_protection_gated_count = 0
    psionic_protection_gated_candidates: list[dict[str, Any]] = []
    below_band_excluded_count = 0
    transit_hazard_excluded_count = 0
    same_boot_cooldown_count = 0
    same_boot_loss_closed_count = 0
    same_boot_negative_consider_count = 0
    same_boot_absence_count = 0
    same_boot_soft_cooldown_count = 0
    plain_executable_current_band_count = 0
    current_band_candidates: list[dict[str, Any]] = []
    plain_executable_candidates: list[dict[str, Any]] = []
    recent_policy_ids = {
        _source_ranked_policy_id(candidate, character_level=character_level)
        for candidate in recent_source_candidates
    }
    no_sanctuary_candidates: list[dict[str, Any]] = []
    sanctuary_required_candidates: list[dict[str, Any]] = []
    trailing_blocked_policy_ids = {str(policy_id) for policy_id in blocked_policy_ids}

    def frontier_same_boot_blockers(
        candidate: HuntCandidate,
        policy_id: str,
        loss_record: Mapping[str, Any] | None,
        same_boot_status: str,
    ) -> list[str]:
        """Explain current-reboot blockers that ordinary ranking will honor."""
        blockers: list[str] = []
        if _source_ranked_crowd_attempts_exhausted(state, policy_id):
            blockers.append("crowd rechecks exhausted for this boot")
        if same_boot_status == "cooldown":
            blockers.append("same-boot result cooldown")

        if _source_ranked_prior_level_loss_record(
            state,
            policy_id,
            character_level=character_level,
        ) is not None:
            blockers.append("prior-level XP loss closes this route")

        if loss_record is not None:
            loss_count = _source_ranked_xp_loss_count(loss_record)
            if _source_ranked_xp_loss_was_protected(loss_record):
                blockers.append(
                    "prior Sanctuary-protected XP loss closes this route"
                )
            elif loss_count >= 2:
                blockers.append("two same-boot XP losses close this route")
            elif not _state_has_sanctuary_reserve(state):
                blockers.append(
                    "prior XP loss requires a Sanctuary reserve before retry"
                )
                if candidate.equipped_weapons:
                    blockers.append(
                        "the narrow post-loss probe requires an unarmed target"
                    )
                if candidate.estimated_level_range[1] > character_level + 2:
                    blockers.append(
                        "the narrow post-loss probe is limited to source "
                        "maximum level +2"
                    )

        return list(dict.fromkeys(blockers))

    for candidate in pool:
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        bounded_bear_transit_route = bool(
            source_world is not None
            and _source_ranked_bounded_bear_transit_route_allowed(
                candidate,
                character_level=character_level,
                source_world=source_world,
            )
        )
        candidate_autonomous_safe = bool(
            candidate.autonomous_safe or bounded_bear_transit_route
        )
        plain_duplicate_rotation = bool(
            source_world is not None
            and _source_ranked_plain_duplicate_rotation_selection_allowed(
                candidate,
                source_world,
            )
        )
        loss_record = _source_ranked_xp_loss_record(state, policy_id)
        if loss_record is None:
            loss_record = _source_ranked_xp_loss_for_mobile(
                state,
                mobile_vnum=candidate.mobile_vnum,
                character_level=character_level,
            )
        prior_level_loss = _source_ranked_prior_level_loss_record(
            state,
            policy_id,
            character_level=character_level,
        )
        research_result = _campaign_research_results(state).get(policy_id)
        hard_loss_closed = bool(
            loss_record is not None or prior_level_loss is not None
        )
        negative_consider = bool(
            isinstance(research_result, Mapping)
            and research_result.get("boot_id") == state.get("world_boot_id")
            and research_result.get("observed") is True
            and research_result.get("consider_viable") is False
        )
        absence_evidence = bool(
            isinstance(research_result, Mapping)
            and research_result.get("boot_id") == state.get("world_boot_id")
            and research_result.get("absent") is True
            and research_result.get("observed") is False
            and research_result.get("viable") is False
        )
        psionic_protection_gated = _source_ranked_psionic_candidate_requires_protection(
            candidate,
            source_world=source_world,
        )
        psionic_protection_requirement = (
            _source_ranked_psionic_protection_requirement(
                candidate,
                source_world=source_world,
            )
            if psionic_protection_gated
            else ""
        )
        if psionic_protection_gated:
            psionic_protection_gated_count += 1
            if len(psionic_protection_gated_candidates) < 32:
                psionic_protection_gated_candidates.append({
                    "policy_id": policy_id,
                    "target": candidate.target,
                    "mobile_vnum": candidate.mobile_vnum,
                    "area_file": candidate.area_file,
                    "room_vnum": candidate.room_vnum,
                    "level_range": list(candidate.estimated_level_range),
                    "specials": list(candidate.specials),
                    "protection_effects": list(
                        _source_ranked_psionic_protection_effects(
                            candidate,
                            source_world=source_world,
                        )
                    ),
                    "reason": psionic_protection_requirement,
                })
        same_boot_status = _source_ranked_result_status(
            candidate,
            state,
            character_level=character_level,
            allow_cooldown_retry=True,
        )
        below_band = _funding_candidate_is_below_band(
            dict(state),
            candidate,
            character_level=character_level,
            boot_id=state.get("world_boot_id"),
        )
        transit_hazard = bool(
            source_world is not None
            and _source_ranked_candidate_excluded_by_transit_hazard(
                candidate,
                state,
                character_level=character_level,
                source_world=source_world,
            )
        )
        requires_sanctuary = _source_ranked_candidate_requires_sanctuary_for_state(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
        current_band = _source_ranked_candidate_in_current_band(
            candidate,
            state,
            world=source_world,
            character_level=character_level,
            character_max_hp=character_max_hp,
            allow_repeated_kills=True,
        )
        if current_band:
            current_band_count += 1
            if below_band:
                below_band_excluded_count += 1
                reason_counts["same-boot below-band evidence"] += 1
            if transit_hazard:
                transit_hazard_excluded_count += 1
                reason_counts["recorded source transit hazard"] += 1
            if same_boot_status == "cooldown":
                same_boot_cooldown_count += 1
                if hard_loss_closed:
                    same_boot_loss_closed_count += 1
                else:
                    same_boot_soft_cooldown_count += int(
                        not negative_consider and not absence_evidence
                    )
            if negative_consider:
                same_boot_negative_consider_count += 1
                reason_counts["live consider below useful XP band"] += 1
            if absence_evidence:
                same_boot_absence_count += 1
                reason_counts["loss-free locator absence"] += 1
            if (
                same_boot_status == "cooldown"
                and not hard_loss_closed
                and not negative_consider
                and not absence_evidence
            ):
                reason_counts["soft research cooldown"] += 1
            if psionic_protection_gated:
                reason_counts[psionic_protection_requirement] += 1
            current_band_blockers = frontier_same_boot_blockers(
                candidate,
                policy_id,
                loss_record,
                same_boot_status,
            )
            if policy_id in trailing_blocked_policy_ids:
                current_band_blockers.append(
                    "trailing no-progress rotation blocks this route"
                )
            if psionic_protection_gated:
                current_band_blockers.append(psionic_protection_requirement)
            current_band_blockers.extend(candidate.autonomy_rejections[:6])
            current_band_blockers = list(dict.fromkeys(current_band_blockers))
            raw_timeout_records = state.get(
                _SOURCE_RANKED_TIMEOUT_POLICIES_KEY
            )
            timeout_revalidation_spent = any(
                isinstance(record, Mapping)
                and record.get("boot_id") == state.get("world_boot_id")
                and record.get("level") in {None, character_level}
                and record.get("policy_id") == policy_id
                and (
                    record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD)
                    is True
                    or _source_ranked_timeout_revalidation_attempts(record)
                    >= _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS
                )
                for record in (
                    raw_timeout_records
                    if isinstance(raw_timeout_records, (list, tuple))
                    else ()
                )
            )
            if candidate_autonomous_safe or plain_duplicate_rotation:
                reason_counts.update(
                    blocker
                    for blocker in current_band_blockers
                    if blocker != "same-boot result cooldown"
                )
            if (
                (candidate_autonomous_safe or plain_duplicate_rotation)
                and not below_band
                and not transit_hazard
                and not (
                    requires_sanctuary
                    and not _state_has_sanctuary_reserve(state)
                )
                and not _source_ranked_candidate_blocked_by_protection_recovery(
                    candidate,
                    state,
                    character_level=character_level,
                    character_max_hp=character_max_hp,
                    allow_protection_recovery_fallback=True,
                    source_world=source_world,
                )
                and same_boot_status != "cooldown"
                and policy_id not in trailing_blocked_policy_ids
                and not timeout_revalidation_spent
                and (
                    not candidate.autonomy_rejections
                    or bounded_bear_transit_route
                    or (
                        plain_duplicate_rotation
                        and set(candidate.autonomy_rejections)
                        == {"target reset capacity exceeds one"}
                    )
                )
            ):
                plain_executable_current_band_count += 1
                if len(plain_executable_candidates) < 32:
                    plain_executable_candidates.append({
                        "policy_id": policy_id,
                        "target": candidate.target,
                        "mobile_vnum": candidate.mobile_vnum,
                        "room_vnum": candidate.room_vnum,
                        "level_range": list(candidate.estimated_level_range),
                        "same_boot_status": same_boot_status,
                    })
            if len(current_band_candidates) < 32:
                same_boot_blockers = current_band_blockers
                current_band_candidates.append({
                    "policy_id": policy_id,
                    "target": candidate.target,
                    "mobile_vnum": candidate.mobile_vnum,
                    "area_file": candidate.area_file,
                    "room_vnum": candidate.room_vnum,
                    "level_range": list(candidate.estimated_level_range),
                    "candidate_status": candidate.status,
                    "autonomous_safe": candidate_autonomous_safe,
                    "autonomy_rejections": list(
                        candidate.autonomy_rejections[:6]
                    ),
                    "requires_sanctuary": (
                        _source_ranked_candidate_requires_sanctuary_for_state(
                            candidate,
                            state,
                            character_level=character_level,
                            source_world=source_world,
                        )
                    ),
                    "specials": list(candidate.specials[:6]),
                    "equipped_weapons": list(candidate.equipped_weapons[:4]),
                    "boot_kills": candidate.boot_kills,
                    "room_spawn_count": candidate.room_spawn_count,
                    "source_spawn_limit": candidate.source_spawn_limit,
                    "route_hazards": list(candidate.hazards[:5]),
                    "same_boot_status": _source_ranked_result_status(
                        candidate,
                        state,
                        character_level=character_level,
                        allow_cooldown_retry=True,
                    ),
                    "same_boot_loss_count": (
                        _source_ranked_xp_loss_count(loss_record)
                        if loss_record is not None
                        else 0
                    ),
                    "same_boot_blockers": same_boot_blockers,
                })
        if not candidate_autonomous_safe and not plain_duplicate_rotation:
            reason_counts.update(candidate.autonomy_rejections)
            continue
        if candidate_autonomous_safe:
            autonomous_safe_count += 1
        if not current_band:
            reason_counts["outside the current useful level band"] += 1
            continue
        if requires_sanctuary:
            sanctuary_required_count += 1
            reason_counts["sanctuary reserve required"] += 1
            if not below_band and len(sanctuary_required_candidates) < 32:
                policy_id = _source_ranked_policy_id(
                    candidate,
                    character_level=character_level,
                )
                loss_record = _source_ranked_xp_loss_record(
                    state,
                    policy_id,
                )
                loss_count = (
                    _source_ranked_xp_loss_count(loss_record)
                    if loss_record is not None
                    else 0
                )
                fallback_allowed = (
                    _source_ranked_protection_recovery_fallback_candidate_allowed(
                        candidate,
                        state,
                        character_level=character_level,
                        character_max_hp=character_max_hp,
                        source_world=source_world,
                    )
                )
                blocked_by_protection_recovery = (
                    _source_ranked_candidate_blocked_by_protection_recovery(
                        candidate,
                        state,
                        character_level=character_level,
                        character_max_hp=character_max_hp,
                        allow_protection_recovery_fallback=True,
                        source_world=source_world,
                    )
                )
                same_boot_blockers: list[str] = []
                if loss_record is not None and _source_ranked_xp_loss_was_protected(
                    loss_record
                ):
                    same_boot_blockers.append(
                        "prior sanctuary-protected XP loss closes this route"
                    )
                elif loss_count >= 2:
                    same_boot_blockers.append(
                        "two same-boot XP losses close this route"
                    )
                if (
                    blocked_by_protection_recovery
                    and not same_boot_blockers
                ):
                    same_boot_blockers.append(
                        "protection-recovery retry policy closes this route"
                    )
                if not fallback_allowed:
                    same_boot_blockers.append(
                        "does not pass unprotected fallback source gates"
                    )
                if any(
                    blocker.startswith((
                        "prior sanctuary-protected XP loss",
                        "two same-boot XP losses",
                    ))
                    for blocker in same_boot_blockers
                ):
                    reason_counts["same-boot XP-loss quarantine"] += 1
                sanctuary_required_candidates.append({
                    "policy_id": policy_id,
                    "selection_pool": (
                        "recent-mobile-kill"
                        if policy_id in recent_policy_ids
                        else "current"
                    ),
                    "target": candidate.target,
                    "mobile_vnum": candidate.mobile_vnum,
                    "area_file": candidate.area_file,
                    "room_vnum": candidate.room_vnum,
                    "room_name": candidate.room_name,
                    "level_range": list(candidate.estimated_level_range),
                    "base_hp_range": list(candidate.estimated_base_hp_range),
                    "peak_round_damage": candidate.estimated_peak_round_damage,
                    "equipped_weapons": list(candidate.equipped_weapons),
                    "specials": list(candidate.specials),
                    "boot_kills": candidate.boot_kills,
                    "route_hazards": list(candidate.hazards[:3]),
                    "same_boot_status": _source_ranked_result_status(
                        candidate,
                        state,
                        character_level=character_level,
                        allow_cooldown_retry=True,
                    ),
                    "same_boot_loss_count": (
                        loss_count
                    ),
                    "unprotected_fallback_allowed": fallback_allowed,
                    "same_boot_blockers": same_boot_blockers,
                })
        elif not below_band:
            no_sanctuary_count += 1
            if len(no_sanctuary_candidates) < 32:
                policy_id = _source_ranked_policy_id(
                    candidate,
                    character_level=character_level,
                )
                raw_timeout_records = state.get(
                    _SOURCE_RANKED_TIMEOUT_POLICIES_KEY
                )
                timeout_records = (
                    raw_timeout_records
                    if isinstance(raw_timeout_records, (list, tuple))
                    else ()
                )
                timeout_revalidation_spent = any(
                    isinstance(record, Mapping)
                    and record.get("boot_id") == state.get("world_boot_id")
                    and record.get("level") in {None, character_level}
                    and record.get("policy_id") == policy_id
                    and (
                        record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD)
                        is True
                        or _source_ranked_timeout_revalidation_attempts(record)
                        >= _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS
                    )
                    for record in timeout_records
                )
                same_boot_blockers = frontier_same_boot_blockers(
                    candidate,
                    policy_id,
                    loss_record,
                    _source_ranked_result_status(
                        candidate,
                        state,
                        character_level=character_level,
                        allow_cooldown_retry=True,
                    ),
                )
                if policy_id in trailing_blocked_policy_ids:
                    same_boot_blockers.append(
                        "trailing no-progress rotation blocks this route"
                    )
                same_boot_blockers.extend(candidate.autonomy_rejections[:6])
                same_boot_blockers = list(dict.fromkeys(same_boot_blockers))
                if timeout_revalidation_spent:
                    same_boot_blockers.append(
                        "timeout revalidation already used"
                    )
                no_sanctuary_candidates.append({
                    "policy_id": policy_id,
                    "selection_pool": (
                        "recent-mobile-kill"
                        if policy_id in recent_policy_ids
                        else "current"
                    ),
                    "target": candidate.target,
                    "mobile_vnum": candidate.mobile_vnum,
                    "area_file": candidate.area_file,
                    "room_vnum": candidate.room_vnum,
                    "room_name": candidate.room_name,
                    "level_range": list(candidate.estimated_level_range),
                    "base_hp_range": list(candidate.estimated_base_hp_range),
                    "boot_kills": candidate.boot_kills,
                    "route_hazards": list(candidate.hazards[:3]),
                    "same_boot_status": _source_ranked_result_status(
                        candidate,
                        state,
                        character_level=character_level,
                        allow_cooldown_retry=True,
                    ),
                    "same_boot_blockers": same_boot_blockers,
                })

    state[_SOURCE_RANKED_FRONTIER_DIAGNOSIS_KEY] = {
        "boot_id": state.get("world_boot_id"),
        "level": character_level,
        "diagnosis_revision": _SOURCE_RANKED_FRONTIER_DIAGNOSIS_REVISION,
        "source_revision": state.get(_SOURCE_REVISION_KEY),
        "known_purse_copper": known_purse(state.get("currencies")),
        "candidate_count": len(pool),
        "current_band_count": current_band_count,
        "current_band_candidates": current_band_candidates,
        "autonomous_safe_count": autonomous_safe_count,
        "sanctuary_required_count": sanctuary_required_count,
        "no_sanctuary_count": no_sanctuary_count,
        "no_sanctuary_candidates": no_sanctuary_candidates,
        "sanctuary_required_candidates": sanctuary_required_candidates,
        "psionic_protection_gated_count": psionic_protection_gated_count,
        "psionic_protection_gated_candidates": psionic_protection_gated_candidates,
        "same_boot_below_band_count": below_band_excluded_count,
        "same_boot_transit_hazard_count": transit_hazard_excluded_count,
        "same_boot_cooldown_count": same_boot_cooldown_count,
        # Keep the legacy aggregate above for report compatibility, but expose
        # the reason categories separately so a cooldown is never mistaken for
        # a reboot-scoped retry quota.
        "same_boot_loss_closed_count": same_boot_loss_closed_count,
        "same_boot_negative_consider_count": same_boot_negative_consider_count,
        "same_boot_absence_count": same_boot_absence_count,
        "same_boot_soft_cooldown_count": same_boot_soft_cooldown_count,
        "plain_executable_current_band_count": plain_executable_current_band_count,
        "plain_executable_candidates": plain_executable_candidates,
        "sanctuary_reserve_available": _state_has_sanctuary_reserve(state),
        "protection_recovery_required": _protection_recovery_required(state),
        "top_blockers": [
            {"reason": reason, "count": count}
            for reason, count in reason_counts.most_common(8)
        ],
        "reason": "no executable source-ranked frontier",
    }


def _source_ranked_productive_unprotected_repeat_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Trust one meaningful same-boot kill over a narrow HP-fuzz gate."""
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if _source_ranked_xp_loss_record(state, policy_id) is not None:
        return False
    result = _campaign_research_results(state).get(policy_id)
    if not isinstance(result, Mapping):
        return False
    if result.get("boot_id") != state.get("world_boot_id"):
        return False
    if not (
        result.get("observed") is True
        and result.get("consider_viable") is True
        and result.get("viable") is True
        and result.get("completed_kill") is True
    ):
        return False
    if any(
        result.get(key)
        for key in (
            "absent",
            "crowded",
            "crowd_exhausted",
            "route_hazard",
            "unattackable",
            "target_vnum_mismatch",
            "fatal_failure",
        )
    ) or result.get("low_reward") is True:
        return False
    try:
        max_kill_xp = int(result.get("max_objective_kill_xp") or 0)
    except (TypeError, ValueError):
        return False
    return bool(
        _source_ranked_multi_kill_reward_allowed(result)
        or max_kill_xp >= _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
    )


def _source_ranked_adjacent_level_unprotected_kill_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Reuse two verified prior-level solo kills for this exact plain reset."""
    if (
        character_level <= 1
        or not candidate.autonomous_safe
        or candidate.is_coin_stash
        or candidate.equipped_weapons
        or candidate.specials
    ):
        return False
    raw_hp, raw_max_hp = state.get("hp"), state.get("max_hp")
    if (
        isinstance(raw_hp, bool)
        or not isinstance(raw_hp, (int, float))
        or isinstance(raw_max_hp, bool)
        or not isinstance(raw_max_hp, (int, float))
        or raw_max_hp <= 0
        or raw_hp < raw_max_hp * 0.95
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    previous_policy_id = _source_identity_policy_id(
        candidate.area_file,
        candidate.mobile_vnum,
        candidate.room_vnum,
        character_level - 1,
        candidate.route_origin_recall_index,
    )
    if (
        _source_ranked_result_status(
            candidate,
            state,
            character_level=character_level,
        )
        not in {"fresh", "productive"}
        or _source_ranked_xp_loss_record(state, policy_id) is not None
        or _source_ranked_xp_loss_record(state, previous_policy_id) is not None
    ):
        return False
    receipts = state.get(_SOURCE_RANKED_ADJACENT_LEVEL_UNPROTECTED_KILLS_KEY)
    if not isinstance(receipts, Mapping):
        return False
    receipt = receipts.get(policy_id)
    if not isinstance(receipt, Mapping):
        return False
    if not (
        receipt.get("boot_id") == state.get("world_boot_id")
        and receipt.get("level") == character_level
        and receipt.get("policy_id") == policy_id
        and receipt.get("previous_policy_id") == previous_policy_id
        and receipt.get("mobile_vnum") == candidate.mobile_vnum
        and receipt.get("room_vnum") == candidate.room_vnum
        and receipt.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
    ):
        return False
    verified_runs = receipt.get("verified_runs")
    if not isinstance(verified_runs, (list, tuple)):
        return False
    try:
        source_output_ceiling = int(receipt.get("source_output_ceiling"))
    except (TypeError, ValueError):
        return False
    if source_output_ceiling <= 0:
        return False
    run_ids: set[int] = set()
    for verified in verified_runs:
        if not isinstance(verified, Mapping):
            continue
        try:
            run_id = int(verified.get("run_id"))
            xp_gained = int(verified.get("xp_gained"))
            health_floor = float(verified.get("lowest_health_fraction"))
            observed_target_max_hp = int(verified.get("observed_target_max_hp"))
        except (TypeError, ValueError):
            continue
        if (
            verified.get("source_policy_id") == previous_policy_id
            and verified.get("source_mobile_vnum") == candidate.mobile_vnum
            and verified.get("world_boot_id") == state.get("world_boot_id")
            and xp_gained > 0
            and health_floor >= 0.20
            and observed_target_max_hp > 0
        ):
            run_ids.add(run_id)
    return len(run_ids) >= 2


def _source_ranked_sanctuary_reserve_cooldown_active(
    state: Mapping[str, Any],
) -> bool:
    """Keep a failed or quarantined reserve route out of the selector."""
    policy_id = _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id
    return _research_retry_cooldown_active(
        state,
        policy_id,
    ) or _research_fatal_failure_active(state, policy_id)


def _source_ranked_sanctuary_recovery_allowed(
    state: Mapping[str, Any],
    *,
    preserve_sanctuary_reserve: bool,
) -> bool:
    """Allow a refill after depletion; prior acquisition is not a reboot quota."""
    return not (
        preserve_sanctuary_reserve
        or _source_ranked_sanctuary_reserve_cooldown_active(state)
    )


def _source_ranked_sanctuary_reserve_acquired_this_reboot(
    state: Mapping[str, Any],
) -> bool:
    """Return whether this reboot already produced a reserve-route item."""
    result = _campaign_research_results(state).get(
        _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id
    )
    return bool(
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("required_object_acquired") is True
    )


def _moria_source_refresh_proves_second_reserve_refill(
    state: Mapping[str, Any],
) -> bool:
    """Allow one double-potion refill after a later reserve-route loss.

    The room-4071 source-refresh receipt proves that the current source
    revision can produce the required potion. It is still only a one-shot
    maintenance entitlement: the caller records the refill marker before
    dispatch, and the normal live loot/reset gates remain in control.
    """
    boot_id = state.get("world_boot_id")
    level = _level(state)
    source_revision = state.get(_SOURCE_REVISION_KEY)
    first_refresh = state.get(_MORIA_SANCTUARY_SOURCE_REFRESH_REVALIDATION_KEY)
    second_refresh = state.get(
        _MORIA_SANCTUARY_SECOND_SOURCE_REFRESH_REVALIDATION_KEY
    )
    recovery_policy_id = _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
    recovery_result = _campaign_research_results(state).get(recovery_policy_id)
    if not (
        boot_id
        and level is not None
        and isinstance(source_revision, str)
        and source_revision
        and source_revision == _current_dd4_source_revision()
        and _current_protection_recovery_marker_present(state)
        and _state_has_sanctuary_reserve(state)
        and not _state_has_blindness_recovery_reserve(state)
        and _source_ranked_sanctuary_reserve_cooldown_active(state)
        and isinstance(recovery_result, Mapping)
        and recovery_result.get("boot_id") == boot_id
        and recovery_result.get("level") == level
        and recovery_result.get("fatal_failure") is True
        and recovery_result.get("completed_kill") is False
        and recovery_result.get("route_hazard")
        == _SANCTUARY_RESOURCE_EXHAUSTED_HAZARD
        and isinstance(first_refresh, Mapping)
        and first_refresh.get("source_refresh") is True
        and first_refresh.get("status") == "closed"
        and first_refresh.get("outcome") == "no_object"
        and first_refresh.get("consumed_before_dispatch") is True
        and first_refresh.get("attempted") is False
        and first_refresh.get("boot_id") == boot_id
        and first_refresh.get("level") == level
        and first_refresh.get("source_revision") == source_revision
        and first_refresh.get("source_mobile_vnum")
        == _MORIA_SANCTUARY_CARRIER_MOBILE_VNUM
        and first_refresh.get("source_object_vnum")
        == _MORIA_SANCTUARY_POTION_OBJECT_VNUM
        and first_refresh.get("source_reset_room_vnum") == 4064
        and isinstance(second_refresh, Mapping)
        and second_refresh.get("source_refresh") is True
        and second_refresh.get("status") == "succeeded"
        and second_refresh.get("outcome") == "required_object_acquired"
        and second_refresh.get("consumed_before_dispatch") is True
        and second_refresh.get("attempted") is False
        and second_refresh.get("boot_id") == boot_id
        and second_refresh.get("level") == level
        and second_refresh.get("source_revision") == source_revision
        and second_refresh.get("source_mobile_vnum")
        == _MORIA_SANCTUARY_CARRIER_MOBILE_VNUM
        and second_refresh.get("source_object_vnum")
        == _MORIA_SANCTUARY_POTION_OBJECT_VNUM
        and second_refresh.get("source_reset_room_vnum") == 4071
    ):
        return False
    prior_source_revision = second_refresh.get("prior_source_revision")
    return bool(
        isinstance(prior_source_revision, str)
        and prior_source_revision
        and prior_source_revision != source_revision
    )


def _source_ranked_second_sanctuary_refill_requested(
    state: Mapping[str, Any],
) -> bool:
    """Return whether this segment must request two purple potions."""
    marker = state.get(_SANCTUARY_SECOND_RESERVE_REFILL_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == _level(state)
        and marker.get("policy_id")
        == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
        and marker.get("policy_revision")
        == _SANCTUARY_SECOND_RESERVE_REFILL_REVALIDATION_REVISION
        and marker.get("requested_potion_count") == 2
        and marker.get("status") in {"pending", "attempted"}
    )


def _source_ranked_second_sanctuary_recovery_priority(
    state: Mapping[str, Any],
) -> bool:
    """Return whether a proven recovery route should use the recovery policy.

    A forward blindness reserve and a retry after the dedicated reserve route
    are both represented by the same two-potion marker.  Only the latter may
    bypass the ordinary reserve policy and flight-funding checkpoint.
    """
    marker = state.get(_SANCTUARY_SECOND_RESERVE_REFILL_KEY)
    if isinstance(marker, Mapping):
        reason = str(marker.get("reason") or "").casefold()
        if "reuse the proven generic recovery route" in reason:
            return True
    if _moria_source_refresh_proves_second_reserve_refill(state):
        return True
    if not (
        _current_protection_recovery_marker_present(state)
        and _state_has_sanctuary_reserve(state)
        and not _state_has_blindness_recovery_reserve(state)
    ):
        return False
    recovery_result = _campaign_research_results(state).get(
        _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
    )
    reserve_result = _campaign_research_results(state).get(
        _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id
    )
    return bool(
        isinstance(recovery_result, Mapping)
        and recovery_result.get("boot_id") == state.get("world_boot_id")
        and recovery_result.get("level") in {None, _level(state)}
        and recovery_result.get("viable") is True
        and recovery_result.get("required_object_acquired") is True
        and isinstance(reserve_result, Mapping)
        and reserve_result.get("boot_id") == state.get("world_boot_id")
        and reserve_result.get("fatal_failure") is True
        and reserve_result.get("route_hazard")
        == _SANCTUARY_RESOURCE_EXHAUSTED_HAZARD
    )


def _source_ranked_second_sanctuary_refill_allowed(
    state: Mapping[str, Any],
) -> bool:
    """Allow one proven recovery-route refill after reserve quarantine."""
    marker = state.get(_SANCTUARY_SECOND_RESERVE_REFILL_KEY)
    if isinstance(marker, Mapping):
        if (
            marker.get("boot_id") == state.get("world_boot_id")
            and marker.get("level") == _level(state)
            and marker.get("status") in {"attempted", "closed", "succeeded"}
        ):
            if (
                marker.get("status") == "succeeded"
                and marker.get("resource_receipt_missing") is True
                and str(
                    marker.get("requested_resource_kind") or ""
                ).casefold()
                == "source_sanctuary_resource"
            ):
                return bool(
                    _current_protection_recovery_marker_present(state)
                    and _state_has_sanctuary_reserve(state)
                    and not _state_has_blindness_recovery_reserve(state)
                    and _source_ranked_sanctuary_reserve_cooldown_active(state)
                )
            # The refill is consumed before dispatch. Keep every terminal
            # outcome closed for this boot and level, including older
            # checkpoints that only retained the completed outcome.
            return False
        if (
            marker.get("boot_id") == state.get("world_boot_id")
            and marker.get("level") == _level(state)
            and marker.get("policy_id")
            == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
            and marker.get("policy_revision")
            == _SANCTUARY_SECOND_RESERVE_REFILL_REVALIDATION_REVISION
            and marker.get("requested_potion_count") == 2
            and marker.get("status") == "pending"
        ):
            return bool(
                _current_protection_recovery_marker_present(state)
                and _state_has_sanctuary_reserve(state)
                and not _state_has_blindness_recovery_reserve(state)
                and _source_ranked_sanctuary_reserve_cooldown_active(state)
            )
    if not _current_protection_recovery_marker_present(state):
        return False
    if not _state_has_sanctuary_reserve(state):
        return False
    if _state_has_blindness_recovery_reserve(state):
        return False
    if not _source_ranked_sanctuary_reserve_cooldown_active(state):
        return False
    if _moria_source_refresh_proves_second_reserve_refill(state):
        return True
    recovery_policy_id = _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
    recovery_result = _campaign_research_results(state).get(
        recovery_policy_id
    )
    if not (
        isinstance(recovery_result, Mapping)
        and recovery_result.get("boot_id") == state.get("world_boot_id")
        and recovery_result.get("viable") is True
        and recovery_result.get("required_object_acquired") is True
    ):
        return False
    return not (
        _research_retry_cooldown_active(state, recovery_policy_id)
        or _research_fatal_failure_active(state, recovery_policy_id)
    )


def _source_ranked_forward_blindness_reserve_allowed(
    state: Mapping[str, Any],
    *,
    carrier_selection: tuple[HuntCandidate, tuple[int, ...]] | None,
) -> bool:
    """Allow one forward purple refill for a newly admitted special route.

    The older recovery gate is intentionally tied to a prior protection loss.
    A healthy Sanctuary reserve can still need a second, independent recovery
    resource before the selector opens a blindness-capable target.  The exact
    carrier and target are both source-ranked by the caller; this helper only
    makes that maintenance handoff available once per current boot/level.
    """
    if carrier_selection is None:
        return False
    if not (
        _state_has_sanctuary_reserve(state)
        and not _state_has_blindness_recovery_reserve(state)
        and _is_safe_healer_checkpoint(state)
    ):
        return False
    marker = state.get(_SANCTUARY_SECOND_RESERVE_REFILL_KEY)
    if (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == _level(state)
        and marker.get("status") in {"pending", "attempted", "closed", "succeeded"}
    ):
        return False
    return carrier_selection[0].status != "reject"


def _sanctuary_resource_attempt_count(
    state: Mapping[str, Any],
    policy_id: str,
    *,
    boot_id: Any = None,
    level: int | None = None,
) -> int:
    """Return the current reboot/level count for a reserve-route attempt."""
    attempts = state.get(_SANCTUARY_RESOURCE_ATTEMPTS_KEY)
    if not isinstance(attempts, Mapping):
        return 0
    record = attempts.get(policy_id)
    if not isinstance(record, Mapping):
        return 0
    expected_boot_id = state.get("world_boot_id") if boot_id is None else boot_id
    if record.get("boot_id") != expected_boot_id:
        return 0
    if level is not None and record.get("level") != level:
        return 0
    try:
        return max(0, int(record.get("count") or 0))
    except (TypeError, ValueError):
        return 0


def _sanctuary_area_reset_recheck_pending(
    state: Mapping[str, Any],
) -> bool:
    """Return whether one bounded post-reset sanctuary retry is armed."""
    marker = state.get(_SANCTUARY_AREA_RESET_RECHECK_KEY)
    policy_ids = marker.get("policy_ids") if isinstance(marker, Mapping) else ()
    return bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == _level(state)
        and marker.get("status") == "pending"
        and isinstance(policy_ids, (list, tuple, set, frozenset))
        and policy_ids
    )


def _sanctuary_area_reset_recheck_dispatch_pending(
    state: Mapping[str, Any],
) -> bool:
    """Return whether a reopened sanctuary route still needs its live attempt."""
    marker = state.get(_SANCTUARY_AREA_RESET_RECHECK_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == _level(state)
        and marker.get("status") == "attempted"
        and marker.get("after_segment_id") is not None
        and marker.get("dispatch_started") is not True
    ):
        return False
    if _state_has_sanctuary_reserve(state):
        return False
    policy_ids = marker.get("policy_ids")
    if not isinstance(policy_ids, (list, tuple, set, frozenset)) or not policy_ids:
        return False
    attempts = state.get(_SANCTUARY_RESOURCE_ATTEMPTS_KEY) or {}
    for raw_policy_id in policy_ids:
        policy_id = str(raw_policy_id)
        attempt = attempts.get(policy_id) if isinstance(attempts, Mapping) else None
        if not isinstance(attempt, Mapping) or attempt.get("area_reset_cycle") not in {
            1,
            2,
        }:
            return False
        if (
            _sanctuary_resource_attempt_count(
                state,
                policy_id,
                boot_id=state.get("world_boot_id"),
                level=_level(state),
            )
            != 0
        ):
            return False
        result = _campaign_research_results(state).get(policy_id)
        if isinstance(result, Mapping) and result.get("boot_id") == state.get(
            "world_boot_id"
        ):
            return False
    return True


def _sanctuary_area_reset_recheck_spent_for_policy(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Return whether the one post-reset retry has already been dispatched."""
    marker = state.get(_SANCTUARY_AREA_RESET_RECHECK_KEY)
    policy_ids = marker.get("policy_ids") if isinstance(marker, Mapping) else ()
    return bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == _level(state)
        and marker.get("status") == "attempted"
        and marker.get("after_segment_id") is not None
        and marker.get("dispatch_started") is True
        and isinstance(policy_ids, (list, tuple, set, frozenset))
        and policy_id in {str(candidate_id) for candidate_id in policy_ids}
    )


def _sanctuary_area_reset_recheck_rearm_after_success_available(
    state: Mapping[str, Any],
) -> bool:
    """Return whether a successful refill can receive one later reset retry."""
    marker = state.get(_SANCTUARY_AREA_RESET_RECHECK_KEY)
    policy_ids = marker.get("policy_ids") if isinstance(marker, Mapping) else ()
    if not (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == _level(state)
        and marker.get("status") == "attempted"
        and marker.get("dispatch_started") is True
        and marker.get("rearm_after_successful_acquisition") is not True
        and marker.get("after_segment_id") is not None
        and isinstance(policy_ids, (list, tuple, set, frozenset))
        and policy_ids
        and not _state_has_sanctuary_reserve(state)
        and _protection_recovery_required(state)
    ):
        return False
    attempts = state.get(_SANCTUARY_RESOURCE_ATTEMPTS_KEY) or {}
    results = _campaign_research_results(dict(state))
    for raw_policy_id in policy_ids:
        policy_id = str(raw_policy_id)
        attempt = attempts.get(policy_id) if isinstance(attempts, Mapping) else None
        if not isinstance(attempt, Mapping):
            continue
        try:
            attempt_count = max(0, int(attempt.get("count") or 0))
        except (TypeError, ValueError):
            attempt_count = 0
        result = results.get(policy_id)
        if (
            attempt_count > 0
            and isinstance(result, Mapping)
            and result.get("boot_id") == state.get("world_boot_id")
            and result.get("level") in {None, _level(state)}
            and result.get("required_object_acquired") is True
        ):
            return True
    return False


def _retire_sanctuary_attempt_quota_results(state: Mapping[str, Any]) -> dict[str, Any]:
    """Archive synthetic count-only failures without changing actual evidence."""
    repaired = dict(state)
    results = dict(_campaign_research_results(state))
    changed = False
    for policy_id, result in list(results.items()):
        if (not _is_sanctuary_resource_policy_id(policy_id)
                or not isinstance(result, Mapping)
                or result.get("route_hazard") != _SANCTUARY_RESOURCE_EXHAUSTED_HAZARD):
            continue
        retired = dict(result)
        retired["retired_attempt_quota"] = {
            "fatal_failure": result.get("fatal_failure"), "route_hazard": result["route_hazard"],
        }
        retired.pop("fatal_failure", None)
        retired.pop("route_hazard", None)
        retired["retryable_failure"] = True
        results[policy_id] = retired
        changed = True
    if changed:
        repaired["campaign_research_results"] = results
    return repaired


def _sanctuary_recovery_attempts_exhausted(
    state: Mapping[str, Any],
    *,
    policy_id: str = _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id,
) -> bool:
    """Retain actual terminal evidence, never a same-boot attempt quota."""
    if _sanctuary_area_reset_recheck_dispatch_pending(state):
        return False
    if (
        policy_id == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
        and _sanctuary_route_suffix_revalidation_pending(state)
    ):
        return False
    if (
        policy_id == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
        and _sanctuary_end_tunnel_revalidation_pending(state)
    ):
        return False
    if policy_id == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id:
        raw_results = state.get("campaign_research_results")
        result = (
            raw_results.get(policy_id)
            if isinstance(raw_results, Mapping)
            else None
        )
        if (
            isinstance(result, Mapping)
            and result.get("fatal_failure") is True
            and result.get("boot_id") == state.get("world_boot_id")
            and result.get("level") in {None, _level(state)}
            and result.get("completed_kill") is not True
            and result.get("route_hazard") != _SANCTUARY_RESOURCE_EXHAUSTED_HAZARD
        ):
            # A fatal same-boot result records the route boundary even when
            # an older checkpoint left its attempt counter behind.
            return True
    return False


def _sanctuary_area_reset_recheck_failure_terminal(
    state: Mapping[str, Any],
) -> bool:
    """Prevent a spent post-reset sanctuary attempt from restarting the wait."""
    marker = state.get(_SANCTUARY_AREA_RESET_RECHECK_KEY)
    policy_ids = marker.get("policy_ids") if isinstance(marker, Mapping) else ()
    if (
        _state_has_sanctuary_reserve(state)
        or not isinstance(policy_ids, (list, tuple, set, frozenset))
    ):
        return False
    return any(
        _sanctuary_area_reset_recheck_spent_for_policy(state, str(policy_id))
        and _sanctuary_recovery_attempts_exhausted(
            state,
            policy_id=str(policy_id),
        )
        for policy_id in policy_ids
    )


def _defer_sanctuary_area_reset_recheck_before_login(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    error: str,
    command_count: int | None,
    segment_id: int | None,
) -> dict[str, Any]:
    """Keep a reset retry available when transport never entered the MUD."""
    if not (
        _sanctuary_area_reset_recheck_spent_for_policy(state, policy_id)
        and _is_pre_login_transport_failure(error, command_count=command_count)
    ):
        return dict(state)
    marker = state.get(_SANCTUARY_AREA_RESET_RECHECK_KEY)
    if not isinstance(marker, Mapping):
        return dict(state)
    updated = dict(state)
    deferred_marker = dict(marker)
    deferred_marker["dispatch_started"] = False
    deferred_marker["dispatch_deferred_for_transport"] = {
        "policy_id": policy_id,
        "segment_id": segment_id,
        "error": error,
        "command_count": command_count,
        "deferred_at": datetime.now(timezone.utc).isoformat(),
    }
    updated[_SANCTUARY_AREA_RESET_RECHECK_KEY] = deferred_marker
    return updated


def _consume_sanctuary_area_reset_recheck(
    state: dict[str, Any],
) -> bool:
    """Consume the reopened sanctuary attempt before opening the live worker."""
    if not _sanctuary_area_reset_recheck_dispatch_pending(state):
        return False
    marker = dict(state[_SANCTUARY_AREA_RESET_RECHECK_KEY])
    marker["dispatch_started"] = True
    marker["dispatch_started_at"] = datetime.now(timezone.utc).isoformat()
    marker.pop("dispatch_deferred_for_transport", None)
    state[_SANCTUARY_AREA_RESET_RECHECK_KEY] = marker
    state.pop("campaign_transport_unavailable", None)
    return True


def _sanctuary_area_reset_recheck_policy_ids(
    state: Mapping[str, Any],
    *,
    allow_unprotected_exhaustion: bool = False,
    allow_successful_reacquisition: bool = False,
) -> tuple[str, ...]:
    """Return exhausted sanctuary policies eligible for one area-reset retry."""
    if _state_has_sanctuary_reserve(state) or (
        not allow_unprotected_exhaustion
        and not _campaign_sanctuary_recovery_required(dict(state))
    ):
        return ()
    boot_id = state.get("world_boot_id")
    level = _level(state)
    results = _campaign_research_results(state)
    policy_ids: list[str] = []
    resource_policy_ids = set(_SANCTUARY_RESOURCE_POLICY_IDS)
    attempts = state.get(_SANCTUARY_RESOURCE_ATTEMPTS_KEY)
    if isinstance(attempts, Mapping):
        resource_policy_ids.update(
            str(policy_id)
            for policy_id in attempts
            if _is_source_ranked_sanctuary_maintenance_policy_id(policy_id)
        )
    for policy_id in sorted(resource_policy_ids):
        level_range = _SANCTUARY_RESOURCE_POLICY_LEVEL_RANGES.get(policy_id)
        if level_range is not None and not (
            level_range[0] <= level <= level_range[1]
        ):
            continue
        result = results.get(policy_id)
        if (
            allow_successful_reacquisition
            and isinstance(result, Mapping)
            and result.get("boot_id") == boot_id
            and result.get("level") in {None, level}
            and result.get("required_object_acquired") is True
            and _sanctuary_resource_attempt_count(
                state,
                policy_id,
                boot_id=boot_id,
                level=level,
            )
            > 0
        ):
            policy_ids.append(policy_id)
            continue
        if not (
            isinstance(result, Mapping)
            and result.get("boot_id") == boot_id
            and result.get("level") in {None, level}
            and result.get("fatal_failure") is True
            and result.get("route_hazard") == _SANCTUARY_RESOURCE_EXHAUSTED_HAZARD
            and result.get("required_object_acquired") is not True
            and result.get("completed_kill") is not True
            and _sanctuary_resource_attempt_count(
                state,
                policy_id,
                boot_id=boot_id,
                level=level,
            )
            >= _SANCTUARY_RESOURCE_MAX_ATTEMPTS
        ):
            continue
        policy_ids.append(policy_id)
    return tuple(policy_ids)


def _repair_sanctuary_area_reset_recheck_boundary(
    state: Mapping[str, Any],
    campaign_segments: Collection[Mapping[str, Any]],
    campaign_checkpoints: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Repair legacy reset markers that lost their segment boundary."""
    marker = state.get(_SANCTUARY_AREA_RESET_RECHECK_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("status") == "attempted"
        and marker.get("after_segment_id") is None
    ):
        return dict(state)
    marker_policy_ids = marker.get("policy_ids")
    attempts = state.get(_SANCTUARY_RESOURCE_ATTEMPTS_KEY) or {}
    if not isinstance(marker_policy_ids, (list, tuple, set, frozenset)) or not any(
        isinstance(attempts.get(str(policy_id)), Mapping)
        for policy_id in marker_policy_ids
    ):
        return dict(state)
    wait_times = [
        str(checkpoint.get("created_at") or "")
        for checkpoint in campaign_checkpoints
        if str(checkpoint.get("reason") or "")
        == _CAMPAIGN_RESEARCH_RESET_WAIT_REASON
        and checkpoint.get("created_at")
    ]
    if not wait_times:
        return dict(state)
    reset_completed_at = max(wait_times)
    prior_segment_ids: list[int] = []
    for segment in campaign_segments:
        finished_at = str(segment.get("finished_at") or "")
        if not finished_at or finished_at > reset_completed_at:
            continue
        try:
            prior_segment_ids.append(int(segment["id"]))
        except (KeyError, TypeError, ValueError):
            continue
    if not prior_segment_ids:
        return dict(state)
    repaired = dict(state)
    repaired_marker = {
        **dict(marker),
        "after_segment_id": max(prior_segment_ids),
    }
    repaired[_SANCTUARY_AREA_RESET_RECHECK_KEY] = repaired_marker
    policy_ids = tuple(
        str(policy_id)
        for policy_id in marker.get("policy_ids", ())
        if _is_sanctuary_resource_policy_id(str(policy_id))
    )
    attempts = dict(repaired.get(_SANCTUARY_RESOURCE_ATTEMPTS_KEY) or {})
    for policy_id in policy_ids:
        attempt = attempts.get(policy_id)
        if not isinstance(attempt, Mapping):
            continue
        repaired_attempt = dict(attempt)
        try:
            current_count = max(0, int(attempt.get("count") or 0))
        except (TypeError, ValueError):
            current_count = 0
        repaired_attempt.setdefault("prior_count", current_count)
        repaired_attempt.setdefault("area_reset_cycle", 1)
        repaired_attempt["count"] = 0
        attempts[policy_id] = repaired_attempt
    if attempts:
        repaired[_SANCTUARY_RESOURCE_ATTEMPTS_KEY] = attempts
    results = dict(_campaign_research_results(repaired))
    for policy_id in policy_ids:
        result = results.get(policy_id)
        if (
            isinstance(result, Mapping)
            and result.get("boot_id") == repaired.get("world_boot_id")
            and result.get("required_object_acquired") is not True
        ):
            results.pop(policy_id, None)
    if results:
        repaired["campaign_research_results"] = results
    else:
        repaired.pop("campaign_research_results", None)
    for cooldown_key in (
        _RESEARCH_ABSENCE_COOLDOWN_KEY,
        _RESEARCH_CROWD_COOLDOWN_KEY,
    ):
        cooldowns = dict(repaired.get(cooldown_key) or {})
        for policy_id in policy_ids:
            cooldowns.pop(policy_id, None)
        if cooldowns:
            repaired[cooldown_key] = cooldowns
        else:
            repaired.pop(cooldown_key, None)
    return repaired


def _sanctuary_reset_recheck_checkpoint_safe(state: Mapping[str, Any]) -> bool:
    """Require a living, quiet healer checkpoint before arming a reset wait."""
    raw_room_flags = state.get("room_flags")
    room_flags = (
        {str(flag).casefold() for flag in raw_room_flags}
        if isinstance(raw_room_flags, Collection)
        and not isinstance(raw_room_flags, (str, bytes))
        else set()
    )
    try:
        hp = int(state.get("hp") or 0)
    except (TypeError, ValueError):
        hp = 0
    return bool(
        str(state.get("room_vnum") or "") == "3054"
        and {"healing", "safe"}.issubset(room_flags)
        and state.get("dead") is not True
        and state.get("campaign_died_during_segment") is not True
        and state.get("in_combat") is not True
        and state.get("enemies") in (None, [])
        and not state.get("combat_target")
        and hp > 0
    )


def _repair_source_ranked_sanctuary_absence_attempt_ids(
    state: Mapping[str, Any],
    campaign_segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Backfill segment identities for older dynamic carrier absences."""
    boot_id = state.get("world_boot_id")
    if not boot_id:
        return dict(state)
    character_level = _level(dict(state))
    latest: dict[str, tuple[int, Mapping[str, Any]]] = {}
    for raw_segment in campaign_segments:
        try:
            segment = dict(raw_segment)
            segment_id = int(segment.get("id") or 0)
        except (TypeError, ValueError):
            continue
        if segment_id <= 0:
            continue
        policy_id = str(segment.get("phase") or "")
        if not _is_sanctuary_resource_policy_id(policy_id):
            continue
        raw_end_state = segment.get("end_state_json")
        if not raw_end_state:
            continue
        try:
            end_state = (
                json.loads(raw_end_state)
                if isinstance(raw_end_state, str)
                else raw_end_state
            )
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(end_state, Mapping):
            continue
        if (
            end_state.get("world_boot_id") != boot_id
            or _level(dict(end_state)) != character_level
        ):
            continue
        result = _campaign_research_results(end_state).get(policy_id)
        if not (
            isinstance(result, Mapping)
            and result.get("absent") is True
            and result.get("boot_id") == boot_id
        ):
            continue
        previous = latest.get(policy_id)
        if previous is None or segment_id > previous[0]:
            latest[policy_id] = (segment_id, end_state)
    current_results = _campaign_research_results(state)
    repaired_results = dict(current_results)
    changed = False
    for policy_id, result in current_results.items():
        if not _is_sanctuary_resource_policy_id(policy_id):
            continue
        if not (
            isinstance(result, Mapping)
            and result.get("absent") is True
            and result.get("boot_id") == boot_id
        ):
            continue
        history = latest.get(policy_id)
        if history is None:
            continue
        segment_id, end_state = history
        try:
            recorded_segment_id = int(result.get("last_attempt_segment_id"))
        except (TypeError, ValueError):
            recorded_segment_id = 0
        if recorded_segment_id >= segment_id:
            continue
        repaired_result = dict(result)
        repaired_result["last_attempt_segment_id"] = segment_id
        repaired_result.setdefault(
            _SOURCE_REVISION_KEY,
            end_state.get(_SOURCE_REVISION_KEY) or state.get(_SOURCE_REVISION_KEY),
        )
        repaired_results[policy_id] = repaired_result
        changed = True
    if not changed:
        return dict(state)
    repaired = dict(state)
    repaired["campaign_research_results"] = repaired_results
    return repaired


def _arm_sanctuary_resource_area_reset_recheck(
    state: Mapping[str, Any],
    *,
    allow_unprotected_exhaustion: bool = False,
    allow_successful_reacquisition: bool = False,
) -> dict[str, Any]:
    """Arm one reset retry for an exhausted, source-backed sanctuary route."""
    if not _sanctuary_reset_recheck_checkpoint_safe(state):
        return dict(state)
    policy_ids = _sanctuary_area_reset_recheck_policy_ids(
        state,
        allow_unprotected_exhaustion=allow_unprotected_exhaustion,
        allow_successful_reacquisition=allow_successful_reacquisition,
    )
    if not policy_ids or _sanctuary_area_reset_recheck_pending(state):
        return dict(state)
    existing = state.get(_SANCTUARY_AREA_RESET_RECHECK_KEY)
    superseded_policy_ids: tuple[str, ...] = ()
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == state.get("world_boot_id")
        and existing.get("level") == _level(state)
        and existing.get("status") == "attempted"
    ):
        # ``attempted`` is written when a route is reopened, before the live
        # worker starts.  A legacy marker can therefore survive without a
        # matching attempt record when its route is no longer selectable (for
        # example, a stale Ota'ar recall handoff).  Do not let that inert
        # marker suppress a fresh source-backed Sanctuary retry.  A marker
        # with either a dispatch receipt or a still-dispatchable attempt is
        # genuinely one-shot and remains authoritative.
        allow_rearm = bool(
            allow_successful_reacquisition
            and _sanctuary_area_reset_recheck_rearm_after_success_available(state)
        )
        if _sanctuary_area_reset_recheck_dispatch_pending(state):
            return dict(state)
        prior_policy_ids = existing.get("policy_ids")
        if not isinstance(
            prior_policy_ids,
            (list, tuple, set, frozenset),
        ):
            prior_policy_ids = ()
        prior_policy_ids = tuple(str(policy_id) for policy_id in prior_policy_ids)
        if existing.get("dispatch_started") is True and not allow_rearm:
            # A prior reset marker may have been consumed before this newer
            # dynamic carrier identity was discovered.  Give only the new
            # identities their first reset retry; never replay the spent set.
            new_policy_ids = tuple(
                policy_id
                for policy_id in policy_ids
                if policy_id not in set(prior_policy_ids)
            )
            if not new_policy_ids:
                return dict(state)
            policy_ids = new_policy_ids
            superseded_policy_ids = prior_policy_ids
    else:
        prior_policy_ids = ()
    prior_counts = {
        policy_id: _sanctuary_resource_attempt_count(
            state,
            policy_id,
            boot_id=state.get("world_boot_id"),
            level=_level(state),
        )
        for policy_id in policy_ids
    }
    armed = dict(state)
    armed[_SANCTUARY_AREA_RESET_RECHECK_KEY] = {
        "boot_id": state.get("world_boot_id"),
        "level": _level(state),
        "status": "pending",
        "policy_ids": list(policy_ids),
        "prior_attempt_counts": prior_counts,
        "reason": _SANCTUARY_AREA_RESET_RECHECK_REASON,
        **(
            {"rearm_after_successful_acquisition": True}
            if allow_successful_reacquisition
            else {}
        ),
        **(
            {
                "replaced_unstarted_policy_ids": [
                    str(policy_id) for policy_id in prior_policy_ids
                ],
                "replaced_unstarted_after_segment_id": existing.get(
                    "after_segment_id"
                ),
            }
            if (
                prior_policy_ids
                and isinstance(existing, Mapping)
                and existing.get("dispatch_started") is not True
            )
            else {}
        ),
        **(
            {
                "superseded_dispatch_policy_ids": list(superseded_policy_ids),
                "superseded_dispatch_after_segment_id": existing.get(
                    "after_segment_id"
                ),
            }
            if superseded_policy_ids and isinstance(existing, Mapping)
            else {}
        ),
    }
    return armed


def _reopen_sanctuary_resource_after_reset_wait(
    state: Mapping[str, Any],
    *,
    after_segment_id: int | None = None,
) -> dict[str, Any]:
    """Reopen one exhausted sanctuary route after the bounded reset wait."""
    if not _sanctuary_area_reset_recheck_pending(state):
        return dict(state)
    marker = dict(state[_SANCTUARY_AREA_RESET_RECHECK_KEY])
    policy_ids = tuple(
        str(policy_id)
        for policy_id in marker.get("policy_ids", ())
        if _is_sanctuary_resource_policy_id(str(policy_id))
    )
    if not policy_ids:
        return dict(state)
    reopened = dict(state)
    results = dict(_campaign_research_results(state))
    rearm_after_successful_acquisition = (
        marker.get("rearm_after_successful_acquisition") is True
    )
    for policy_id in policy_ids:
        result = results.get(policy_id)
        if (
            isinstance(result, Mapping)
            and result.get("boot_id") == state.get("world_boot_id")
            and (
                result.get("fatal_failure") is True
                or (
                    rearm_after_successful_acquisition
                    and result.get("required_object_acquired") is True
                )
            )
        ):
            results.pop(policy_id, None)
    # Keep the mapping present even when this reset consumed its last stale
    # receipt.  Callers may append a fresh, independent absence result during
    # the same preparation pass; an absent key would turn that ordinary state
    # update into a special case.
    reopened["campaign_research_results"] = results
    for cooldown_key in (
        _RESEARCH_ABSENCE_COOLDOWN_KEY,
        _RESEARCH_CROWD_COOLDOWN_KEY,
    ):
        cooldowns = dict(state.get(cooldown_key) or {})
        for policy_id in policy_ids:
            cooldowns.pop(policy_id, None)
        if cooldowns:
            reopened[cooldown_key] = cooldowns
        else:
            reopened.pop(cooldown_key, None)
    attempts = dict(state.get(_SANCTUARY_RESOURCE_ATTEMPTS_KEY) or {})
    for policy_id in policy_ids:
        attempt = attempts.get(policy_id)
        if not isinstance(attempt, Mapping):
            continue
        updated_attempt = dict(attempt)
        try:
            prior_count = max(0, int(attempt.get("count") or 0))
        except (TypeError, ValueError):
            prior_count = 0
        updated_attempt["prior_count"] = prior_count
        updated_attempt["count"] = 0
        updated_attempt["area_reset_cycle"] = (
            2 if rearm_after_successful_acquisition else 1
        )
        if after_segment_id is not None:
            updated_attempt["area_reset_after_segment_id"] = int(after_segment_id)
        attempts[policy_id] = updated_attempt
    if attempts:
        reopened[_SANCTUARY_RESOURCE_ATTEMPTS_KEY] = attempts
    reopened[_SANCTUARY_AREA_RESET_RECHECK_KEY] = {
        **marker,
        "status": "attempted",
        "after_segment_id": (
            int(after_segment_id) if after_segment_id is not None else None
        ),
    }
    cleared = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared.difference_update(policy_ids)
    if cleared:
        reopened[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        reopened.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    if state.get("campaign_last_policy") in policy_ids:
        reopened["campaign_last_policy"] = policy_ids[0]
    reopened.pop(_SOURCE_RANKED_RETRY_EXHAUSTED_KEY, None)
    reopened.pop(_SOURCE_RANKED_RETRY_EXHAUSTED_BOOT_KEY, None)
    reopened.pop(_SOURCE_RANKED_RETRY_EXHAUSTED_SEGMENT_KEY, None)
    for key in (
        "campaign_fastwalk_abort_reason",
        "campaign_fastwalk_target_absent",
        "campaign_fastwalk_target_present_observed",
        "campaign_fastwalk_crowded",
        "campaign_fastwalk_consider_outcomes",
        "campaign_fastwalk_required_object_vnums",
        "campaign_fastwalk_where_area_checks",
        "campaign_fastwalk_where_relocation_attempts",
        _SOURCE_RANKED_CANDIDATE_KEY,
        _SOURCE_CONSUMABLE_SPELL_KEY,
        _SOURCE_RESOURCE_RESERVES_KEY,
    ):
        reopened.pop(key, None)
    return reopened


def _magic_shop_see_invisible_failure_active(
    state: Mapping[str, Any],
) -> bool:
    if not state.get(_MAGIC_SHOP_SEE_INVISIBLE_FAILED_KEY):
        return False
    if _see_invisible_revalidation_pending(state):
        return False
    failed_boot = state.get(_MAGIC_SHOP_SEE_INVISIBLE_FAILED_BOOT_KEY)
    current_boot = state.get("world_boot_id")
    return failed_boot in {None, current_boot} or current_boot is None


def _source_capacity_blocked_policy_id(
    state: Mapping[str, Any],
    *,
    marker_key: str,
) -> str | None:
    """Return one exact route blocked by a verified full inventory."""
    marker = state.get(marker_key)
    if not isinstance(marker, Mapping) or marker.get("status") != "blocked":
        return None
    policy_id = str(marker.get("policy_id") or "").strip()
    if not policy_id:
        return None
    marker_boot = marker.get("boot_id")
    current_boot = state.get("world_boot_id")
    if marker_boot is not None and marker_boot != current_boot:
        return None
    marker_level = marker.get("level")
    current_level = state.get("level")
    if marker_level is not None and marker_level != current_level:
        return None
    marker_revision = marker.get("source_revision")
    current_revision = state.get(_SOURCE_REVISION_KEY)
    if marker_revision is not None and marker_revision != current_revision:
        return None
    stats = state.get("stats")
    if not isinstance(stats, Mapping):
        return None
    carry_count = stats.get("carry_num")
    maximum_count = stats.get("maxcarry_num")
    if type(carry_count) is not int or type(maximum_count) is not int:
        return None
    if carry_count < maximum_count:
        return None
    return policy_id


def _source_detect_hidden_capacity_blocked_policy_id(
    state: Mapping[str, Any],
) -> str | None:
    """Return the exact hidden-target route blocked by a full inventory."""
    return _source_capacity_blocked_policy_id(
        state, marker_key=_SOURCE_DETECT_HIDDEN_CAPACITY_BLOCKED_KEY,
    )


def _source_ranked_capacity_blocked_policy_id(
    state: Mapping[str, Any],
) -> str | None:
    """Return the exact XP route blocked by its safe capacity preflight."""
    return _source_capacity_blocked_policy_id(
        state, marker_key=_SOURCE_RANKED_CAPACITY_BLOCKED_KEY,
    )


def _source_ranked_visibility_preparation_policy(
    selected: ProgressionPolicy,
    candidate: HuntCandidate | None,
    state: Mapping[str, Any],
    *,
    character_level: int,
    can_prepare: bool,
    source_world: WorldSource | None = None,
) -> ProgressionPolicy | None:
    if getattr(candidate, "status", None) == "reject":
        # Rejected candidates are source-research observations, not executable
        # hunts. Their visibility metadata must not turn an optional shop
        # purchase into a progression-blocking funding policy.
        return None
    if (
        selected.execution == "source-ranked-hunt"
        and candidate is not None
        and source_world is not None
    ):
        raw_max_hp = state.get("max_hp")
        character_max_hp = (
            int(raw_max_hp)
            if isinstance(raw_max_hp, (int, float))
            and not isinstance(raw_max_hp, bool)
            and raw_max_hp > 0
            else None
        )
        if _source_ranked_plain_sentinel_risk_revalidation_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=source_world,
            allow_dispatched_marker=True,
        ):
            # This exact receipt deliberately tests the target without the
            # generic see-invisible preparation step; live identity,
            # consider, combat, and health-floor checks remain authoritative.
            return None
    retry_pending = _see_invisible_revalidation_pending(state)
    if _magic_shop_see_invisible_failure_active(state) and not retry_pending:
        # A failed optional visibility purchase is useful evidence for the
        # hidden route, but it must not turn that route into a funding loop.
        # Let the ordinary selector rotate to a visible target instead.
        return None
    if (
        selected.execution != "source-ranked-hunt"
        or candidate is None
        or not candidate.requires_detect_invisibility
        or not can_prepare
        or _state_has_active_affect(state.get("affects"), "detect invis")
        or state.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY)
    ):
        return None
    if not retry_pending and not _state_has_active_affect(
        state.get("affects"), "detect invis"
    ):
        price = _see_invisible_purchase_price(state)
        if (
            isinstance(state, dict)
            and price is not None
            and _state_copper_value(state) < price
        ):
            state[_SEE_INVISIBLE_FUNDING_REQUIRED_KEY] = True
            return replace(
                _PROVISION_FUNDING_POLICY,
                minimum_level=character_level,
                maximum_level=character_level,
                summary=(
                    "Fund the current-reboot see-invisible quote before "
                    "reopening the audited non-psionic target; protected "
                    "visibility preparation remains mandatory."
                ),
            )
    if retry_pending and isinstance(state, dict):
        marker = state.get(_MAGIC_SHOP_SEE_INVISIBLE_RETRY_KEY)
        if isinstance(marker, Mapping):
            state[_MAGIC_SHOP_SEE_INVISIBLE_RETRY_KEY] = {
                **dict(marker),
                "status": "attempted",
                "consumed_before_dispatch": True,
            }
    return replace(
        _BUY_SEE_INVISIBLE_POLICY,
        minimum_level=character_level,
        maximum_level=character_level,
    )


def _source_ranked_candidate_has_absence_cooldown(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Defer absent resets and contradictory live population layouts."""
    if (
        getattr(candidate, "requires_detect_invisibility", False)
        and not _state_has_active_affect(state.get("affects"), "detect invis")
        and (
            _magic_shop_see_invisible_failure_active(state)
            or state.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY)
        )
    ):
        return True
    if population_locator_mismatch_blocks(state, candidate, character_level=character_level):
        return True
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if _source_locator_revalidation_pending(state, policy_id):
        return False
    results = _campaign_research_results(state)
    result = results.get(policy_id)
    if not isinstance(result, Mapping):
        return False
    if result.get("boot_id") != state.get("world_boot_id"):
        return False
    if result.get("absent") is not True:
        return False
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    try:
        return int(cooldowns.get(policy_id) or 0) > 0
    except (AttributeError, TypeError, ValueError):
        return False


def _source_ranked_aggressive_target_below_useful_floor(
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    """Reject aggressive targets whose source load is below the XP floor.

    A fuzzy source range can straddle the useful boundary.  That is a live
    ``consider`` probe, not a reason to discard the target before travelling.
    Aggressive entry is different: a below-floor mobile can start combat
    before that probe is possible, so the nominal source level is also a hard
    pre-travel bound.
    """
    target_is_aggressive = (
        "target is aggressive" in candidate.autonomy_rejections
        or "target is aggressive" in candidate.hazards
    )
    return bool(
        target_is_aggressive
        and (
            candidate.level <= character_level - 5
            or candidate.estimated_level_range[1] <= character_level - 5
        )
    )


def _source_ranked_bounded_route_program_capacity_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Recognize a capacity probe behind one audited low-level locator."""
    return bool(
        source_world is not None
        and not candidate.specials
        and not candidate.equipped_weapons
        and not candidate.route_hard_hazard_targets
        and (
            not candidate.route_special_mobile_vnums
            or candidate.route_economic_hunt_mobile_vnums
            and _source_ranked_route_specials_noncombat_only(candidate, source_world)
        )
        and candidate.route_attack_program_mobile_vnums
        and _source_ranked_route_program_preflight_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
        )
        and _source_ranked_route_program_aggressors_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
        )
    )


def _source_ranked_capacity_research_candidate(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None = None,
    allow_bounded_route_program: bool = False,
) -> bool:
    """Allow bounded live isolation research for a clean crowded reset.

    A source reset can place more than one same-prototype mobile in a room,
    which may make the mobiles assist each other before the client can issue
    ``consider``.  Keep research narrow: no more than two source reset
    entries, a global prototype limit of four, and no other source rejection.
    DD4 db.c compares each M reset with pMobIndex->count; reset entries do not
    multiply that global population. Once exact live isolation and the live
    consider gate pass, the bounded stop may fight
    for useful XP while retaining research status until another reboot proves
    the reset behavior.
    """
    if _source_ranked_aggressive_target_below_useful_floor(
        candidate,
        character_level=character_level,
    ):
        # Older checkpoints may contain the capacity-only shape without the
        # newer autonomy rejection. Reapply the source gate before allowing a
        # persisted or freshly ranked capacity probe.
        return False
    route_capacity_allowed = bool(
        allow_bounded_route_program
        or (
            not candidate.route_preflight_hard_hazard
            and not candidate.route_hard_hazard_targets
            and not candidate.route_attack_program_mobile_vnums
            and not candidate.route_special_mobile_vnums
            and (
                not candidate.route_aggressive_mobile_vnums
                or (
                    source_world is not None
                    and _source_ranked_route_aggressors_are_bounded(
                        candidate,
                        character_level=character_level,
                        source_world=source_world,
                    )
                )
            )
        )
    )
    capacity_only = (
        candidate.autonomy_rejections == ("target reset capacity exceeds one",)
        and type(candidate.source_spawn_limit) is int
        and type(candidate.room_spawn_count) is int
        and (
            2 <= candidate.source_spawn_limit
            <= _SOURCE_CAPACITY_RESEARCH_MAX_GLOBAL_POPULATION
        )
        and (
            1 <= candidate.room_spawn_count
            <= _SOURCE_CAPACITY_RESEARCH_MAX_RESET_ENTRIES
        )
        and route_capacity_allowed
    )
    # The current source ranker represents a small passive population with a
    # clean caution record rather than the older explicit capacity rejection.
    # ``plain_bounded_population`` audits every reset, room, object, special,
    # and global population limit; only that exact shape may use this research
    # path. It remains research, never ordinary multi-target permission.
    source_ranked_plain_population = bool(
        source_world is not None
        and route_capacity_allowed
        and plain_bounded_population(candidate, source_world)
    )
    return bool(
        (
            candidate.status == "reject"
            and not candidate.specials
            and candidate.autonomy_rejections
            and (
                capacity_only
                or all(
                    _SOURCE_CAPACITY_RESEARCH_RE.fullmatch(reason)
                    for reason in candidate.autonomy_rejections
                )
            )
        )
        or source_ranked_plain_population
    )


def _source_ranked_capacity_history_plain_progression_candidate(
    candidate: HuntCandidate,
    *,
    source_world: WorldSource | None = None,
) -> bool:
    """Keep a fresh plain-population reset eligible after capacity research.

    A prior capacity-only probe quarantines the mobile prototype so the
    selector does not repeat the same research on every reset. It must not
    hide a distinct, source-audited passive and unarmed reset that can be
    evaluated as an ordinary progression candidate. The normal live
    isolation, ``consider``, output, health, and recovery gates still run
    after this source-only exception.
    """
    return bool(
        source_world is not None
        and candidate.status in {"caution", "promising"}
        and not candidate.autonomy_rejections
        and plain_bounded_population(candidate, source_world)
    )


def _source_ranked_capacity_observation_candidate(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None = None,
    allow_bounded_route_program: bool = False,
) -> bool:
    """Keep a reset-aged capacity probe out of rooms that can start combat."""
    if not _source_ranked_capacity_research_candidate(
        candidate,
        character_level=character_level,
        source_world=source_world,
        allow_bounded_route_program=allow_bounded_route_program,
    ):
        return False
    hazards = {
        str(hazard).casefold().strip()
        for hazard in candidate.hazards
    }
    return bool(
        not candidate.equipped_weapons
        and "target is aggressive" not in hazards
        and not candidate.route_hard_hazard_targets
        and not candidate.route_aggressive_mobile_vnums
        and not candidate.route_attack_program_mobile_vnums
        and not candidate.route_special_mobile_vnums
    )


def _source_ranked_wandering_capacity_execution_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Allow an isolated live fight for a bounded wandering reset.

    Capacity research must not turn every multi-reset wanderer into a
    permanent no-combat probe.  A target whose exact source reset holds one
    unarmed, unscripted mobile can be handled by the normal live locator,
    room-isolation, and ``consider`` gates.  Other reset rooms remain subject
    to the ordinary crowd check when the mobile is actually found there.
    """
    if source_world is None:
        return False
    if (
        candidate.status != "reject"
        or candidate.autonomy_rejections
        != ("target reset capacity exceeds one",)
        or candidate.specials
        or candidate.equipped_weapons
        or candidate.source_spawn_limit != 2
        or candidate.room_spawn_count != 1
        or not candidate.level - 5 <= character_level <= candidate.level + 5
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
    ):
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        mobile is None
        or not mobile.wanders
        or mobile.sentinel
        or mobile.stay_area
        or mobile.aggressive
        or mobile.programs
        or source_world.mobile_specials.get(mobile.vnum)
        or mobile.non_corporeal
        or mobile.fear_aura
        or mobile.confused
    ):
        return False
    resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
    )
    target_resets = tuple(
        reset for reset in resets if reset.room_vnum == candidate.room_vnum
    )
    return bool(
        len(resets) >= 2
        and len({reset.room_vnum for reset in resets}) == len(resets)
        and len(target_resets) == 1
        and target_resets[0].maximum_count == 1
    )


def _source_ranked_capacity_research_in_current_band(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
    allow_repeated_kills: bool = False,
    allow_bounded_route_program: bool = False,
) -> bool:
    """Apply ordinary level, movement, and reboot gates to a research reset."""
    if not _source_ranked_capacity_research_candidate(
        candidate,
        character_level=character_level,
        source_world=source_world,
        allow_bounded_route_program=allow_bounded_route_program,
    ):
        return False
    bounded_plain_fuzz = bool(
        source_world is not None
        and plain_bounded_population(candidate, source_world)
        and candidate.level <= character_level
        and candidate.estimated_level_range[1] <= character_level + 2
        and _source_ranked_post_loss_plain_probe_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    )
    return not (
        (candidate.boot_kills >= 3 and not allow_repeated_kills)
        or candidate.estimated_level_range[1] <= character_level - 5
        or candidate.estimated_level_range[1]
        > character_level + (2 if bounded_plain_fuzz else 1)
        or not _source_candidate_fits_movement(candidate, state)
        or _funding_candidate_is_below_band(
            dict(state),
            candidate,
            character_level=character_level,
            boot_id=state.get("world_boot_id"),
        )
    )


def _source_ranked_ground_fallback_in_current_band(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    world: WorldSource | None,
    character_level: int,
    allow_repeated_kills: bool = False,
) -> bool:
    """Retain the selector's bounded capacity admission at the funding handoff."""
    # This is a production XP/funding fallback, not a deliberate source-fuzz
    # probe.  Do not let a nominally more-than-five-level-below mobile through
    # merely because its estimated reset range reaches the useful band; the
    # explicit probe paths retain that scouting permission and live ``consider``
    # remains the final authority before combat. A target exactly five levels
    # below the pilot is still inside DD4's useful boundary.
    if candidate.level < character_level - 5:
        return False
    relative_level_target = bool(
        world is not None
        and _source_ranked_relative_level_target_admission_allowed(
            candidate,
            character_level=character_level,
            source_world=world,
            allow_detect_invisibility=_state_has_active_affect(
                state.get("affects"), "detect invis"
            ),
        )
    )
    return _source_ranked_candidate_in_current_band(
        candidate,
        state,
        world=world,
        character_level=character_level,
        allow_repeated_kills=allow_repeated_kills,
        allow_relative_level_target=relative_level_target,
    ) or _source_ranked_capacity_research_in_current_band(
        candidate,
        state,
        character_level=character_level,
        source_world=world,
        allow_bounded_route_program=(
            _source_ranked_bounded_route_program_capacity_allowed(
                candidate,
                character_level=character_level,
                source_world=world,
            )
        ),
    )


def _source_ranked_ground_fallback_candidates(
    candidates: Collection[HuntCandidate],
    state: Mapping[str, Any],
    *,
    world: WorldSource | None,
    character_level: int,
    allow_repeated_policy_ids: Collection[str] = (),
) -> tuple[HuntCandidate, ...]:
    """Keep admitted current-band ground targets, including proven repeats."""
    repeatable_policy_ids = frozenset(
        str(policy_id) for policy_id in allow_repeated_policy_ids
    )
    return tuple(
        candidate
        for candidate in candidates
        if not candidate.requires_flight
        and _source_ranked_ground_fallback_in_current_band(
            candidate,
            state,
            world=world,
            character_level=character_level,
            allow_repeated_kills=(
                _source_ranked_policy_id(
                    candidate,
                    character_level=character_level,
                )
                in repeatable_policy_ids
            ),
        )
    )


_SOURCE_PEAK_DAMAGE_REJECTION = "source peak round can exceed character HP"
_SOURCE_BOUNDED_PEAK_SPECIALS = frozenset({"spec_thief"})
_SOURCE_DYNAMIC_WANDERER_REJECTION = (
    "an aggressive wanderer inside the useful XP band can reach the route"
)
_SOURCE_FAMILIAR_TRANSIT_RISK_REJECTION = (
    "an aggressive wanderer inside the transit-risk band can reach the route"
)
_SOURCE_FAMILIAR_EDGE_BAND_WANDER_REJECTION = (
    "below-band wandering aggressor is not an XP target"
)
_SOURCE_DYNAMIC_WANDERER_HAZARD_PREFIXES = (
    "room companion:",
    "source-backed trivial companion:",
    "source-backed noncombat route special:",
    "reachable wanderer:",
)
_SOURCE_RANKED_SAFE_RETURN_RUNTIME_HAZARD = (
    "segment runtime boundary requested a safe healer return"
)


def _source_ranked_bounded_peak_probe_allowed(
    candidate: HuntCandidate,
    *,
    state: Mapping[str, Any],
    character_max_hp: int | None,
    allow_cooldown_retry: bool,
) -> bool:
    """Allow one bounded source-policy retry without a target-HP gate."""
    if not allow_cooldown_retry:
        return False
    if candidate.is_coin_stash:
        return False
    del character_max_hp
    rejections = set(candidate.autonomy_rejections)
    if _SOURCE_PEAK_DAMAGE_REJECTION not in rejections:
        return False
    remaining_rejections = rejections - {_SOURCE_PEAK_DAMAGE_REJECTION}
    specials = frozenset(candidate.specials)
    if remaining_rejections:
        if remaining_rejections != {
            "target has special procedure spec_thief"
        } or specials != _SOURCE_BOUNDED_PEAK_SPECIALS:
            return False
        carried_coins = _state_copper_value(dict(state))
        if carried_coins * 20 // 100 > _SPEC_THIEF_MAX_EXPOSURE_COINS:
            return False
    elif specials:
        return False

    # The former minimum source peak comparison was a target-output/HP
    # admission gate. Keep the source hazard and purse checks above; live
    # consider and the player's own combat floor decide the encounter.
    return True


def _source_ranked_bounded_peak_probe_in_current_band(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    allow_cooldown_retry: bool,
    allow_repeated_kills: bool = False,
) -> bool:
    """Apply ordinary level, movement, and reboot gates to a peak probe."""
    if not _source_ranked_bounded_peak_probe_allowed(
        candidate,
        state=state,
        character_max_hp=character_max_hp,
        allow_cooldown_retry=allow_cooldown_retry,
    ):
        return False
    return not (
        (candidate.boot_kills >= 3 and not allow_repeated_kills)
        or candidate.estimated_level_range[1] <= character_level - 5
        or candidate.estimated_level_range[1] > character_level + 1
        or not _source_candidate_fits_movement(candidate, state)
        or _funding_candidate_is_below_band(
            dict(state),
            candidate,
            character_level=character_level,
            boot_id=state.get("world_boot_id"),
        )
    )


def _source_ranked_dynamic_wanderer_probe_allowed(
    candidate: HuntCandidate,
    *,
    character_level: int,
    character_max_hp: int | None,
    allow_cooldown_retry: bool,
) -> bool:
    """Allow one bounded probe when only a reachable useful-band wanderer blocks it."""
    if not allow_cooldown_retry:
        return False
    del character_max_hp
    if (
        candidate.is_coin_stash
        or candidate.status == "reject"
        or candidate.specials
        or set(candidate.autonomy_rejections)
        != {_SOURCE_DYNAMIC_WANDERER_REJECTION}
    ):
        return False
    minimum_level, maximum_level = candidate.estimated_level_range
    if minimum_level <= character_level - 5 or maximum_level > character_level + 1:
        return False
    if candidate.route_preflight_hard_hazard or candidate.route_hard_hazard_targets:
        return False
    return all(
        hazard.startswith(_SOURCE_DYNAMIC_WANDERER_HAZARD_PREFIXES)
        for hazard in candidate.hazards
    )


def _source_ranked_dynamic_wanderer_repeatability_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
) -> bool:
    """Allow one post-kill repeatability probe for a dynamic-wanderer route."""
    if not _source_ranked_dynamic_wanderer_probe_allowed(
        candidate,
        character_level=character_level,
        character_max_hp=character_max_hp,
        allow_cooldown_retry=True,
    ):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("viable") is True
        and result.get("completed_kill") is True
        and not result.get("crowded")
        and not result.get("low_reward")
    ):
        return False
    marker = state.get(_SOURCE_DYNAMIC_WANDERER_REPEATABILITY_KEY)
    return not (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("policy_id") == policy_id
    )


def _record_source_ranked_dynamic_wanderer_repeatability(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> None:
    """Persist the one repeatability attempt before its live segment starts."""
    raw_max_hp = state.get("max_hp")
    character_max_hp = (
        int(raw_max_hp)
        if isinstance(raw_max_hp, (int, float)) and raw_max_hp > 0
        else None
    )
    if not _source_ranked_dynamic_wanderer_repeatability_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
    ):
        return
    state[_SOURCE_DYNAMIC_WANDERER_REPEATABILITY_KEY] = {
        "boot_id": state.get("world_boot_id"),
        "level": character_level,
        "policy_id": _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        ),
    }


def _source_ranked_protected_peak_probe_allowed(
    candidate: HuntCandidate,
    *,
    state: Mapping[str, Any],
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None = None,
) -> bool:
    """Allow one legacy Sanctuary retry without comparing target HP/output."""
    del character_max_hp
    if source_world is None:
        return False
    if not _state_has_sanctuary_reserve(state):
        return False
    if (
        candidate.is_coin_stash
        or candidate.specials
        or len(candidate.equipped_weapons) > 1
        or candidate.route_hard_hazard_targets
    ):
        return False
    if set(candidate.autonomy_rejections) != {
        _SOURCE_PEAK_DAMAGE_REJECTION
    }:
        return False
    if candidate.route_preflight_hard_hazard:
        if not _source_ranked_route_program_candidate_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
            allow_sanctuary_protected_target=True,
        ):
            return False
    elif candidate.route_attack_program_mobile_vnums:
        # An unverified program attacker can engage before the protected
        # opener and cannot use this ordinary peak-probe contract.
        return False
    if candidate.estimated_level_range[0] <= character_level - 5:
        return False
    # Match the existing one-fuzz-step source-level policy. Sanctuary remains
    # a source-hazard prerequisite; it does not turn target HP into a gate.
    if candidate.estimated_level_range[1] > character_level + 2:
        return False
    return True


def _source_ranked_protected_peak_output_fits(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Require one executable action, never a target-HP/output comparison."""
    return _source_ranked_caster_output_can_cover(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
        allow_armed_defense_probe=bool(candidate.equipped_weapons),
    )


def _source_ranked_protected_peak_revalidation_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Allow one retry of an old live ceiling result after peak gating changed."""
    if source_world is None or candidate.status != "reject":
        return False
    if len(candidate.equipped_weapons) != 1 or candidate.specials:
        return False
    if set(candidate.autonomy_rejections) != {
        _SOURCE_PEAK_DAMAGE_REJECTION
    }:
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("observed") is True
        and result.get("consider_viable") is True
        and result.get("completed_kill") is False
        and result.get("viable") is False
        and result.get("retryable_failure") is True
        and not any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "route_hazard",
                "unattackable",
                "target_vnum_mismatch",
                "low_reward",
            )
        )
    ):
        return False
    candidate_source_revision = getattr(candidate, "source_revision", None)
    if candidate_source_revision and state.get(_SOURCE_REVISION_KEY):
        if candidate_source_revision != state.get(_SOURCE_REVISION_KEY):
            return False
    marker = state.get(_SOURCE_RANKED_PROTECTED_PEAK_REVALIDATION_KEY)
    if (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
        and marker.get("policy_id") == policy_id
        and marker.get("status") in {"attempted", "closed", "succeeded"}
    ):
        return False
    return (
        _source_ranked_protected_peak_probe_in_current_band(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=source_world,
        )
        and _source_ranked_protected_peak_output_fits(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    )


def _source_ranked_protected_armed_opener_revalidation_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Allow one correction for the protected armed target opener gap."""
    if source_world is None:
        return False
    old_marker = state.get(_SOURCE_RANKED_PROTECTED_PEAK_REVALIDATION_KEY)
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if not (
        isinstance(old_marker, Mapping)
        and old_marker.get("boot_id") == state.get("world_boot_id")
        and old_marker.get("level") in {None, character_level}
        and old_marker.get("policy_id") == policy_id
        and old_marker.get("mobile_vnum") == candidate.mobile_vnum
        and old_marker.get("room_vnum") == candidate.room_vnum
        and old_marker.get("status") == "closed"
        and old_marker.get("outcome") == "no_kill"
    ):
        return False
    marker_source_revision = old_marker.get("source_revision")
    if (
        marker_source_revision
        and state.get(_SOURCE_REVISION_KEY)
        and marker_source_revision != state.get(_SOURCE_REVISION_KEY)
    ):
        return False
    abort_reason = str(state.get("campaign_fastwalk_abort_reason") or "")
    opener_gap = old_marker.get("opener_gap")
    legacy_marker = (
        "opener_gap" not in old_marker
        and (
            not old_marker.get("reason")
            or str(old_marker.get("reason")).startswith(
                "one source-validated retry after sanctuary-protected peak"
            )
        )
    )
    if opener_gap is False or (
        opener_gap is not True
        and not legacy_marker
        and "no authoritative live HP before sanctuary or opener dispatch"
        not in abort_reason
    ):
        return False
    retry_state = dict(state)
    retry_state.pop(_SOURCE_RANKED_PROTECTED_PEAK_REVALIDATION_KEY, None)
    return _source_ranked_protected_peak_revalidation_allowed(
        candidate,
        retry_state,
        character_level=character_level,
        character_max_hp=character_max_hp,
        source_world=source_world,
    )


