def _source_ranked_multi_random_route_revalidation_candidate_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Admit only the stale Giant Clam route whose planner was repaired."""
    if source_world is None:
        return False
    if (
        _source_ranked_multi_random_route_revalidation_result(
            state,
            candidate,
            character_level=character_level,
        )
        is None
        or candidate.area_file.casefold() != "pirates_isles.are"
        or candidate.route_origin_room_vnum != RECALL_VNUM
    ):
        return False
    source_shape_state = dict(state)
    source_results = dict(_campaign_research_results(state))
    source_results.pop(
        _source_ranked_policy_id(candidate, character_level=character_level),
        None,
    )
    source_shape_state["campaign_research_results"] = source_results
    if not _source_ranked_giant_clam_route_risk_allowed(
        candidate,
        character_level=character_level,
        source_world=source_world,
        state=source_shape_state,
    ):
        return False
    try:
        route_rooms = _source_route_room_vnums(
            source_world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
    except (TypeError, ValueError):
        return False
    if not route_rooms or route_rooms[-1] != candidate.room_vnum:
        return False
    random_area_files = {
        str(source_world.rooms[room_vnum].area_file).casefold()
        for room_vnum in route_rooms
        if room_vnum in source_world.rooms
        and source_world.rooms[room_vnum].random_exits
    }
    if len(random_area_files) < 2:
        return False
    navigation = _source_ranked_route_live_navigation(
        source_world,
        candidate,
        character_level=character_level,
        extend_to_route_end=True,
    )
    return navigation.get("live_navigation_target") == str(candidate.room_vnum)


def _source_ranked_multi_random_route_revalidation_pending(
    state: Mapping[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    """Return whether the exact one-shot route repair is ready to dispatch."""
    marker = state.get(_SOURCE_RANKED_MULTI_RANDOM_ROUTE_REVALIDATION_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("revision")
        == _SOURCE_RANKED_MULTI_RANDOM_ROUTE_REVALIDATION_REVISION
        and marker.get("policy_id")
        == _source_ranked_policy_id(candidate, character_level=character_level)
        and marker.get("status") == "pending"
        and _source_ranked_multi_random_route_revalidation_result(
            state,
            candidate,
            character_level=character_level,
        )
        is not None
    )


def _source_ranked_light_route_revalidation_pending(
    state: Mapping[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    """Return whether the exact darkness-only route retry is pending."""
    marker = state.get(_SOURCE_RANKED_LIGHT_ROUTE_REVALIDATION_KEY)
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    return bool(
        isinstance(marker, Mapping)
        and marker.get("status") == "pending"
        and marker.get("revision")
        == _SOURCE_RANKED_LIGHT_ROUTE_REVALIDATION_REVISION
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("policy_id") == policy_id
        and isinstance(marker.get("prior_result"), Mapping)
        and " ".join(
            str(marker["prior_result"].get("route_hazard") or "")
            .casefold()
            .split()
        )
        == " ".join(_SOURCE_RANKED_LIGHT_ROUTE_ABORT_REASON.casefold().split())
    )


def _mark_source_ranked_light_route_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    """Consume the darkness repair immediately before its live dispatch."""
    if not _source_ranked_light_route_revalidation_pending(
        state,
        candidate,
        character_level=character_level,
    ):
        return False
    marker = state[_SOURCE_RANKED_LIGHT_ROUTE_REVALIDATION_KEY]
    assert isinstance(marker, Mapping)
    state[_SOURCE_RANKED_LIGHT_ROUTE_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
        "attempted_before_dispatch": True,
        "attempted_at": datetime.now(timezone.utc).isoformat(),
    }
    return True


def _arm_source_ranked_multi_random_route_revalidation(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> dict[str, Any]:
    """Persist one repair for the old multi-random route controller miss."""
    boot_id = state.get("world_boot_id")
    if boot_id is None or source_world is None:
        return state
    existing = state.get(_SOURCE_RANKED_MULTI_RANDOM_ROUTE_REVALIDATION_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
        and existing.get("level") in {None, character_level}
        and existing.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and existing.get("revision")
        == _SOURCE_RANKED_MULTI_RANDOM_ROUTE_REVALIDATION_REVISION
        and existing.get("status") in {"pending", "attempted", "closed", "succeeded"}
    ):
        return state
    eligible = [
        candidate
        for candidate in candidates
        if _source_ranked_multi_random_route_revalidation_candidate_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    ]
    if not eligible:
        return state
    candidate = max(
        eligible,
        key=lambda item: (
            float(item.score),
            item.estimated_level_range[1],
            -len(item.route),
        ),
    )
    result = _source_ranked_multi_random_route_revalidation_result(
        state,
        candidate,
        character_level=character_level,
    )
    if result is None:
        return state
    navigation = _source_ranked_route_live_navigation(
        source_world,
        candidate,
        character_level=character_level,
        extend_to_route_end=True,
    )
    random_area_files = sorted(
        {
            str(source_world.rooms[room_vnum].area_file).casefold()
            for room_vnum in _source_route_room_vnums(
                source_world,
                candidate.route_origin_room_vnum,
                candidate.route,
            )
            if room_vnum in source_world.rooms
            and source_world.rooms[room_vnum].random_exits
        }
    )
    state[_SOURCE_RANKED_MULTI_RANDOM_ROUTE_REVALIDATION_KEY] = {
        "boot_id": boot_id,
        "level": character_level,
        "policy_id": _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        ),
        "source_revision": state.get(_SOURCE_REVISION_KEY),
        "source_mobile_vnum": candidate.mobile_vnum,
        "source_room_vnum": candidate.room_vnum,
        "prior_result": dict(result),
        "route_controller_revision": _SOURCE_RANKED_MULTI_RANDOM_ROUTE_REVALIDATION_REVISION,
        "random_area_files": random_area_files,
        "live_navigation_target": navigation.get("live_navigation_target"),
        "status": "pending",
        "reason": (
            "one exact retry after the route planner was corrected to span "
            "multiple reboot-randomized sections"
        ),
        "revision": _SOURCE_RANKED_MULTI_RANDOM_ROUTE_REVALIDATION_REVISION,
    }
    return state


def _mark_source_ranked_multi_random_route_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    """Consume the route-controller repair immediately before dispatch."""
    if not _source_ranked_multi_random_route_revalidation_pending(
        state,
        candidate,
        character_level=character_level,
    ):
        return False
    marker = state[_SOURCE_RANKED_MULTI_RANDOM_ROUTE_REVALIDATION_KEY]
    state[_SOURCE_RANKED_MULTI_RANDOM_ROUTE_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
        "attempted_before_dispatch": True,
        "target_dispatch_started": True,
    }
    return True


def _source_ranked_endpoint_revalidation_result(
    state: Mapping[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> Mapping[str, Any] | None:
    """Return one exact, no-combat endpoint-observation failure."""
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    if not isinstance(result, Mapping):
        return None
    hazard = " ".join(str(result.get("route_hazard") or "").casefold().split())
    if (
        result.get("boot_id") != state.get("world_boot_id")
        or result.get("observed") is not False
        or result.get("viable") is not False
        or not hazard.startswith(_SOURCE_RANKED_ENDPOINT_NOT_OBSERVED_PREFIX)
        or any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "crowd_exhausted",
                "unattackable",
                "target_vnum_mismatch",
                "consider_viable",
                "completed_kill",
                "xp_loss_observed",
            )
        )
    ):
        return None
    return result


def _source_ranked_endpoint_revalidation_attempted(
    state: Mapping[str, Any],
    *,
    policy_id: str,
) -> bool:
    """Return whether the exact endpoint retry has already been consumed."""
    marker = state.get(_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, _level(state)}
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("policy_id") == policy_id
        and marker.get("status") in {"attempted", "closed", "succeeded"}
    )


def _source_ranked_endpoint_revalidation_pending(
    state: Mapping[str, Any],
    *,
    policy_id: str,
) -> bool:
    """Return whether one exact endpoint retry is ready for dispatch."""
    marker = state.get(_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, _level(state)}
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("policy_id") == policy_id
        and marker.get("status") == "pending"
    )


def _source_ranked_endpoint_revalidation_candidate_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Admit one plain source route whose endpoint was not observed."""
    if source_world is None:
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if (
        candidate.status == "reject"
        or not candidate.autonomous_safe
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or candidate.specials
        or candidate.equipped_weapons
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or not (
            1
            <= candidate.source_spawn_limit
            <= _SOURCE_CAPACITY_RESEARCH_MAX_GLOBAL_POPULATION
        )
        or candidate.room_spawn_count != 1
        or _source_ranked_xp_loss_record(state, policy_id) is not None
        or _source_ranked_endpoint_revalidation_result(
            state,
            candidate,
            character_level=character_level,
        ) is None
        or not _source_ranked_candidate_in_current_band(
            candidate,
            state,
            world=source_world,
            character_level=character_level,
            allow_repeated_kills=True,
        )
    ):
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    room = source_world.rooms.get(candidate.room_vnum)
    if (
        mobile is None
        or room is None
        or mobile.aggressive
        or mobile.programs
        or source_world.mobile_specials.get(candidate.mobile_vnum)
    ):
        return False
    return True


def _source_ranked_endpoint_frontier_is_closed(
    candidates: Collection[HuntCandidate],
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource,
) -> bool:
    """Avoid pre-empting a normal current-band route with route repair."""
    for candidate in candidates:
        if (
            not candidate.autonomous_safe
            or candidate.specials
            or candidate.equipped_weapons
            or candidate.source_spawn_limit != 1
            or candidate.room_spawn_count != 1
            or candidate.route_preflight_hard_hazard
            or candidate.route_hard_hazard_targets
        ):
            continue
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        if _source_ranked_endpoint_revalidation_result(
            state,
            candidate,
            character_level=character_level,
        ) is not None:
            continue
        if _source_ranked_xp_loss_record(state, policy_id) is not None:
            continue
        if not _source_ranked_candidate_in_current_band(
            candidate,
            state,
            world=source_world,
            character_level=character_level,
            allow_repeated_kills=True,
        ):
            continue
        if (
            _source_ranked_candidate_requires_sanctuary_for_state(
                candidate,
                state,
                character_level=character_level,
                source_world=source_world,
            )
            and not _state_has_sanctuary_reserve(state)
        ):
            continue
        status = _source_ranked_result_status(
            candidate,
            state,
            character_level=character_level,
        )
        if (
            status == "fresh"
            and _source_ranked_useful_fuzz_probability(
                candidate,
                character_level=character_level,
            )
            < _SOURCE_RANKED_MIN_FRESH_USEFUL_FUZZ_PROBABILITY
        ):
            # A source range that only occasionally reaches the useful band
            # is research, not an executable current-band route.
            continue
        if status in {"fresh", "productive", "retryable"}:
            return False
    return True


def _arm_source_ranked_endpoint_revalidation(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> dict[str, Any]:
    """Arm one exact no-combat route endpoint recheck at a closed frontier."""
    boot_id = state.get("world_boot_id")
    if boot_id is None or source_world is None or not candidates:
        return state
    existing = state.get(_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
        and existing.get("level") in {None, character_level}
        and existing.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and existing.get("status") in {"pending", "attempted", "closed", "succeeded"}
    ):
        return state
    eligible = [
        candidate
        for candidate in candidates
        if _source_ranked_endpoint_revalidation_candidate_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    ]
    if not eligible:
        return state
    candidate = max(
        eligible,
        key=lambda item: (
            float(item.score),
            item.estimated_level_range[1],
            -len(item.route),
            item.source_value,
        ),
    )
    state[_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY] = {
        "boot_id": boot_id,
        "level": character_level,
        "policy_id": _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        ),
        "source_revision": state.get(_SOURCE_REVISION_KEY),
        "source_mobile_vnum": candidate.mobile_vnum,
        "source_room_vnum": candidate.room_vnum,
        "route_hazard": str(
            _source_ranked_endpoint_revalidation_result(
                state,
                candidate,
                character_level=character_level,
            ).get("route_hazard")
        ),
        "status": "pending",
        "reason": "one exact retry after a safe route endpoint was not observed",
    }
    return state


def _mark_source_ranked_endpoint_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    """Consume the endpoint retry immediately before live dispatch."""
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    marker = state.get(_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("policy_id") == policy_id
        and marker.get("status") == "pending"
    ):
        return False
    state[_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
    }
    return True


