def _next_absent_research_retry_policy(
    state: dict[str, Any],
    *,
    current_group: frozenset[str],
    current_policy_id: str,
    only_expired: bool = True,
) -> str:
    """Rotate to another absent target after retrying the current one.

    A reset wait is a chance to inspect a different registered target as well
    as the one that just expired.  Keeping the cooldown map intact prevents a
    depleted route from being reopened on every campaign invocation.
    """
    results = _campaign_research_results(state)
    boot_id = state.get("world_boot_id")
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    candidates: list[tuple[int, str]] = []
    for policy_id, remaining_value in cooldowns.items():
        candidate_id = str(policy_id)
        if candidate_id in current_group:
            continue
        try:
            remaining = int(remaining_value)
        except (TypeError, ValueError):
            continue
        result = results.get(candidate_id)
        cooldown_ready = remaining <= 0 if only_expired else remaining > 0
        if (
            cooldown_ready
            and isinstance(result, dict)
            and result.get("absent") is True
            and result.get("boot_id") == boot_id
        ):
            candidates.append((remaining, candidate_id))
    if not candidates:
        return current_policy_id
    return min(candidates)[1]


def _next_pending_absent_research_retry_policy(
    state: dict[str, Any],
    *,
    maximum_remaining: int = 1,
    source_ranked_hunt_only: bool = False,
    preferred_policy_id: str | None = None,
    allow_attempted_city_route: bool = False,
) -> str | None:
    """Find a current-reboot absence retry that is one step from reopening."""
    results = _campaign_research_results(state)
    boot_id = state.get("world_boot_id")
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    city_blocked = _field_city_departure_blocked_policy_ids(state)
    clear_marker = state.get(_FIELD_CITY_CLEAR_ROUTE_REVALIDATION_KEY)
    cleared_policy_id = (
        str(clear_marker.get("policy_id") or "")
        if isinstance(clear_marker, Mapping)
        and clear_marker.get("status") == "succeeded"
        and clear_marker.get("boot_id") == boot_id
        and clear_marker.get("level") == _level(state)
        else None
    )
    city_attempted = set(_field_city_route_attempted_policy_ids(state))
    character_level = _level(state)
    if source_ranked_hunt_only:
        route_attempts = state.get(_FIELD_CITY_ROUTE_ATTEMPTS_KEY)
        if (
            isinstance(route_attempts, Mapping)
            and route_attempts.get("status") == "attempted"
            and route_attempts.get("boot_id") == boot_id
            and route_attempts.get("level") == character_level
        ):
            raw_attempted_ids = route_attempts.get("policy_ids")
            if isinstance(raw_attempted_ids, (list, tuple, set, frozenset)):
                city_attempted.update(str(value) for value in raw_attempted_ids)
    candidates: list[tuple[int, str]] = []
    for raw_policy_id, raw_remaining in cooldowns.items():
        policy_id = str(raw_policy_id)
        if not _is_research_absence_retry_policy(policy_id):
            continue
        if source_ranked_hunt_only:
            level_match = re.search(r"-(\d+)$", policy_id)
            if (
                not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                or (
                    policy_id in city_blocked
                    and policy_id != cleared_policy_id
                )
                or (
                    policy_id in city_attempted
                    and not (
                        allow_attempted_city_route
                        and policy_id == preferred_policy_id
                    )
                )
                or level_match is None
                or int(level_match.group(1)) != character_level
            ):
                continue
        result = results.get(policy_id)
        if not (
            isinstance(result, dict)
            and result.get("boot_id") == boot_id
        ):
            continue
        if source_ranked_hunt_only:
            # A normal frontier rotation may reopen an absence, but it must
            # never erase an exact current-level loss, a prior-level loss, or
            # a loss recorded against the same mobile in another reset room.
            if (
                _source_ranked_xp_loss_record(state, policy_id) is not None
                or _source_ranked_prior_level_loss_record(
                    state,
                    policy_id,
                    character_level=character_level,
                )
                is not None
            ):
                continue
            mobile_match = re.search(r"-(\d+)-\d+-\d+$", policy_id)
            if (
                mobile_match is not None
                and _source_ranked_xp_loss_for_mobile(
                    state,
                    mobile_vnum=int(mobile_match.group(1)),
                    character_level=character_level,
                )
                is not None
            ):
                continue
        route_hazard = result.get("route_hazard")
        if source_ranked_hunt_only and not (
            result.get("absent") is True
            and result.get("observed") is False
            and result.get("viable") is False
            and not route_hazard
        ):
            continue
        retryable_route_hazard = (
            route_hazard == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
            or (
                policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                and _is_retryable_source_ranked_route_hazard(
                    policy_id,
                    route_hazard,
                )
            )
        )
        if not (
            (result.get("absent") is True and not route_hazard)
            or retryable_route_hazard
        ):
            continue
        try:
            remaining = int(raw_remaining)
        except (TypeError, ValueError):
            continue
        if 0 < remaining <= maximum_remaining:
            candidates.append((remaining, policy_id))
    if preferred_policy_id and any(
        candidate_id == preferred_policy_id for _, candidate_id in candidates
    ):
        return preferred_policy_id
    return min(candidates)[1] if candidates else None


def _productive_source_hunt_absence_wait_policy(
    state: dict[str, Any],
    segments: Collection[Any],
    *,
    source_world: WorldSource | None,
) -> str | None:
    """Let a freshly depleted productive hunt enter its first bounded wait."""
    policy_id = _next_pending_absent_research_retry_policy(
        state, maximum_remaining=3, source_ranked_hunt_only=True,
        preferred_policy_id=str(state.get("campaign_last_policy") or ""),
        allow_attempted_city_route=True,
    )
    if (
        policy_id is None or source_world is None
        or (state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}).get(policy_id) != 3
        or _source_ranked_xp_loss_record(state, policy_id) is not None
        or not _is_safe_healer_checkpoint(state)
    ):
        return None
    current_city = state.get("campaign_field_city_preflight")
    if isinstance(current_city, Mapping) and current_city.get("blocked") is True:
        return None
    boot = state.get("world_boot_id")
    revision = state.get(_SOURCE_REVISION_KEY)
    level = _level(state)
    absence_seen = False
    candidate: HuntCandidate | None = None
    # The productive proof is deliberately local: a stale kill far back in a
    # long campaign history must not authorize a new city wait.
    for raw_segment in reversed(tuple(segments)[-8:]):
        segment = dict(raw_segment)
        if segment.get("phase") != policy_id:
            continue
        try:
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
            if not isinstance(start, Mapping) or not isinstance(end, Mapping):
                return None
            gain = int(end.get("xp")) - int(start.get("xp"))
            loss_unchanged = (
                int(start.get("xp_loss_total")) == int(end.get("xp_loss_total"))
                == int(state.get("xp_loss_total"))
            )
            run_id = int(segment.get("run_id"))
        except (TypeError, ValueError):
            return None
        if not (
            segment.get("status") == "success" and run_id > 0 and loss_unchanged
            and start.get("world_boot_id") == end.get("world_boot_id") == boot
            and start.get(_SOURCE_REVISION_KEY) == end.get(_SOURCE_REVISION_KEY) == revision
            and _level(dict(start)) == _level(dict(end)) == level
            and _is_safe_healer_checkpoint(end)
            and not end.get("xp_loss_observed")
            and not end.get("campaign_fastwalk_abort_reason")
        ):
            return None
        if not absence_seen:
            candidate = _source_ranked_candidate_from_record(
                start.get(_SOURCE_RANKED_CANDIDATE_KEY), source_revision=revision,
            )
            sightings = end.get("campaign_fastwalk_source_absent_sightings")
            if not (
                candidate is not None and candidate.autonomous_safe
                and not candidate.specials and not candidate.equipped_weapons
                and _source_ranked_policy_id(candidate, character_level=level) == policy_id
                and gain == 0 and end.get("xp") == state.get("xp")
                and end.get("campaign_fastwalk_target_absent") is True
                and not end.get("campaign_objective_kills")
                and not end.get("campaign_completed_kills")
                and isinstance(sightings, list) and any(
                    isinstance(item, Mapping) and item.get("policy_id") == policy_id
                    and str(item.get("room_vnum")) == str(candidate.room_vnum)
                    for item in sightings
                )
                and not _source_ranked_candidate_requires_sanctuary_for_state(
                    candidate, state, character_level=level, source_world=source_world,
                )
            ):
                return None
            absence_seen = True
            continue
        kills = end.get("campaign_objective_kills")
        productive_candidate = _source_ranked_candidate_from_record(
            start.get(_SOURCE_RANKED_CANDIDATE_KEY), source_revision=revision,
        )
        if (
            candidate is not None and gain > _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
            and productive_candidate is not None
            and productive_candidate.mobile_vnum == candidate.mobile_vnum
            and productive_candidate.room_vnum == candidate.room_vnum
            and productive_candidate.route == candidate.route
            and isinstance(kills, list) and any(
                isinstance(kill, Mapping) and kill.get("source_policy_id") == policy_id
                and kill.get("source_mobile_vnum") == candidate.mobile_vnum
                and isinstance(kill.get("xp_gained"), int)
                and kill["xp_gained"] > _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
                for kill in kills
            )
        ):
            return policy_id
        return None
    return None


def _retry_current_absent_research_policy(
    state: dict[str, Any],
    *,
    productive_only: bool = False,
) -> dict[str, Any]:
    """Re-open the next target whose bounded reset wait has just expired."""
    policy_id = str(state.get("campaign_last_policy") or "")
    if not _is_research_absence_retry_policy(policy_id):
        return state
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, dict)
        and (
            result.get("absent")
            or (
                policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                and result.get("route_hazard")
            )
        )
        and result.get("boot_id") == state.get("world_boot_id")
    ):
        return state
    retried = dict(state)
    retried.pop(_POLICY_HANDOFF_KEY, None)
    current_group = _research_absence_retry_group(policy_id)
    results = dict(_campaign_research_results(state))
    protection_recovery_blocks_handoff = (
        _protection_recovery_required(state)
        and not _state_has_sanctuary_reserve(state)
    )
    productive_policy_id = state.get(_LAST_PRODUCTIVE_POLICY_KEY)
    productive_result = (
        results.get(productive_policy_id)
        if isinstance(productive_policy_id, str)
        else None
    )
    productive_handoff = bool(
        isinstance(productive_policy_id, str)
        and productive_policy_id not in current_group
        and isinstance(productive_result, dict)
        and productive_result.get("boot_id") == state.get("world_boot_id")
        and productive_result.get("observed") is True
        and productive_result.get("viable") is True
        and productive_result.get("completed_kill") is True
        and not protection_recovery_blocks_handoff
    )
    historical_handoff = (
        None
        if productive_handoff or protection_recovery_blocks_handoff
        else _historical_productive_handoff_policy_id(
            state,
            current_group=current_group,
        )
    )
    handoff_policy_id = (
        productive_policy_id
        if productive_handoff
        else historical_handoff
    )
    if productive_only and handoff_policy_id is None:
        return state
    if handoff_policy_id is not None:
        selected_policy_id = handoff_policy_id
        retry_policy_ids = ()
        retried[_POLICY_HANDOFF_KEY] = selected_policy_id
    else:
        cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
        current_cooldown = 0
        for candidate_id in current_group:
            try:
                current_cooldown = max(
                    current_cooldown,
                    int(cooldowns.get(candidate_id) or 0),
                )
            except (TypeError, ValueError):
                continue
        selected_policy_id = _next_absent_research_retry_policy(
            state,
            current_group=current_group,
            current_policy_id=policy_id,
        )
        if (
            selected_policy_id == policy_id
            and current_cooldown > 0
        ):
            return state
        retry_policy_ids = _research_absence_retry_group(selected_policy_id)
    for candidate_id in retry_policy_ids:
        results.pop(candidate_id, None)
    if results:
        retried["campaign_research_results"] = results
    else:
        retried.pop("campaign_research_results", None)
    cooldowns = dict(state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {})
    for candidate_id in retry_policy_ids:
        cooldowns.pop(candidate_id, None)
    if cooldowns:
        retried[_RESEARCH_ABSENCE_COOLDOWN_KEY] = cooldowns
    else:
        retried.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if retry_policy_ids:
        cleared_research_policies = {
            str(candidate_id)
            for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
        }
        cleared_research_policies.update(retry_policy_ids)
        retried[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
    retried["campaign_fastwalk_target_absent"] = False
    retried["campaign_fastwalk_crowded"] = False
    retried.pop("campaign_fastwalk_abort_reason", None)
    retried["campaign_last_policy"] = selected_policy_id
    return retried


def _retry_any_pending_absent_research_policy(
    state: dict[str, Any],
    *,
    maximum_remaining: int = 1,
    source_ranked_hunt_only: bool = False,
) -> dict[str, Any]:
    """Reopen one bounded absence route after the frontier is exhausted."""
    policy_id = _next_pending_absent_research_retry_policy(
        state,
        maximum_remaining=maximum_remaining,
        source_ranked_hunt_only=source_ranked_hunt_only,
        preferred_policy_id=str(state.get("campaign_last_policy") or ""),
    )
    if policy_id is None:
        return state
    retry_policy_ids = _research_absence_retry_group(policy_id)
    retried = dict(state)
    results = dict(_campaign_research_results(state))
    for candidate_id in retry_policy_ids:
        results.pop(candidate_id, None)
    if results:
        retried["campaign_research_results"] = results
    else:
        retried.pop("campaign_research_results", None)
    cooldowns = dict(state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {})
    for candidate_id in retry_policy_ids:
        cooldowns.pop(candidate_id, None)
    if cooldowns:
        retried[_RESEARCH_ABSENCE_COOLDOWN_KEY] = cooldowns
    else:
        retried.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    cleared_research_policies = {
        str(candidate_id)
        for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared_research_policies.update(retry_policy_ids)
    retried[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
        cleared_research_policies
    )
    retried["campaign_fastwalk_target_absent"] = False
    retried.pop("campaign_fastwalk_abort_reason", None)
    retried["campaign_last_policy"] = policy_id
    return retried


def _retry_required_sanctuary_research_policy(
    state: dict[str, Any],
) -> dict[str, Any]:
    """Reopen an absent sanctuary carrier after the bounded reset wait."""
    policy_id = _MORIA_SANCTUARY_THIEF_LEVEL_SEVENTEEN_POLICY_ID
    moria_policy_ids = _MORIA_SANCTUARY_RESEARCH_POLICY_IDS
    generic_policy_ids = frozenset(
        {
            _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id,
            _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id,
        }
    )
    sanctuary_policy_ids = moria_policy_ids | generic_policy_ids
    results = _campaign_research_results(state)
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    cooldown_active = isinstance(cooldowns, dict) and any(
        int(cooldowns.get(candidate_id) or 0) > 0
        for candidate_id in sanctuary_policy_ids
    )
    deferred_policy_ids = {
        candidate_id
        for candidate_id in sanctuary_policy_ids
        if isinstance(results.get(candidate_id), dict)
        and (
            results[candidate_id].get("absent") is True
            or results[candidate_id].get("retryable_failure") is True
        )
        and results[candidate_id].get("boot_id") == state.get("world_boot_id")
    }
    deferred_generic_policy_ids = generic_policy_ids.intersection(
        deferred_policy_ids
    )
    if deferred_generic_policy_ids:
        retry_policy_ids = {
            candidate_id
            for candidate_id in deferred_generic_policy_ids
            if not _sanctuary_recovery_attempts_exhausted(
                state,
                policy_id=candidate_id,
            )
        }
        if not retry_policy_ids:
            # A reset wait may reopen a deferred sanctuary route only while
            # its bounded retry contract remains available. A stale
            # retryable result must not revive a spent generic fallback.
            return state
        reopened_policy_id = (
            _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
            if _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
            in retry_policy_ids
            else _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id
        )
    else:
        retry_policy_ids = moria_policy_ids
        reopened_policy_id = policy_id
    sanctuary_target_deferred = any(
        isinstance(results.get(candidate_id), dict)
        and (
            results[candidate_id].get("absent") is True
            or results[candidate_id].get("retryable_failure") is True
        )
        and results[candidate_id].get("boot_id") == state.get("world_boot_id")
        for candidate_id in retry_policy_ids
    )
    if not (
        cooldown_active
        and sanctuary_target_deferred
        and _campaign_sanctuary_recovery_required(state)
    ):
        return state
    retried = dict(state)
    results = dict(results)
    for candidate_id in retry_policy_ids:
        results.pop(candidate_id, None)
    if results:
        retried["campaign_research_results"] = results
    else:
        retried.pop("campaign_research_results", None)
    remaining_cooldowns = dict(cooldowns)
    for candidate_id in retry_policy_ids:
        remaining_cooldowns.pop(candidate_id, None)
    if remaining_cooldowns:
        retried[_RESEARCH_ABSENCE_COOLDOWN_KEY] = remaining_cooldowns
    else:
        retried.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    cleared = {
        str(candidate_id)
        for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared.update(retry_policy_ids)
    retried[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    retried["campaign_fastwalk_target_absent"] = False
    retried.pop("campaign_fastwalk_abort_reason", None)
    retried["campaign_last_policy"] = reopened_policy_id
    return retried


def _active_crowded_research_policy_id(
    state: dict[str, Any],
    *,
    exclude_policy_id: str | None = None,
) -> str | None:
    """Prefer a current-band field recheck over unrelated maintenance crowds."""
    results = _campaign_research_results(state)
    cooldowns = state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    try:
        character_level = int(state.get("level"))
    except (TypeError, ValueError):
        character_level = None
    candidates: list[tuple[bool, int, str]] = []
    for policy_id, result in results.items():
        policy_id = str(policy_id)
        if (
            policy_id == exclude_policy_id
            or not isinstance(result, dict)
            or result.get("crowded") is not True
            or result.get("crowd_exhausted") is True
            or result.get("boot_id") != state.get("world_boot_id")
        ):
            continue
        if policy_id == _RESTOCK_POLICY.policy_id:
            # A crowded bakery visit is optional maintenance once a durable
            # food reserve is already present. Do not let that old shop
            # result block a current-band XP route; retain the wait only
            # while food is genuinely needed or live urgency is active.
            if state.get("campaign_urgent_food_acquisition") is not True:
                food_units = len(
                    _inventory_food_keywords(
                        state.get("inventory"),
                        gear_catalog=None,
                    )
                )
                if not _source_ranked_field_food_reserve_needed(
                    state,
                    food_units,
                ):
                    continue
        if (
            (policy_id in _SANCTUARY_RESOURCE_POLICY_IDS
             or _is_source_ranked_sanctuary_maintenance_policy_id(policy_id))
            and _state_has_full_staff_fight_reserve(state)
        ):
            # Keep the carrier's actual crowd receipt, but do not wait for
            # optional supplies when the carried staff already covers a fight.
            continue
        if character_level is not None and policy_id.startswith(
            _SOURCE_RANKED_POLICY_PREFIX
        ):
            level_match = re.search(r"-(\d+)$", policy_id)
            if (
                level_match is not None
                and int(level_match.group(1)) != character_level
            ):
                # Source-ranked policy ids end with the character level. A
                # prior-band crowd must not block a fresh current-band route.
                continue
        try:
            remaining = int(cooldowns.get(policy_id) or 0)
        except (TypeError, ValueError):
            continue
        if remaining > 0:
            candidates.append((
                not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX),
                remaining,
                policy_id,
            ))
    if not candidates:
        return None
    return min(candidates)[2]


def _crowd_policy_has_active_wait(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Return whether one current-reboot crowd still has a reset wait."""
    if not policy_id:
        return False
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("crowded") is True
        and result.get("crowd_exhausted") is not True
    ):
        return False
    cooldowns = state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    try:
        return int(cooldowns.get(policy_id) or 0) > 0
    except (AttributeError, TypeError, ValueError):
        return False


def _source_ranked_crowd_policy_exhausted(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Return whether a current-reboot source crowd is already exhausted."""
    if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        return False
    if _source_ranked_crowd_attempts_exhausted(state, policy_id):
        return True
    result = _campaign_research_results(state).get(policy_id)
    return (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("crowd_exhausted") is True
    )


def _active_source_ranked_reset_policy_id(
    state: dict[str, Any],
) -> str | None:
    """Return a source route that is waiting on current-reboot evidence."""
    results = _campaign_research_results(state)
    boot_id = state.get("world_boot_id")
    try:
        character_level = int(state.get("level"))
    except (TypeError, ValueError):
        character_level = None
    candidates: list[tuple[int, str]] = []
    for cooldown_key in (
        _RESEARCH_ABSENCE_COOLDOWN_KEY,
        _RESEARCH_CROWD_COOLDOWN_KEY,
    ):
        cooldowns = state.get(cooldown_key) or {}
        for raw_policy_id, raw_remaining in cooldowns.items():
            policy_id = str(raw_policy_id)
            if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
                continue
            loss = _source_ranked_xp_loss_record(state, policy_id)
            if character_level is not None and loss is not None and loss.get("level") in (
                character_level, str(character_level),
            ):
                # Resetting an area cannot clear a recorded combat failure.
                continue
            if (
                policy_id.endswith("-sanctuary-maintenance")
                and _state_has_sanctuary_reserve(state)
            ):
                # A missed out-of-band carrier must not pause ordinary XP
                # progression once a verified Sanctuary reserve is already
                # available. The carrier can be reconsidered later as
                # maintenance; it is not a prerequisite for current-band
                # hunting.
                continue
            if character_level is not None:
                level_match = re.search(r"-(\d+)$", policy_id)
                if level_match is not None and int(level_match.group(1)) != character_level:
                    # Source-ranked candidate ids are generated per level.
                    # A stale cooldown from an earlier band must not make a
                    # current-level frontier appear unavailable.
                    continue
            result = results.get(policy_id)
            if not (
                isinstance(result, dict)
                and result.get("boot_id") == boot_id
                and result.get("crowd_exhausted") is not True
                and (
                    result.get("absent") is True
                    or result.get("crowded") is True
                    or result.get("crowd_exhausted") is True
                    or (
                        result.get("retryable_failure") is True
                        and not (
                            result.get("observed") is True
                            and result.get("consider_viable") is True
                            and result.get("completed_kill") is False
                            and result.get("viable") is False
                        )
                    )
                    or result.get("route_hazard")
                )
            ):
                continue
            try:
                remaining = int(raw_remaining)
            except (TypeError, ValueError):
                continue
            if remaining > 0:
                candidates.append((remaining, policy_id))
    return min(candidates)[1] if candidates else None


def _source_ranked_reset_policy_has_route_hazard(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Return whether a reset marker is only a route-specific hazard."""
    if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        return False
    result = _campaign_research_results(state).get(policy_id)
    return bool(
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("route_hazard")
    )


def _retry_any_crowded_research_policy(
    state: dict[str, Any],
    *,
    exclude_policy_id: str | None = None,
) -> dict[str, Any]:
    """Reopen one crowded route after its explicit reset wait."""
    policy_id = _active_crowded_research_policy_id(
        state,
        exclude_policy_id=exclude_policy_id,
    )
    if policy_id is None:
        return state
    retried = dict(state)
    results = dict(_campaign_research_results(state))
    retained = (
        productive_crowd_reset_result(
            results.get(policy_id), level=_level(state), boot_id=state.get("world_boot_id"),
        )
        if policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and _source_ranked_xp_loss_record(state, policy_id) is None else None
    )
    if retained is None:
        results.pop(policy_id, None)
    else:
        results[policy_id] = retained
    if results:
        retried["campaign_research_results"] = results
    else:
        retried.pop("campaign_research_results", None)
    cooldowns = dict(state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {})
    cooldowns.pop(policy_id, None)
    if cooldowns:
        retried[_RESEARCH_CROWD_COOLDOWN_KEY] = cooldowns
    else:
        retried.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    cleared_research_policies = {
        str(candidate_id)
        for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared_research_policies.add(policy_id)
    retried[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
        cleared_research_policies
    )
    retried["campaign_fastwalk_target_absent"] = False
    retried["campaign_fastwalk_crowded"] = False
    retried.pop("campaign_fastwalk_abort_reason", None)
    retried["campaign_last_policy"] = policy_id
    return retried


def _retry_current_crowded_research_policy(state: dict[str, Any]) -> dict[str, Any]:
    """Rotate a crowded research checkpoint after its bounded wait."""
    policy_id = str(state.get("campaign_last_policy") or "")
    abort_reason = str(state.get("campaign_fastwalk_abort_reason") or "")
    current_result = _campaign_research_results(state).get(policy_id)
    if (
        policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and isinstance(current_result, dict)
        and current_result.get("crowd_exhausted") is True
    ):
        active_policy_id = _active_crowded_research_policy_id(
            state,
            exclude_policy_id=policy_id,
        )
        if active_policy_id and active_policy_id != policy_id:
            # Preserve this exhausted route's evidence, but use the explicit
            # reset retry to reopen a different active crowd route. Without
            # this handoff, the retry can clear no route and fall through to
            # an unavailable policy even though executable work remains.
            return _retry_any_crowded_research_policy(
                state,
                exclude_policy_id=policy_id,
            )
        # Keep the evidence and cooldown intact.  `_policy_for_state` will
        # exclude this candidate and select another source-safe current-band
        # route, while a later reboot can reconsider the original target.
        rotated = dict(state)
        rotated["campaign_fastwalk_target_absent"] = False
        rotated["campaign_fastwalk_crowded"] = False
        rotated.pop("campaign_fastwalk_abort_reason", None)
        rotated["campaign_last_policy"] = policy_id
        return rotated
    if (
        abort_reason == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
        or _is_retryable_source_ranked_route_hazard(policy_id, abort_reason)
    ):
        result = _campaign_research_results(state).get(policy_id)
        cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
        if not (
            isinstance(result, dict)
            and result.get("route_hazard") == abort_reason
            and result.get("boot_id") == state.get("world_boot_id")
            and isinstance(cooldowns, dict)
            and int(cooldowns.get(policy_id) or 0) > 0
        ):
            return state
        retried = dict(state)
        results = dict(_campaign_research_results(state))
        results.pop(policy_id, None)
        if results:
            retried["campaign_research_results"] = results
        else:
            retried.pop("campaign_research_results", None)
        remaining_cooldowns = dict(cooldowns)
        remaining_cooldowns.pop(policy_id, None)
        if remaining_cooldowns:
            retried[_RESEARCH_ABSENCE_COOLDOWN_KEY] = remaining_cooldowns
        else:
            retried.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
        cleared_research_policies = {
            str(candidate_id)
            for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
        }
        cleared_research_policies.add(policy_id)
        retried[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
        retried["campaign_fastwalk_target_absent"] = False
        retried["campaign_fastwalk_crowded"] = False
        retried.pop("campaign_fastwalk_abort_reason", None)
        retried["campaign_last_policy"] = policy_id
        return retried
    if not policy_id or not any(
        abort_reason.startswith(prefix) for prefix in _FIELD_CROWD_ABORT_PREFIXES
    ):
        return _retry_any_crowded_research_policy(state)
    retry_policy_id = _next_absent_research_retry_policy(
        state,
        current_group=_research_absence_retry_group(policy_id),
        current_policy_id=policy_id,
        only_expired=False,
    )
    if retry_policy_id == policy_id:
        return _retry_any_crowded_research_policy(state)
    retried = dict(state)
    # Crowd rotation selects one executable route.  Paired probe/hunt
    # identities share absence-reset state only in the dedicated reset path;
    # clearing the whole group here can erase an unrelated sanctuary probe.
    retry_policy_ids = (retry_policy_id,)
    results = dict(_campaign_research_results(state))
    for candidate_id in retry_policy_ids:
        results.pop(candidate_id, None)
    if results:
        retried["campaign_research_results"] = results
    else:
        retried.pop("campaign_research_results", None)
    cooldowns = dict(state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {})
    for candidate_id in retry_policy_ids:
        cooldowns.pop(candidate_id, None)
    if cooldowns:
        retried[_RESEARCH_ABSENCE_COOLDOWN_KEY] = cooldowns
    else:
        retried.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    cleared_research_policies = {
        str(candidate_id)
        for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared_research_policies.update(retry_policy_ids)
    retried[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
        cleared_research_policies
    )
    retried["campaign_fastwalk_target_absent"] = False
    retried["campaign_fastwalk_crowded"] = False
    retried.pop("campaign_fastwalk_abort_reason", None)
    retried["campaign_last_policy"] = retry_policy_id
    return retried


def _is_equipment_audit_response(response: str) -> bool:
    """Reject stale command pulses while reconstructing an equipment audit."""
    return "you are not using any equipment" in response or bool(
        re.search(r"(?:\[weapon\]|\[held\]|<[^>]*worn[^>]*>)", response)
    )


def _state_has_item(value: Any, item_name: str) -> bool:
    target = item_name.casefold()
    if isinstance(value, str):
        try:
            decoded = json.loads(_ANSI_ESCAPE.sub("", value))
        except json.JSONDecodeError:
            return target in value.casefold()
        return _state_has_item(decoded, item_name)
    if isinstance(value, dict):
        for key in ("short_desc", "name", "item"):
            description = value.get(key)
            if isinstance(description, str) and target in description.casefold():
                return True
        return any(_state_has_item(item, item_name) for item in value.values())
    if isinstance(value, (list, tuple)):
        return any(_state_has_item(item, item_name) for item in value)
    return False


_STATE_HAS_ITEM_UNCACHED = _state_has_item


def _state_has_item(value: Any, item_name: str) -> bool:
    # The selector cache is scoped to one campaign decision and is already
    # bounded by the caller. Reuse it for offline policy selection too; the
    # same inventory/equipment value is queried thousands of times while
    # ranking source candidates.
    cache = _CAMPAIGN_SOURCE_SELECTOR_CACHE.get()
    cache_key = ("state-has-item", id(value), item_name.casefold())
    if (
        cache is not None
        and cache_key in cache
    ):
        return bool(cache[cache_key])
    result = _STATE_HAS_ITEM_UNCACHED(value, item_name)
    if cache is not None:
        cache[cache_key] = result
    return result


def _state_has_carried_item(state: Mapping[str, Any], item_name: str) -> bool:
    """Check inventory plus structured worn/held equipment for an item."""
    return any(
        _state_has_item(state.get(key), item_name)
        for key in (
            "inventory",
            "equipment",
            "campaign_worn_equipment",
            "acquired_items",
        )
    )


def _state_has_carried_object_vnum(
    state: Mapping[str, Any],
    object_vnum: int,
) -> bool:
    """Check the structured carried/equipment views for one exact VNUM."""
    try:
        expected = int(object_vnum)
    except (TypeError, ValueError):
        return False

    def contains(value: Any) -> bool:
        if isinstance(value, str):
            try:
                decoded = json.loads(_ANSI_ESCAPE.sub("", value))
            except (TypeError, json.JSONDecodeError):
                return False
            return contains(decoded)
        if isinstance(value, Mapping):
            for key in ("vnum", "object_vnum", "objectVnum"):
                raw_value = value.get(key)
                try:
                    if int(raw_value) == expected:
                        return True
                except (TypeError, ValueError):
                    pass
            return any(contains(item) for item in value.values())
        if isinstance(value, (list, tuple)):
            return any(contains(item) for item in value)
        return False

    return any(
        contains(state.get(key))
        for key in (
            "inventory",
            "equipment",
            "campaign_worn_equipment",
            "acquired_items",
        )
    )


def _state_has_structured_equipment_vnum(
    equipment: Any,
    object_vnum: int,
) -> bool:
    """Check only the exact structured equipment packet for one VNUM."""
    try:
        expected = int(object_vnum)
    except (TypeError, ValueError):
        return False

    def contains(value: Any) -> bool:
        if isinstance(value, str):
            try:
                decoded = json.loads(_ANSI_ESCAPE.sub("", value))
            except (TypeError, json.JSONDecodeError):
                return False
            return contains(decoded)
        if isinstance(value, Mapping):
            for key in ("vnum", "object_vnum", "objectVnum"):
                raw_value = value.get(key)
                try:
                    if int(raw_value) == expected:
                        return True
                except (TypeError, ValueError):
                    pass
            return any(contains(item) for item in value.values())
        if isinstance(value, (list, tuple)):
            return any(contains(item) for item in value)
        return False

    return contains(equipment)


def _state_has_active_light_source(
    state: Mapping[str, Any],
    gear_catalog: GearCatalog | None,
) -> bool:
    """Return whether the worn light slot contains a charged source item."""
    equipment = state.get("equipment")
    if isinstance(equipment, str):
        try:
            equipment = json.loads(_ANSI_ESCAPE.sub("", equipment))
        except (TypeError, json.JSONDecodeError):
            equipment = None
    if not isinstance(equipment, (list, tuple)):
        return False
    for raw_item in equipment:
        if not isinstance(raw_item, Mapping):
            continue
        try:
            vnum = int(raw_item.get("vnum"))
        except (TypeError, ValueError):
            continue
        item = gear_catalog.objects.get(vnum) if gear_catalog is not None else None
        if item is None:
            # Some live-only light objects use a generated VNUM that is not
            # present in the source mirror. GMCP still gives us the exact
            # worn slot and item type, which is sufficient live evidence for
            # an active light without guessing from its display name.
            raw_slot = str(raw_item.get("slot") or "").casefold()
            raw_wear_loc = raw_item.get("wear_loc")
            try:
                raw_item_type = int(raw_item.get("item_type"))
            except (TypeError, ValueError):
                raw_item_type = None
            if (
                raw_item_type == 1
                and (raw_slot == "light" or raw_wear_loc == 0)
                and any(
                    isinstance(raw_item.get(key), str)
                    and raw_item.get(key).strip()
                    for key in ("name", "keywords")
                )
            ):
                return True
            continue
        if item_category(item) != "light":
            continue
        try:
            return len(item.values) >= 3 and int(item.values[2]) != 0
        except (TypeError, ValueError):
            return False
    return False


def _state_item_count(value: Any, item_name: str) -> int:
    target = item_name.casefold()
    if isinstance(value, str):
        try:
            decoded = json.loads(_ANSI_ESCAPE.sub("", value))
        except json.JSONDecodeError:
            return int(target in value.casefold())
        return _state_item_count(decoded, item_name)
    if isinstance(value, dict):
        description = next(
            (
                value[key]
                for key in ("short_desc", "name", "item")
                if isinstance(value.get(key), str)
            ),
            None,
        )
        if description is not None and target in description.casefold():
            quantity = value.get("quan", 1)
            try:
                return max(1, int(quantity))
            except (TypeError, ValueError):
                return 1
        return sum(_state_item_count(item, item_name) for item in value.values())
    if isinstance(value, (list, tuple)):
        return sum(_state_item_count(item, item_name) for item in value)
    return 0


def _state_has_active_affect(value: Any, affect_name: str) -> bool:
    target = affect_name.casefold()
    if isinstance(value, str):
        try:
            decoded = json.loads(_ANSI_ESCAPE.sub("", value))
        except json.JSONDecodeError:
            return target in value.casefold()
        return _state_has_active_affect(decoded, affect_name)
    if isinstance(value, dict):
        name = value.get("name")
        if isinstance(name, str):
            # Affect identity lives in the explicit name field.  Searching
            # nested prose such as ``gives: detect invisibility`` can make a
            # detect-invisibility affect look like the invisibility spell.
            return target == name.casefold()
        return any(
            _state_has_active_affect(item, affect_name)
            for item in value.values()
        )
    if isinstance(value, (list, tuple)):
        return any(_state_has_active_affect(item, affect_name) for item in value)
    return False


def _state_flight_duration(value: Any) -> int | None:
    """Return the longest observed duration for fly or levitation."""
    durations: list[int] = []

    def collect(item: Any) -> None:
        if isinstance(item, str):
            try:
                decoded = json.loads(_ANSI_ESCAPE.sub("", item))
            except json.JSONDecodeError:
                return
            collect(decoded)
            return
        if isinstance(item, dict):
            name = item.get("name")
            if isinstance(name, str) and name.casefold() in {
                "fly",
                "levitation",
            }:
                try:
                    durations.append(int(item.get("duration")))
                except (TypeError, ValueError):
                    pass
            for nested in item.values():
                collect(nested)
            return
        if isinstance(item, (list, tuple)):
            for nested in item:
                collect(nested)

    collect(value)
    return max(durations) if durations else None


def _flight_refresh_runtime_cap(
    state: Mapping[str, Any],
    *,
    configured: float | None,
) -> float | None:
    """Bound a flight-purchase worker while an old flight affect expires.

    DD4's ``spell_fly`` and ``spell_levitation`` return immediately when the
    character is already flying.  The worker must wait at the healer rather
    than consume a replacement potion, but a stale long segment would turn
    that safe wait into an apparent stall.  The observed duration is measured
    in 30-second ticks; add one route/cleanup allowance after expiry and keep
    a short minimum for an affect whose remaining duration is zero or one.
    """
    if state.get("affects") is None:
        return configured
    if not any(
        _state_has_active_affect(state.get("affects"), effect)
        for effect in ("fly", "levitation")
    ):
        return configured
    duration = _state_flight_duration(state.get("affects"))
    if duration is None:
        return configured
    expiry_and_route = max(
        _FLIGHT_REFRESH_MIN_RUNTIME_SECONDS,
        max(0, duration) * _FLIGHT_AFFECT_PULSE_SECONDS
        + _FLIGHT_REFRESH_ROUTE_GRACE_SECONDS,
    )
    if configured is None:
        return expiry_and_route
    return min(float(configured), expiry_and_route)


_FLIGHT_REFRESH_RUNTIME_EXECUTIONS = frozenset(
    {"cast-flight", "source-ranked-flight-reserve"}
)


def _flight_refresh_runtime_for_policy(
    execution: str | None,
    state: Mapping[str, Any],
    *,
    configured: float | None,
) -> float | None:
    """Cap only workers whose job is to refresh or acquire flight.

    An expiring flight affect can be present while an ordinary ground hunt is
    being resumed. That hunt still needs its full bounded field window; the
    short expiry cap is only useful for the dedicated refresh workers.
    """
    if execution not in _FLIGHT_REFRESH_RUNTIME_EXECUTIONS:
        return None
    return _flight_refresh_runtime_cap(state, configured=configured)


def _state_copper_value(state: dict[str, Any]) -> int:
    currencies = state.get("currencies")
    source = currencies if isinstance(currencies, dict) else state

    def amount(name: str) -> int:
        value = source.get(name, 0)
        try:
            return max(0, int(value))
        except (TypeError, ValueError):
            return 0

    return (
        amount("platinum") * 1_000
        + amount("gold") * 100
        + amount("silver") * 10
        + amount("copper")
    )


def _flight_purchase_minimum(state: dict[str, Any]) -> int:
    """Return the current reboot's observed price, with a legacy floor."""
    observed = state.get(_MAGIC_SHOP_FLIGHT_PRICE_KEY)
    try:
        price = int(observed)
    except (TypeError, ValueError):
        price = 0
    if price <= 0:
        return 90
    current_boot = state.get("world_boot_id")
    price_boot = state.get(_MAGIC_SHOP_FLIGHT_PRICE_BOOT_KEY)
    if current_boot and price_boot != current_boot:
        return 90
    return max(90, price)


def _state_needs_coin_deposit(state: dict[str, Any]) -> bool:
    """Bank coins that either consume carry room or expose a thief route."""
    currencies = state.get("currencies")
    source = currencies if isinstance(currencies, dict) else state
    coin_count = 0
    for denomination in ("platinum", "gold", "silver", "copper"):
        try:
            coin_count += max(0, int(source.get(denomination, 0)))
        except (TypeError, ValueError):
            continue

    # DD4's spec_thief uses total_coins_char(), not the number of physical
    # coins. Keep a compact working reserve before a source-ranked thief
    # special can remove a meaningful fraction of a carried hoard.
    if (
        _state_copper_value(state) * 20 // 100
        > _SPEC_THIEF_MAX_EXPOSURE_COINS
    ):
        return True

    stats = state.get("stats")
    if not isinstance(stats, dict):
        return False
    carry_weight = stats.get("carry_wt")
    maximum_weight = stats.get("maxcarry_wt")
    if not isinstance(carry_weight, (int, float)):
        return False
    if not isinstance(maximum_weight, (int, float)) or maximum_weight <= 0:
        return False
    if maximum_weight - carry_weight >= 10:
        return False
    return coin_count >= 10


def _has_campaign_sellable_loot(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None = None,
) -> bool:
    if _liquidation_retention_matches(state, gear_catalog=gear_catalog):
        # A completed no-sale healer pass is authoritative for this unchanged
        # carried signature, including when a description maps to multiple
        # source objects. New loot or a changed signature reopens the audit.
        return False
    character_class = (
        state.get("character_class")
        if isinstance(state.get("character_class"), str)
        else None
    )
    subclass = (
        state.get("subclass")
        if isinstance(state.get("subclass"), str)
        else None
    )
    # A completed liquidation records the inventory that the sale planner
    # intentionally retained.  Weight pressure alone must not reopen that
    # same no-op maintenance pass; only a changed liquidation signature can
    # justify another shop visit.
    if _matches_liquidation_baseline(state, gear_catalog=gear_catalog):
        ambiguous_sellable = bool(
            gear_catalog is not None
            and any(
                len(gear_catalog.candidates(description)) > 1
                and _sellable_inventory_keyword(
                    [[{"short_desc": description}]],
                    gear_catalog,
                    worn_descriptions=state.get("campaign_worn_equipment"),
                    character_class=character_class,
                    subclass=subclass,
                )
                is not None
                for description in _inventory_descriptions(state.get("inventory"))
                if "water skin" not in description.casefold()
                and not _is_pie_description(description)
            )
        )
        if not ambiguous_sellable:
            return False
    descriptions = _campaign_liquidation_descriptions(
        state,
        gear_catalog=gear_catalog,
    )
    candidate_inventory = [[{"short_desc": description} for description in descriptions]]
    stats = state.get("stats")
    if gear_catalog is not None and isinstance(stats, dict):
        carry_items = stats.get("carry_num")
        maximum_items = stats.get("maxcarry_num")
        if (
            isinstance(carry_items, (int, float))
            and isinstance(maximum_items, (int, float))
            and carry_items >= maximum_items
            and any(
                item is not None and is_disposable_food(item)
                for description in descriptions
                for item in (gear_catalog.match(description),)
            )
        ):
            return True
    keyword = _sellable_inventory_keyword(
        candidate_inventory,
        gear_catalog,
        worn_descriptions=state.get("campaign_worn_equipment"),
        character_class=character_class,
        subclass=subclass,
    )
    if keyword is None:
        return False
    if keyword == "collar":
        carried_collars = _state_item_count(
            state.get("inventory"),
            "war dog collar",
        )
        worn_collars = sum(
            "war dog collar" in normalize_item_name(description)
            for description in state.get("campaign_worn_equipment") or ()
        )
        retained_carried_collars = max(0, 2 - worn_collars)
        if carried_collars <= retained_carried_collars:
            return False
        stats = state.get("stats")
        if not isinstance(stats, dict):
            return False
        carry_weight = stats.get("carry_wt")
        maximum_weight = stats.get("maxcarry_wt")
        if not isinstance(carry_weight, (int, float)):
            return False
        if not isinstance(maximum_weight, (int, float)) or maximum_weight <= 0:
            return False
        if carry_weight / maximum_weight < 0.85:
            return False
    if isinstance(stats, dict):
        carry_weight = stats.get("carry_wt")
        maximum_weight = stats.get("maxcarry_wt")
        if (
            isinstance(carry_weight, (int, float))
            and isinstance(maximum_weight, (int, float))
            and maximum_weight > 0
            and maximum_weight - carry_weight <= 10
        ):
            empty_categories = set(
                state.get("campaign_empty_equipment_categories") or ()
            )
            for description in _inventory_descriptions(state.get("inventory")):
                if _sellable_inventory_keyword(
                    [[{"short_desc": description}]],
                    gear_catalog,
                    worn_descriptions=state.get("campaign_worn_equipment"),
                    character_class=character_class,
                    subclass=subclass,
                ) is None:
                    continue
                item = gear_catalog.match(description) if gear_catalog else None
                if (
                    item is not None
                    and item_category(item) in empty_categories
                    and not is_strength_penalty_ring(item)
                ):
                    continue
                return True
            return False
    # A failed purchase is not new loot. Once a liquidation checkpoint has
    # recorded the retained inventory, repeating the same no-op sale only
    # stalls the pending purchase retry; a changed signature will still
    # schedule one fresh liquidation pass.
    return not _matches_liquidation_baseline(state, gear_catalog=gear_catalog)


def _campaign_capacity_relief_inventory_keyword(
    state: Mapping[str, Any],
    *,
    gear_catalog: GearCatalog | None,
) -> str | None:
    """Resolve one exact carried item that can free a needed slot."""
    if gear_catalog is None:
        return None
    character_class = state.get("character_class")
    if not isinstance(character_class, str) or not character_class.strip():
        return None
    subclass = (
        state.get("subclass") if isinstance(state.get("subclass"), str) else None
    )
    worn_source_items: list[ObjectSource] = []
    structured_equipment = state.get("equipment")
    if isinstance(structured_equipment, (list, tuple)):
        for raw_item in structured_equipment:
            if not isinstance(raw_item, Mapping):
                continue
            try:
                vnum = int(raw_item.get("vnum"))
            except (TypeError, ValueError):
                continue
            item = gear_catalog.objects.get(vnum)
            if item is not None:
                worn_source_items.append(item)
    if not worn_source_items:
        worn_source_items.extend(
            gear_catalog.match_many_usable(
                state.get("campaign_worn_equipment") or (),
                character_class=character_class,
                subclass=subclass,
                character_alignment=_state_alignment(state),
            )
        )
    return _capacity_relief_inventory_keyword(
        state.get("inventory"),
        gear_catalog,
        inventory_source_hints=state.get(_CAMPAIGN_INVENTORY_SOURCE_HINTS_KEY),
        character_class=character_class,
        subclass=subclass,
        character_alignment=_state_alignment(state),
        worn_source_vnums={item.vnum for item in worn_source_items},
        worn_source_items=tuple(worn_source_items),
    )


def _campaign_should_liquidate_loot(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None = None,
    allow_bounded_city_transit: bool = False,
    force: bool = False,
) -> bool:
    capacity_relief_keyword = (
        _campaign_capacity_relief_inventory_keyword(
            state,
            gear_catalog=gear_catalog,
        )
        if force
        else None
    )
    retained = state.get(_LIQUIDATION_RETENTION_KEY)
    if capacity_relief_keyword is not None and isinstance(retained, Mapping):
        recorded = retained.get("signature") or ()
        already_retained = any(
            isinstance(description, str)
            and any(word.startswith(capacity_relief_keyword) for word in description.casefold().split())
            for description in recorded
        )
        retained_hints = retained.get("inventory_source_hints")
        current_hints = state.get(_CAMPAIGN_INVENTORY_SOURCE_HINTS_KEY)
        retained_hints = retained_hints if isinstance(retained_hints, Mapping) else {}
        current_hints = current_hints if isinstance(current_hints, Mapping) else {}

        def source_hint(description: str, hints: Mapping[str, Any]) -> Any:
            normalized = normalize_item_name(description)
            for raw_description, vnum in hints.items():
                if normalize_item_name(str(raw_description)) == normalized:
                    return vnum
            return None

        # A new hint for an unrelated inventory item must not reopen the
        # retained capacity candidate. Only a changed source identity for the
        # exact retained item justifies another sale audit.
        retained_descriptions = tuple(
            description
            for description in recorded
            if isinstance(description, str)
            and any(
                word.startswith(capacity_relief_keyword)
                for word in description.casefold().split()
            )
        )
        source_identity_changed = any(
            source_hint(description, retained_hints)
            != source_hint(description, current_hints)
            for description in retained_descriptions
        )
        if already_retained and not source_identity_changed:
            capacity_relief_keyword = None
    if (
        force
        and capacity_relief_keyword is None
        and _liquidation_retention_matches(
            state,
            gear_catalog=gear_catalog,
        )
    ):
        # A completed healer pass already proved that this unchanged carried
        # set is intentionally retained. A funding marker must wait for new
        # loot or a changed inventory signature, not reopen the same no-sale
        # visit on every reconnect. An exact capacity-relief identity repaired
        # from a failed source-gear handoff is the narrow exception: it is a
        # newly actionable disposal, even though the visible inventory set is
        # otherwise unchanged.
        return False
    if force and _matches_liquidation_baseline(
        state,
        gear_catalog=gear_catalog,
    ):
        funding_attempt = state.get(_PROVISION_FUNDING_LAST_ATTEMPT_KEY)
        no_proceeds = state.get(_PROVISION_FUNDING_NO_PROCEEDS_KEY)
        current_boot = state.get("world_boot_id")
        if (
            current_boot is not None
            and isinstance(funding_attempt, Mapping)
            and funding_attempt.get("boot_id") == current_boot
            and funding_attempt.get("completed_kill") is True
            and funding_attempt.get("candidate_key") is not None
            and isinstance(no_proceeds, (list, tuple))
            and any(
                isinstance(record, Mapping)
                and record.get("boot_id") == current_boot
                and record.get("candidate_key")
                == funding_attempt.get("candidate_key")
                for record in no_proceeds
            )
        ):
            # A funding kill whose exact liquidation already produced no
            # proceeds must not reopen an unchanged baseline merely because
            # a later segment compacted the retention receipt.
            return False
    if not _has_campaign_sellable_loot(state, gear_catalog=gear_catalog):
        if not force:
            return False
        # A previous liquidation can deliberately retain one plain, saleable
        # fallback item in its baseline.  When an explicit provision-funding
        # handoff is now active, that unchanged item is the bounded cash
        # reserve we already audited; permit one fresh sale pass rather than
        # waiting for unrelated loot to change the signature.  Keep ordinary
        # no-op liquidation suppression intact, and do not broaden this to
        # ambiguous or protected inventory.
        if (
            not _matches_liquidation_baseline(state, gear_catalog=gear_catalog)
            and capacity_relief_keyword is None
        ):
            return False
        descriptions = _campaign_liquidation_descriptions(
            state,
            gear_catalog=gear_catalog,
        )
        if not any(
            _sellable_inventory_keyword(
                [[{"short_desc": description}]],
                gear_catalog,
                worn_descriptions=state.get("campaign_worn_equipment"),
                character_class=state.get("character_class"),
                subclass=state.get("subclass"),
            )
            is not None
            for description in descriptions
        ) and capacity_relief_keyword is None:
            return False
    if force and capacity_relief_keyword is not None:
        # The live liquidation runner will still perform its bounded drop or
        # sacrifice acknowledgement before the funding purchase.
        return True
    completed_plan = state.get("campaign_liquidation_completion")
    if (
        force
        and _matches_liquidation_baseline(state, gear_catalog=gear_catalog)
        and isinstance(completed_plan, Mapping)
        and str(completed_plan.get("room_vnum") or "") == "3054"
        and completed_plan.get("run_id") is not None
        and int(completed_plan.get("confirmed_sales") or 0) == 0
        and int(completed_plan.get("pending_sales") or 0) == 0
        and int(completed_plan.get("pending_donations") or 0) == 0
    ):
        # A settled no-sale pass at the healer has already proved that this
        # unchanged inventory cannot fund the current purchase. Do not repeat
        # the same healer visit forever; a changed signature will reopen it.
        return False
    if (
        state.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY)
        and not (allow_bounded_city_transit and force)
        and (
            int(state.get(_CITY_SHOP_ROUTE_COOLDOWN_KEY) or 0) > 0
            or int(state.get(_FLIGHT_PURCHASE_COOLDOWN_KEY) or 0) > 0
        )
    ):
        # The source-bounded transit allowance is not a reason to send routine
        # loot back through a known-blocked city route. Keep it for explicit
        # funding needs; otherwise age the cooldown with productive work.
        return False
    if force:
        return True
    funding_attempt = state.get(_PROVISION_FUNDING_LAST_ATTEMPT_KEY)
    if (
        isinstance(funding_attempt, Mapping)
        and state.get("world_boot_id") is not None
        and funding_attempt.get("boot_id") == state.get("world_boot_id")
        and funding_attempt.get("completed_kill") is True
        and (
            state.get(_PROVISION_FUNDING_REQUIRED_KEY)
            or state.get(_FLIGHT_FUNDING_REQUIRED_KEY)
            or state.get(_FLIGHT_FUNDING_RETRY_KEY)
            or state.get(_SHADOW_KEEP_LOCKPICK_FUNDING_REQUIRED_KEY)
        )
    ):
        # Close a funding hunt with measured sales even when carried coins
        # exceed an estimated purchase price. The baseline gate above still
        # prevents another visit for unchanged retained inventory.
        return True
    if state.get(_PROTECTION_RECOVERY_KEY):
        # A protected loss leaves the character needing a reserve before the
        # next field attempt.  Do not make a single redundant weapon wait for
        # three more kills before converting it into that reserve.
        return True
    if (
        len(_campaign_liquidation_signature(state, gear_catalog=gear_catalog))
        >= _CAMPAIGN_LIQUIDATION_BATCH_SIZE
    ):
        return True

    stats = state.get("stats")
    if not isinstance(stats, dict):
        return True
    observed_capacity = False
    for current_key, maximum_key in (
        ("carry_num", "maxcarry_num"),
        ("carry_wt", "maxcarry_wt"),
    ):
        current = stats.get(current_key)
        maximum = stats.get(maximum_key)
        if not isinstance(current, (int, float)):
            continue
        if not isinstance(maximum, (int, float)) or maximum <= 0:
            continue
        observed_capacity = True
        if current / maximum >= _CAMPAIGN_LIQUIDATION_CAPACITY_RATIO:
            return True
    return not observed_capacity


def _campaign_liquidation_descriptions(
    state: Mapping[str, Any],
    *,
    gear_catalog: GearCatalog | None,
) -> tuple[str, ...]:
    """Exclude carried items already reserved by the stance planner.

    The live sale runner retains a carried item when it is a better candidate
    for a combat, recovery, or pre-level loadout than the currently worn item.
    The campaign gate must use the same fact; otherwise an un-worn upgrade can
    trigger an endless no-op liquidation loop at the healer.
    """
    descriptions = tuple(_inventory_descriptions(state.get("inventory")))
    if gear_catalog is None or not descriptions:
        return descriptions
    character_class = state.get("character_class")
    if not isinstance(character_class, str) or not character_class.strip():
        return descriptions
    worn_values = state.get("campaign_worn_equipment")
    worn_descriptions = (
        tuple(value for value in worn_values if isinstance(value, str))
        if isinstance(worn_values, (list, tuple))
        else ()
    )
    worn_items = []
    structured_equipment = state.get("equipment")
    if isinstance(structured_equipment, (list, tuple)):
        for raw_item in structured_equipment:
            if not isinstance(raw_item, Mapping):
                continue
            try:
                vnum = int(raw_item.get("vnum"))
            except (TypeError, ValueError):
                continue
            item = gear_catalog.objects.get(vnum)
            if item is not None:
                worn_items.append(item)
    if not worn_items:
        worn_items = gear_catalog.match_many(worn_descriptions)
    carried_items = gear_catalog.match_many_usable(
        descriptions,
        character_class=character_class,
        subclass=(
            state.get("subclass")
            if isinstance(state.get("subclass"), str)
            else None
        ),
        character_alignment=_state_alignment(state),
    )
    if not carried_items:
        return descriptions
    stats = state.get("stats")
    current_strength = (
        stats.get("str_mod")
        if isinstance(stats, Mapping)
        and isinstance(stats.get("str_mod"), (int, float))
        else None
    )
    try:
        character_level = _level(dict(state))
    except (TypeError, ValueError):
        character_level = None
    retained: Counter[int] = Counter()
    for stance in (STANCE_COMBAT, STANCE_RECOVERY, STANCE_PRE_LEVEL):
        for choice in plan_stance(
            carried_items,
            worn_items,
            stance,
            character_level=character_level,
            object_sets=gear_catalog.object_sets.values(),
            current_strength=(
                int(current_strength) if current_strength is not None else None
            ),
        ):
            retained[choice.item.vnum] += 1
    known_skills = {
        " ".join(str(skill).casefold().split())
        for skill in (state.get("campaign_known_skills") or ())
        if isinstance(skill, str) and " ".join(skill.casefold().split())
    }
    known_skills.update(_skill_levels_from_state(state))
    opener_preferences = []
    if "backstab" in known_skills:
        opener_preferences.append(is_piercing_weapon)
    if "stun" in known_skills:
        opener_preferences.append(is_blunt_weapon)
    for preference in opener_preferences:
        if any(
            item_category(item) == "wield" and preference(item)
            for item in worn_items
        ):
            continue
        opener_weapon = max(
            (
                item
                for item in carried_items
                if item_category(item) == "wield" and preference(item)
            ),
            key=lambda item: (weapon_combat_score(item), -item.vnum),
            default=None,
        )
        if opener_weapon is not None:
            retained[opener_weapon.vnum] = max(
                retained[opener_weapon.vnum],
                1,
            )
    if not retained:
        return descriptions
    remaining = retained.copy()
    result: list[str] = []
    for description in descriptions:
        item = gear_catalog.match(description)
        normalized_item_name = (
            normalize_item_name(item.short_description)
            if item is not None
            else ""
        )
        money_container = (
            item is not None
            and item_category(item) == "hold"
            and any(
                marker in normalized_item_name
                for marker in ("purse", "coin", "money")
            )
        )
        if (
            item is not None
            and not is_capacity_infrastructure(item)
            and not money_container
            and remaining[item.vnum] > 0
        ):
            remaining[item.vnum] -= 1
            continue
        result.append(description)
    return tuple(result)


def _campaign_vault_stow_items(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None,
    required_free_weight: int = 10,
) -> tuple[str, ...]:
    if gear_catalog is None:
        return ()
    stats = state.get("stats")
    if not isinstance(stats, dict):
        return ()
    carry_weight = stats.get("carry_wt")
    maximum_weight = stats.get("maxcarry_wt")
    if not isinstance(carry_weight, (int, float)):
        return ()
    if not isinstance(maximum_weight, (int, float)):
        return ()
    if maximum_weight - carry_weight >= required_free_weight:
        return ()

    keywords: list[str] = []
    selected_weight = 0
    capacity_candidates: list[tuple[int, str]] = []
    worn_counts = Counter(
        normalize_item_name(description)
        for description in state.get("campaign_worn_equipment") or ()
    )
    for description in _inventory_descriptions(state.get("inventory")):
        item = gear_catalog.match(description)
        if item is None:
            continue
        normalized_description = normalize_item_name(description)
        if worn_counts[normalized_description] > 0:
            worn_counts[normalized_description] -= 1
            continue
        candidates = gear_catalog.candidates(description)
        ambiguous_weapon = (
            item.item_type == 5
            and len(candidates) > 1
            and all(candidate.item_type == 5 for candidate in candidates)
        )
        plain_armour = item.item_type == 9 and not protects_from_sale(item)
        protected_spare = (
            protects_from_sale(item)
            and not is_capacity_infrastructure(item)
            and item_category(item) not in {"light", "wield"}
        )
        keyword = item_keyword(item)
        normalized_name = normalize_item_name(item.short_description)
        if is_capacity_infrastructure(item):
            if "large sack" in normalized_name:
                keyword = "sack"
            elif "backpack" in normalized_name:
                keyword = "backpack"
            elif "girdle of many pouches" in normalized_name:
                keyword = "girdle"
        if not keyword:
            continue
        if is_capacity_infrastructure(item):
            capacity_candidates.append((item.weight, keyword))
            continue
        if ambiguous_weapon or plain_armour or protected_spare:
            selected_weight += item.weight
        else:
            continue
        if keyword not in keywords:
            keywords.append(keyword)

    free_weight = maximum_weight - carry_weight
    for weight, keyword in sorted(capacity_candidates, reverse=True):
        if free_weight + selected_weight >= required_free_weight:
            break
        if keyword not in keywords:
            keywords.append(keyword)
            selected_weight += weight
    if free_weight + selected_weight < required_free_weight:
        return ()
    return tuple(keywords)


def _has_oversized_capacity_stow_item(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None,
    stow_items: tuple[str, ...],
) -> bool:
    if gear_catalog is None or not stow_items:
        return False
    stats = state.get("stats")
    maximum_weight = stats.get("maxcarry_wt") if isinstance(stats, dict) else None
    if not isinstance(maximum_weight, (int, float)) or maximum_weight <= 0:
        return False
    stow_keywords = {keyword.casefold() for keyword in stow_items}
    for description in _inventory_descriptions(state.get("inventory")):
        item = gear_catalog.match(description)
        if item is None or not is_capacity_infrastructure(item):
            continue
        if not stow_keywords.intersection(item.keywords.casefold().split()):
            continue
        if item.weight >= max(20, maximum_weight * 0.2):
            return True
    return False


def _has_campaign_free_weight(
    state: dict[str, Any],
    required_free_weight: int,
) -> bool:
    stats = state.get("stats")
    if not isinstance(stats, dict):
        return True
    carry_weight = stats.get("carry_wt")
    maximum_weight = stats.get("maxcarry_wt")
    if not isinstance(carry_weight, (int, float)):
        return True
    if not isinstance(maximum_weight, (int, float)):
        return True
    return maximum_weight - carry_weight >= required_free_weight


def _campaign_liquidation_signature(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None = None,
) -> tuple[str, ...]:
    # Keep the signature in lockstep with the live sale planner. In
    # particular, a carried item that is retained as a stance upgrade is not
    # new saleable loot just because its description is individually sellable.
    descriptions = _campaign_liquidation_descriptions(
        state,
        gear_catalog=gear_catalog,
    )
    worn_descriptions = state.get("campaign_worn_equipment")
    character_class = (
        state.get("character_class")
        if isinstance(state.get("character_class"), str)
        else None
    )
    subclass = (
        state.get("subclass")
        if isinstance(state.get("subclass"), str)
        else None
    )
    protected_seen: Counter[str] = Counter()
    candidates: list[str] = []
    for description in descriptions:
        normalized = normalize_item_name(description)
        item = gear_catalog.match(description) if gear_catalog is not None else None
        if (
            item is not None
            and protects_from_sale(item)
            and not any(
                location == 1 and modifier < 0
                for location, modifier in item.affects
            )
            and _sellable_inventory_keyword(
                [[{"short_desc": description}]],
                gear_catalog,
                worn_descriptions=worn_descriptions,
                character_class=character_class,
                subclass=subclass,
            ) is None
        ):
            protected_seen[normalized] += 1
            retained_capacity = {
                "finger": 2,
                "neck": 2,
                "wrist": 2,
            }.get(item_category(item) or "", 1)
            if protected_seen[normalized] <= retained_capacity:
                continue
        elif (
            _sellable_inventory_keyword(
                [[{"short_desc": description}]],
                gear_catalog,
                worn_descriptions=worn_descriptions,
                character_class=character_class,
                subclass=subclass,
            )
            is None
        ):
            continue
        candidates.append(normalized)
    return tuple(sorted(candidates))


def _matches_liquidation_baseline(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None = None,
) -> bool:
    baseline = state.get(_LIQUIDATION_BASELINE_KEY)
    if not isinstance(baseline, (list, tuple)) or not all(
        isinstance(item, str) for item in baseline
    ):
        return False
    current = _campaign_liquidation_signature(state, gear_catalog=gear_catalog)
    recorded = tuple(sorted(normalize_item_name(item) for item in baseline))
    if current == recorded:
        # A worn namesake may be a different instance from retained carried
        # gear. Do not subtract it from an already unchanged inventory.
        return True
    # A retained item can move from inventory into a wear slot during a
    # later gear-maintenance pass.  Older checkpoints keep the item in the
    # liquidation baseline; compare the two signatures after accounting for
    # that one-for-one inventory-to-worn transition.
    worn_counts = Counter(
        normalize_item_name(description)
        for description in state.get("campaign_worn_equipment") or ()
        if isinstance(description, str)
    )

    def without_currently_worn(values: Collection[str]) -> tuple[str, ...]:
        remaining = worn_counts.copy()
        result: list[str] = []
        for value in sorted(normalize_item_name(item) for item in values):
            if remaining[value] > 0:
                remaining[value] -= 1
            else:
                result.append(value)
        return tuple(result)

    return current == without_currently_worn(baseline)


def _liquidation_retention_matches(
    state: Mapping[str, Any],
    *,
    gear_catalog: GearCatalog | None = None,
) -> bool:
    """Return whether a no-sale retention receipt still matches inventory."""
    receipt = state.get(_LIQUIDATION_RETENTION_KEY)
    if (
        not isinstance(receipt, Mapping)
        or receipt.get("retention_only") is not True
        or receipt.get("retention_policy_revision")
        != _LIQUIDATION_RETENTION_POLICY_REVISION
    ):
        return False
    recorded = receipt.get("signature")
    if not isinstance(recorded, (list, tuple)) or not all(
        isinstance(value, str) for value in recorded
    ):
        return False
    current = _campaign_liquidation_signature(
        state,
        gear_catalog=gear_catalog,
    )
    recorded_signature = tuple(
        sorted(normalize_item_name(value) for value in recorded)
    )
    if current == recorded_signature:
        return True
    # Source-aware stance planning can make an older retained item cease to
    # be an actionable sale candidate. A smaller current signature is still
    # the same no-sale inventory; only a new or additional candidate reopens
    # the liquidation pass.
    return not (Counter(current) - Counter(recorded_signature))


def _liquidation_retention_receipt(
    *,
    run_id: int,
    segment_id: int,
    signature: Collection[str],
    inventory_source_hints: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    return {
        "retention_only": True,
        "retention_policy_revision": _LIQUIDATION_RETENTION_POLICY_REVISION,
        "run_id": run_id,
        "segment_id": segment_id,
        "room_vnum": "3054",
        "signature": list(signature),
        "inventory_source_hints": dict(inventory_source_hints) if isinstance(inventory_source_hints, Mapping) else {},
    }


def _repair_liquidation_retention_marker(
    storage: RunStorage,
    campaign_id: int,
    state: Mapping[str, Any],
    *,
    gear_catalog: GearCatalog | None = None,
) -> dict[str, Any]:
    """Recover a retention receipt from an older completed liquidation."""
    existing = state.get(_LIQUIDATION_RETENTION_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("retention_policy_revision")
        == _LIQUIDATION_RETENTION_POLICY_REVISION
    ):
        return dict(state)
    for segment in reversed(_runtime_campaign_segments(storage, campaign_id)):
        if str(segment["phase"] or "") != "liquidate-loot":
            continue
        if segment["run_id"] is None:
            continue
        if isinstance(existing, Mapping):
            try:
                existing_run_id = int(existing.get("run_id") or 0)
                segment_run_id = int(segment["run_id"])
            except (TypeError, ValueError):
                existing_run_id = segment_run_id = 0
            if segment_run_id <= existing_run_id:
                break
        try:
            start_state = json.loads(segment["start_state_json"] or "{}")
            end_state = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(start_state, dict) or not isinstance(end_state, dict):
            continue
        completed_plan = end_state.get("campaign_liquidation_completion")
        if not (
            isinstance(completed_plan, Mapping)
            and completed_plan.get("complete") is True
            and completed_plan.get("retention_only") is True
            and completed_plan.get("run_id") == segment["run_id"]
            and str(completed_plan.get("room_vnum")) == "3054"
        ):
            continue
        if storage.list_loot_sales_for_run(int(segment["run_id"])):
            continue
        start_signature = _campaign_liquidation_signature(
            start_state,
            gear_catalog=gear_catalog,
        )
        end_signature = _campaign_liquidation_signature(
            end_state,
            gear_catalog=gear_catalog,
        )
        if start_signature != end_signature:
            continue
        if (
            existing is not None
            and completed_plan.get("retention_policy_revision")
            != _LIQUIDATION_RETENTION_POLICY_REVISION
        ):
            continue
        repaired = dict(state)
        repaired[_LIQUIDATION_RETENTION_KEY] = _liquidation_retention_receipt(
            run_id=int(segment["run_id"]),
            segment_id=int(segment["id"]),
            signature=end_signature,
            inventory_source_hints=end_state.get(_CAMPAIGN_INVENTORY_SOURCE_HINTS_KEY),
        )
        return repaired
    return dict(state)


def _repair_noop_liquidation_baseline(
    storage: RunStorage,
    campaign_id: int,
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None = None,
) -> dict[str, Any]:
    """Remove a baseline written by a liquidation segment that sold nothing.

    A bounded liquidation segment can spend its entire runtime returning a
    character to the healer. That is a resumable interruption, not proof that
    the unchanged inventory was intentionally retained.
    """
    baseline = state.get(_LIQUIDATION_BASELINE_KEY)
    if not isinstance(baseline, (list, tuple)):
        return dict(state)
    baseline_signature = tuple(
        sorted(normalize_item_name(item) for item in baseline if isinstance(item, str))
    )
    for segment in reversed(_runtime_campaign_segments(storage, campaign_id)):
        if str(segment["phase"] or "") != "liquidate-loot":
            continue
        if segment["run_id"] is None:
            continue
        try:
            start_state = json.loads(segment["start_state_json"] or "{}")
            end_state = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(start_state, dict) or not isinstance(end_state, dict):
            continue
        completed_plan = end_state.get("campaign_liquidation_completion")
        if (isinstance(completed_plan, Mapping) and completed_plan.get("complete") is True
                and completed_plan.get("run_id") == segment["run_id"]
                and str(completed_plan.get("room_vnum")) == "3054"):
            continue
        start_baseline = start_state.get(_LIQUIDATION_BASELINE_KEY)
        if isinstance(start_baseline, (list, tuple)) and start_baseline:
            continue
        if storage.list_loot_sales_for_run(int(segment["run_id"])):
            continue
        start_signature = _campaign_liquidation_signature(
            start_state,
            gear_catalog=gear_catalog,
        )
        end_signature = _campaign_liquidation_signature(
            end_state,
            gear_catalog=gear_catalog,
        )
        if start_signature != end_signature or baseline_signature != end_signature:
            continue
        repaired = dict(state)
        repaired.pop(_LIQUIDATION_BASELINE_KEY, None)
        return repaired
    return dict(state)


def _budget_failure(spec: CampaignSpec, totals: Any) -> str | None:
    if (
        spec.max_segments is not None
        and int(totals["segment_count"]) >= spec.max_segments
    ):
        return f"Campaign exceeded its {spec.max_segments} segment budget."
    if int(totals["command_count"]) >= spec.max_total_commands:
        return f"Campaign exceeded its {spec.max_total_commands} command budget."
    if float(totals["duration_seconds"]) >= spec.max_total_runtime:
        return f"Campaign exceeded its {spec.max_total_runtime:g} second runtime budget."
    return None


def _stalled_count(
    before: dict[str, Any],
    after: dict[str, Any],
    checkpoint: Any,
) -> int:
    previous = _checkpoint_state(checkpoint)
    previous_stalled = int(previous.get("campaign_stalled_segments", 0))
    if previous.get("campaign_policy_revision") != before.get(
        "campaign_policy_revision"
    ):
        previous_stalled = 0
    if _level(after) > _level(before):
        return 0
    before_xp = before.get("xp")
    after_xp = after.get("xp")
    if isinstance(before_xp, (int, float)) and isinstance(after_xp, (int, float)):
        if after_xp > before_xp:
            return 0
    if not before and _level(after) > 0:
        return 0
    return previous_stalled + 1


def _run_duration(run: Any) -> float:
    if run is None or not run["finished_at"]:
        return 0.0
    try:
        elapsed = datetime.fromisoformat(run["finished_at"]) - datetime.fromisoformat(
            run["started_at"]
        )
    except ValueError:
        return 0.0
    return max(0.0, elapsed.total_seconds())
